[32703] = {id=32703,name="Quest Reward Summary: PvE Stage 3",level=1,requiredLevel=1,faction="alliance",expansion=5,zoneID=6507,mapID=504,questType="pvp"},
[32704] = {id=32704,name="Quest Reward Summary: PvE Stage 4-5",level=1,requiredLevel=1,faction="alliance",expansion=5,zoneID=6507,mapID=504,questType="pvp"},
[32706] = {id=32706,name="Allies in the Shadows",level=32,requiredLevel=32,faction="alliance",expansion=5,zoneID=6507,description="The Shado-Pan arrived here before we did, and they are already at work undermining the Thunder King's forces. I want you to meet with Taran Zhu , the leader of the Shado-Pan, and offer your services on behalf of the Kirin Tor. I doubt he is truly in need of the aid, but the gesture holds importance in itself.",starts={{npcID=67992,x=0.632,y=0.722,zoneID=6507},{npcID=70370,x=0.346,y=0.894,zoneID=6507}},ends={{npcID=70160,x=0.514,y=0.46,zoneID=6507}},coords={x=0.632,y=0.722,source="quest_giver",zoneID=6507},questType="standard"},
[32707] = {id=32707,name="Secrets in the Isle of Thunder",level=32,requiredLevel=32,faction="both",expansion=5,zoneID=6507,description="I do have one thing I would ask of you, . We've gotten our hands on a powerful ritual stone that the Shan'ze mogu use to beckon their allies into battle, but we need more than one to perform their rituals. If you come upon three of these stones, bring them back to me. We can gather our forces and use these stones to beckon some of Lei Shen's most powerful servants directly into our traps.",starts={{npcID=70160,x=0.514,y=0.46,zoneID=6507}},ends={{npcID=70160,x=0.514,y=0.46,zoneID=6507}},coords={x=0.514,y=0.46,source="quest_giver",zoneID=6507},questType="standard"},
[32708] = {id=32708,name="Setting the Trap",level=32,requiredLevel=32,faction="both",expansion=5,zoneID=6507,description="Take these 3 ritual stones to the location I have marked on your map. There, you will find a Shan'ze ritual object that you can use to beckon one of their powerful allies. You will need capable friends at your side for this trap to work. Do not go alone, for these will be some of the Thunder King's most powerful servants. When your enemy shows itself, show no mercy.",starts={{npcID=70160,x=0.514,y=0.46,zoneID=6507}},ends={{npcID=70160,x=0.514,y=0.46,zoneID=6507}},coords={x=0.514,y=0.46,source="quest_giver",zoneID=6507},questType="group"},
[32709] = {id=32709,name="Allies in the Shadows",level=32,requiredLevel=32,faction="horde",expansion=5,zoneID=6507,description="The Shado-Pan arrived here before we did, and they are already at work undermining the Thunder King's forces. I want you to meet with Taran Zhu , the leader of the Shado-Pan, and offer your services on behalf of the Sunreavers. I doubt he is truly in need of the aid, but the gesture holds importance in itself.",starts={{npcID=67990,x=0.326,y=0.354,zoneID=6507},{npcID=70371,x=0.284,y=0.522,zoneID=6507}},ends={{npcID=70160,x=0.514,y=0.46,zoneID=6507}},coords={x=0.326,y=0.354,source="quest_giver",zoneID=6507},questType="standard"},
