[32900] = {id=32900,name="Heroic Deeds",level=35,requiredLevel=35,faction="alliance",expansion=5,zoneID=9105,description="My mind is spinning with boredom - I never get to leave this place! You look like you've seen some adventures. If you can bring me a truly heroic story, I've got something special I'm sure you'll be interested in.",starts={{npcID=64101,x=0.884,y=0.65,zoneID=9105}},ends={{npcID=64101,x=0.884,y=0.65,zoneID=9105}},coords={x=0.884,y=0.65,source="quest_giver",zoneID=9105},questType="dungeon"},
[32901] = {id=32901,name="Heroic Deeds",level=35,requiredLevel=35,faction="horde",expansion=5,zoneID=9105,description="My mind is spinning with boredom - I never get to leave this place! You look like you've seen some adventures. If you can bring me a truly heroic story, I've got something special I'm sure you'll be interested in.",starts={{npcID=66998,x=0.61,y=0.136,zoneID=9105}},ends={{npcID=66998,x=0.61,y=0.136,zoneID=9105}},coords={x=0.61,y=0.136,source="quest_giver",zoneID=9105},questType="dungeon"},
[32910] = {id=32910,name="reuse me",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6507,mapID=504,description="There's more you must do. Kill Itoka , master of the forge, and find a codex fragment from Fleshcrafter Hoku, gatekeeper of the Thunder King.",questType="standard"},
