[32924] = {id=32924,name="Short-Supply Reward",level=1,requiredLevel=1,faction="both",expansion=5,questType="standard"},
[32929] = {id=32929,name="They Rely on Numbers",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=7004,description="Thunderlord spend their days training to hunt as a team, but as individuals they are weak. Their only strength is in numbers. So... to win, we must cull their numbers. As we move up through the Daggermaw Ravine, slay any Thunderlord who stand in your way, and their clan will be made the weaker for it.",questType="standard"},
[32941] = {id=32941,name="Vignette: Oasis Icemother",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6720,mapID=525,questType="standard"},
[32942] = {id=32942,name="Work Order: Sunreaver Onslaught I",level=15,requiredLevel=15,faction="horde",expansion=5,zoneID=5805,starts={{npcID=218750,x=0.522,y=0.487,zoneID=5805}},coords={x=0.522,y=0.487,source="quest_giver",zoneID=5805},questType="standard"},
[32943] = {id=32943,name="Work Order: Sunreaver Onslaught II",level=15,requiredLevel=15,faction="horde",expansion=5,zoneID=5805,description="Once your scallions are ready to be picked, you'll need only to package them for pick-up. Just think; your scallions will feed so many hungry soldiers on the front lines!",starts={{npcID=218765,x=0.517,y=0.487,zoneID=5805}},ends={{npcID=218765,x=0.517,y=0.487,zoneID=5805}},coords={x=0.517,y=0.487,source="quest_giver",zoneID=5805},questType="standard"},
[32944] = {id=32944,name="Work Order: Kirin Tor Offensive I",level=15,requiredLevel=15,faction="alliance",expansion=5,zoneID=5805,starts={{npcID=218750,x=0.522,y=0.487,zoneID=5805}},coords={x=0.522,y=0.487,source="quest_giver",zoneID=5805},questType="standard"},
[32945] = {id=32945,name="Work Order: Kirin Tor Offensive II",level=15,requiredLevel=15,faction="alliance",expansion=5,zoneID=5805,description="Once your juicycrunch carrots are ready to be picked, you'll need only to package them for pick-up. Just think; your juicycrunch carrots will feed so many hungry soldiers on the front lines!",starts={{npcID=218765,x=0.517,y=0.487,zoneID=5805}},ends={{npcID=218765,x=0.517,y=0.487,zoneID=5805}},coords={x=0.517,y=0.487,source="quest_giver",zoneID=5805},questType="standard"},
