[33239] = {id=33239,name="Pristine Firestorm Egg",level=30,requiredLevel=30,faction="both",expansion=5,zoneID=6757,mapID=554,starts={{npcID=73657,x=0.418,y=0.634,mapID=554}},ends={{npcID=73657,x=0.418,y=0.634,mapID=554}},coords={x=0.418,y=0.634,source="quest_giver",mapID=554},questType="standard"},
[33248] = {id=33248,name="Proving Grounds",level=35,requiredLevel=35,faction="alliance",expansion=5,zoneID=6852,description="You there! It's , right? Greetings. I'm Taijing. You look strong. I've seen you a few times here in the Vale, but I've never seen you fight before. I wonder... are you as strong as you seem? If you're interested in proving yourself, speak with Trial Master Rotun at the Temple of the White Tiger, in Kun-Lai. He will put you to the test.",starts={{npcID=64101,x=0.884,y=0.65,zoneID=9105}},coords={x=0.884,y=0.65,source="quest_giver",zoneID=9105},questType="standard"},
[33249] = {id=33249,name="Proving Grounds",level=35,requiredLevel=35,faction="horde",expansion=5,zoneID=6852,description="You there! It's , right? Greetings. I'm Jinho. You look strong. I've seen you a few times here in the Vale, but I've never seen you fight before. I wonder... are you as strong as you seem? If you're interested in proving yourself, speak with Trial Master Rotun at the Temple of the White Tiger, in Kun-Lai. He will put you to the test.",starts={{npcID=66998,x=0.61,y=0.136,zoneID=9105}},coords={x=0.61,y=0.136,source="quest_giver",zoneID=9105},questType="standard"},
[33255] = {id=33255,name="The Righteous March",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=6719,description="The Iron Horde have overtaken Karabor. If we don't act now, we will lose the city. Exarch Akama and the last of our forces are trapped within the city, but your garrison forces are still outside the temple, awaiting your orders. Come and fly with me. We will meet your forces on the field. With the naaru by our side, we will make one last charge to retake the city!",starts={{npcID=75145,x=0.522,y=0.46,zoneID=6719},{npcID=77312,x=0.522,y=0.46,zoneID=6719}},ends={{npcID=72413,x=0.774,y=0.376,zoneID=6719}},coords={x=0.522,y=0.46,source="quest_giver",zoneID=6719},questType="standard"},
[33256] = {id=33256,name="The Defense of Karabor",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=6719,description="Defend Karabor from the Iron Horde. At the end of the northern courtyard is Arnokk the Burner. He guards the entrance to the harbor behind Karabor, where the main Iron Horde army is waiting. Once we've taken care of him, we'll need to deal with the Iron Horde leader, Commander Vorka.",starts={{npcID=72413,x=0.774,y=0.376,zoneID=6719}},ends={{npcID=73395,x=0.462,y=0.386,zoneID=6719}},coords={x=0.774,y=0.376,source="quest_giver",zoneID=6719},questType="standard"},
[33263] = {id=33263,name="Gloomshade Grove",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=6719,description="You probably should investigate.>",starts={{npcID=79966,x=0.396,y=0.296,zoneID=6719}},ends={{npcID=73877,x=0.47,y=0.144,zoneID=6719}},coords={x=0.396,y=0.296,source="quest_giver",zoneID=6719},questType="standard"},
[33266] = {id=33266,name="A Light in the Dark - Tracking Quest",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6719,mapID=539,questType="standard"},
[33269] = {id=33269,name="Cleaning Up Gul'var",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=6719,description="Khadgar wants you to concentrate on Gul'dan, but that doesn't mean we're not going to take down the Shadow Council in the process. Gul'var's filthy with Shadow Council villains. Let's do something about them.",starts={{npcID=72637,x=0.292,y=0.256,zoneID=6719}},ends={{npcID=72637,x=0.292,y=0.256,zoneID=6719}},coords={x=0.292,y=0.256,source="quest_giver",zoneID=6719},questType="standard"},
[33271] = {id=33271,name="Game of Thorns",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=6719,mapID=539,description="My lead forest operator, Shelly... she is being held not far from here...",starts={{npcID=73877,x=0.47,y=0.144,mapID=539}},ends={{npcID=76748,x=0.364,y=0.192,mapID=539}},coords={x=0.47,y=0.144,source="quest_giver",mapID=539},questType="standard"},
[33323] = {id=33323,name="Finale - Tracking Quest",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6719,mapID=539,questType="standard"},
[33331] = {id=33331,name="Captured Critters",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=6719,description="This poor critter is about to be podling food. It would be pretty easy to set this little guy free.",starts={{npcID=77270,x=0.462,y=0.158,zoneID=6719}},coords={x=0.462,y=0.158,source="quest_giver",zoneID=6719},questType="standard"},
[33332] = {id=33332,name="Hints From The Past",level=30,requiredLevel=30,faction="both",expansion=5,zoneID=6757,description="There is much to learn of this place, yet it does not yield its secrets willingly. Something you mentioned the last time that we spoke intrigues me. This Mistweaver Ai, she carries a time-worn journal , if I recall? This may be the answer to many of our questions, or it may simply raise more. I suppose that it all depends on the diligence of the explorer that put pen to paper in this preposterous place. Obtain a time-worn journal and return to me with it. We shall delve into its mysteries together.",starts={{npcID=72870,x=0.346,y=0.536,zoneID=6757}},ends={{npcID=72870,x=0.346,y=0.536,zoneID=6757}},coords={x=0.346,y=0.536,source="quest_giver",zoneID=6757},questType="standard"},
[33333] = {id=33333,name="Timeless Treasures",level=30,requiredLevel=30,faction="both",expansion=5,zoneID=6757,description="The journal indicates that treasures abound across the island, sometimes temptingly out of reach, and other times hidden in dark caves and hollows. What might have been secreted away here, many generations ago? And perhaps more importantly, by whom? Search the island for such treasures, and return to me with your findings. Be warned that all that glitters is not gold, yet the reverse is also true. Sometimes the simple hollowed-out stump is the best hiding place for one's valuables.",starts={{npcID=72870,x=0.346,y=0.536,zoneID=6757}},ends={{npcID=72870,x=0.346,y=0.536,zoneID=6757}},coords={x=0.346,y=0.536,source="quest_giver",zoneID=6757},questType="standard"},
[33334] = {id=33334,name="Strong Enough To Survive",level=30,requiredLevel=30,faction="both",expansion=5,zoneID=6757,description="An island lost in time and yet it returns flourishing with life! Where did this island travel to? Did it simply hop forward in time, or did it languish in the dark reaches of the Twisting Nether? There is one thing for certain: the creatures that inhabit this place are far more than they seem. I sense a hidden power in them, forged by the eons. Seek out the champions of their species, duly marked by their power and prowess, and vanquish five such creatures. In death, we may find the clues we seek.",questType="group"},
[33335] = {id=33335,name="The Last Emperor",level=30,requiredLevel=30,faction="both",expansion=5,zoneID=6757,description="From what I have gathered, this place used to be a tournament ground of sorts, where warriors from throughout Pandaria would show their prowess by following in the footsteps of their last emperor, Shaohao. I have heard that when Shaohao completed his trials, he became one with the land, and enveloped Pandaria in a thick mist, obscuring it from even our abilities to penetrate the passages of time. That sounds quite interesting, perhaps you should speak with him?",starts={{npcID=72870,x=0.346,y=0.536,zoneID=6757}},ends={{npcID=73303,x=0.428,y=0.552,zoneID=6757}},coords={x=0.346,y=0.536,source="quest_giver",zoneID=6757},questType="standard"},
[33336] = {id=33336,name="The Essence of Time",level=30,requiredLevel=30,faction="both",expansion=5,zoneID=6757,description="It is about time that I revealed to you my purpose on this island. The bronze dragonflight's powers have diminished greatly - we can now only catch furtive glimpses through time. It is... quite frustrating. But we are not entirely without means. I hold in my hand the Vision of Time, an artifact of my own creation. The creatures of this isle have passed through time, and may carry with them some of its essence. With it, we will fill the hourglass, granting us a window into the timeways once more.",questType="standard"},
[33337] = {id=33337,name="A Vision in Time",level=30,requiredLevel=30,faction="both",expansion=5,zoneID=6757,description="Look at how the Vision reacts! Astounding! Even now it shows shadows of timeways that flit around us constantly. Though not true sands of the Hourglass of Time, the finely-ground epoch stones certainly have a power all their own. Our first task is to use them to calibrate the Vision of Time . Take the Vision of Time to a location where history is in the making: the Siege of Orgrimmar. Once there, turn the hourglass and see what happens.",starts={{npcID=72870,x=0.346,y=0.536,zoneID=6757}},ends={{npcID=72870,x=0.346,y=0.536,zoneID=6757}},coords={x=0.346,y=0.536,source="quest_giver",zoneID=6757},questType="standard"},
[33338] = {id=33338,name="Empowering the Hourglass",level=30,requiredLevel=30,faction="both",expansion=5,zoneID=6757,description="The hourglass gives us glimpses into the streams of time we once walked as easily as a well-worn path. Gather additional epoch stones , so that we may continue to use the power of the hourglass to delve into the mysteries of the timeways. The future depends on it.",questType="standard"},
[33340] = {id=33340,name="Timeless Nutriment",level=30,requiredLevel=30,faction="both",expansion=5,zoneID=6757,description="As you have surmised, the flora and fauna of this island are quite unusual. Not all explanations are mysterious, however. Sometimes, we must listen to the land, to hear the tales of the world around us. Have you considered that the creatures of this island grew to such proportions simply from the nutriment of the land you walk upon? You will find nutriment in abundance throughout the island: ripe fruits, eggs, meat, flowers, nuts, and even the stones themselves. Eat, and discover the power of the land.",starts={{npcID=73303,x=0.428,y=0.552,zoneID=6757}},ends={{npcID=73303,x=0.428,y=0.552,zoneID=6757}},coords={x=0.428,y=0.552,source="quest_giver",zoneID=6757},questType="standard"},
[33341] = {id=33341,name="Wayshrines Of The Celestials",level=30,requiredLevel=30,faction="both",expansion=5,zoneID=6757,description="Many years ago, these grounds were a place where my people would come in pilgrimage. Here, they would listen to the words of the celestials, and meditate for many days. In their meditations, they found the fear, anger, despair, doubt, and violence that plagued their spirits. Before them would be a pathway to enlightenment. For each, the pathway would be different. For all of them, the pathway began with wisdom. Travel the island, as they did, and discover one of the lost wayshrines of the celestials.",starts={{npcID=73303,x=0.428,y=0.552,zoneID=6757}},ends={{npcID=73303,x=0.428,y=0.552,zoneID=6757}},coords={x=0.428,y=0.552,source="quest_giver",zoneID=6757},questType="standard"},
[33342] = {id=33342,name="Drive Back The Flame",level=30,requiredLevel=30,faction="both",expansion=5,zoneID=6757,description="The pandaren once existed in harmony with the Ordon yaungol. When the island suddenly disappeared, the Ordon faced certain death. In their desperation, the chief shaman called out for aid to the Fire Lords, and was answered. Ordos was his name. Now, he is a creature of anger and violence. Though his people were saved, he burns endlessly in molten agony. There is harmony no longer. The Ordon seek to take the Celestial Court, and sacrifice us all to Ordos. Drive them back, and restore balance.",starts={{npcID=73303,x=0.428,y=0.552,zoneID=6757}},ends={{npcID=73303,x=0.428,y=0.552,zoneID=6757}},coords={x=0.428,y=0.552,source="quest_giver",zoneID=6757},questType="standard"},
[33343] = {id=33343,name="The Archiereus Of Flame",level=30,requiredLevel=30,faction="both",expansion=5,zoneID=6757,description="Your efforts have driven back the Ordon and brought peace to the Celestial Court, but it will not last. It is time to silence the great emissary of Ordos - the Archiereus of Flame . Speak with Mistweaver Ku and purchase a scroll of challenge, then travel to Three-Breeze Terrace to the north. Issue a challenge at the challenge stone, it will undoubtedly catch the attention of the Ordon, drawing the archiereus out of the Ordon Sanctuary. It is your only chance.",starts={{npcID=73303,x=0.428,y=0.552,zoneID=6757}},ends={{npcID=73303,x=0.428,y=0.552,zoneID=6757}},coords={x=0.428,y=0.552,source="quest_giver",zoneID=6757},questType="group"},
[33344] = {id=33344,name="Armed and Dangerous",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=6720,description="Ligra was sent with extra weapons to equip enslaved Frostwolves. Arm the Frostwolf Slaves so they can cut their way from their slavers.",questType="standard"},
[33349] = {id=33349,name="STARTER QUEST - RED->PURPLE 15",level=1,requiredLevel=1,faction="none",expansion=5,zoneID=6170,mapID=37,description="BFor this challenge, run through the arch, then get to the RED marker, the PURPLE marker, then return here before the bell tolls 15 times. Good luck!",questType="standard"},
[33350] = {id=33350,name="Redridge Group Trial",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=44,mapID=49,questType="standard"},
[33354] = {id=33354,name="Den Mother's Demise",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=5861,description="This is the pelt of Darkmoon Island's monstrous den mother. Yebb Neblegear , beastmaster of the Darkmoon Faire, will be happy to know the ghostly wolf and her spawn will no longer be terrorizing his menagerie... at least for a little while. Bring it to him.",ends={{npcID=14829,x=0.51,y=0.818,zoneID=5861}},questType="standard"},
[33358] = {id=33358,name="Noodle Time: Bonus",level=35,requiredLevel=35,faction="both",expansion=5,zoneID=5805,description="Hello, . Think you're a truly extraordinary noodle chef? Let's see what you've got!",starts={{npcID=64231,x=0.536,y=0.512,zoneID=5805}},ends={{npcID=64231,x=0.536,y=0.512,zoneID=5805}},coords={x=0.536,y=0.512,source="quest_giver",zoneID=5805},questType="dungeon"},
[33359] = {id=33359,name="Meet Us at Starfall Outpost",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=6719,description="The archmage has uncovered a potential Shadow Council presence in the valley. He asked me to let you know. As soon as you can, join us at Starfall Outpost. We're going to need your muscle to root them out, commander.",starts={{npcID=80645,x=0.438,y=0.448,zoneID=7078}},ends={{npcID=77184,x=0.292,y=0.256,zoneID=6719}},coords={x=0.438,y=0.448,source="quest_giver",zoneID=7078},questType="standard"},
[33374] = {id=33374,name="Path of the Mistwalker",level=30,requiredLevel=30,faction="both",expansion=5,zoneID=6757,description="You have heard the words of the celestials, but what did you learn on your path to the shrines? The wisdom of the pilgrimage is in its silence and simplicity. As you listen to the wind rustling in the trees, and note even the smallest butterfly, your mind is open to learning the deepest lessons the trials have to teach us. Perhaps you noticed the many great beasts that roam the island? Therein lies your trial. You have learned much from Pandaria, now let us put your knowledge to the test.",questType="group"},
[33375] = {id=33375,name="Refining The Vision",level=30,requiredLevel=30,faction="both",expansion=5,zoneID=6757,description="I have finished grinding the stones, and have attuned the hourglass to a new series of timeways. Will you return to the Siege of Orgrimmar and turn the hourglass once more? Return quickly, I am most curious.",starts={{npcID=72870,x=0.346,y=0.536,zoneID=6757}},ends={{npcID=72870,x=0.346,y=0.536,zoneID=6757}},coords={x=0.346,y=0.536,source="quest_giver",zoneID=6757},questType="standard"},
[33376] = {id=33376,name="Seeking Fate",level=30,requiredLevel=30,faction="both",expansion=5,zoneID=6757,description="I have not been completely forthright with you, despite all that you have done to aid the Timewalkers. I cannot tell you everything, not yet, but know this - there is a traitor amongst us. Tell no one of your mission today, and take caution around any of my flight while you hold the Vision of Time . Quickly now, return to the Siege of Orgrimmar once more and use the hourglass. And be safe.",starts={{npcID=72870,x=0.346,y=0.536,zoneID=6757}},ends={{npcID=72870,x=0.346,y=0.536,zoneID=6757}},coords={x=0.346,y=0.536,source="quest_giver",zoneID=6757},questType="standard"},
[33377] = {id=33377,name="Hidden Threads",level=30,requiredLevel=30,faction="both",expansion=5,zoneID=6757,description="You have kept our mission a secret, and for that I thank you. Knowledge of the timeways, when in the wrong hands, can cause catastrophic devastation. My flight has little power to repair it, now. We must be careful. The hourglass grows in power. I believe it can now be used to see much further than before. I wish you to push it to its limits. Return to the Siege of Orgrimmar, and focus the hourglass on the most devastating timeway you can find.",starts={{npcID=72870,x=0.346,y=0.536,zoneID=6757}},ends={{npcID=72870,x=0.346,y=0.536,zoneID=6757}},coords={x=0.346,y=0.536,source="quest_giver",zoneID=6757},questType="standard"},
[33378] = {id=33378,name="Courting Destiny",level=30,requiredLevel=30,faction="both",expansion=5,zoneID=6757,description="The Vision of Time is nearly perfected, we now have much more control over the visions we seek. Your efforts have been instrumental in completing the artifact and restoring the strength of not only my flight, but also our allies in the Timewalkers. All of us are in your debt. Quite fortunately, I have located a sort of crux in time - an intersection of timeways - right here in Pandaria. Take the Vision of Time to the Temple of the White Tiger. There, in the cellars, turn the hourglass.",starts={{npcID=72870,x=0.346,y=0.536,zoneID=6757}},ends={{npcID=72870,x=0.346,y=0.536,zoneID=6757}},coords={x=0.346,y=0.536,source="quest_giver",zoneID=6757},questType="standard"},
[33379] = {id=33379,name="One Final Turn",level=30,requiredLevel=30,faction="both",expansion=5,zoneID=6757,description="I do not wish to ask this of you again, but I do not know who I can trust any longer. I have been using the Vision of Time to gather information, and in my searches, I believe I have found another crux in time. It is in the Caverns of Time itself. I did not want to believe it when the vision first came to me, but I cannot sit idly by and let this information pass. The Caverns of Time - you must go there, now, and use the Vision of Time . Move quickly!",starts={{npcID=72870,x=0.346,y=0.536,zoneID=6757}},ends={{npcID=72870,x=0.346,y=0.536,zoneID=6757}},coords={x=0.346,y=0.536,source="quest_giver",zoneID=6757},questType="standard"},
[33382] = {id=33382,name="Tracking Quest: Saw Maraad Storm Off",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6719,mapID=539,questType="standard"},
[33384] = {id=33384,name="Treasure: Burial Fields A",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6719,mapID=539,ends={{npcID=223533,x=0.445,y=0.635,mapID=539}},questType="standard"},
[33389] = {id=33389,name="Vignette: Yggdrel the Corrupted",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6719,mapID=539,questType="standard"},
[33398] = {id=33398,name="South Sprint Practice",level=1,requiredLevel=1,faction="none",expansion=5,zoneID=6170,mapID=37,description="For this challenge, run through the arch, then get to the red marker, the purple marker, then return here. You have all the time you need.",questType="standard"},
[33408] = {id=33408,name="Great Balls of Fire!",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=6720,description="Ga'nar led Ligra and the others to the second level of the fortress. Your friend, Thrall , also went to lend his skills. Follow the ramp on the south end of the ramparts outside to join them. Help them bring victory to the Frostwolf Clan!",starts={{npcID=75177,x=0.28,y=0.356,zoneID=6720},{npcID=75177,x=0.34,y=0.724,zoneID=6720},{npcID=75177,x=0.506,y=0.332,zoneID=6720}},ends={{npcID=75186,x=0.3,y=0.404,zoneID=6720},{npcID=75186,x=0.702,y=0.784,zoneID=6720}},coords={x=0.28,y=0.356,source="quest_giver",zoneID=6720},questType="standard"},
[33409] = {id=33409,name="Elwynn Run",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6170,mapID=37,description="Welcome to the Ironelf games! For this challenge: get to the blue marker, then the green marker, then return here. Score is based on your time, so get back as fast as you can!",questType="standard"},
[33410] = {id=33410,name="The Butcher of Bladespire",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=6720,description="After Ga'nar advanced into the fortress, the Bladespire unleashed a giant creature on our forces. I am still weak after using my magic, but at least I can help this orc in her recovery. Help take Dorogg down, .",questType="standard"},
[33412] = {id=33412,name="Mopping Up",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=6720,description="We've won the day, but our work here is far from finished. Frostwolves will scour the citadel and root out any survivors. To you, I offer the glory of cleansing the gladiator pits to the north. As we launched our attack, we dispatched one of our best to recon that area. If you still thirst for blood, join her there. There's surely some sport left.",starts={{npcID=81678,x=0.254,y=0.364,zoneID=6720},{npcID=81678,x=0.286,y=0.46,zoneID=6720}},ends={{npcID=74635,x=0.244,y=0.284,zoneID=6720}},coords={x=0.254,y=0.364,source="quest_giver",zoneID=6720},questType="standard"},
[33416] = {id=33416,name="South Sprint 12",level=1,requiredLevel=1,faction="none",expansion=5,zoneID=6170,mapID=37,description="For this challenge, run through the arch, then get to the red marker, the purple marker, then return here before the bell tolls 12 times. Good luck!",questType="standard"},
[33419] = {id=33419,name="A Matter of Life and Death",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=6719,description="Stranger, please help me! My companions and I ventured here to seek the bounty on a monstrous wasp queen. After we set up camp down the hill, we fell asleep. We were attacked in the middle of the night by these horrid, pale... things! I don't know where my friends have gone, but I heard screams from further down the cavern. Please, find my companions. I can't leave here without them!",questType="standard"},
[33422] = {id=33422,name="Elwynn Long Distance Practice",level=1,requiredLevel=1,faction="none",expansion=5,zoneID=12,mapID=37,description="For this challenge: run through the arch, then get to the blue marker, the green marker, and finally return here. You have all the time you need.",questType="standard"},
[33424] = {id=33424,name="Northshire Dash 12",level=1,requiredLevel=1,faction="none",expansion=5,zoneID=6170,mapID=37,description="For this challenge: run through the arch, then get to the blue marker and return here as fast as you can. Get back before you hear the bell toll 12 times.",questType="standard"},
[33425] = {id=33425,name="Blue/Yellow Sprint 15 INTERNAL REPEATABLE",level=1,requiredLevel=1,faction="none",expansion=5,zoneID=6170,mapID=37,description="Ready for a tougher challenge? This one has an extra leg: Run through the arch... Get to the blue marker... Get to the green marker... then return here before the bell tolls 15 times. Good luck!",questType="standard"},
[33427] = {id=33427,name="Ours is the Fury",level=40,requiredLevel=40,faction="horde",expansion=5,zoneID=7004,description="Drek'Thar will be fine, once he adjusts. The vision the elemental has bestowed upon him is powerful, and he is on the path of becoming this world's greatest shaman. You may wish to inform Warmaster Zog in your garrison of what has transpired here. He should be able to deploy some of your troops to the area to further secure the area.",starts={{npcID=76622,x=0.7,y=0.382,zoneID=6720}},ends={{npcID=79740,x=0.538,y=0.542,zoneID=7004}},coords={x=0.7,y=0.382,source="quest_giver",zoneID=6720},questType="standard"},
[33429] = {id=33429,name="Elwynn Long Distance Trial: 25",level=1,requiredLevel=1,faction="none",expansion=5,zoneID=12,mapID=37,description="For this challenge: run through the arch, then get to the blue marker, the green marker, and finally return here before the bell tolls 25 times.",questType="standard"},
[33431] = {id=33431,name="Elwynn South Distance Trial: 30",level=1,requiredLevel=1,faction="none",expansion=5,zoneID=12,mapID=37,description="For this challenge: run through the arch, then get to the red marker, the purple marker, and finally return here before the bell tolls 30 times.",questType="standard"},
[33432] = {id=33432,name="Elwynn South Distance Practice",level=1,requiredLevel=1,faction="none",expansion=5,zoneID=12,mapID=37,description="You want to get some practice in? For this challenge: run through the arch, then get to the red marker, the purple marker, and finally return here. You have all the time you need.",questType="standard"},
[33434] = {id=33434,name="Westfall Race 30",level=1,requiredLevel=1,faction="none",expansion=5,zoneID=6170,mapID=37,description="Run through the arch... Get to the blue marker... Get to the green marker... then return here before the bell tolls 15 times. Good luck!",questType="standard"},
