[33525] = {id=33525,name="Treasure: Orc Couple",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6720,mapID=525,ends={{npcID=75081,x=0.634,y=0.148,mapID=525}},questType="standard"},
[33526] = {id=33526,name="These Colors Don't Run",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=6720,description="Bladespire has been a plague on my people for many years. That ends today! Now to explain it to the ogres in a way they will understand. If you still wish to help us, place our banner in the corpses of our adversaries. Their courage will falter as they behold a field of Frostwolf trophies! This is our way. I will meet with you ahead when you have completed this deed.",starts={{npcID=70860,x=0.27,y=0.36,zoneID=6720},{npcID=76240,x=0.212,y=0.442,zoneID=6720},{npcID=70860,x=0.428,y=0.414,zoneID=6720}},ends={{npcID=74273,x=0.27,y=0.338,zoneID=6720},{npcID=74273,x=0.432,y=0.234,zoneID=6720}},coords={x=0.27,y=0.36,source="quest_giver",zoneID=6720},questType="standard"},
[33527] = {id=33527,name="Last Steps",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=6720,description="In a rage, Ga'nar ascended to fight Gorr'thog, the ogre king. He is alone, and the ramp to the throne room is now blocked. You've proven resourceful. Perhaps you could find another way up? I sustained wounds on my way here, but I will work to cut my way through and up the ramp so we may rejoin. Hurry traveler, ensure that the Frostwolf clan wins our assault on the citadel.",starts={{npcID=75177,x=0.28,y=0.356,zoneID=6720},{npcID=75177,x=0.34,y=0.724,zoneID=6720},{npcID=75177,x=0.506,y=0.332,zoneID=6720}},ends={{npcID=75188,x=0.284,y=0.358,zoneID=6720},{npcID=75188,x=0.656,y=0.568,zoneID=6720}},coords={x=0.28,y=0.356,source="quest_giver",zoneID=6720},questType="standard"},
[33530] = {id=33530,name="Nightmare in the Tomb",level=20,requiredLevel=20,faction="alliance",expansion=5,zoneID=6662,description="Down there... horrible... bodies everywhere... Dark ritual... please... you must stop it...",questType="standard"},
[33531] = {id=33531,name="Treasure: Fallen Ogre",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6720,mapID=525,ends={{npcID=75120,x=0.5,y=0.186,mapID=525}},questType="standard"},
[33532] = {id=33532,name="Treasure: Ogre Cache",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6720,mapID=525,questType="standard"},
[33533] = {id=33533,name="The Secrets of Gorgrond",level=15,requiredLevel=15,faction="alliance",expansion=5,zoneID=7078,description="Our victory today was costly. Too costly. There is no guarantee that we can turn another attack. We need to know what the Iron Horde is up to, and there is only one place we can go to find out. Gorgrond . It is a savage land that few ever return from. I mean to go there, I mean to find their stronghold at Blackrock, and I mean to learn how we can defeat these vile orcs. Will you join me, Commander?",starts={{npcID=73395,x=0.462,y=0.386,zoneID=6719}},ends={{npcID=80978,x=0.64,y=0.572,zoneID=6721}},coords={x=0.462,y=0.386,source="quest_giver",zoneID=6719},questType="standard"},
[33540] = {id=33540,name="Treasure: Uzko's Knickknacks",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6719,mapID=539,ends={{npcID=232587,x=0.359,y=0.409,mapID=539}},questType="standard"},
[33543] = {id=33543,name="The Laughing Skull",level=15,requiredLevel=15,faction="horde",expansion=5,zoneID=6721,description="Ah, $p, good. I need someone who is not of my clan to negotiate with the Laughing Skull. We could use their help navigating this land, but they are dangerous and unpredictable, much like Gorgrond itself. Follow this road and seek out someone willing to speak with you. Perhaps they will see you as something new and be willing to talk first and stab later.",starts={{npcID=74594,x=0.372,y=0.77,zoneID=6721}},ends={{npcID=84176,x=0.386,y=0.736,zoneID=6721}},coords={x=0.372,y=0.77,source="quest_giver",zoneID=6721},questType="standard"},
[33544] = {id=33544,name="Goren, Goren, Gone!",level=15,requiredLevel=15,faction="horde",expansion=5,zoneID=6721,description="We... we left the goren alone for too long. They have grown bold and forgotten who we are. Kill them! Kill them all. Rip them apart until they scream. Remind them what happens to anyone who tries to attack a Laughing Skull village. Oh, and welcome to Gorgrond .",starts={{npcID=84176,x=0.386,y=0.736,zoneID=6721}},ends={{npcID=84176,x=0.386,y=0.736,zoneID=6721}},coords={x=0.386,y=0.736,source="quest_giver",zoneID=6721},questType="standard"},
[33546] = {id=33546,name="Deeds Left Undone",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=6720,description="In his haste, Ga'nar advanced before this area was secured. He is a matchless warrior, mind you, but his tactics are sometimes costly. Gol'kosh and his troops were ordered to destroy enemy supplies, but ogres have stolen the oil he needs. Retrieve the oil and see that their mission is carried out, traveler. Then, if they still live, direct them to rejoin me at the citadel's entrance. I must see my wounded brothers to safety.",starts={{npcID=74273,x=0.27,y=0.338,zoneID=6720},{npcID=74273,x=0.432,y=0.234,zoneID=6720}},ends={{npcID=75177,x=0.28,y=0.356,zoneID=6720},{npcID=75177,x=0.34,y=0.724,zoneID=6720},{npcID=75177,x=0.506,y=0.332,zoneID=6720}},coords={x=0.27,y=0.338,source="quest_giver",zoneID=6720},questType="standard"},
[33548] = {id=33548,name="We Die Laughing!",level=15,requiredLevel=15,faction="horde",expansion=5,zoneID=6721,description="Are you here to help or hinder? This village is being eaten, and we must move quickly to salvage what we can. Gather the masks of our fallen Laughing Skull brothers and sisters and meet me on the western side of the village. I will need them if our clan is to rebuild.",starts={{npcID=76987,x=0.392,y=0.72,zoneID=6721}},ends={{npcID=74606,x=0.414,y=0.74,zoneID=6721}},coords={x=0.392,y=0.72,source="quest_giver",zoneID=6721},questType="standard"},
[33561] = {id=33561,name="Multiplayer Race",level=1,requiredLevel=1,faction="none",expansion=5,zoneID=6170,mapID=37,description="Run through the arch... Get to the blue marker... Get to the green marker... Get to the red marker Get to the purple marker Return here... Then do it all again. That's right - 2 laps! Good luck!",questType="standard"},
[33562] = {id=33562,name="Trophy: Gorg'ak's Obsidian Spines",level=10,requiredLevel=10,faction="none",expansion=5,zoneID=6720,mapID=525,questType="standard"},
[33563] = {id=33563,name="Eye Candy",level=15,requiredLevel=15,faction="horde",expansion=5,zoneID=6721,description="You! Get in the fight or get out of our way. This is no ordinary goren attack. Look over there, a gronnling is sacking our grubhall. That hunchbacked gorebucket bit a chunk out of my lovely Marrow! Rip the eye out of its forehead and bring it to me. That should buy me enough time to get her clear of this goren hole.",starts={{npcID=74611,x=0.404,y=0.72,zoneID=6721}},ends={{npcID=74611,x=0.404,y=0.72,zoneID=6721}},coords={x=0.404,y=0.72,source="quest_giver",zoneID=6721},questType="standard"},
