[33614] = {id=33614,name="Treasure: Greka's Urn",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6719,mapID=539,ends={{npcID=232588,x=0.385,y=0.43,mapID=539}},questType="standard"},
[33622] = {id=33622,name="To the Slaughter",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=6720,description="This entrance to the fortress is clear again, thanks to your help. Inside is another story. Find your way inside and leave no ogre standing as you go.",questType="standard"},
[33633] = {id=33633,name="Rooter the Ravenous",level=15,requiredLevel=15,faction="both",expansion=5,zoneID=6721,description="The stray boar is digging through garbage left behind by the iron horde. He stops chewing and stares at you-then he burps. He smells terrible. It looks like he's chewing on a chunk of rotten meat. Maybe you can find something a bit healthier for him to snack on?",starts={{npcID=75593,x=0.426,y=0.378,zoneID=6721}},ends={{npcID=75593,x=0.426,y=0.378,zoneID=6721}},coords={x=0.426,y=0.378,source="quest_giver",zoneID=6721},questType="standard"},
[33640] = {id=33640,name="Vignette: Veloss",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6719,mapID=539,questType="standard"},
