[33643] = {id=33643,name="Vignette: Venomshade (Plant Hydra)",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6719,mapID=539,questType="standard"},
[33645] = {id=33645,name="Tracking Quest - Iskar's Hired Hand",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6662,mapID=535,questType="standard"},
[33649] = {id=33649,name="Treasure: Torched Iron Horde Scout",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6662,mapID=535,ends={{npcID=75644,x=0.75,y=0.36,mapID=535}},questType="standard"},
[33657] = {id=33657,name="Moving In",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=6720,description="Gorr'thog is now dead. It is time now to secure our hold on Bladespire Citadel. Meet me below and we can begin strengthening our presence.",questType="standard"},
[33660] = {id=33660,name="The Sacking of the Saberon",level=15,requiredLevel=15,faction="horde",expansion=5,zoneID=15347,description="The stash mostly contains bits of old animal parts and other junk. Upon closer inspection there are remains of a bundle of herbs and plants. Rakthoth might be more willing to help if some of these herb bundles were found and gathered for her...",starts={{npcID=234474,x=0.519,y=0.5,zoneID=6721}},ends={{npcID=82222,x=0.522,y=0.49,zoneID=6721},{npcID=82225,x=0.528,y=0.516,zoneID=6721}},coords={x=0.519,y=0.5,source="quest_giver",zoneID=6721},questType="standard"},
[33661] = {id=33661,name="Steamscar \"Reagents\"",level=15,requiredLevel=15,faction="horde",expansion=5,zoneID=6721,description="Now we get to the heart of the matter, heh. Saberon have strong hearts, our shaman find many uses for them. I will search for the ancient's magic if you get me those hearts. Do we have a deal?",starts={{npcID=82222,x=0.522,y=0.49,zoneID=6721}},ends={{npcID=82225,x=0.528,y=0.516,zoneID=6721}},coords={x=0.522,y=0.49,source="quest_giver",zoneID=6721},questType="standard"},
[33662] = {id=33662,name="Beatface vs. Boulder",level=15,requiredLevel=15,faction="horde",expansion=5,zoneID=6721,description="After the saberon stole from these plants, they were forced further up Steamscar Rise and barricaded themselves in. I could not find a way to get in but you have the solution. One path is blocked by a boulder, but it looks weak. A strong warrior, such as an ogre, could break it. I think you know an ogre gladiator...",starts={{npcID=85089,x=0.512,y=0.48,zoneID=6721}},ends={{npcID=82222,x=0.522,y=0.49,zoneID=6721}},coords={x=0.512,y=0.48,source="quest_giver",zoneID=6721},questType="standard"},
[33663] = {id=33663,name="Shredder vs. Saberon",level=15,requiredLevel=15,faction="horde",expansion=5,zoneID=6721,description="After the saberon stole from these plants, they were forced further up Steamscar Rise and barricaded themselves in. I could not find a way to get in but you have the solution. One path is blocked by a tangle of hard vines. I have heard you have a machine that could cut through that with ease. I would get on a shredder and take those vines down.",starts={{npcID=85089,x=0.512,y=0.48,zoneID=6721}},ends={{npcID=82222,x=0.522,y=0.49,zoneID=6721}},coords={x=0.512,y=0.48,source="quest_giver",zoneID=6721},questType="standard"},
[33664] = {id=33664,name="Vignette: Gorum",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6719,mapID=539,questType="standard"},
[33684] = {id=33684,name="The Inkmasters of the Arboretum",level=10,requiredLevel=10,faction="none",expansion=5,description="I have heard that the Inkmasters at the Arboretum are in need of aid from a scribe of great skill. You should speak with Inkmaster Wei, if you wish to help.",questType="standard"},
[33685] = {id=33685,name="Ambassador to the Ancient",level=15,requiredLevel=15,faction="horde",expansion=5,zoneID=6721,description="I have seen a tough looking \"tree\" in that growth. It cries and moans but does not act hostile. It may know how to get rid of these plants. Go and see if it does.",starts={{npcID=81731,x=0.492,y=0.496,zoneID=6721},{npcID=85089,x=0.512,y=0.48,zoneID=6721}},ends={{npcID=85089,x=0.512,y=0.48,zoneID=6721}},coords={x=0.492,y=0.496,source="quest_giver",zoneID=6721},questType="standard"},
[33689] = {id=33689,name="Plant Pruning",level=15,requiredLevel=15,faction="horde",expansion=5,zoneID=6721,description="I have a hunting den not far from here where I gather my trophies as well as reagents for the Laughing Skull. Not long ago this giant plant monster charged in from the overgrowth and was killed by several of the giant rock monsters. Since it died smaller plant beasts have sprung up and made a mess of the place. They have also cut me off from my best source of reagents. Kill them, I will attempt to reach my den and salvage what I can...",starts={{npcID=81731,x=0.492,y=0.496,zoneID=6721}},ends={{npcID=85089,x=0.512,y=0.48,zoneID=6721}},coords={x=0.492,y=0.496,source="quest_giver",zoneID=6721},questType="standard"},
[33694] = {id=33694,name="Reagents from Rakthoth",level=15,requiredLevel=15,faction="horde",expansion=5,zoneID=6721,description="The destruction of our village will not be easy to come back from. Our best hunter, Rakthoth , \"finds\" reagents for our shaman. She has not been seen for some time and we need those more than ever. Go to her hunting grounds and see if she still lives.",starts={{npcID=82732,x=0.462,y=0.7,zoneID=6721}},ends={{npcID=81731,x=0.492,y=0.496,zoneID=6721}},coords={x=0.462,y=0.7,source="quest_giver",zoneID=6721},questType="standard"},
[33695] = {id=33695,name="Taking the Death Bloom",level=15,requiredLevel=15,faction="horde",expansion=5,zoneID=6721,description="You have helped me and now I will help you, $p. The bloom you seek is within the nearby cave, being pawed over by the new leader of these saberon. Kill him and take the bloom back to the ancient below. I hope this will clear out those plants and I can get back to my hunting...",starts={{npcID=82225,x=0.528,y=0.516,zoneID=6721}},ends={{npcID=82302,x=0.502,y=0.474,zoneID=6721}},coords={x=0.528,y=0.516,source="quest_giver",zoneID=6721},questType="standard"},
[33705] = {id=33705,name="Sacking the Saberon Stronghold",level=1,requiredLevel=1,faction="none",expansion=5,zoneID=6721,mapID=543,description="Destroy the barricade and take back stuff!",questType="standard"},
[33706] = {id=33706,name="Laying Dionor to Rest",level=15,requiredLevel=15,faction="horde",expansion=5,zoneID=6721,description="You have given me a tremendous gift with this bloom. I can finally send Dionor back to the Overgrowth for good and end this nightmare. All that remains is the ritual... stay and behold something you will never see again in your lifetime...",starts={{npcID=82302,x=0.502,y=0.474,zoneID=6721}},ends={{npcID=82302,x=0.502,y=0.474,zoneID=6721}},coords={x=0.502,y=0.474,source="quest_giver",zoneID=6721},questType="standard"},
[33720] = {id=33720,name="Decommissioned Mission",level=20,requiredLevel=20,faction="horde",expansion=5,zoneID=6662,description="Ketya Shrediron, Your new Iron Shredders are a menace to our own soldiers. Decommission the prototype and store it in the cave on Talador beach until you've worked out the kinks. I will send Engineer Draxen to work on it in the meantime. - Orgrim Doomhammer",starts={{npcID=225726,x=0.618,y=0.276,zoneID=6662}},ends={{npcID=75924,x=0.59,y=0.206,zoneID=6662}},coords={x=0.618,y=0.276,source="quest_giver",zoneID=6662},questType="standard"},
[33721] = {id=33721,name="Gazlowe's Solution",level=20,requiredLevel=20,faction="horde",expansion=5,zoneID=6662,description="I've identified some high value targets down in the forest below. When you get near one, you can deploy my solution. Deploy it and the objectives will be neutralized with great ceremony.",starts={{npcID=75873,x=0.62,y=0.104,zoneID=6662}},ends={{npcID=75924,x=0.59,y=0.206,zoneID=6662}},coords={x=0.62,y=0.104,source="quest_giver",zoneID=6662},questType="standard"},
[33722] = {id=33722,name="Too Many Irons in the Fire",level=20,requiredLevel=20,faction="horde",expansion=5,zoneID=6721,description="We must not head into battle prematurely. Before we go after Orgrim, we must first deal with his troops. If we are to succeed in our mission of wiping out the Iron Horde from Talador , we need to start on these shores.",starts={{npcID=75806,x=0.614,y=0.108,zoneID=6662}},ends={{npcID=75958,x=0.59,y=0.202,zoneID=6662}},coords={x=0.614,y=0.108,source="quest_giver",zoneID=6662},questType="standard"},
[33724] = {id=33724,name="Vol. X Pages ?",level=20,requiredLevel=20,faction="horde",expansion=5,zoneID=6662,description="The manual for the shredder was wedged in there, but it's missing lots of pages. We need to find as many pages of that manual as possible and I might--MIGHT--be able to get this shredder operational. Based on the direction of the wind, I bet the pages flew toward Archenon Siegeyard.",starts={{npcID=75924,x=0.59,y=0.206,zoneID=6662}},ends={{npcID=75941,x=0.556,y=0.41,zoneID=6662}},coords={x=0.59,y=0.206,source="quest_giver",zoneID=6662},questType="standard"},
[33727] = {id=33727,name="Heal Up",level=20,requiredLevel=20,faction="none",expansion=5,zoneID=6662,mapID=535,questType="standard"},
[33728] = {id=33728,name="An Eye for a Spy",level=20,requiredLevel=20,faction="horde",expansion=5,zoneID=6662,description="Excellent, excellent! I'll make sense of these manual pages and will get the Iron Shredder operational immediately! While I do that, take a look through my Eye 'n' Ear. That's where you'll be headed soon!",starts={{npcID=75941,x=0.556,y=0.41,zoneID=6662}},ends={{npcID=75941,x=0.556,y=0.41,zoneID=6662}},coords={x=0.556,y=0.41,source="quest_giver",zoneID=6662},questType="standard"},
[33729] = {id=33729,name="Born to Shred",level=20,requiredLevel=20,faction="horde",expansion=5,zoneID=6980,description="The Iron Shredder is operational! It should be primed and ready for you to shred our enemies in Tuurem! Head inside and see what damage you can do. Can't say I'm not jealous.",starts={{npcID=75941,x=0.556,y=0.41,zoneID=6662}},ends={{npcID=75941,x=0.556,y=0.41,zoneID=6662},{npcID=75968,x=0.604,y=0.394,zoneID=6662}},coords={x=0.556,y=0.41,source="quest_giver",zoneID=6662},questType="standard"},
[33730] = {id=33730,name="Engineering Her Demise",level=20,requiredLevel=20,faction="horde",expansion=5,zoneID=6662,description="-- THE MOTHER HAS BEEN DETECTED. WARNING! WARNING! --",starts={{npcID=75941,x=0.556,y=0.41,zoneID=6662},{npcID=75968,x=0.604,y=0.394,zoneID=6662}},ends={{npcID=75959,x=0.556,y=0.41,zoneID=6662}},coords={x=0.556,y=0.41,source="quest_giver",zoneID=6662},questType="standard"},
[33731] = {id=33731,name="The Battle for Shattrath",level=20,requiredLevel=20,faction="horde",expansion=5,zoneID=6662,description="To stop the Iron Horde, we must overcome prejudice and work together, if only for this purpose. Horde, Alliance, past, present... all meaningless in the face of this enemy. We will retake Shattrath together... or die trying.",starts={{npcID=75805,x=0.542,y=0.364,zoneID=6662}},ends={{npcID=79604,x=0.714,y=0.296,zoneID=6662}},coords={x=0.542,y=0.364,source="quest_giver",zoneID=6662},questType="standard"},
[33732] = {id=33732,name="Sabotage Siege Weapons",level=20,requiredLevel=20,faction="none",expansion=5,zoneID=6662,mapID=535,questType="standard"},
[33734] = {id=33734,name="Pieces of Us",level=20,requiredLevel=20,faction="both",expansion=5,zoneID=6662,mapID=535,description="When the fires broke out, I took only my daughter's hand before we fled. It was the right decision, of course, but I do long for some of the things we left behind. I am an artificer, a shaper of crystals and gems. Without my tools I am just another refugee. Our town records are kept in a memory crystal in the main hall. With it, I can carry forward the knowledge and legacy of Aruuna. Also, my daughter is terrified - it would be a great comfort for her to hold her favorite doll again.",starts={{npcID=75896,x=0.73,y=0.386,mapID=535}},ends={{npcID=75913,x=0.766,y=0.552,mapID=535}},coords={x=0.73,y=0.386,source="quest_giver",mapID=535},questType="standard"},
[33735] = {id=33735,name="In Short Supply",level=20,requiredLevel=20,faction="horde",expansion=5,zoneID=6662,description="The enemy has explosive devices stored on the beach below. We must recover them so they are not used against us. Reports indicate that crates of explosives are scattered along the shoreline. While you search, Durotan and I will carve deeper into Iron Horde territory.",starts={{npcID=75808,x=0.62,y=0.108,zoneID=6662}},ends={{npcID=75808,x=0.62,y=0.108,zoneID=6662}},coords={x=0.62,y=0.108,source="quest_giver",zoneID=6662},questType="standard"},
[33736] = {id=33736,name="Iron Them Out",level=20,requiredLevel=20,faction="horde",expansion=5,zoneID=6662,description="The orcs themselves are not the only threat. We may have weakened them considerably, but they still have siege weapons of significant power. Sabotage siege weapons you find with the explosives you collected from the beach.",starts={{npcID=75808,x=0.62,y=0.108,zoneID=6662}},ends={{npcID=75808,x=0.62,y=0.108,zoneID=6662}},coords={x=0.62,y=0.108,source="quest_giver",zoneID=6662},questType="standard"},
[33740] = {id=33740,name="Burning Sky",level=20,requiredLevel=20,faction="both",expansion=5,zoneID=6662,mapID=535,description="It happened so fast. A white-hot flash of light ignited the nearby woods, followed by terrible winds that swept the flames across Aruuna. Moments later, arakkoa began descending through the smoke. I need to get Melani to the Pilgrim's Road. From there we can head for Anchorite's Sojourn and the protection of the vindicators. With the arakkoa roaming the area freely, I fear we'll be run down or worse: taken by the spreading wildfires.",starts={{npcID=75896,x=0.73,y=0.386,mapID=535}},ends={{npcID=75913,x=0.766,y=0.552,mapID=535}},coords={x=0.73,y=0.386,source="quest_giver",mapID=535},questType="standard"},
[33754] = {id=33754,name="Through the Looking Glass",level=20,requiredLevel=20,faction="horde",expansion=5,zoneID=6662,description="Your allies sent along a goblin, Gazlowe, to advise us against the Iron Horde. Thus far, he has proven a valuable asset. He has a looking glass set up that can see a great distance and, he claims, even hear. Use this looking glass and report back what you've seen. I will stick to my standard spyglass.",starts={{npcID=75806,x=0.614,y=0.108,zoneID=6662}},ends={{npcID=75806,x=0.614,y=0.108,zoneID=6662}},coords={x=0.614,y=0.108,source="quest_giver",zoneID=6662},questType="standard"},
[33756] = {id=33756,name="Let's Keep Racing!",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=5861,description="Want to keep racing, huh? That's the spirit! See if you can beat your best time! Get to the blue post, then green, then red, then back here. Your time matters, so do it fast!",starts={{npcID=74056,x=0.49,y=0.88,zoneID=5861}},ends={{npcID=74056,x=0.49,y=0.88,zoneID=5861}},coords={x=0.49,y=0.88,source="quest_giver",zoneID=5861},questType="standard"},
[33761] = {id=33761,name="Barum's Notes",level=20,requiredLevel=20,faction="both",expansion=5,zoneID=6662,mapID=535,description="The most recent pages detail a series of cuts intended to aid the draenei vindicators in battle.> \"...honed to a fine edge, the material can expose weaknesses...\" \"when rounded and polished to such a degree, it wards off harmful...\" \"...this incredible discovery that a crystal can be attuned to the bearer's vitality!\"",starts={{npcID=225778,x=0.763,y=0.427,mapID=535}},ends={{npcID=75913,x=0.766,y=0.552,mapID=535}},coords={x=0.763,y=0.427,source="quest_giver",mapID=535},questType="standard"},
[33765] = {id=33765,name="Dark Enemies",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=6719,description="Your arrival should be cause for celebration, hero, but I fear our troubles are just beginning. Warlord Ner'zhul and his Shadowmoon clan have launched a surprise attack on a draenei settlement to the north. Prophet Velen has gone to aid the wounded at Teluuna Observatory, but we need more defenders. I must go to assist the others. If you wish to help us, go to Arbor Glen and kill any Shadowmoon enemies that you see.",starts={{npcID=75005,x=0.46,y=0.388,zoneID=6719}},ends={{npcID=74043,x=0.492,y=0.374,zoneID=6719}},coords={x=0.46,y=0.388,source="quest_giver",zoneID=6719},questType="standard"},
[33782] = {id=33782,name="Keeping the Balance",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=6719,mapID=539,description="Look at these teeth, friend. These stress markings suggest that the crocolisk are being subjugated by one of their own. When a crocolisk female grows large enough, she exerts dominance over her kin. It is my duty as a hunter to ensure balance is restored to these creatures as thanks for their sacrifice for my own life. Track down the beast and slay her while I tend to my wounds. She is likely at the far end of the arbitum.",questType="standard"},
[33784] = {id=33784,name="Gormaul Tower",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=6720,description="It is time for us to strike out against those who would enslave us! We travel to Gormaul Tower to wrest it from the Bladespire ogres. I would welcome your company. Mount up, and together we will ride to battle!",starts={{npcID=76557,x=0.208,y=0.58,zoneID=6720}},ends={{npcID=76240,x=0.212,y=0.442,zoneID=6720}},coords={x=0.208,y=0.58,source="quest_giver",zoneID=6720},questType="standard"},
[33785] = {id=33785,name="Karg Unchained",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=6720,description="They took my brothers and sisters. They took my wolf. Now we take their heads.",questType="standard"},
[33786] = {id=33786,name="Crippled Caravan",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=6719,description="I'm getting reports that the botani have started leaving their bloom and attacking wandering travelers. This is most unusual. We already dispatched a number of rangari to try and resolve this issue. A caravan from Azeroth passed through here recently, you should probably check on your people to ensure their safety.",starts={{npcID=76200,x=0.57,y=0.574,zoneID=6719}},ends={{npcID=76204,x=0.536,y=0.572,zoneID=6719}},coords={x=0.57,y=0.574,source="quest_giver",zoneID=6719},questType="standard"},
[33787] = {id=33787,name="Fiona's Solution",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=6719,description="Gidwin was attacked by one of those plant creatures. From the looks of it, he is suffering from some kind of paralysis. I can make a cure, but I'll need some local ingredients.",starts={{npcID=76204,x=0.536,y=0.572,zoneID=6719}},ends={{npcID=76204,x=0.536,y=0.572,zoneID=6719}},coords={x=0.536,y=0.572,source="quest_giver",zoneID=6719},questType="standard"},
[33788] = {id=33788,name="Cooking With Unstable Herbs",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=6719,description="The base is boiling and ready for those ingredients. Add each of the ingredients, one at a time, and I will handle the mixing and frothing. Speak to me when you are ready.",starts={{npcID=76204,x=0.536,y=0.572,zoneID=6719}},ends={{npcID=76204,x=0.536,y=0.572,zoneID=6719}},coords={x=0.536,y=0.572,source="quest_giver",zoneID=6719},questType="standard"},
[33793] = {id=33793,name="Harbingers of the Void",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=6719,description="Our scouts have made a horrifying discovery, . The souls of the prisoners are being used to summon creatures from the void. Inside, three beings of darkness already await - the Essence of Shadow , the Essence of Darkness , and the Essence of Anguish . They must be destroyed immediately, before their power can be unleashed.",starts={{npcID=81176,x=0.358,y=0.368,zoneID=6719}},ends={{npcID=77282,x=0.462,y=0.386,zoneID=6719}},coords={x=0.358,y=0.368,source="quest_giver",zoneID=6719},questType="standard"},
[33794] = {id=33794,name="The Great Salvation",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=6719,description="We've located the prisoners. They are being held in captivity here, inside the Shadowmoon fortress. Please rescue as many of them as you can. And hurry. We can hear their screams out here.",starts={{npcID=81176,x=0.358,y=0.368,zoneID=6719}},ends={{npcID=73395,x=0.462,y=0.386,zoneID=6719}},coords={x=0.358,y=0.368,source="quest_giver",zoneID=6719},questType="standard"},
[33795] = {id=33795,name="Across the Stars",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=6719,description="A key source of the Shadowmoon clan's power comes from their understanding of the stars and their omens. For centuries, they have recorded the patterns of the stars and their interpretations. While you are in the fortress, collect some of these documents for me. We will take their own knowledge and use it against them.",starts={{npcID=81173,x=0.354,y=0.368,zoneID=6719}},ends={{npcID=77282,x=0.462,y=0.386,zoneID=6719}},coords={x=0.354,y=0.368,source="quest_giver",zoneID=6719},questType="standard"},
[33807] = {id=33807,name="Free Our Brothers and Sisters",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=6720,description="These Thunderlord curs use coward's weapons like nets and chains. Many of our villagers and wolf-brothers and sisters have been trapped. If you free them, they will fight at your side with honor. We must quell this attack with haste so I may return to Bladespire Citadel and continue my preparations.",starts={{npcID=74507,x=0.19,y=0.582,zoneID=6720},{npcID=79415,x=0.218,y=0.564,zoneID=6720}},ends={{npcID=74651,x=0.208,y=0.58,zoneID=6720}},coords={x=0.19,y=0.582,source="quest_giver",zoneID=6720},questType="standard"},
[33808] = {id=33808,name="Swamplighter Queen",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=6719,description="It looks like those plant creatures used some kind of poison when they attacked Gidwin. It's a powerful concoction to say the least. If we are going to cure Gidwin we need one more special ingredient. This one might be a bit harder to obtain than the others. You up to the challenge, ?",starts={{npcID=76204,x=0.536,y=0.572,zoneID=6719}},ends={{npcID=76204,x=0.536,y=0.572,zoneID=6719}},coords={x=0.536,y=0.572,source="quest_giver",zoneID=6719},questType="standard"},
[33813] = {id=33813,name="In Need of a Hero",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=6719,description="I... ... I can't leave... ... without... Squiggy...! He... he's... trapped! You need... to put out... the fire! Ariaana points across the room and bursts into tears.>",starts={{npcID=71502,x=0.52,y=0.326,zoneID=6719}},ends={{npcID=71502,x=0.52,y=0.326,zoneID=6719}},coords={x=0.52,y=0.326,source="quest_giver",zoneID=6719},questType="standard"},
[33814] = {id=33814,name="Fast Expansion",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=7078,description="Greetings, Commander. I am here on behalf of architect Baros Alexston . We have gathered enough resources for the next phase of expansion. He wishes to speak to you at your earliest convenience.",starts={{npcID=81152,x=0.406,y=0.548,zoneID=6719},{npcID=81152,x=0.308,y=0.316,zoneID=7078}},ends={{npcID=77209,x=0.32,y=0.314,zoneID=7078},{npcID=88223,x=0.376,y=0.364,zoneID=7078}},coords={x=0.406,y=0.548,source="quest_giver",zoneID=6719},questType="standard"},
[33815] = {id=33815,name="A Song of Frost and Fire",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=7004,description="You have rescued many of my clan from the slave pens of Tanaan. Their liberation and the destruction of the Dark Portal are more than enough for me to consider you one of us. However, you are still a stranger to our leader, Durotan . I would like to introduce you to him.",starts={{npcID=76411,x=0.408,y=0.67,zoneID=6720},{npcID=76411,x=0.494,y=0.5,zoneID=7004}},ends={{npcID=78272,x=0.418,y=0.696,zoneID=6720}},coords={x=0.408,y=0.67,source="quest_giver",zoneID=6720},questType="standard"},
[33816] = {id=33816,name="Honor Has Its Rewards",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=7004,description="You have honored my people. Now, we wish to honor you. We have a rite of initiation in my clan. When one comes of age, they cover themselves in the blood of their first hunt, and rest their hands upon a shamanstone to honor the ancestors who came before them. In our brief time together you have already slain many foes more fierce than our hunters have ever had to face. Go, touch the shamanstone here in Wor'gol, and join our pack as an equal.",starts={{npcID=80456,x=0.21,y=0.578,zoneID=6720}},ends={{npcID=74272,x=0.168,y=0.578,zoneID=6720},{npcID=76616,x=0.176,y=0.566,zoneID=6720},{npcID=80456,x=0.21,y=0.578,zoneID=6720}},coords={x=0.21,y=0.578,source="quest_giver",zoneID=6720},questType="standard"},
[33826] = {id=33826,name="Where's My Wolf?!",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=6720,description="My frost wolf, Nerok , was captured with me and the others. I do not know where they are keeping him, but I'll bet the so-called \"beastmaster\" who dragged us here does. He is at the beast pens nearby, boasting about his catch to the younger hunters. We'll see how he boasts with my axe in his skull.",questType="standard"},
[33828] = {id=33828,name="The Master Siegesmith",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=6720,description="Not long ago, the most advanced weapon a Thunderlord could make was a really, really big spear. The Blackrock orcs must have shipped in a fearsome master to have them producing cannons so rapidly. We need to find that master.",starts={{npcID=72940,x=0.513,y=0.534,zoneID=6720}},ends={{npcID=72940,x=0.513,y=0.534,zoneID=6720}},coords={x=0.513,y=0.534,source="quest_giver",zoneID=6720},questType="standard"},
[33833] = {id=33833,name="WANTED: Kuu'rat's Tusks",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=6719,description="Posted by: Eremor A ferocious elekk of unprecedented size has been seen near Gloomshade Grove. Known to some as the ivory death, she is abnormally aggressive and has already taken the lives of several unwary travelers. The rangari have as yet been unable to corner this creature. Anyone capable of taking down this beast should exchange proof of her demise to Eremor for a hefty bounty.",starts={{npcID=237016,x=0.332,y=0.308,zoneID=6719}},ends={{npcID=76447,x=0.454,y=0.378,zoneID=6719}},coords={x=0.332,y=0.308,source="quest_giver",zoneID=6719},questType="group"},
[33834] = {id=33834,name="WANTED: Kliaa's Stinger",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=6719,description="Posted by: Dyuna A vicious queen swamplighter has made the northern forests of Shadowmoon its home. Unfortunately, this poisonous pest terrorizes the forest between Embaari Village and Shattrath. As local traders put their lives at risk, prices of goods will continue to rise. Anyone who can put an end to the beast should detach its stinger as proof and bring it to Dyuna in Embaari Village. The merchant traders will reward generously.",starts={{npcID=237021,x=0.264,y=0.328,zoneID=6719}},ends={{npcID=81292,x=0.448,y=0.386,zoneID=6719}},coords={x=0.264,y=0.328,source="quest_giver",zoneID=6719},questType="group"},
[33836] = {id=33836,name="WANTED: Maa'run's Hoof",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=6719,description="Posted by: Orrin A wild talbuk called \"Maa'run\" wanders the hills southeast of Embaari Village and west of The Draakorium. My brother was injured by this foul beast, and now lays in recovery. For the safety of all the nearby villages, we must put an end to this vicious, rampaging creature! A handsome reward will be given to anyone who can bring me his hoof as proof of his demise.",starts={{npcID=232405,x=0.575,y=0.572,zoneID=6719}},ends={{npcID=82227,x=0.58,y=0.576,zoneID=6719}},coords={x=0.575,y=0.572,source="quest_giver",zoneID=6719},questType="group"},
[33837] = {id=33837,name="Darkness Falls",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=6719,description="It is already beginning, over the hills to the southeast. Ner'zhul has everything he needs to summon the Dark Star. The Iron Horde attack on Karabor is imminent. This is where everything ends. Champion, I must ask you to ride ahead and delay Ner'zhul . I will join you as quickly as I can.",starts={{npcID=77282,x=0.462,y=0.386,zoneID=6719}},ends={{npcID=73395,x=0.462,y=0.386,zoneID=6719}},coords={x=0.462,y=0.386,source="quest_giver",zoneID=6719},questType="standard"},
[33838] = {id=33838,name="Smeltcraft",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=6720,description="Stranger! Thank the spirits for them sending you to me now. I am forging a blade and cannot leave it at this delicate state. But I need more ore to complete this task. Here, take my mining pick. It is crafted from the teeth and acid of the local goren and will cut through the ore of this area as if it were air. Bring me the ore and I will lend this blade to your cause.",starts={{npcID=74977,x=0.65,y=0.394,zoneID=6720}},ends={{npcID=74977,x=0.65,y=0.394,zoneID=6720}},coords={x=0.65,y=0.394,source="quest_giver",zoneID=6720},questType="standard"},
[33839] = {id=33839,name="Tracking Quest: Saw Naaru Purified",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6719,mapID=539,questType="standard"},
[33843] = {id=33843,name="Vignette: Broodmother Reeg'ak",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6720,mapID=525,description="Goren are dangerous, especially in large numbers, and especially when we have a blind, under powered shaman with us. Fortunately, they have very short lifespans. Unfortunately, they multiply fast and grow faster. If we are going to do this we need to find the brood mother. Slaying her and her eggs should slow down the onslaught of goren. Check the burrows near the Forge Gates and I will to keep them off of Drek'Thar's scent.",questType="standard"},
[33866] = {id=33866,name="Treasure: Veema's Herb Bag",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6719,mapID=539,ends={{npcID=232589,x=0.342,y=0.435,mapID=539}},questType="standard"},
[33867] = {id=33867,name="Treasure: Star-Reader's Box",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6719,mapID=539,ends={{npcID=226831,x=0.494,y=0.375,mapID=539}},questType="standard"},
[33868] = {id=33868,name="The Home of the Frostwolves",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=7004,mapID=525,description="You have arrived in Frostfire Ridge . Farseer Drek'Thar can guide you from here.",ends={{npcID=76411,x=0.408,y=0.67,mapID=525},{npcID=76411,x=0.494,y=0.5,mapID=525}},questType="standard"},
[33869] = {id=33869,name="Treasure: Elekk Horn",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6719,mapID=539,ends={{npcID=226854,x=0.415,y=0.279,mapID=539}},questType="standard"},
[33871] = {id=33871,name="Seek Out the Seer",level=20,requiredLevel=20,faction="alliance",expansion=5,zoneID=6662,description="We've been watching you, . Seer Malune , keeper of memories, has requested an audience with you, adventurer. She has long foretold the coming of a great hero to destroy the lurking shadow. We believe you are that hero. Come to Duskfall Island, not far south of here, and fulfill your destiny.",starts={{npcID=79724,x=0.71,y=0.472,zoneID=6662}},ends={{npcID=76665,x=0.654,y=0.508,zoneID=6662}},coords={x=0.71,y=0.472,source="quest_giver",zoneID=6662},questType="standard"},
[33872] = {id=33872,name="Dust of the Dead",level=20,requiredLevel=20,faction="both",expansion=5,zoneID=6662,description="I thought if I could just bring him here that I might be able to correct his transgression against the Light. That perhaps I could save my son! Now my beloved Arumel is a twisted phantasm. I'm left with no choice but to right my wrongs and I need your help. Bring me duskwing dust from the moths on Duskfall Island. With your aid I can craft an elixir that will let us travel to the realm of the dead and lay Arumel to rest.",starts={{npcID=76665,x=0.654,y=0.508,zoneID=6662}},ends={{npcID=76665,x=0.654,y=0.508,zoneID=6662}},coords={x=0.654,y=0.508,source="quest_giver",zoneID=6662},questType="standard"},
[33873] = {id=33873,name="Cure of Aruunem",level=20,requiredLevel=20,faction="both",expansion=5,zoneID=6662,description="I need your help in creating an elixir that will allow us passage into the realm of the dead. In order to create it I require a sampling of the local vegetation. You will find Aruunem berries scattered about on the island. Bring me as many as you can carry. Be warned, : do not eat them raw! The poison in the berries would kill you within minutes!",starts={{npcID=76665,x=0.654,y=0.508,zoneID=6662}},ends={{npcID=76665,x=0.654,y=0.508,zoneID=6662}},coords={x=0.654,y=0.508,source="quest_giver",zoneID=6662},questType="standard"},
[33874] = {id=33874,name="Aruumel's Rest",level=20,requiredLevel=20,faction="both",expansion=5,zoneID=6662,description="It is my job to see what others cannot. I keep the memories and read them for others, but I can no longer do so because of my son. My son turned his back on the light. When he perished I could not stand the thought that his spirit might not be welcomed into Auchindoun. I interfered and trapped him here. Now he twists and tortures the memories until they cannot be read. You must do what I cannot bear to do myself. Use this elixir to enter the spirit realm... ...and destroy my son's spirit.",starts={{npcID=76665,x=0.654,y=0.508,zoneID=6662}},ends={{npcID=76665,x=0.654,y=0.508,zoneID=6662}},coords={x=0.654,y=0.508,source="quest_giver",zoneID=6662},questType="standard"},
[33882] = {id=33882,name="Just Peachicky",level=20,requiredLevel=20,faction="alliance",expansion=5,zoneID=6662,description="That mean old Sher'khaan! He's always been a bully to these poor peachicks, but this is crossing the line! I was trying to move this poor clutch out of the way of the demons when he attacked! Now the peachicks are spread out all over and they're scared! Please help me bring them all back!",starts={{npcID=76826,x=0.362,y=0.65,zoneID=6662}},ends={{npcID=76826,x=0.362,y=0.65,zoneID=6662}},coords={x=0.362,y=0.65,source="quest_giver",zoneID=6662},questType="standard"},
[33884] = {id=33884,name="Sher'KHAAAAAAANNNN!",level=20,requiredLevel=20,faction="alliance",expansion=5,zoneID=6662,description="The tigers here have gotten out of control! They're everywhere and meaner than ever! Sher'khaan is the worst of them! He's huge and mean! Maybe a brave adventurer like you could take care of Sher'khaan and the other tigers once and for all.",starts={{npcID=76826,x=0.362,y=0.65,zoneID=6662}},ends={{npcID=76826,x=0.362,y=0.65,zoneID=6662}},coords={x=0.362,y=0.65,source="quest_giver",zoneID=6662},questType="standard"},
[33885] = {id=33885,name="Treasure: Harbor Treasure",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6719,mapID=539,ends={{npcID=226865,x=0.845,y=0.447,mapID=539}},questType="standard"},
[33886] = {id=33886,name="Treasure: Ronokk's Belongings",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6719,mapID=539,ends={{npcID=226861,x=0.313,y=0.391,mapID=539}},questType="standard"},
[33891] = {id=33891,name="Treasure: Moonwillow Seed",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6719,mapID=539,ends={{npcID=226862,x=0.345,y=0.462,mapID=539}},questType="standard"},
[33898] = {id=33898,name="Slaying Slavers",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=6720,description="These ogres keep takin' my clan and turnin' them into slaves! Slay some ogres and I'll hold 'em off if they try to run.",questType="standard"},
[33899] = {id=33899,name="Tracking Quest: Turn on the Holograms",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=5805,mapID=376,questType="standard"},
[33900] = {id=33900,name="Tracking Quest: Activated Arkonite 3",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=5805,mapID=376,questType="standard"},
[33901] = {id=33901,name="Tracking Quest: Activated Arkonite 4",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=5805,mapID=376,questType="standard"},
[33903] = {id=33903,name="Tracking Quest: Romuul & Yrel Leave for Teluuna",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=5805,mapID=376,questType="standard"},
[33905] = {id=33905,name="Closing the Door",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=6719,description="The Shadowmoon orcs are using portals to bring in reinforcements and smuggle away draenei captives. If we are to have any hope of retaking the village, we must destroy the portals at once. The only way to do this is to kill the portalmasters who keep the rifts open.",starts={{npcID=74343,x=0.466,y=0.374,zoneID=6719}},ends={{npcID=74043,x=0.492,y=0.374,zoneID=6719}},coords={x=0.466,y=0.374,source="quest_giver",zoneID=6719},questType="standard"},
[33910] = {id=33910,name="Aklana Rescue",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6719,mapID=539,questType="standard"},
[33915] = {id=33915,name="Young Hearts",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=6720,description="My nephew never pays attention to his surroundings. In his eagerness to prove himself, he has strayed from the pack -- again. He reminds me of myself when I was a youngling. If you see Orac , tell him to return home. We need to finish preparing for tomorrow's hunt.",starts={{npcID=76862,x=0.192,y=0.592,zoneID=6720}},ends={{npcID=76862,x=0.192,y=0.592,zoneID=6720}},coords={x=0.192,y=0.592,source="quest_giver",zoneID=6720},questType="standard"},
[33916] = {id=33916,name="Treasure: Arena Master's Warhorn",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6720,mapID=525,ends={{npcID=226955,x=0.231,y=0.25,mapID=525}},questType="standard"},
[33917] = {id=33917,name="Disrupting the Flow",level=20,requiredLevel=20,faction="both",expansion=5,zoneID=6662,description="You there, we need to stop the flow of demon reinforcements! Do you see the floating fel crystals spread throughout the front? Those resonators are powering the portals unleashing hell on our forces. I need you to take them out!",starts={{npcID=78482,x=0.566,y=0.66,zoneID=6662}},ends={{npcID=78482,x=0.566,y=0.66,zoneID=6662}},coords={x=0.566,y=0.66,source="quest_giver",zoneID=6662},questType="standard"},
[33918] = {id=33918,name="WANTED: Grondo's Bounty",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=6720,description="Grondo , a mad gronn, has been seen roaming the Crackling Plains. This beast has been killing entire herds of clefthoof and devouring innocent frost wolves. We must destroy this threat before it reaches the Garrison.",starts={{npcID=232416,x=0.493,y=0.413,zoneID=7004},{npcID=233291,x=0.493,y=0.415,zoneID=7004},{npcID=237022,x=0.493,y=0.413,zoneID=7004}},ends={{npcID=78487,x=0.456,y=0.432,zoneID=7004}},coords={x=0.493,y=0.413,source="quest_giver",zoneID=7004},questType="group"},
[33919] = {id=33919,name="WANTED: Gutsmash the Destroyer",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=6720,description="Gutsmash has proven to be more than a worthy adversary. Gather a small group together and end his reign of terror once and for all.",starts={{npcID=226961,x=0.254,y=0.365,zoneID=6720},{npcID=226961,x=0.29,y=0.441,zoneID=6720}},ends={{npcID=76746,x=0.27,y=0.364,zoneID=6720},{npcID=76746,x=0.426,y=0.446,zoneID=6720}},coords={x=0.254,y=0.365,source="quest_giver",zoneID=6720},questType="group"},
[33920] = {id=33920,name="The Heart of Auchindoun",level=20,requiredLevel=20,faction="alliance",expansion=5,zoneID=6662,description="A band of Shadow Council orcs stole the Heart of Auchindoun! The Heart powers all of Auchindoun's defenses. Thankfully we were able to save its core and one of its four pieces. The warlock O'mogg Blackheart is using Karab'uun , one of the stolen pieces, to power the largest portal in the Burning Front. Return Karab'uun to me.",starts={{npcID=78519,x=0.564,y=0.67,zoneID=6662}},ends={{npcID=78519,x=0.564,y=0.67,zoneID=6662}},coords={x=0.564,y=0.67,source="quest_giver",zoneID=6662},questType="standard"},
[33925] = {id=33925,name="Treasure: Frostwolf Cache 01",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6720,mapID=525,questType="standard"},
[33926] = {id=33926,name="Treasure: Lagoon Pool",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6720,mapID=525,ends={{npcID=226967,x=0.219,y=0.096,mapID=525}},questType="standard"},
[33927] = {id=33927,name="Draenei Camp Explosion Tracker",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6662,mapID=535,questType="standard"},
[33928] = {id=33928,name="A Wrong of Earth and Fire",level=35,requiredLevel=35,faction="both",expansion=5,zoneID=6755,description="The molten core appears to be the mutated remains of an elemental that consisted of both earth and fire. Slag elementals should not exist upon the plateau where the elements live in purity. You decide that the core should be taken to Incineratus at the Throne of Elements for examination. Perhaps the great fury of fire will know what to make of this core and your battle with Magmire.",ends={{npcID=80593,x=0.714,y=0.18,zoneID=6755}},questType="standard"},
[33929] = {id=33929,name="Shivertail's Den",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=6720,description="The Frostwolf pup looks at you with his big eyes. He howls and stares into the cave. It's unusual for a wolf this young to be wandering around by itself. Shivertail 's parents must be nearby.",starts={{npcID=76889,x=0.194,y=0.51,zoneID=6720}},ends={{npcID=76889,x=0.194,y=0.51,zoneID=6720}},coords={x=0.194,y=0.51,source="quest_giver",zoneID=6720},questType="standard"},
[33930] = {id=33930,name="Treasure: Saberon Stash",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6720,mapID=525,questType="standard"},
[33931] = {id=33931,name="This Is Not a Quest",level=20,requiredLevel=20,faction="horde",expansion=5,zoneID=6662,description="We need help! But not from you...",ends={{npcID=76904,x=0.588,y=0.12,zoneID=6662}},questType="standard"},
[33933] = {id=33933,name="Treasure: Deceptia's Smoldering Boots",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6662,mapID=535,ends={{npcID=226976,x=0.589,y=0.12,mapID=535}},questType="standard"},
[33938] = {id=33938,name="Vignette: Ogre Primalist",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6720,mapID=525,questType="standard"},
[33940] = {id=33940,name="Treasure: Crag-Leaper's Cache",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6720,mapID=525,ends={{npcID=226983,x=0.427,y=0.317,mapID=525}},questType="standard"},
[33942] = {id=33942,name="Treasure: Frostwolf Cache 02",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6720,mapID=525,ends={{npcID=226990,x=0.161,y=0.498,mapID=525}},questType="standard"},
[33944] = {id=33944,name="And the Elekk Too?!",level=20,requiredLevel=20,faction="alliance",expansion=5,zoneID=6662,description="The little stuffed elekk has seen better days. It's torn and the stuffing is poking out. The name Caleb is sewn onto the bottom of the left back foot. Sher'khaan must have snatched it from the cart. The little draenei might appreciate its return.",starts={{npcID=226987,x=0.309,y=0.709,zoneID=6662}},ends={{npcID=76826,x=0.362,y=0.65,zoneID=6662}},coords={x=0.309,y=0.709,source="quest_giver",zoneID=6662},questType="standard"},
[33945] = {id=33945,name="Treasure: Frostwolf Cache 03",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6720,mapID=525,questType="standard"},
[33946] = {id=33946,name="Treasure: Frostwolf Cache 04",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6720,mapID=525,ends={{npcID=226993,x=0.647,y=0.257,mapID=525}},questType="standard"},
[33947] = {id=33947,name="Treasure: Grimfrost Cache",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6720,mapID=525,ends={{npcID=226994,x=0.682,y=0.458,mapID=525}},questType="standard"},
[33948] = {id=33948,name="Treasure: Goren Leftovers",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6720,mapID=525,ends={{npcID=226996,x=0.667,y=0.263,mapID=525}},questType="standard"},
[33949] = {id=33949,name="Treasure: Frostwolf Cache 07",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6720,mapID=525,questType="standard"},
[33955] = {id=33955,name="Missing Pack",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=6720,description="Strange, I wonder where little Shivertail and his pack are? They normally show up for a feeding about now. I hope everything is alright.",starts={{npcID=76941,x=0.216,y=0.552,zoneID=6720}},ends={{npcID=76889,x=0.194,y=0.51,zoneID=6720}},coords={x=0.216,y=0.552,source="quest_giver",zoneID=6720},questType="standard"},
[33957] = {id=33957,name="A Gift for Raa'la",level=10,requiredLevel=10,faction="none",expansion=5,zoneID=6720,mapID=525,description="I need to pack up this kill. I promised my daughter Raa'la I would bring her home a gift from the hunt. There are a couple baby Rylaks in the cave nearby. Maybe Raa'la would like one as a pet? Would you mind catching one while I finish up here?",questType="standard"},
[33958] = {id=33958,name="Into the Hollow",level=20,requiredLevel=20,faction="alliance",expansion=5,zoneID=6662,description="I've learned that the Shadow Council is using the nearby deathweb spiders' venom to spread fel corruption and augment their forces after their defeat at the Burning Front. One of my soulbinders saw a dreadlord headed into the eastern mines with Sha'tari , one of the remaining pieces of the Heart of Auchindoun. I need you to wrest Sha'tari from the dreadlord's quivering corpse and bring it to me, champion.",starts={{npcID=75256,x=0.572,y=0.768,zoneID=6662}},ends={{npcID=75256,x=0.572,y=0.768,zoneID=6662}},coords={x=0.572,y=0.768,source="quest_giver",zoneID=6662},questType="standard"},
[33960] = {id=33960,name="Talador Flowerpicker",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6662,mapID=535,questType="standard"},
[33961] = {id=33961,name="Frostfire Flowerpicker",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6662,mapID=535,questType="standard"},
[33962] = {id=33962,name="Shadowmoon Flowerpicker",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6662,mapID=535,questType="standard"},
[33963] = {id=33963,name="Nagrand Flowerpicker",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6662,mapID=535,questType="standard"},
[33964] = {id=33964,name="Arak Flowerpicker",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6662,mapID=535,questType="standard"},
[33965] = {id=33965,name="Tanaan Flowerpicker",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6662,mapID=535,questType="standard"},
[33966] = {id=33966,name="Gorgrond Flowerpicker",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6662,mapID=535,questType="standard"},
[33967] = {id=33967,name="Antivenin",level=20,requiredLevel=20,faction="alliance",expansion=5,zoneID=6662,description="I'm worried about Nyami. She's so focused on retrieving the Heart of Auchindoun that she seems to have lost sight of everything else. I'm sorry, I'm not trying to belittle her wisdom, but look around! Every soldier we sent into the mine has been gravely injured by the deathweb spiders. Their wounds need immediate attention! Please, can you retrieve some fangs from the spiders? I can use them to create an antivenin, but I need to stay here and keep them stable until then.",starts={{npcID=78028,x=0.572,y=0.768,zoneID=6662}},ends={{npcID=78028,x=0.572,y=0.768,zoneID=6662}},coords={x=0.572,y=0.768,source="quest_giver",zoneID=6662},questType="standard"},
[33969] = {id=33969,name="Vile Defilers",level=20,requiredLevel=20,faction="alliance",expansion=5,zoneID=6662,description="The spiders in the nearby overrun mine are feared by many, for their venom twists the very form of their victims. Many of the locals stay far away from their hollow, but I fear the Shadow Council has become privy to this information. Our scouts report that their warlocks are infusing these spiders with fel energy so that their venom turns their victims into demonic minions! We must destroy the defiling crystals so this madness does not spread.",starts={{npcID=78102,x=0.574,y=0.766,zoneID=6662}},ends={{npcID=78102,x=0.574,y=0.766,zoneID=6662}},coords={x=0.574,y=0.766,source="quest_giver",zoneID=6662},questType="standard"},
[33970] = {id=33970,name="Into the Hollow",level=20,requiredLevel=20,faction="horde",expansion=5,zoneID=6662,description="I've learned that the Shadow Council is using the nearby deathweb spiders' venom to spread fel corruption and augment their forces after their defeat at the Burning Front. One of my soulbinders saw a dreadlord headed into the eastern mines with Sha'tari , one of the remaining pieces of the Heart of Auchindoun. I need you to wrest Sha'tari from the dreadlord's quivering corpse and bring it to me, champion.",starts={{npcID=75256,x=0.572,y=0.768,zoneID=6662}},ends={{npcID=75256,x=0.572,y=0.768,zoneID=6662}},coords={x=0.572,y=0.768,source="quest_giver",zoneID=6662},questType="standard"},
[33971] = {id=33971,name="Antivenin",level=20,requiredLevel=20,faction="horde",expansion=5,zoneID=6662,description="I'm worried about Nyami. She's so focused on retrieving the Heart of Auchindoun that she seems to have lost sight of everything else. I'm sorry, I'm not trying to belittle her wisdom, but look around! Every soldier we sent into the mine has been gravely injured by the deathweb spiders. Their wounds need immediate attention! Please, can you retrieve some fangs from the spiders? I can use them to create an antivenin, but I need to stay here and keep them stable until then.",starts={{npcID=78028,x=0.572,y=0.768,zoneID=6662}},ends={{npcID=78028,x=0.572,y=0.768,zoneID=6662}},coords={x=0.572,y=0.768,source="quest_giver",zoneID=6662},questType="standard"},
[33972] = {id=33972,name="Vile Defilers",level=20,requiredLevel=20,faction="horde",expansion=5,zoneID=6662,description="The deathweb spiders are remarkable creatures. Their venom twists the very form of their victims. We are not the only ones privy to this information. The Shadow Council has already dispatched its warlocks to Deathweb Hollow to infuse the spiders with fel energy so that their venom turns creatures into demonic minions! We must destroy the defiling crystals to prevent all of Talador from bending to Teron'gor's will!",starts={{npcID=75249,x=0.606,y=0.724,zoneID=6662}},ends={{npcID=75249,x=0.606,y=0.724,zoneID=6662}},coords={x=0.606,y=0.724,source="quest_giver",zoneID=6662},questType="standard"},
[33973] = {id=33973,name="Dying Wish",level=20,requiredLevel=20,faction="both",expansion=5,zoneID=6662,description="I am too far gone to rescue, but thank you for speaking with me. Blademaster Bralok had his men starve and beat me, and he stole an heirloom that has been in my family since before we arrived on Draenor. Should you find it, please let me see it once more so I may die in peace.",starts={{npcID=77031,x=0.568,y=0.26,zoneID=6662}},ends={{npcID=77031,x=0.568,y=0.26,zoneID=6662}},coords={x=0.568,y=0.26,source="quest_giver",zoneID=6662},questType="standard"},
[33974] = {id=33974,name="Dying Wish",level=20,requiredLevel=20,faction="none",expansion=5,zoneID=6662,mapID=535,description="This appears to be an ancient Draenei heirloom. Blood stains on it would indicate that it was taken from its owner by force. An inscription on the back says \"Ahm,\" which is likely its rightful owner.",questType="standard"},
[33975] = {id=33975,name="Treasure: Blasting Charges - Rubble A",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6720,mapID=525,questType="standard"},
[33976] = {id=33976,name="The Final Piece",level=20,requiredLevel=20,faction="both",expansion=5,zoneID=6662,description="I am too injured to fight, . I have failed my city and its people. This battle is yours. Vorpil waits just ahead. He's trying to use Auch'naaru 's powers for some sort of dark ritual. You must do what I could not. Cut Vorpil down and retrieve Auch'naaru so the Heart of Auchindoun can be whole once more!",starts={{npcID=77082,x=0.448,y=0.906,zoneID=6662}},ends={{npcID=77082,x=0.448,y=0.906,zoneID=6662}},coords={x=0.448,y=0.906,source="quest_giver",zoneID=6662},questType="standard"},
[33977] = {id=33977,name="Blessing of the Wolf",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6662,mapID=535,questType="standard"},
[33978] = {id=33978,name="Spirit of the Wolf",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6662,mapID=535,questType="standard"},
[33979] = {id=33979,name="Buffeting Galefury",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6662,mapID=535,questType="standard"},
[33980] = {id=33980,name="Ogrish Fortitude",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6662,mapID=535,questType="standard"},
[33981] = {id=33981,name="Touched by Fire",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6662,mapID=535,questType="standard"},
[33982] = {id=33982,name="Touched by Ice",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6662,mapID=535,questType="standard"},
[33988] = {id=33988,name="Invasion of the Soul Eaters",level=20,requiredLevel=20,faction="both",expansion=5,zoneID=6662,description="Telmor is lost. The Shadow Council is dragging our fallen into piles and feeding the souls to their leader. There is blood on my hands... Please, if anyone reads this message, burn the bodies of our fallen so our enemy cannot use them. - Restalaan, Captain of the Guard",starts={{npcID=227069,x=0.492,y=0.88,zoneID=6662}},coords={x=0.492,y=0.88,source="quest_giver",zoneID=6662},questType="standard"},
[33989] = {id=33989,name="Treasure: Blasting Charges - Cave A Cache",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6720,mapID=525,questType="standard"},
[33990] = {id=33990,name="Treasure: Blasting Charges - Rubble B",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6720,mapID=525,questType="standard"},
[33991] = {id=33991,name="Treasure: Blasting Charges - Cave B Cache",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6720,mapID=525,questType="standard"},
