[33997] = {id=33997,name="Treasure: Blasting Charges - Rubble D",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6720,mapID=525,questType="standard"},
[33998] = {id=33998,name="Treasure: Blasting Charges - Cave D Cache",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6720,mapID=525,questType="standard"},
[34012] = {id=34012,name="Need More Teeth",level=15,requiredLevel=15,faction="both",expansion=5,zoneID=6721,description="Prowler Sasha silently holds out his hand to reveal a necklace crafted of stained leather and putrid brown ogre teeth. All have a matching tone of rot to them.>",starts={{npcID=75008,x=0.414,y=0.66,zoneID=6721}},ends={{npcID=75008,x=0.414,y=0.66,zoneID=6721}},coords={x=0.414,y=0.66,source="quest_giver",zoneID=6721},questType="standard"},
[34013] = {id=34013,name="Never Forget",level=20,requiredLevel=20,faction="both",expansion=5,zoneID=6662,description="We had to escape Telmor with what few we could save. Someone disabled Leafshadow 's cloaking field; I know not who, but I suspect it had to have been one of our own. We will retrieve our livelihoods in time, but we cannot risk losing our sacred artifacts. If you are able, bring Leafshadow , our town registry, and our prayerbook to safety.",starts={{npcID=78083,x=0.504,y=0.874,zoneID=6662}},ends={{npcID=78083,x=0.504,y=0.874,zoneID=6662}},coords={x=0.504,y=0.874,source="quest_giver",zoneID=6662},questType="standard"},
[34019] = {id=34019,name="Shadows Awaken",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=6719,description="We've managed to pin Ner'zhul inside the Observatory, but he's taken many down with him. He has taken Yrel's sister, Samaara. I am needed to hold the line here. Please, do whatever you can to save her, hero.",starts={{npcID=74043,x=0.492,y=0.374,zoneID=6719}},ends={{npcID=74043,x=0.492,y=0.374,zoneID=6719}},coords={x=0.492,y=0.374,source="quest_giver",zoneID=6719},questType="standard"},
[34026] = {id=34026,name="Garrison Campaign: Seismic Matters",level=40,requiredLevel=40,faction="alliance",expansion=5,zoneID=7078,description="One of our junior surveyors has been harassing me about unusual seismic activity. I find it hard to believe that we accidentally built on some kind of fault line - we triple checked! Can you have a word with him?",starts={{npcID=77209,x=0.32,y=0.314,zoneID=7078}},ends={{npcID=77217,x=0.64,y=0.696,zoneID=7078}},coords={x=0.32,y=0.314,source="quest_giver",zoneID=7078},questType="standard"},
[34027] = {id=34027,name="Groundbreaking Data",level=40,requiredLevel=40,faction="alliance",expansion=5,zoneID=7078,description="Aye, we triple-checked the site before we set up here. Nary a peep from the ol' earthly deep. But there's been rumblin's today, and they're gettin' closer! I tell ya somethin' ain't right! Ye don't have to take my word for it - the Tremor-Tracker is just about finished collecting data. Check it out an' see fer yerself!",starts={{npcID=77217,x=0.64,y=0.696,zoneID=7078}},ends={{npcID=77217,x=0.64,y=0.696,zoneID=7078}},coords={x=0.64,y=0.696,source="quest_giver",zoneID=7078},questType="standard"},
[34028] = {id=34028,name="These Look Familiar...",level=40,requiredLevel=40,faction="alliance",expansion=5,zoneID=6721,description="So what is the Iron Horde doing with Dark Iron technology? I know who ta ask! Thaelin Darkanvil is a genius engineer from the Dark Iron clan who's been helping us here on Draenor. You may have already met him in yer travels, eh? Word is he set up a bunker somewhere in Gorgrond, a secret workshop so-to-speak. If ye can find him, he may know somethin' about this. Er, and be cautious, eh? The Dark Iron may be our allies now, but I trust 'em about as far as I can throw 'em.",starts={{npcID=77217,x=0.64,y=0.696,zoneID=7078}},ends={{npcID=77160,x=0.864,y=0.488,zoneID=6720},{npcID=77160,x=0.696,y=0.26,zoneID=6721}},coords={x=0.64,y=0.696,source="quest_giver",zoneID=7078},questType="standard"},
[34029] = {id=34029,name="The Prototype",level=40,requiredLevel=40,faction="alliance",expansion=5,zoneID=6721,description="A few days ago a bunch of Iron Horde orcs showed up and kidnapped Thaelin. They've been keeping me alive as collateral to make sure he cooperates. I don't know where they took him, but I know how to get us there. Thaelin keeps a tracking device on him at all times - don't ask where he hides it. Anything he makes that can move has a \"Come to Papa\" button that sends it straight to him. In retrospect, not a great feature for the walking bombs... but perfect for the mole machine! Jump in and let's go!",starts={{npcID=77160,x=0.864,y=0.488,zoneID=6720},{npcID=77160,x=0.696,y=0.26,zoneID=6721}},ends={{npcID=77160,x=0.864,y=0.488,zoneID=6720},{npcID=77160,x=0.696,y=0.26,zoneID=6721}},coords={x=0.864,y=0.488,source="quest_giver",zoneID=6720},questType="standard"},
[34030] = {id=34030,name="The Captive Engineer",level=40,requiredLevel=40,faction="alliance",expansion=5,zoneID=7078,description="Argh... I'm sorry, $p, but I'm too weak to fight. They kept me alive, but just barely. I'll keep an eye on the mole machine while you look for Thaelin. He should be somewhere close!",starts={{npcID=77160,x=0.864,y=0.488,zoneID=6720},{npcID=77160,x=0.696,y=0.26,zoneID=6721}},ends={{npcID=77161,x=0.884,y=0.494,zoneID=6720},{npcID=77161,x=0.648,y=0.68,zoneID=7078}},coords={x=0.864,y=0.488,source="quest_giver",zoneID=6720},questType="standard"},
[34033] = {id=34033,name="And The Mole You Rode In On",level=40,requiredLevel=40,faction="alliance",expansion=5,zoneID=6721,description="I think we've kept Hansel waiting long enough. Can you take me to him? Then we can all hitch a ride out of here on the mole machine.",starts={{npcID=77167,x=0.847,y=0.538,zoneID=6720}},ends={{npcID=77161,x=0.884,y=0.494,zoneID=6720},{npcID=77161,x=0.648,y=0.68,zoneID=7078}},coords={x=0.847,y=0.538,source="quest_giver",zoneID=6720},questType="standard"},
[34034] = {id=34034,name="Garrison Campaign: Grinding Gears",level=40,requiredLevel=40,faction="horde",expansion=5,zoneID=6720,description="Commanda! Da Frostwolf orcs at Thunder Pass have reported a horrible grinding noise boomin' tru da canyon. We suspect it's some kind of Iron Horde war machine. Gazlowe has agreed ta investigate, but he be wantin' a cash bonus. Goblins! Meet wit him at Thunder Pass and deliver dis payment.",starts={{npcID=78487,x=0.456,y=0.432,zoneID=7004}},ends={{npcID=77928,x=0.8,y=0.562,zoneID=6720}},coords={x=0.456,y=0.432,source="quest_giver",zoneID=7004},questType="standard"},
[34035] = {id=34035,name="I Know The Drill!",level=40,requiredLevel=40,faction="horde",expansion=5,zoneID=7004,description="It's a machine alright. A drill - a BIG one! Fortunately, we don't have to take apart the whole thing. They're relying on forced induction, using twin superchargers to pipe extra boost into the engine. Without that boost, the drill is useless. Get in there and open the clutch on the back of the drill. That'll draw some attention away from the turbines. I'll take care of the turbines - you just worry about the hordes of bloodthirsty orcs.",starts={{npcID=77928,x=0.8,y=0.562,zoneID=6720},{npcID=78466,x=0.488,y=0.65,zoneID=6720},{npcID=78466,x=0.42,y=0.55,zoneID=7004}},ends={{npcID=77928,x=0.8,y=0.562,zoneID=6720}},coords={x=0.8,y=0.562,source="quest_giver",zoneID=6720},questType="standard"},
[34040] = {id=34040,name="Maker's Mark",level=40,requiredLevel=40,faction="horde",expansion=5,zoneID=7004,description="I don't get it - most of the Iron Horde junk is about as advanced as strapping cannons to a gronn. Even the drill itself is nothing special. But that induction system was a work of art... This don't add up at all! Despite my better judgment, I gotta find out who made this. I wanna look at more of what they got in the Iron Siegeworks, see if anything's been signed. Gazlowe pats the sack of coins on his belt.> Whaddaya say? Wanna be my bodyguard?",starts={{npcID=77928,x=0.8,y=0.562,zoneID=6720},{npcID=78466,x=0.488,y=0.65,zoneID=6720},{npcID=78466,x=0.42,y=0.55,zoneID=7004}},coords={x=0.8,y=0.562,source="quest_giver",zoneID=6720},questType="standard"},
[34041] = {id=34041,name="Four Finger Discount",level=40,requiredLevel=40,faction="horde",expansion=5,zoneID=7004,description="I gotta admit, establishing a supply chain to a primal world on the wrong side of time is tough, even for me. Gotta make due with, uh... \"locally sourced\" goods. Say what you want about the Iron Horde, but when it comes to raw materials, they got connections! Keep an eye out for some of the more valuable goods in the Iron Siegeworks. I packed a few rocket chickens we can use to send the good stuff back to your garrison.",starts={{npcID=77928,x=0.8,y=0.562,zoneID=6720},{npcID=78466,x=0.488,y=0.65,zoneID=6720},{npcID=78466,x=0.42,y=0.55,zoneID=7004}},coords={x=0.8,y=0.562,source="quest_giver",zoneID=6720},questType="standard"},
[34043] = {id=34043,name="Darkest Night",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=6719,description="This keystone will grant its bearer entry into Anguish Fortress. Take it and meet Prophet Velen outside the Shadowmoon fortress. He intends to face Ner'zhul head-on.",starts={{npcID=75884,x=0.456,y=0.262,zoneID=6719}},ends={{npcID=77282,x=0.462,y=0.386,zoneID=6719}},coords={x=0.456,y=0.262,source="quest_giver",zoneID=6719},questType="standard"},
[34047] = {id=34047,name="Tuurem Explosion Tracker",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6662,mapID=535,questType="standard"},
[34053] = {id=34053,name="SoL Conversation Tracker",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6662,mapID=535,questType="standard"},
[34054] = {id=34054,name="The Dark Side of the Moon",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=6719,description="Prophet Velen 's voice continues.> Yrel and I have located Warlord Ner'zhul. He is meeting with Grommash Hellscream atop the highest altar overlooking Anguish Fortress. Meet us there. We must stop him.",starts={{npcID=77282,x=0.462,y=0.386,zoneID=6719}},ends={{npcID=73395,x=0.462,y=0.386,zoneID=6719}},coords={x=0.462,y=0.386,source="quest_giver",zoneID=6719},questType="standard"},
[34063] = {id=34063,name="Enemies Above",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=6720,mapID=525,description="We have dealt a crushing blow to the Thunderlords with the death of the Iron Wolf , but we can not rest yet. The Thunderlord generals will be fighting like caged wolves to maintain their place in the Iron Horde and that means bad news for us. I sent Scout Ruk'gan to keep an eye on their movements but he hasn't reported back for some time now. If you would help us then seek out Ruk'gan. Lok'tar !",questType="standard"},
[34066] = {id=34066,name="Savage Vengeance",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=6720,description="The Thunderlord are a blight . My daughter, Grishna, was killed by those monsters. Only their blood will bring me peace now. If you would help me then I need you to cause a distraction so I can sneak to a position closer to their camp. Killing a few of their so called \" Iron Thunderguard \" would be perfect.",starts={{npcID=77210,x=0.826,y=0.698,zoneID=6720}},ends={{npcID=77210,x=0.826,y=0.698,zoneID=6720}},coords={x=0.826,y=0.698,source="quest_giver",zoneID=6720},questType="standard"},
[34067] = {id=34067,name="A Collection of Coils",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=6720,description="This coil of rope has been woven thick, the better for the Thunderlord Wranglers to handle the dangerous beasts they tame. Scout Ruk'gan might have a use for this and a few more like it.",ends={{npcID=77210,x=0.826,y=0.698,zoneID=6720}},questType="standard"},
[34068] = {id=34068,name="Vignette: Rockhoof",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6719,mapID=539,questType="standard"},
[34069] = {id=34069,name="Getting the Points",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=6720,description="The Thunderlord Spear is extremely light and strong. Scout Ruk'gan might be able to use this and a few more like it.",starts={{npcID=227504,x=0.841,y=0.651,zoneID=6720}},ends={{npcID=77210,x=0.826,y=0.698,zoneID=6720}},coords={x=0.841,y=0.651,source="quest_giver",zoneID=6720},questType="standard"},
[34070] = {id=34070,name="At the End of Your Rope",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=6720,description="With the spears and rope you gathered the Thunderlord Sky Riders will no longer be out of our reach. Even they will feel our wrath! I've tied the rope to the spears you brought me to fashion a harpoon. Hunt the Sky Riders that are flying all over the valley. Take the Harpoon and throw it at them as they circle by. If your aim is true the barbs should allow the spear a firm hold allowing you to yank the rider right towards you! If your aim is bad... well... try not to miss.",starts={{npcID=77210,x=0.826,y=0.698,zoneID=6720}},ends={{npcID=77210,x=0.826,y=0.698,zoneID=6720}},coords={x=0.826,y=0.698,source="quest_giver",zoneID=6720},questType="standard"},
[34072] = {id=34072,name="Tar Get of Opportunity",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=6720,description="General Vul'gath leads this band of Thunderlord. He is a coward and hides in his hut, yelling orders at his warriors through the walls. We will need to show him that his flimsy defenses can not stand against the Frostwolves! I'll need some tar to carry this out. There are a couple of tar pits to the south, go gather a few globs from the oozes that reside there and bring them to me.",starts={{npcID=77210,x=0.826,y=0.698,zoneID=6720}},ends={{npcID=77210,x=0.826,y=0.698,zoneID=6720}},coords={x=0.826,y=0.698,source="quest_giver",zoneID=6720},questType="standard"},
[34073] = {id=34073,name="Burn Them Down",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=6720,description="Now, we begin our assault, ! Get down to Agurak's Fall and use these tarbombs to destroy their rylak egg incubators. While you are busy I will sneak down into their camp and prepare for the next phase of our attack. Meet me there once you have burned everything.",starts={{npcID=77210,x=0.826,y=0.698,zoneID=6720}},ends={{npcID=77210,x=0.826,y=0.698,zoneID=6720}},coords={x=0.826,y=0.698,source="quest_giver",zoneID=6720},questType="standard"},
[34075] = {id=34075,name="Vul'gath's End",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=6720,description="Vul'gath's time has come to an end, . My daughter's blood is upon his hands, now his blood will be on ours! Show no mercy and strike him down!",starts={{npcID=77210,x=0.826,y=0.698,zoneID=6720}},ends={{npcID=77210,x=0.826,y=0.698,zoneID=6720}},coords={x=0.826,y=0.698,source="quest_giver",zoneID=6720},questType="standard"},
[34077] = {id=34077,name="Trouble to the South",level=1,requiredLevel=1,faction="alliance",expansion=5,zoneID=6719,mapID=539,description="A group of Alliance soldiers headed south from here not long ago. They said they were searching for some sort of special flower. To be frank, I'm concerned for their safety. This area is still crawling with Iron Horde. They could surely use your help if you're able. Follow the road south and you should find their position.",questType="standard"},
[34078] = {id=34078,name="Payment Due for Services Rendered",level=40,requiredLevel=40,faction="horde",expansion=5,zoneID=7004,description="I'm ready to get outta here, and I ain't hoofin' it back through all those orcs. Fortunately, I kept a few extra rocket chickens to get us back to your garrison in style! Let's get up to the roof and find a decent place to take off.",ends={{npcID=78466,x=0.488,y=0.65,zoneID=6720},{npcID=78466,x=0.42,y=0.55,zoneID=7004}},questType="standard"},
[34079] = {id=34079,name="Mission Successful",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=6720,mapID=525,description="The Thunderlords are finished and our job is complete. I'll stay here and watch over the area. You should head back to Sergeant Gil'nath. I'm certain he will have another task for you.",questType="standard"},
[34087] = {id=34087,name="Through the Looking Glass",level=20,requiredLevel=20,faction="alliance",expansion=5,zoneID=6662,description="An ally of yours, Thaelin, is helping us counter the Iron Horde. He claims this device can be used to spy on the enemy, even so far as hearing what they are saying at great distance. I do not trust such devices. Use it and let me know what you see.",starts={{npcID=75803,x=0.63,y=0.258,zoneID=6662}},ends={{npcID=75803,x=0.63,y=0.258,zoneID=6662}},coords={x=0.63,y=0.258,source="quest_giver",zoneID=6662},questType="standard"},
[34088] = {id=34088,name="Too Many Irons in the Fire",level=20,requiredLevel=20,faction="alliance",expansion=5,zoneID=6721,description="We must slay the Iron Horde troops who infest our lands. Find those who would sully our great forest and show them the hand of justice.",starts={{npcID=75803,x=0.63,y=0.258,zoneID=6662}},ends={{npcID=75803,x=0.63,y=0.258,zoneID=6662}},coords={x=0.63,y=0.258,source="quest_giver",zoneID=6662},questType="standard"},
[34089] = {id=34089,name="In Short Supply",level=20,requiredLevel=20,faction="alliance",expansion=5,zoneID=6662,description="The Iron Horde has explosive devices stored throughout the heart of their logging camp. We must recover them so they are not used against us. I will keep an eye on Maraad... I worry for him in his anger.",starts={{npcID=75804,x=0.63,y=0.258,zoneID=6662}},ends={{npcID=75804,x=0.63,y=0.258,zoneID=6662}},coords={x=0.63,y=0.258,source="quest_giver",zoneID=6662},questType="standard"},
[34090] = {id=34090,name="Thaelin's Quick Fix",level=20,requiredLevel=20,faction="alliance",expansion=5,zoneID=6662,description="Those orcs sure like to pile things up in one place. That gave me an idea... I've built this ingenious device for ya! When you get near a target, it'll let you know, and you can deploy it for a big, satisfying, kerBOOM!",starts={{npcID=75874,x=0.63,y=0.26,zoneID=6662}},ends={{npcID=75874,x=0.63,y=0.26,zoneID=6662}},coords={x=0.63,y=0.26,source="quest_giver",zoneID=6662},questType="standard"},
[34091] = {id=34091,name="Decommissioned Mission",level=20,requiredLevel=20,faction="alliance",expansion=5,zoneID=6662,description="Ketya Shrediron, Your new Iron Shredders are a menace to our own soldiers. Decommission the prototype and store it out of the way until you've worked out the kinks. I will send Engineer Trak to work on it in the meantime. - Orgrim Doomhammer",starts={{npcID=225726,x=0.618,y=0.276,zoneID=6662}},ends={{npcID=75874,x=0.63,y=0.26,zoneID=6662}},coords={x=0.618,y=0.276,source="quest_giver",zoneID=6662},questType="standard"},
[34092] = {id=34092,name="Desperate Measures",level=20,requiredLevel=20,faction="both",expansion=5,zoneID=6662,description="We've identified the location of Teron'gor's compound, but his forces are already far stronger than anything we've ever faced. We need to gain an edge, and quickly. The cursed spirits of the Ango'rosh ogres, our ancient enemies, linger in nearby ruins. Go there and gather the Ango'rosh Spellbook and the Grimoire of Binding . Perform the ritual described within at their altar to lift their curse and seek their aid. It's a long shot, but we don't have any other options.",starts={{npcID=77799,x=0.434,y=0.76,zoneID=6662}},ends={{npcID=77799,x=0.434,y=0.76,zoneID=6662}},coords={x=0.434,y=0.76,source="quest_giver",zoneID=6662},questType="standard"},
[34093] = {id=34093,name="Getting the Points",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=6720,description="Those Thunderlords circling above us are a problem . They fly their pathetic Rylaks leisurely across the valley, thinking they are safe to rain spears down on our heads. We need to show them they are not safe from Frostwolf Vengeance! I have a plan but we will need to gather some material. Go hunt across the valley for any of their spears that survived intact. I think five should be enough.",starts={{npcID=77210,x=0.826,y=0.698,zoneID=6720}},ends={{npcID=77210,x=0.826,y=0.698,zoneID=6720}},coords={x=0.826,y=0.698,source="quest_giver",zoneID=6720},questType="standard"},
[34094] = {id=34094,name="Vol. X Pages ?",level=20,requiredLevel=20,faction="alliance",expansion=5,zoneID=6662,description="That shredder had a manual jammed in the cockpit, but it's missing a lot o' pages. If we can find those manual pages, I'd bet my third toe I can get the prototype shredder working again. I coulda swore I saw a few of those pages floatin' about in Archenon Siegeyard. Maybe the orcs there carry them.",starts={{npcID=75874,x=0.63,y=0.26,zoneID=6662}},ends={{npcID=75874,x=0.63,y=0.26,zoneID=6662}},coords={x=0.63,y=0.26,source="quest_giver",zoneID=6662},questType="standard"},
[34095] = {id=34095,name="Iron Them Out",level=20,requiredLevel=20,faction="alliance",expansion=5,zoneID=6662,description="The orcs themselves are not the only threat. They still have siege weapons of significant power. They've already been used against Tuurem, and we must not allow for their continued operation. Sabotage siege weapons using the explosives you collected from the logging camp.",starts={{npcID=75804,x=0.63,y=0.258,zoneID=6662}},ends={{npcID=75804,x=0.63,y=0.258,zoneID=6662}},coords={x=0.63,y=0.258,source="quest_giver",zoneID=6662},questType="standard"},
[34096] = {id=34096,name="An Eye for a Spy",level=20,requiredLevel=20,faction="alliance",expansion=5,zoneID=6662,description="I'll get the prototype shredder working right now! Take a look through my Observicopter. You'll see what you're about to head into...",starts={{npcID=75874,x=0.63,y=0.26,zoneID=6662}},ends={{npcID=75874,x=0.63,y=0.26,zoneID=6662}},coords={x=0.63,y=0.26,source="quest_giver",zoneID=6662},questType="standard"},
[34097] = {id=34097,name="Born to Shred",level=20,requiredLevel=20,faction="alliance",expansion=5,zoneID=6980,description="I've got this prototype shredder operating on most cylinders. Boy, will they be surprised when you stomp them with their own machine! Can't wait to watch you from the safety of the Observicopter.",starts={{npcID=75874,x=0.63,y=0.26,zoneID=6662}},ends={{npcID=75874,x=0.63,y=0.26,zoneID=6662},{npcID=75968,x=0.604,y=0.394,zoneID=6662}},coords={x=0.63,y=0.26,source="quest_giver",zoneID=6662},questType="standard"},
[34098] = {id=34098,name="Engineering Her Demise",level=20,requiredLevel=20,faction="alliance",expansion=5,zoneID=6662,description="-- THE MOTHER HAS BEEN DETECTED. WARNING! WARNING! --",starts={{npcID=75874,x=0.63,y=0.26,zoneID=6662},{npcID=75968,x=0.604,y=0.394,zoneID=6662}},ends={{npcID=75803,x=0.63,y=0.258,zoneID=6662}},coords={x=0.63,y=0.26,source="quest_giver",zoneID=6662},questType="standard"},
[34099] = {id=34099,name="The Battle for Shattrath",level=20,requiredLevel=20,faction="alliance",expansion=5,zoneID=6662,description="To stop the Iron Horde, we must overcome prejudice and work together, if only for this purpose. Horde, Alliance, past, present... all meaningless in the face of this enemy. We will retake Shattrath together... or die trying.",starts={{npcID=75805,x=0.542,y=0.364,zoneID=6662}},ends={{npcID=79608,x=0.696,y=0.21,zoneID=6662}},coords={x=0.542,y=0.364,source="quest_giver",zoneID=6662},questType="standard"},
[34101] = {id=34101,name="Vignette: Aruumel's Worn Mace",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6662,mapID=535,ends={{npcID=227527,x=0.688,y=0.561,mapID=535}},questType="standard"},
[34102] = {id=34102,name="The Mark of Defiance",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=6720,description="As you look upon the Frostwolf banner you remember struggles that have led you and the Frostwolves to this point. Ruk'gan has suffered in his battles with the Thunderlord and would appreciate an extra show of defiance. As the banner rustles in the wind you're inspired to mark the foes of the Frostwolf with its standard.",starts={{npcID=227806,x=0.826,y=0.698,zoneID=6720}},ends={{npcID=77210,x=0.826,y=0.698,zoneID=6720}},coords={x=0.826,y=0.698,source="quest_giver",zoneID=6720},questType="standard"},
[34103] = {id=34103,name="WANTED: Kil'uun",level=20,requiredLevel=20,faction="alliance",expansion=5,zoneID=9525,description="I have a bounty set on a bird, commander. Yes, a bird. The issue is this thing is massive, and it was last sighted a stone's throw away from the Horde base to the south in the forest. The locals call it Kil'uun. If you'd like to track the creature down and bring back its beak I wager it would fetch a sack or two of gold for your coffers!",starts={{npcID=80854,x=0.694,y=0.212,zoneID=6662}},ends={{npcID=80854,x=0.694,y=0.212,zoneID=6662}},coords={x=0.694,y=0.212,source="quest_giver",zoneID=6662},questType="group"},
[34104] = {id=34104,name="WANTED: Hilaani",level=20,requiredLevel=20,faction="alliance",expansion=5,zoneID=6662,description="O'riley wants to thank our peasants for their hard work with a riverbeast dinner. $I don't want to waste your time asking you to slaughter the things all day, commander. We've gotten reports of a huge riverbeast called Hilaani that would feed the whole fort twice over living in the lake to the south. If you have a chance to bring cuts of her meat back, the men would be grateful.",starts={{npcID=80854,x=0.694,y=0.212,zoneID=6662}},ends={{npcID=80854,x=0.694,y=0.212,zoneID=6662}},coords={x=0.694,y=0.212,source="quest_giver",zoneID=6662},questType="group"},
[34105] = {id=34105,name="WANTED: Ra'tok the Hammer",level=20,requiredLevel=20,faction="alliance",expansion=5,zoneID=6662,description="I've got an issue that could use your assistance, commander. A few of our men spotted an Iron Horde lieutenant wandering in the cliffs near here. We suspect she's directing their forces to strategic ground as they land on the Orunai Coast. I would feel much better about the safety of this fort if you could take her out.",starts={{npcID=80854,x=0.694,y=0.212,zoneID=6662}},ends={{npcID=80854,x=0.694,y=0.212,zoneID=6662}},coords={x=0.694,y=0.212,source="quest_giver",zoneID=6662},questType="group"},
[34106] = {id=34106,name="WANTED: Ra'tok the Hammer",level=20,requiredLevel=20,faction="horde",expansion=5,zoneID=6662,description="The Iron Horde have no honor. They disgust me. We spotted one of their lieutenants wandering the cliffs not far from our base. I believe that she is tracking our movements to prepare for some sort of assault from the Orunai Coast. I understand you have much to do, commander. If you have the time, I believe it would be beneficial to our position's integrity.",starts={{npcID=80833,x=0.708,y=0.296,zoneID=6662}},ends={{npcID=80833,x=0.708,y=0.296,zoneID=6662}},coords={x=0.708,y=0.296,source="quest_giver",zoneID=6662},questType="group"},
[34107] = {id=34107,name="WANTED: Hilaani",level=20,requiredLevel=20,faction="horde",expansion=5,zoneID=6662,description="We need more meat, commander. I know what you're thinking. What about all of that meat right behind me? That's the problem. It'll be gone in a day if we're lucky. There's a riverbeast that lives in the lake to the south. Locals call her Hilaani. Massive, lots of meat. If you would take down the beast and bring me her meat, your wolves will be better off for it.",starts={{npcID=80833,x=0.708,y=0.296,zoneID=6662}},ends={{npcID=80833,x=0.708,y=0.296,zoneID=6662}},coords={x=0.708,y=0.296,source="quest_giver",zoneID=6662},questType="group"},
[34108] = {id=34108,name="WANTED: Kil'uun",level=20,requiredLevel=20,faction="horde",expansion=5,zoneID=9525,description="It's that damned bird! Every few hours, this blasted thing flies right past here, and none of these idiots will stop it. \"It's got the crazy in its eyes,\" they tell me. Pah! Commander, this bird will be the end of me. If you see it, could you cut off its stupid head and give it to me? It'd make me feel better.",starts={{npcID=80833,x=0.708,y=0.296,zoneID=6662}},ends={{npcID=80833,x=0.708,y=0.296,zoneID=6662}},coords={x=0.708,y=0.296,source="quest_giver",zoneID=6662},questType="group"},
