[34122] = {id=34122,name="Ogre Diplomacy",level=20,requiredLevel=20,faction="horde",expansion=5,zoneID=6662,description="They may be spirits, but the Ango'rosh are still ogres. Even with their books in hand, they won't respect you until you prove yourself, and there's only one way to earn that. By killing them. You should take out as many of the Ango'rosh spirits and their pets as you can while in the ruins.",starts={{npcID=75389,x=0.43,y=0.762,zoneID=6662}},ends={{npcID=75389,x=0.43,y=0.762,zoneID=6662}},coords={x=0.43,y=0.762,source="quest_giver",zoneID=6662},questType="standard"},
[34123] = {id=34123,name="To Thunder Pass",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=6720,description="There is no time to mourn our fallen or lick our wounds. Your scouts have already reported sighting a massive Iron Horde army making its way through Thunder Pass. I advise you let your garrison forces secure this area while you and I make for the pass east of here with the rest of the Frostwolves. It is time to show this Iron Horde what a united Frostwolf clan can do.",questType="standard"},
[34124] = {id=34124,name="The Battle of Thunder Pass",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=6720,description="The Iron Horde has an army tenfold our number marching down the Thunder Pass as we speak. Durotan is amassing our forces at the mouth of the pass. He is doing what he can to mount a defense but war on this scale is not what we Frostwolves are masters of. He will need your expertise. Please, go to him.",starts={{npcID=76487,x=0.734,y=0.588,zoneID=6720}},ends={{npcID=76484,x=0.75,y=0.558,zoneID=6720},{npcID=77485,x=0.75,y=0.558,zoneID=6720}},coords={x=0.734,y=0.588,source="quest_giver",zoneID=6720},questType="standard"},
