[34144] = {id=34144,name="Retribution for the Light",level=20,requiredLevel=20,faction="horde",expansion=5,zoneID=6662,description="There are agents of darkness everywhere, fighting tooth and nail to envelop the world. The Light relies on us to balance the scale. You have the power needed to destroy Teron'gor's demonic minions once and for all. Send them to the Twisting Nether in pieces!",starts={{npcID=75389,x=0.43,y=0.762,zoneID=6662}},ends={{npcID=75389,x=0.43,y=0.762,zoneID=6662},{npcID=77580,x=0.456,y=0.744,zoneID=6662}},coords={x=0.43,y=0.762,source="quest_giver",zoneID=6662},questType="standard"},
