[34154] = {id=34154,name="Destination: Unknown",level=20,requiredLevel=20,faction="alliance",expansion=5,zoneID=8485,description="Teron'gor and Gul'dan were just leaving through the portal as I arrived... and I... I know I won't be able to defeat them. I'll hold open the portal as long as I can. It will be up to you to strike the killing blow. Our fate is in your hands, .",starts={{npcID=77582,x=0.312,y=0.736,zoneID=6662}},ends={{npcID=79434,x=0.462,y=0.74,zoneID=6662}},coords={x=0.312,y=0.736,source="quest_giver",zoneID=6662},questType="standard"},
[34155] = {id=34155,name="Treasure: Gorgrond Treasure 06",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6721,mapID=543,questType="standard"},
[34157] = {id=34157,name="Into the Heart of Madness",level=20,requiredLevel=20,faction="alliance",expansion=5,zoneID=6662,description=", Nyami ran off to 'take down Teron'gor herself.' You need to find her. She has no chance against him on her own. I must remain here and organize our ranks should another attack fall upon us. I'm counting on you.",starts={{npcID=75392,x=0.43,y=0.76,zoneID=6662}},ends={{npcID=77582,x=0.312,y=0.736,zoneID=6662}},coords={x=0.43,y=0.76,source="quest_giver",zoneID=6662},questType="standard"},
[34160] = {id=34160,name="Vignette: Nixxie the Goblin",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6721,mapID=543,questType="standard"},
[34162] = {id=34162,name="Vignette: Icklarv",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6721,mapID=543,questType="standard"},
[34163] = {id=34163,name="Hiding in the Shadows",level=20,requiredLevel=20,faction="both",expansion=5,zoneID=6662,description="Our final move must remain concealed from the Auchenai, my minions. Use the shadow orbs Gul'dan provided for us to veil Gul'rok in darkness. Prepare our forces, we march on Auchindoun on my order. We will feast on the souls of the draenei and usher our demonic allies into this world! shadow orbs would help the defenders at Auchindoun greatly.>",starts={{npcID=227737,x=0.373,y=0.794,zoneID=6662}},coords={x=0.373,y=0.794,source="quest_giver",zoneID=6662},questType="standard"},
[34164] = {id=34164,name="Book Burning",level=20,requiredLevel=20,faction="both",expansion=5,zoneID=6662,description="Please, ... I don't have much time. The Shadow Council have allowed themselves to be turned into demons by Teron'gor and his warlocks! I have reason to believe that the shadowborne dementors are using spells given to them by Gul'dan to empower the demonic orcs. Take their spellbooks and cast them into the fire by me... it will be a pleasant sight to die to.",starts={{npcID=77629,x=0.34,y=0.74,zoneID=6662}},ends={{npcID=77629,x=0.34,y=0.74,zoneID=6662}},coords={x=0.34,y=0.74,source="quest_giver",zoneID=6662},questType="standard"},
