[34192] = {id=34192,name="Things Are Not Goren Our Way",level=15,requiredLevel=15,faction="alliance",expansion=5,zoneID=7004,description="The abandoned mine shaft has been overrun with goren! They seem to be responding to commands from a big one farther down in the mine. If you can take him out, the rest will probably retreat. Once you have those goren cleared out, we can get that mine up and working!",questType="standard"},
[34193] = {id=34193,name="Clearing the Garden",level=30,requiredLevel=30,faction="horde",expansion=5,zoneID=7004,description="This cave is the perfect climate to grow herbs for our Garrison, there is just one little problem. All these damn nibblers! I need you to clear them out and we can get this garden growing.",starts={{npcID=81981,x=0.438,y=0.83,zoneID=7004}},ends={{npcID=81981,x=0.438,y=0.83,zoneID=7004}},coords={x=0.438,y=0.83,source="quest_giver",zoneID=7004},questType="standard"},
[34194] = {id=34194,name="Looking For Help",level=20,requiredLevel=20,faction="alliance",expansion=5,zoneID=6719,description="We have an accessible fishing spot here, but no bait seems to work! We need to find a local fisherman with some knowledge of the area to help us out. Head northwest and see if you can find anyone on the shoreline.",starts={{npcID=77733,x=0.54,y=0.134,zoneID=7078}},ends={{npcID=84372,x=0.27,y=0.066,zoneID=6719}},coords={x=0.54,y=0.134,source="quest_giver",zoneID=7078},questType="standard"},
