[34209] = {id=34209,name="Vouchsafe Our Arrival",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=6720,description="A matter of great importance has arisen. While you were away, Archmage Khadgar contacted me. He is investigating demonic influences to the north. Being a human, the Frostwolves will not accept Khadgar without you there to vouch for him, nor will they accept a night elf such as myself. I will wait for you outside Throm'var in the Frostwind Crag.",starts={{npcID=79252,x=0.494,y=0.37,zoneID=7004}},ends={{npcID=72814,x=0.314,y=0.162,zoneID=6720}},coords={x=0.494,y=0.37,source="quest_giver",zoneID=7004},questType="standard"},
[34210] = {id=34210,name="Treasure: Gorgrond Treasure 19",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6721,mapID=543,questType="standard"},
[34211] = {id=34211,name="Treasure: Gorgrond Treasure 20",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6721,mapID=543,questType="standard"},
[34213] = {id=34213,name="They Have My Son",level=40,requiredLevel=40,faction="alliance",expansion=5,description="Please, $p! Can you help me. I received a ransom note from a very corrupt and uncouth orc within the ranks of the Iron Horde. He has my son! He made sure to include a number of graphic words to describe what would happen if the ransom is not paid. Clearly he thinks my people conjure gold from the nether. And if I try to rescue him myself, both of us will be killed in the process. Can you go to Gron'mar for me and rescue my son? His name is Corki .",questType="standard"},
[34214] = {id=34214,name="Treasure: Gorgrond Treasure 21",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6721,mapID=543,questType="standard"},
[34215] = {id=34215,name="Treasure: Gorgrond Treasure 22",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6721,mapID=543,questType="standard"},
[34216] = {id=34216,name="Safe Passage",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=6720,description="Being a human and a night elf, the archmage and I aren't likely to be well-received by the orcs of the Frostwolf clan. We need you to make an introduction for us with the Throm'var farseer. There is much to discuss. Shall I bring you up to speed on the way to the village?",starts={{npcID=72814,x=0.314,y=0.162,zoneID=6720}},ends={{npcID=72837,x=0.318,y=0.118,zoneID=6720}},coords={x=0.314,y=0.162,source="quest_giver",zoneID=6720},questType="standard"},
[34217] = {id=34217,name="Smash Blon'sky!",level=40,requiredLevel=40,faction="none",expansion=5,description="Grulk not choose to be mutated. Grulk not monster like Blon'sky ! Blon'sky evil... chose mutation for power! You go to Grommar? Smash Blon'sky before he hurt innocents, make Grulk happy!",questType="standard"},
