[34544] = {id=34544,name="Spires of Arak Challenge Mode - Gold Addition (Nth)",level=40,requiredLevel=40,faction="none",expansion=5,questType="standard"},
[34556] = {id=34556,name="Upper Blackrock Spire Challenge Mode - Gold Addition (Nth)",level=40,requiredLevel=40,faction="none",expansion=5,questType="standard"},
[34557] = {id=34557,name="Tracking Quest: Treasure Map",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6720,mapID=525,questType="standard"},
[34558] = {id=34558,name="At Your Command",level=20,requiredLevel=20,faction="alliance",expansion=5,zoneID=6662,description="I'm glad you're here! Fort Wrynn is nearly complete. We only need to fill this last plot. Baros provided us with blueprints for two different structures that would fit this space - an Artillery Tower or an Arcane Sanctum. It's your call, commander. The plans are on the drafting table for your perusal.",starts={{npcID=79133,x=0.698,y=0.208,zoneID=6662}},ends={{npcID=79133,x=0.698,y=0.208,zoneID=6662}},coords={x=0.698,y=0.208,source="quest_giver",zoneID=6662},questType="standard"},
[34559] = {id=34559,name="Vignette: Yaga the Scarred",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6720,mapID=525,description="Goren are dangerous, especially in large numbers, and especially when we have a blind, under powered shaman with us. Fortunately, they have very short lifespans. Unfortunately, they multiply fast and grow faster. If we are going to do this we need to find the brood mother. Slaying her and her eggs should slow down the onslaught of goren. Check the burrows near the Forge Gates and I will to keep them off of Drek'Thar's scent.",questType="standard"},
[34560] = {id=34560,name="Armory",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6662,mapID=535,questType="standard"},
[34561] = {id=34561,name="Mage Tower",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6662,mapID=535,questType="standard"},
[34562] = {id=34562,name="Trigger Teron'gor Defense Spawns",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6662,mapID=535,questType="standard"},
[34563] = {id=34563,name="The Quarry Quandary",level=20,requiredLevel=20,faction="alliance",expansion=5,zoneID=6662,description="Now that we have the artillery tower built, we're going to need some skilled hands to run it. I've heard that Ared, one of the best smiths in Shattrath, managed to escape the city's fall. He should be just outside the north wall with the rest of the refugees. See if you can convince him to work for us.",starts={{npcID=79133,x=0.698,y=0.208,zoneID=6662}},ends={{npcID=79159,x=0.692,y=0.192,zoneID=6662}},coords={x=0.698,y=0.208,source="quest_giver",zoneID=6662},questType="standard"},
[34564] = {id=34564,name="Destination: Unknown",level=20,requiredLevel=20,faction="horde",expansion=5,zoneID=8485,description="Teron'gor and Gul'dan were just leaving through the portal as I arrived... and I... I know I won't be able to defeat them. I'll hold open the portal as long as I can. It will be up to you to strike the killing blow. Our fate is in your hands, .",starts={{npcID=77582,x=0.312,y=0.736,zoneID=6662}},ends={{npcID=79434,x=0.462,y=0.74,zoneID=6662}},coords={x=0.312,y=0.736,source="quest_giver",zoneID=6662},questType="standard"},
[34566] = {id=34566,name="At Your Command",level=20,requiredLevel=20,faction="horde",expansion=5,zoneID=6662,description="Commander, the outpost is nearly fully operational. Gazlowe provided us with two different blueprints to fill this final plot - an Arsenal or an Arcane Sanctum. Either one would provide us with the additional firepower we need to stop the Iron Horde's advance. The plans are on the drafting table . It's your call.",starts={{npcID=79176,x=0.71,y=0.298,zoneID=6662}},ends={{npcID=79176,x=0.71,y=0.298,zoneID=6662}},coords={x=0.71,y=0.298,source="quest_giver",zoneID=6662},questType="standard"},
[34567] = {id=34567,name="Mage Tower",level=1,requiredLevel=1,faction="horde",expansion=5,zoneID=6662,mapID=535,questType="standard"},
[34568] = {id=34568,name="Armory",level=1,requiredLevel=1,faction="horde",expansion=5,zoneID=6662,mapID=535,questType="standard"},
[34569] = {id=34569,name="The Quarry Quandary",level=20,requiredLevel=20,faction="horde",expansion=5,zoneID=6662,description="Now that our arsenal is built we need a skilled smith to operate it. We recently caught an Iron Horde deserter who claims he used to be one of the Blackrock's best iron workers. Normally I'd ignore the ravings of a captive, but the weapons we took out of his pack had the finest workmanship I've ever seen. Commander, I think we should see if he's as good as he claims.",starts={{npcID=79176,x=0.71,y=0.298,zoneID=6662}},ends={{npcID=79210,x=0.718,y=0.294,zoneID=6662}},coords={x=0.71,y=0.298,source="quest_giver",zoneID=6662},questType="standard"},
[34571] = {id=34571,name="Out of Jovite",level=20,requiredLevel=20,faction="alliance",expansion=5,zoneID=6662,description="Ared and I came this way because we needed a good supply of metal to build his designs and some of the best metal is the jovite that comes from the mine in Kuuro's Claim. In order to supply the artillery tower I'm going to need this metal. Unfortunately that place was recently overwhelmed by a pack of goren, so you're going to have to fight your way in to get the ore before they manage to devour it. Nothing that should be too much of a problem for you.",starts={{npcID=79329,x=0.7,y=0.2,zoneID=6662}},ends={{npcID=79329,x=0.7,y=0.2,zoneID=6662}},coords={x=0.7,y=0.2,source="quest_giver",zoneID=6662},questType="standard"},
[34572] = {id=34572,name="Obliterating Ogres",level=35,requiredLevel=35,faction="alliance",expansion=5,zoneID=6755,description="With actual ogre mages present, the Highmaul have been increasing patrols and aggression. Thinning their ranks will go a long way to deterring the Highmaul from making a comeback in Nagrand . Head up to my sister Mirana afterwards, she should have more news.",starts={{npcID=79282,x=0.788,y=0.692,zoneID=6755}},ends={{npcID=81144,x=0.84,y=0.768,zoneID=6755}},coords={x=0.788,y=0.692,source="quest_giver",zoneID=6755},questType="standard"},
[34573] = {id=34573,name="Iridium Recovery",level=20,requiredLevel=20,faction="alliance",expansion=5,zoneID=6662,description="Ared used to always teach me that the purity of the metal is key. If the metal isn't pure it will crack under stress and be of no use to anyone. For the artillery tower to function I'll need to make metal as pure as my master would, and for that I need a strong flux. The dust from crushed iridium geodes would work in a pinch, but we need to find some first. They tend to congregate underground, so check out the mine in Kuuro's Claim nearby.",starts={{npcID=79329,x=0.7,y=0.2,zoneID=6662}},ends={{npcID=79329,x=0.7,y=0.2,zoneID=6662}},coords={x=0.7,y=0.2,source="quest_giver",zoneID=6662},questType="standard"},
[34575] = {id=34575,name="Step Three: Prophet!",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=6719,description="You have arrived in Shadowmoon Valley . It is time to speak with the prophet.",ends={{npcID=79206,x=0.27,y=0.08,zoneID=6719}},questType="standard"},
[34576] = {id=34576,name="Iridium Recovery",level=20,requiredLevel=20,faction="horde",expansion=5,zoneID=6662,description="My goods used to be for the very best, now the Iron Horde make copies out of poor metal and give them to everyone. I'm going to show them what a real smith can do in your arsenal, but first I'm going to need a powerful flux to make the metal as pure as it can get. The dust from crushed iridium geodes would work in a pinch but we need to find some first. They tend to congregate underground, so check out the mine in Kuuro's Claim nearby.",starts={{npcID=79356,x=0.708,y=0.304,zoneID=6662}},ends={{npcID=79356,x=0.708,y=0.304,zoneID=6662}},coords={x=0.708,y=0.304,source="quest_giver",zoneID=6662},questType="standard"},
[34577] = {id=34577,name="Out of Jovite",level=20,requiredLevel=20,faction="horde",expansion=5,zoneID=6662,description="Crafting good equipment requires the best metal and some of the best metal is the jovite that comes from the mine in Kuuro's Claim, just east of here. In order to supply the arsenal I'm going to need this metal. Unfortunately the place was recently overwhelmed by a pack of goren so you're going to have to fight your way in to get the ore before they manage to devour it. Nothing that should be too much of a problem for you, .",starts={{npcID=79356,x=0.708,y=0.304,zoneID=6662}},ends={{npcID=79356,x=0.708,y=0.304,zoneID=6662}},coords={x=0.708,y=0.304,source="quest_giver",zoneID=6662},questType="standard"},
[34578] = {id=34578,name="Going to the Gordunni",level=20,requiredLevel=20,faction="alliance",expansion=5,zoneID=6662,description="We have a good supply of jovite now but there just isn't enough of the material in the mine to keep the artillery tower in stock for long. Down south of here there's a mountain that's just full of the stuff but there's one problem; Ogres! The Gordunni live on top of that mountain and they have begun trading the jovite to the Iron Horde. We need to go down there and secure the minerals for ourselves. I'll pack some supplies and meet you near their fortress down south.",starts={{npcID=79329,x=0.7,y=0.2,zoneID=6662}},ends={{npcID=80627,x=0.624,y=0.678,zoneID=6662}},coords={x=0.7,y=0.2,source="quest_giver",zoneID=6662},questType="standard"},
[34579] = {id=34579,name="Gas Guzzlers",level=20,requiredLevel=20,faction="horde",expansion=5,zoneID=6662,description=", to make the best equipment for your arsenal I need not only the best materials, but to use the best techniques. Over the years I've developed a method to greatly strengthen my metal, but it does require an exotic resource: goren gut gas! The nearby mine at Kuuro's Claim just came down with an infestation of the things. Could you collect a few samples for the arsenal supplies? Just kill a few goren and give their bodies a good prod with this gas extractor.",starts={{npcID=79356,x=0.708,y=0.304,zoneID=6662}},ends={{npcID=79356,x=0.708,y=0.304,zoneID=6662}},coords={x=0.708,y=0.304,source="quest_giver",zoneID=6662},questType="standard"},
[34580] = {id=34580,name="Draenor Flowerpicker",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6662,mapID=535,questType="standard"},
[34581] = {id=34581,name="Draenor Flowerpicker Note Found",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6662,mapID=535,questType="standard"},
[34582] = {id=34582,name="Finding a Foothold",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=7078,description="So, you are the one that has led my children home? I have been waiting for you. The Iron Horde grows stronger every day. I have foreseen a great battle, but my visions are clouded. It's as if time is sitting on top of itself. One thing is certain, your presence here is of great importance.",starts={{npcID=79206,x=0.27,y=0.08,zoneID=6719}},ends={{npcID=79470,x=0.288,y=0.162,zoneID=6719},{npcID=79470,x=0.306,y=0.344,zoneID=7078}},coords={x=0.27,y=0.08,source="quest_giver",zoneID=6719},questType="standard"},
[34583] = {id=34583,name="For the Alliance!",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=7078,description="We wouldn't have survived Tanaan without your strength, . Many draenei and Alliance alike owe you a great debt. Before we departed for the Dark Portal, King Wrynn personally recommended that I place you in charge of our operations here in Draenor. After seeing you in action, I'm inclined to agree. This is your garrison to found. Plant the banner and we'll begin construction immediately, commander.",starts={{npcID=79470,x=0.288,y=0.162,zoneID=6719},{npcID=79470,x=0.306,y=0.344,zoneID=7078}},ends={{npcID=79243,x=0.29,y=0.162,zoneID=6719},{npcID=79243,x=0.324,y=0.342,zoneID=7078}},coords={x=0.288,y=0.162,source="quest_giver",zoneID=6719},questType="standard"},
[34584] = {id=34584,name="Looking for Lumber",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=7004,description="Some of the trees around here look small enough that the workers should be able to down them in no time. We can leave the hard labor to Shelly's men, but if you'd be willing to mark the trees for them to start with, we should be able to get this operation rolling much faster.",starts={{npcID=79243,x=0.29,y=0.162,zoneID=6719},{npcID=79243,x=0.324,y=0.342,zoneID=7078}},ends={{npcID=79243,x=0.29,y=0.162,zoneID=6719},{npcID=79243,x=0.324,y=0.342,zoneID=7078}},coords={x=0.29,y=0.162,source="quest_giver",zoneID=6719},questType="standard"},
[34585] = {id=34585,name="Quakefist",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=7078,description="I'm getting reports of a giant in the forest. A few of the Karabor peacekeepers have followed it to a cave. In all honesty I don't think any of our troops are willing to engage the beast. Maybe you could investigate? I'm sure the peacekeepers would appreciate the help.",starts={{npcID=79567,x=0.288,y=0.164,zoneID=6719},{npcID=79567,x=0.316,y=0.354,zoneID=7078}},ends={{npcID=79567,x=0.288,y=0.164,zoneID=6719},{npcID=79567,x=0.316,y=0.354,zoneID=7078}},coords={x=0.288,y=0.164,source="quest_giver",zoneID=6719},questType="standard"},
[34586] = {id=34586,name="Establish Your Garrison",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=7078,description="I'm impressed with how quickly you have pulled this group together, commander. I think it's time we start putting up some walls and establishing a firm perimeter around our base.",starts={{npcID=79243,x=0.29,y=0.162,zoneID=6719},{npcID=79243,x=0.324,y=0.342,zoneID=7078}},ends={{npcID=77209,x=0.32,y=0.314,zoneID=7078}},coords={x=0.29,y=0.162,source="quest_giver",zoneID=6719},questType="standard"},
[34587] = {id=34587,name="Build Your Barracks",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=7078,description="I must say, commander, this garrison has really come along. We have enough materials, all we need now are the blueprints I drafted up and I can begin construction on your barracks. Hmm... now where did I put those blueprints?",starts={{npcID=77209,x=0.32,y=0.314,zoneID=7078}},ends={{npcID=79457,x=0.44,y=0.528,zoneID=7078}},coords={x=0.32,y=0.314,source="quest_giver",zoneID=7078},questType="standard"},
[34588] = {id=34588,name="The Bounty of Bladespire",level=1,requiredLevel=1,faction="none",expansion=5,zoneID=6720,mapID=525,description="The sacking of this fortress is as much your victory as ours. It is only fair you should share in the bounty. I will have resources set aside as we find them. All you need do is report to your garrison and have them dispatch peons to collect these materials.",questType="standard"},
[34592] = {id=34592,name="A Gronnling Problem",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=7004,description="It's gonna be quite a task to build you a fortress if there's gronnlings rampaging around. I don't think anyone else here can handle taking those big beasts out, so you might need to take care of it yourself.",starts={{npcID=78466,x=0.488,y=0.65,zoneID=6720},{npcID=78466,x=0.42,y=0.55,zoneID=7004}},ends={{npcID=78466,x=0.488,y=0.65,zoneID=6720},{npcID=78466,x=0.42,y=0.55,zoneID=7004}},coords={x=0.488,y=0.65,source="quest_giver",zoneID=6720},questType="standard"},
[34593] = {id=34593,name="Obtaining Ogre Offensive Orders",level=35,requiredLevel=35,faction="alliance",expansion=5,zoneID=6755,description="My sister, Mirana, is scouting the upper bluff while I've checked out the lower area. There are two particular ogre mages that do a lot of bossing around in the lower area. They seem to have some orders or scrolls on them that would help us figure out what's really going on. Collect that information and meet with my sister on the long stairway up there.",starts={{npcID=79282,x=0.788,y=0.692,zoneID=6755}},ends={{npcID=81144,x=0.84,y=0.768,zoneID=6755}},coords={x=0.788,y=0.692,source="quest_giver",zoneID=6755},questType="standard"},
[34596] = {id=34596,name="Reglakk's Research",level=35,requiredLevel=35,faction="alliance",expansion=5,zoneID=6755,description="These ogres have been using ancient Titan artifacts to empower a small cadre of specialized units called the Breakers. This Magister Reglakk is here studying ways to improve the process. Let's put a stop to whatever rituals he has going up on the bluff.",starts={{npcID=81144,x=0.84,y=0.768,zoneID=6755}},ends={{npcID=79576,x=0.634,y=0.618,zoneID=6755}},coords={x=0.84,y=0.768,source="quest_giver",zoneID=6755},questType="standard"},
[34597] = {id=34597,name="Removing the Paper Trail",level=35,requiredLevel=35,faction="alliance",expansion=5,zoneID=6755,description="This box is filled with writings and diagrams that oddly resemble research into the nullification of magic. It would be best to ruin these efforts by destroying any research found.",starts={{npcID=231901,x=0.813,y=0.703,zoneID=6755}},ends={{npcID=81144,x=0.84,y=0.768,zoneID=6755}},coords={x=0.813,y=0.703,source="quest_giver",zoneID=6755},questType="standard"},
[34598] = {id=34598,name="The Missing Caravan",level=35,requiredLevel=35,faction="both",expansion=5,zoneID=6755,description="I've got a problem and you look like you're just the for the job! A trade shipment was supposed to arrive yesterday, but it's nowhere to be found. I'm running low on merchandise here and I need somebody to go find out what happened! If I were to guess, I'd say the saberon are probably involved. Those brutes have been a pain in our side ever since we got here! Search for the wagon on the road near Sabermaw and hurry! Time is money!",starts={{npcID=79310,x=0.786,y=0.484,zoneID=6755}},ends={{npcID=79312,x=0.79,y=0.588,zoneID=6755}},coords={x=0.786,y=0.484,source="quest_giver",zoneID=6755},questType="standard"},
[34599] = {id=34599,name="Tracking Quest: Saw Yrel Leave Twilight Glade",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6719,mapID=539,questType="standard"},
[34600] = {id=34600,name="Tracking Quest: Saw Vorka, Rangari Leave",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6719,mapID=539,questType="standard"},
[34609] = {id=34609,name="Creating the Ink",level=20,requiredLevel=20,faction="alliance",expansion=5,zoneID=6662,description="We need a way to create an artificial nexus at your tower. I know where we can get the conduit to do that, but it's well-guarded. We need to keep our cool and do this the right way. I have a plan - a scroll of mass teleportation. The fungal giants and shamblers down below are covered with pustules full of an oily substance. We can use the oil to craft a makeshift ink substitute for the scroll.",starts={{npcID=79392,x=0.848,y=0.31,zoneID=6662}},ends={{npcID=80260,x=0.849,y=0.309,zoneID=6662}},coords={x=0.848,y=0.31,source="quest_giver",zoneID=6662},questType="standard"},
[34612] = {id=34612,name="Forming the Scroll",level=20,requiredLevel=20,faction="alliance",expansion=5,zoneID=6662,description="We'll need arcane parchment to make the scroll. The arcane energy everywhere at this nexus froze the ancients in place and settled in their bark. If we take pieces from the few that haven't been destroyed by the fungal creatures, I can mold them into parchment.",starts={{npcID=79392,x=0.848,y=0.31,zoneID=6662},{npcID=80260,x=0.849,y=0.309,zoneID=6662}},ends={{npcID=80260,x=0.849,y=0.309,zoneID=6662}},coords={x=0.848,y=0.31,source="quest_giver",zoneID=6662},questType="standard"},
[34616] = {id=34616,name="Ravenous Ravens",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=7078,description="Do you see that? There is a gigantic raven just past the tree line. I'm not getting anywhere near that. In fact, I'm not sure any of the men are sufficiently equipped to deal with a threat like that. Do you want to handle this one yourself, commander? Once those ravens are gone we can start sending more troops into the woods. So we will be killing two birds with one stone... or should I say kill five birds with... You get the point.",starts={{npcID=79243,x=0.29,y=0.162,zoneID=6719},{npcID=79243,x=0.324,y=0.342,zoneID=7078}},ends={{npcID=79243,x=0.29,y=0.162,zoneID=6719},{npcID=79243,x=0.324,y=0.342,zoneID=7078}},coords={x=0.29,y=0.162,source="quest_giver",zoneID=6719},questType="standard"},
[34619] = {id=34619,name="Gathering the Spark",level=20,requiredLevel=20,faction="alliance",expansion=5,zoneID=6662,description="We need arcane energy to complete our scroll. It needs that to coalesce the scroll together. I have an artifact that can capture energy vortexes in the caldera below, so let's get moving.",starts={{npcID=79392,x=0.848,y=0.31,zoneID=6662}},ends={{npcID=80260,x=0.849,y=0.309,zoneID=6662}},coords={x=0.848,y=0.31,source="quest_giver",zoneID=6662},questType="standard"},
[34622] = {id=34622,name="Tracking Quest: Saw Ner'zhul Leave",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6719,mapID=539,questType="standard"},
[34624] = {id=34624,name="Gas Guzzlers",level=20,requiredLevel=20,faction="alliance",expansion=5,zoneID=6662,description="To complete my master's designs and to stock up the artillery tower we need to use an exotic resource, namely goren gut gas. The nearby mine at Kuuro's Claim just came down with an infestation of the things. Could you collect a few samples for me? The stuff is concentrated, so only a few are needed. Just kill one and give its body a good prod with this gas extractor.",starts={{npcID=79329,x=0.7,y=0.2,zoneID=6662}},ends={{npcID=79329,x=0.7,y=0.2,zoneID=6662}},coords={x=0.7,y=0.2,source="quest_giver",zoneID=6662},questType="standard"},
[34631] = {id=34631,name="An Audience With The Archmage",level=20,requiredLevel=20,faction="alliance",expansion=5,zoneID=6662,description="I'm pleased to report that your Arcane Sanctum is up and running, commander! Everything is exactly as the blueprint says... except for this note Baros scrawled on the bottom. \"Don't forget to connect the sanctum to the ley line network!\" Commander, I'm a foreman, not a mage. I... have absolutely no idea how to do that. We've found Archmage Khadgar and some other Kirin Tor not far from here. To the east, near the mountains. Perhaps we should ask them for a hand?",starts={{npcID=79133,x=0.698,y=0.208,zoneID=6662}},ends={{npcID=80142,x=0.75,y=0.31,zoneID=6662}},coords={x=0.698,y=0.208,source="quest_giver",zoneID=6662},questType="standard"},
[34632] = {id=34632,name="An Audience With The Archmage",level=20,requiredLevel=20,faction="horde",expansion=5,zoneID=6662,description="Your Arcane Sanctum is coming along nicely, commander. Everything's built to spec... except for one detail Gazlowe scrawled in at the bottom of the blueprint. \"Don't forget to connect the sanctum to the ley line network!\" I, uh... I have no idea how to do that. I'm sorry commander, but magic just isn't my thing. We did spot Archmage Khadgar and some Kirin Tor not far from here. To the east, up near the mountains. Maybe we should ask them for help?",starts={{npcID=79176,x=0.71,y=0.298,zoneID=6662}},ends={{npcID=80142,x=0.75,y=0.31,zoneID=6662}},coords={x=0.71,y=0.298,source="quest_giver",zoneID=6662},questType="standard"},
[34634] = {id=34634,name="Creating the Ink",level=20,requiredLevel=20,faction="horde",expansion=5,zoneID=6662,description="We're going to need a way to create an artificial nexus at your tower. I know where we can get what we need, but it's heavily protected. We don't have the firepower to just waltz in the front door. I have a plan - a scroll of mass teleportation. The fungal giants and spore creatures down below are covered in pustules filled with an oily substance. If we gather enough of the oil I can craft a makeshift ink substitute for the scroll.",starts={{npcID=79393,x=0.842,y=0.304,zoneID=6662},{npcID=80193,x=0.841,y=0.302,zoneID=6662}},ends={{npcID=80193,x=0.841,y=0.302,zoneID=6662}},coords={x=0.842,y=0.304,source="quest_giver",zoneID=6662},questType="standard"},
[34635] = {id=34635,name="Forming the Scroll",level=20,requiredLevel=20,faction="horde",expansion=5,zoneID=6662,description="For this plan to work, we'll need infused parchment. The latent arcane energy at this nexus quickly froze the ancients in place and settled in their bark. If we rip off strips from the few that haven't been destroyed by the fungal creatures, I can form them into parchment.",starts={{npcID=79393,x=0.842,y=0.304,zoneID=6662},{npcID=80193,x=0.841,y=0.302,zoneID=6662}},ends={{npcID=80193,x=0.841,y=0.302,zoneID=6662}},coords={x=0.842,y=0.304,source="quest_giver",zoneID=6662},questType="standard"},
[34636] = {id=34636,name="Gathering the Spark",level=20,requiredLevel=20,faction="horde",expansion=5,zoneID=6662,description="We need to get our hands on arcane energy to complete our scroll. It needs that fiery kick. I have a device capable of capturing energy in the space below, so let's get moving. The infused creatures shouldn't be an issue for the two of us.",starts={{npcID=79393,x=0.842,y=0.304,zoneID=6662}},ends={{npcID=80193,x=0.841,y=0.302,zoneID=6662}},coords={x=0.842,y=0.304,source="quest_giver",zoneID=6662},questType="standard"},
[34641] = {id=34641,name="Vignette/Treasure: Waterlogged Journal",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6720,mapID=525,ends={{npcID=230401,x=0.098,y=0.454,mapID=525}},questType="standard"},
[34642] = {id=34642,name="Vignette/Treasure: Lucky Coin",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6720,mapID=525,ends={{npcID=230402,x=0.192,y=0.12,mapID=525}},questType="standard"},
[34645] = {id=34645,name="Vignette: Warmaster Blugthol",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6755,mapID=550,questType="standard"},
[34646] = {id=34646,name="Qiana Moonshadow",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=6719,description="If we are to win this war we are going to need more than foot soldiers. We need champions. Qiana Moonshadow 's performance in Tanaan and Eventide Landing was quite impressive. Perhaps you should speak with her about taking on a greater role in the battle against the Iron Horde.",starts={{npcID=79457,x=0.44,y=0.528,zoneID=7078}},ends={{npcID=81948,x=0.408,y=0.536,zoneID=7078}},coords={x=0.44,y=0.528,source="quest_giver",zoneID=7078},questType="standard"},
[34647] = {id=34647,name="Vignette/Treasure: Snow-Covered Strongbox",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6720,mapID=525,ends={{npcID=230424,x=0.24,y=0.13,mapID=525}},questType="standard"},
[34648] = {id=34648,name="Vignette/Treasure: Gnawed Bone",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6720,mapID=525,ends={{npcID=230425,x=0.255,y=0.204,mapID=525}},questType="standard"},
[34649] = {id=34649,name="Vignette/Treasure: Smoldering True Iron Deposit",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6720,mapID=525,questType="standard"},
[34652] = {id=34652,name="Vignette/Treasure: Savage Clam",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6720,mapID=525,questType="standard"},
[34653] = {id=34653,name="Arakkoa Exodus",level=30,requiredLevel=30,faction="both",expansion=5,zoneID=6722,mapID=542,description="I assume you're familiar with the arakkoa, commander? Great, flying birdfolk. Extremely territorial. Some, however, have withered wings - a disease, maybe. They seem to be outcast from arakkoa society. You find them now and then, squatting in forgotten ruins or peddling trinkets on the roadside. It seems the Iron Horde has incited the arakkoa by moving into their lands, and the outcasts are fleeing in droves. We should make contact with these outcasts - they could have valuable information.",starts={{npcID=78487,x=0.456,y=0.432,mapID=525},{npcID=81492,x=0.378,y=0.368,mapID=539}},ends={{npcID=79539,x=0.378,y=0.18,mapID=542}},coords={x=0.456,y=0.432,source="quest_giver",mapID=542},questType="standard"},
[34655] = {id=34655,name="The Shadows of Skettis",level=30,requiredLevel=30,faction="both",expansion=5,zoneID=6722,description="My people flee our homeland in droves. I sell trinkets to ease the journey. But I see that you are not interested in trinkets... No, what you seek are answers. Skettis lies just ahead. Once a great city built by Terokk as a refuge for the unwanted. Now a ruined slum. An old storyteller lives there - a scrollkeeper named Reshad . Find him and speak these words: \"Shadows gather.\" He will know you are a friend. Now go. Your presence is bad for business.",starts={{npcID=79539,x=0.378,y=0.18,zoneID=6722}},ends={{npcID=79519,x=0.436,y=0.13,zoneID=6722}},coords={x=0.378,y=0.18,source="quest_giver",zoneID=6722},questType="standard"},
[34656] = {id=34656,name="Hidden in Plain Sight",level=30,requiredLevel=30,faction="both",expansion=5,zoneID=6722,description="Reshad begins hastily stuffing scrolls into his robes.> I thought I would have more time to prepare! There are powerful relics hidden out there in Skettis - if I leave without them, I may as well have died. The first is a pair of wingblades being held by an effigy near the front gate. You likely walked right past them on your way in. Another effigy on the east side of the ruins bears a white mask over its face. Bring those relics to me, and their secrets shall be yours.",starts={{npcID=79519,x=0.436,y=0.13,zoneID=6722}},ends={{npcID=79519,x=0.436,y=0.13,zoneID=6722}},coords={x=0.436,y=0.13,source="quest_giver",zoneID=6722},questType="standard"},
[34657] = {id=34657,name="Adherents of the Sun God",level=30,requiredLevel=30,faction="both",expansion=5,zoneID=6722,description="The arakkoa from Skyreach are all ruled by the Adherents of Rukhmar. They revile those of us who bear the Curse of Sethe, and decree that we must be purged in the name of their sun god. Soon their gaze will turn to lands beyond Arak. Challenge their warriors. Buy me time to prepare my escape, and help me set into motion their downfall.",starts={{npcID=79519,x=0.436,y=0.13,zoneID=6722}},ends={{npcID=79519,x=0.436,y=0.13,zoneID=6722}},coords={x=0.436,y=0.13,source="quest_giver",zoneID=6722},questType="standard"},
[34658] = {id=34658,name="Orders From On High",level=30,requiredLevel=30,faction="both",expansion=5,zoneID=6722,description="The Adherents of Rukhmar are the ruling body atop the spires. Their influence is absolute. Their proclamations taken as the will of Rukhmar Herself. The herald leading this purge is surely carrying out such orders - likely no more than a list of names and places they plan to erase. That list would prove invaluable in the days to come. Acquire it for me, and shut that herald up!",starts={{npcID=79519,x=0.436,y=0.13,zoneID=6722}},ends={{npcID=79519,x=0.436,y=0.13,zoneID=6722}},coords={x=0.436,y=0.13,source="quest_giver",zoneID=6722},questType="standard"},
[34659] = {id=34659,name="The Crone",level=30,requiredLevel=30,faction="both",expansion=5,zoneID=6722,description="Do you remember our greeting, $p? \"Shadows gather when the raven swallows the day.\" It is more than an old verse - it is a call to action. Followers of the old ways are gathering, and I must join them. You are needed, too, I should think Follow this road down to Crow's Crook. There you will find the home of an old crone. Greet her as you greeted me, and she will guide the way. You will not see me, but I will be close behind.",starts={{npcID=79519,x=0.436,y=0.13,zoneID=6722}},ends={{npcID=79890,x=0.516,y=0.312,zoneID=6722}},coords={x=0.436,y=0.13,source="quest_giver",zoneID=6722},questType="standard"},
[34662] = {id=34662,name="Ring of Trials: Crushmaul",level=35,requiredLevel=35,faction="both",expansion=5,zoneID=6755,description="So you want to fight in the Ring of Trials do you? It's your funeral, bub! Your first fight is against an exceptionally large and angry ogre named Crushmaul . That's not all though, you'll have to take out his armored boar companion too; Crushmaul never goes into the ring without him! I hope your affairs are in order, because the last gladiator that fought Crushmaul went home in a body bag... I'm counting on you! Get your ass inside the arena and speak with my associate Guzrug to start the fight!",starts={{npcID=79188,x=0.794,y=0.502,zoneID=6755}},ends={{npcID=79188,x=0.794,y=0.502,zoneID=6755}},coords={x=0.794,y=0.502,source="quest_giver",zoneID=6755},questType="standard"},
[34663] = {id=34663,name="Ring of Trials: Raketalon",level=35,requiredLevel=35,faction="both",expansion=5,zoneID=6755,description="You may have defeated Crushmaul, but the party's over now...you've got another fight! The Highmaul take gladiatin' seriously; so when they built the Ring of Trials, they searched far and wide for the most brutal creatures they could find! You're up against a dread raven the ogres are calling Raketalon ! I'm telling you, , something about that bird just ain't right...I think it truly enjoys the act of killing! Raketalon toyed with the last gladiator for hours before eating him. Try not to die!",starts={{npcID=79188,x=0.794,y=0.502,zoneID=6755}},ends={{npcID=79188,x=0.794,y=0.502,zoneID=6755}},coords={x=0.794,y=0.502,source="quest_giver",zoneID=6755},questType="standard"},
[34664] = {id=34664,name="Ring of Trials: Hol'yelaa",level=35,requiredLevel=35,faction="both",expansion=5,zoneID=6755,description="You won your first two fights, but it's only going to get tougher from here! Your next fight is against Hol'yelaa , a former rangari who is as crazy as they come. No, really... Hol'yelaa is bonkers! Years ago, while on a scouting mission, he single handedly saved his entire rangari unit from a pack of Garn. But something inside of him snapped.... It wasn't long before Hol'yelaa went completely marbles and turned on his own unit! Alright, the pep talk is over! Get in there and kick some ass!",starts={{npcID=79188,x=0.794,y=0.502,zoneID=6755}},ends={{npcID=79188,x=0.794,y=0.502,zoneID=6755}},coords={x=0.794,y=0.502,source="quest_giver",zoneID=6755},questType="standard"},
[34665] = {id=34665,name="Ring of Trials: Captain Boomspark",level=35,requiredLevel=35,faction="both",expansion=5,zoneID=6755,description="You've been making a name for yourself in the arena, ! Don't get too excited though...fame has its consequences! You've been challenged by an up-and-coming gladiator who is looking to make a name for himself, sound familiar? Your next fight is against Captain Boomspark, a mercenary who came here to fight for the Iron Horde. The Iron Horde ain't exactly throwing piles of gold around, so now he's here! He's got a shredder, so watch out for the blades... and the fire too... especially the fire!",starts={{npcID=79188,x=0.794,y=0.502,zoneID=6755}},ends={{npcID=79188,x=0.794,y=0.502,zoneID=6755}},coords={x=0.794,y=0.502,source="quest_giver",zoneID=6755},questType="standard"},
[34666] = {id=34666,name="Ring of Trials: Roakk the Zealot",level=35,requiredLevel=35,faction="both",expansion=5,zoneID=6755,description="The final match is at hand, ! You've decimated all of the best challengers! There's nowhere to go from here but the very top...the reigning champion of the Ring of Trials! The current champ is an arakkoa named Roakk the Zealot . Roakk is a lunatic! He says he's on some divine crusade for the sun or something. Crazy or not, he's one of the most dangerous fighters I've ever seen and has even fought in the Highmaul Coliseum! I'm not going to lie, you're probably going to die in there...good luck!",starts={{npcID=79188,x=0.794,y=0.502,zoneID=6755}},ends={{npcID=79188,x=0.794,y=0.502,zoneID=6755}},coords={x=0.794,y=0.502,source="quest_giver",zoneID=6755},questType="standard"},
[34668] = {id=34668,name="Vignette: Talonpriest Zorkra",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6662,mapID=535,questType="standard"},
[34671] = {id=34671,name="Vignette: Shirzir",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6662,mapID=535,questType="standard"},
[34674] = {id=34674,name="Taking the Fight to Nagrand",level=35,requiredLevel=35,faction="alliance",expansion=5,zoneID=6755,description="**Eyes Only -- Commander ** With the fall of the rangari base at Telaar, Vindicator Yrel, recommended we establish a new foothold in Nagrand . I've taken the liberty of dispatching some of our men and supplies. Rangari D'kaan's already reporting that a new outpost is nearly complete. He has indicated that they are ready to receive you. A gryphon is waiting to catch you up with the latest caravan shipment whenever you're ready, . -- Bodrick Grey, SI:7",starts={{npcID=232398,x=0.424,y=0.453,zoneID=7078},{npcID=232400,x=0.428,y=0.452,zoneID=7078}},ends={{npcID=79263,x=0.864,y=0.662,zoneID=6755}},coords={x=0.424,y=0.453,source="quest_giver",zoneID=7078},questType="standard"},
[34675] = {id=34675,name="The Might of the Warsong",level=35,requiredLevel=35,faction="alliance",expansion=5,zoneID=6755,description="The Warsong. Surprise attack. Headed... west. They took the... blueprints....",starts={{npcID=79263,x=0.864,y=0.662,zoneID=6755}},ends={{npcID=79576,x=0.634,y=0.618,zoneID=6755}},coords={x=0.864,y=0.662,source="quest_giver",zoneID=6755},questType="standard"},
[34676] = {id=34676,name="The Critical Path",level=20,requiredLevel=20,faction="alliance",expansion=5,zoneID=6662,description="The auburn forests of Talador sit at a critical crossroads of this continent, commander. The Iron Horde's fleet is already en route from Gorgrond to Shattrath on the west coast. Talador will fall if we don't reinforce them. I took the liberty of dispatching Foreman Eksos , who has already begun construction on an outpost for your forces not far from the Iron Horde landing point. He awaits your orders sir.",starts={{npcID=232397,x=0.43,y=0.45,zoneID=7078},{npcID=232400,x=0.428,y=0.452,zoneID=7078}},ends={{npcID=79133,x=0.698,y=0.208,zoneID=6662}},coords={x=0.43,y=0.45,source="quest_giver",zoneID=7078},questType="standard"},
[34677] = {id=34677,name="NOT USED",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6662,mapID=535,questType="standard"},
[34678] = {id=34678,name="Up and Running",level=35,requiredLevel=35,faction="alliance",expansion=5,zoneID=6755,description="The Warsong struck us hard. We lost Telaar, but we have a rare opportunity to strike at the heart of the Warsong. We need your wisdom and leadership to pull it off, . First though, we're going to get our survivors out of Telaar. My rangari are ready to strike. We just need to get you to them. Thaelin has a copter that can get you to them. Unfortunately, his hands are full just trying to keep the infernal thing running. Help him get it up and running?",starts={{npcID=79576,x=0.634,y=0.618,zoneID=6755}},ends={{npcID=79674,x=0.63,y=0.62,zoneID=6755}},coords={x=0.634,y=0.618,source="quest_giver",zoneID=6755},questType="standard"},
[34679] = {id=34679,name="Alliance Stables Tracking Event",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6755,mapID=550,questType="standard"},
[34680] = {id=34680,name="Alliance Workshop Tracking Event",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6755,mapID=550,questType="standard"},
[34681] = {id=34681,name="It's a Matter of Strategy",level=20,requiredLevel=20,faction="horde",expansion=5,zoneID=6662,description="Da Iron Horde have proved themselves worthy foes. They managed to get their fleet movin' to Talador from Gorgrond without my spies seein' a thing. Talador be a crossroads for the whole continent. We can't let them have it. Don't worry boss, we got a plan. Foreman Grobash be settin' up an outpost for our forces as we speak. They be ready for you when you arrive, commander.",starts={{npcID=78487,x=0.456,y=0.432,zoneID=7004}},ends={{npcID=79176,x=0.71,y=0.298,zoneID=6662}},coords={x=0.456,y=0.432,source="quest_giver",zoneID=7004},questType="standard"},
[34682] = {id=34682,name="Operation: Surprise Party",level=35,requiredLevel=35,faction="alliance",expansion=5,zoneID=6755,description="There weren't many survivors of the Warsong attack. The few remaining rangari have gone up to one of the bluffs overlooking Telaar. The rangari are waiting for you. They're planning a surprise counter-attack. My copter's taken a beating. The auto-pilot's set to take you up there. I think she's got one last trip in her. Maybe.",starts={{npcID=79674,x=0.63,y=0.62,zoneID=6755}},ends={{npcID=79722,x=0.658,y=0.686,zoneID=6755}},coords={x=0.63,y=0.62,source="quest_giver",zoneID=6755},questType="standard"},
[34683] = {id=34683,name="One Step Ahead",level=20,requiredLevel=20,faction="horde",expansion=5,zoneID=6662,description="Boss, Durotan set off with Draka and Gazlowe to track da Iron Horde's movements along da coast. Dey waitin' for ya on the cliffs to da northwest.",starts={{npcID=79627,x=0.712,y=0.298,zoneID=6662}},ends={{npcID=75806,x=0.614,y=0.108,zoneID=6662}},coords={x=0.712,y=0.298,source="quest_giver",zoneID=6662},questType="standard"},
[34685] = {id=34685,name="As the Smoke Rises",level=20,requiredLevel=20,faction="both",expansion=5,zoneID=6662,mapID=535,description="Aruuna burns. The arakkoa swooped down from their spires and are turning everything to ash. Draenei, talbuk, even orc; they care not for allegiances. They merely want to watch the world burn. I barely escaped with my life, but my best friend, Barum, stayed behind to find his daughter. The others all say you are a great champion. Please, I beg of you, go to Aruuna and find them.",starts={{npcID=79573,x=0.694,y=0.214,mapID=535}},ends={{npcID=75896,x=0.73,y=0.386,mapID=535}},coords={x=0.694,y=0.214,source="quest_giver",mapID=535},questType="standard"},
[34688] = {id=34688,name="DEPRECATED",level=1,requiredLevel=1,faction="horde",expansion=5,zoneID=6722,mapID=542,questType="standard"},
[34691] = {id=34691,name="Just the Beginning",level=20,requiredLevel=20,faction="horde",expansion=5,zoneID=6662,mapID=535,description="I forgive Orgrim. He acted as well all must - we do what our hearts tell us is right. We should return to your outpost and discuss our next course of action. There is nothing left for us here. I will ask the human to open a portal for us. We shall speak again there.",questType="standard"},
[34692] = {id=34692,name="Delegating on Draenor",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=7078,description="There is more work to do on Draenor than we can possibly handle by ourselves. We need to start delegating. A group of night elves need a champion at Starfall Outpost. Qiana is a perfect fit for this mission.",starts={{npcID=79953,x=0.292,y=0.346,zoneID=7078}},ends={{npcID=79953,x=0.292,y=0.346,zoneID=7078}},coords={x=0.292,y=0.346,source="quest_giver",zoneID=7078},questType="standard"},
[34696] = {id=34696,name="The Lady of Light",level=20,requiredLevel=20,faction="horde",expansion=5,zoneID=6662,description=", yes? You are the one in charge here? I am Knight-Lord Dranarus , at your service. Lady Liadrin has responded to a suspected demon presence near Auchindoun, southwest of here. She has asked specifically for your assistance in ensuring Auchindoun does not fall into Gul'dan's hands. If you could set forth at your nearest convenience, I am sure the Lady would be most grateful.",starts={{npcID=79612,x=0.718,y=0.296,zoneID=6662}},ends={{npcID=75121,x=0.554,y=0.676,zoneID=6662}},coords={x=0.718,y=0.296,source="quest_giver",zoneID=6662},questType="standard"},
[34697] = {id=34697,name="A Rediscovered Legend",level=15,requiredLevel=15,faction="horde",expansion=5,zoneID=6721,description="If your troops are going to learn to fight people you better get people to fight! And they better be good. Ever hear of Kash'drakor ? He's a big famous Frostwolf orc warrior type that tried to kill us Skulls. He would have won too, if the ogres hadn't snatched him. To the north is the Stonemaul Arena where they took him and a bunch of other big bad mean fighter gladiators. If you can find a way to free them, they could be the best trainers you could hope for.",starts={{npcID=76688,x=0.462,y=0.696,zoneID=6721}},ends={{npcID=79320,x=0.428,y=0.63,zoneID=6721}},coords={x=0.462,y=0.696,source="quest_giver",zoneID=6721},questType="standard"},
[34698] = {id=34698,name="Slave Hunters",level=15,requiredLevel=15,faction="both",expansion=5,zoneID=6721,description="Anytime a gladiator escapes Stonemaul, they send their hardened slave hunters after us. I consider myself a capable warrior, years of surviving in an arena have taught me that. But these slave hunters keep pendants magically tethered to the slaves. With these pendants they can track us down anywhere we go, and kill us in our sleep or when our guard is down. I have no right to ask this, but can you enter Stonemaul and retrieve these pendants?",starts={{npcID=79320,x=0.428,y=0.63,zoneID=6721}},ends={{npcID=79320,x=0.428,y=0.63,zoneID=6721}},coords={x=0.428,y=0.63,source="quest_giver",zoneID=6721},questType="standard"},
[34699] = {id=34699,name="Getting Gladiators",level=15,requiredLevel=15,faction="both",expansion=5,zoneID=6721,description="When we fled Stonemaul, we had to leave others behind. If we try to rescue them and are recognized, the ogres will know our purpose, and the first thing they will do is kill our friends. The ogres do not know you, which might give you a fighting chance. Enter Stonemaul, find the other gladiators, and release them from their bonds. Do this and you will have our loyalty.",starts={{npcID=79322,x=0.428,y=0.63,zoneID=6721}},ends={{npcID=77014,x=0.368,y=0.678,zoneID=6721}},coords={x=0.428,y=0.63,source="quest_giver",zoneID=6721},questType="standard"},
[34700] = {id=34700,name="Nazgrel",level=15,requiredLevel=15,faction="both",expansion=5,zoneID=6721,description="Escaping Stonemaul was the easy part. The ogre filth that rule the pits still have my son. For a while they used him as leverage to ensure I would fight in their arenas. But now that I have escaped they will try to train him to replace me. Please, rescue my son. If they see me they will kill him instantly.",starts={{npcID=79320,x=0.428,y=0.63,zoneID=6721}},ends={{npcID=79320,x=0.428,y=0.63,zoneID=6721}},coords={x=0.428,y=0.63,source="quest_giver",zoneID=6721},questType="standard"},
[34701] = {id=34701,name="Speaker for the Dead",level=20,requiredLevel=20,faction="alliance",expansion=5,zoneID=6662,description="Oh, praise the Light, you're here! Exarch Maladaar asked for me to find you. We need your help. Auchindoun is under attack by demons! Go to the Burning Front to the southwest as soon as possible! You're one of the few people he trusts to help lead the defense.",starts={{npcID=79618,x=0.696,y=0.216,zoneID=6662}},ends={{npcID=75119,x=0.556,y=0.676,zoneID=6662}},coords={x=0.696,y=0.216,source="quest_giver",zoneID=6662},questType="standard"},
[34702] = {id=34702,name="Krav'ogra",level=15,requiredLevel=15,faction="both",expansion=5,zoneID=6721,description="Stonemaul has chieftain, and it has slavemaster. Today, we kill both. First, Slavemaster Ok'mok . Me fight in arenas since me your size. Me know cruelty. Slavemaster Ok'mok is cruelty. Want to be true gladiator? Go to Stonemaul Arena, bang challenge gong in center of arena, and face beasts of slavemaster. Maybe you make Ok'mok so mad he jump down himself to kill you. If he do, kill him instead.",starts={{npcID=79331,x=0.426,y=0.63,zoneID=6721}},ends={{npcID=79331,x=0.426,y=0.63,zoneID=6721}},coords={x=0.426,y=0.63,source="quest_giver",zoneID=6721},questType="standard"},
[34703] = {id=34703,name="The Axe of Kor'gall",level=15,requiredLevel=15,faction="both",expansion=5,zoneID=6721,description="Time for vengeance! We are going to kill Kor'gall and you are going to take his axe. Shatter this feeble barrier, follow the bridge beyond until you reach the chieftain's throne. You freed us, so the honor of first blood is yours. Strike the first blow and we will join you in the cutting.",starts={{npcID=77014,x=0.368,y=0.678,zoneID=6721},{npcID=79322,x=0.428,y=0.63,zoneID=6721}},ends={{npcID=79322,x=0.428,y=0.63,zoneID=6721}},coords={x=0.368,y=0.678,source="quest_giver",zoneID=6721},questType="standard"},
[34704] = {id=34704,name="A Rediscovered Legend",level=15,requiredLevel=15,faction="alliance",expansion=5,zoneID=6721,description="This Sparring Arena is a good start, but we will need trainers to help mold your forces into worthy fighters. There has been a reported spotting of a draenei to the west who matches the description of Akaani. This is interesting, as we all believed her dead. She was one of the finest warriors the draenei have ever fielded and a master of nearly any weapon forged or found. Commander, you could not ask for a more skilled trainer. I advise seeking her out, if it is really her...",starts={{npcID=81076,x=0.528,y=0.598,zoneID=6721}},ends={{npcID=79322,x=0.428,y=0.63,zoneID=6721}},coords={x=0.528,y=0.598,source="quest_giver",zoneID=6721},questType="standard"},
[34706] = {id=34706,name="Come Together",level=20,requiredLevel=20,faction="horde",expansion=5,zoneID=6662,description="Your work is done here, . I will stay here for now and help clean up any remaining demons. You should return to your outpost and let Dranarus know of our success. He can relay that information to Azeroth.",starts={{npcID=77580,x=0.456,y=0.744,zoneID=6662}},ends={{npcID=79612,x=0.718,y=0.296,zoneID=6662}},coords={x=0.456,y=0.744,source="quest_giver",zoneID=6662},questType="standard"},
[34707] = {id=34707,name="Come Together",level=20,requiredLevel=20,faction="alliance",expansion=5,zoneID=6662,description="Gul'dan and his cronies would do well to remember this day. We Auchenai are not to be trifled with. You should inform Vindicator Icia in your outpost of our success. She can reach out to the scattered refugees and their families.",starts={{npcID=77581,x=0.456,y=0.74,zoneID=6662}},ends={{npcID=79618,x=0.696,y=0.216,zoneID=6662}},coords={x=0.456,y=0.74,source="quest_giver",zoneID=6662},questType="standard"},
[34708] = {id=34708,name="Vignette: Jehil the Climber",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6720,mapID=525,description="Goren are dangerous, especially in large numbers, and especially when we have a blind, under powered shaman with us. Fortunately, they have very short lifespans. Unfortunately, they multiply fast and grow faster. If we are going to do this we need to find the brood mother. Slaying her and her eggs should slow down the onslaught of goren. Check the burrows near the Forge Gates and I will to keep them off of Drek'Thar's scent.",questType="standard"},
[34709] = {id=34709,name="Every Bit Counts",level=20,requiredLevel=20,faction="alliance",expansion=5,zoneID=6662,description="The Jorune Mine, west of here, needs your help! My good friend Ageilaa sent me to look for help. Exarch Maladaar sent over what vindicators he could spare, but it isn't enough! Will you go to the mine and help us? We need the crystals from the mine to create more defenses like the crystals you see on the Burning Front.",starts={{npcID=79689,x=0.558,y=0.682,zoneID=6662}},ends={{npcID=78534,x=0.498,y=0.562,zoneID=6662}},coords={x=0.558,y=0.682,source="quest_giver",zoneID=6662},questType="standard"},
[34710] = {id=34710,name="Every Bit Counts",level=20,requiredLevel=20,faction="horde",expansion=5,zoneID=6662,description="Manduil Skycaller was sent on a sensitive mission to Jorune Mine, but he hasn't returned for hours. I suspect he requires assistance. I will let him brief you on the situation when you find him, but he is likely deep within the mine. You should report to Ageilaa , a local draenei miner who has agreed to cooperate with us in exchange for helping her regain control of the mine.",starts={{npcID=79696,x=0.554,y=0.668,zoneID=6662}},ends={{npcID=78534,x=0.498,y=0.562,zoneID=6662}},coords={x=0.554,y=0.668,source="quest_giver",zoneID=6662},questType="standard"},
[34711] = {id=34711,name="Due Cause to Celebrate",level=20,requiredLevel=20,faction="alliance",expansion=5,zoneID=6662,description="Shall we return to your outpost? It would be a much better - and safer - place to celebrate. I'll teleport us there.",starts={{npcID=80617,x=0.629,y=0.827,zoneID=6662}},ends={{npcID=80672,x=0.696,y=0.208,zoneID=6662}},coords={x=0.629,y=0.827,source="quest_giver",zoneID=6662},questType="standard"},
[34712] = {id=34712,name="Due Cause to Celebrate",level=20,requiredLevel=20,faction="horde",expansion=5,zoneID=6662,description="This isn't exactly my idea of the best place to talk. Shall we return to your outpost? It will be a much better place to celebrate. I'll teleport us there.",starts={{npcID=80389,x=0.683,y=0.703,zoneID=6662}},ends={{npcID=80553,x=0.712,y=0.298,zoneID=6662}},coords={x=0.683,y=0.703,source="quest_giver",zoneID=6662},questType="standard"},
[34713] = {id=34713,name="Treasure: Gronnstalker's Cache",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6720,mapID=525,questType="standard"},
[34714] = {id=34714,name="Frostfire Ridge: (RRP) - Treasure - Pale Leather Cache",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6720,mapID=525,questType="standard"},
[34716] = {id=34716,name="Mo'mor Might Know",level=35,requiredLevel=35,faction="alliance",expansion=5,zoneID=6755,description="We know the Warsong packleader that attacked the caravan is in Telaar. She has the blueprints. We don't know where she is down there, but there's one who might. Vindicator Mo'mor was last seen alive, but taken prisoner. If he's still alive, he might know where the blueprints are.",starts={{npcID=79722,x=0.658,y=0.686,zoneID=6755}},ends={{npcID=79743,x=0.666,y=0.686,zoneID=6755}},coords={x=0.658,y=0.686,source="quest_giver",zoneID=6755},questType="standard"},
[34717] = {id=34717,name="Operation: Just Arrowhead",level=35,requiredLevel=35,faction="alliance",expansion=5,zoneID=6755,description="It goes without saying that we'll help you kill any of the Warsong out in the open down there. You just start the fight, and we'll end it with extreme prejudice.",starts={{npcID=79722,x=0.658,y=0.686,zoneID=6755}},ends={{npcID=79576,x=0.634,y=0.618,zoneID=6755}},coords={x=0.658,y=0.686,source="quest_giver",zoneID=6755},questType="standard"},
[34718] = {id=34718,name="The Others",level=35,requiredLevel=35,faction="alliance",expansion=5,zoneID=6755,description="There are yet a few survivors. I saw them pile onto Arbiter Khan during the fighting. More importantly, I can hear little Isel's sobs. She's nearby. I hope her mother is still alive. Your dwarf friend, Hansel, came in to try to rescue us. He thought he could take the Warsong on his own. I'm afraid I don't know what happened to him.",starts={{npcID=79743,x=0.666,y=0.686,zoneID=6755}},ends={{npcID=79743,x=0.666,y=0.686,zoneID=6755}},coords={x=0.666,y=0.686,source="quest_giver",zoneID=6755},questType="standard"},
[34719] = {id=34719,name="... and My Hammer",level=35,requiredLevel=35,faction="alliance",expansion=5,zoneID=6755,description="When they captured me, the Warsong took my hammer. Will you help me to recover it? I ask only because it's a holy relic. It should be taken from these orc dogs for no other reason than to return it to Auchindoun. Perhaps then, a worthy vindicator of the Light will take it up to smite the enemies of the draenei.",starts={{npcID=79743,x=0.666,y=0.686,zoneID=6755}},ends={{npcID=79743,x=0.666,y=0.686,zoneID=6755}},coords={x=0.666,y=0.686,source="quest_giver",zoneID=6755},questType="standard"},
[34720] = {id=34720,name="Operation: Just Arrowhead",level=35,requiredLevel=35,faction="alliance",expansion=5,zoneID=6755,description="It goes without saying that the Warsong in Telaar need to be dealt with. Rangari Ogir and his forces on the overlook will help you kill any of the orcs that are out in the open. You just start the fight, and they'll end it with extreme prejudice.",starts={{npcID=79576,x=0.634,y=0.618,zoneID=6755}},ends={{npcID=79576,x=0.634,y=0.618,zoneID=6755}},coords={x=0.634,y=0.618,source="quest_giver",zoneID=6755},questType="standard"},
[34721] = {id=34721,name="Seek Out the Seer",level=20,requiredLevel=20,faction="horde",expansion=5,zoneID=6662,description="We've been watching you, . Seer Malune , keeper of memories, has requested an audience with you, adventurer. She has long foretold the coming of a great hero to destroy the lurking shadow. We believe you are that hero. Come to Duskfall Island, not far southeast of here, and fulfill your destiny.",starts={{npcID=79724,x=0.71,y=0.472,zoneID=6662}},ends={{npcID=76665,x=0.654,y=0.508,zoneID=6662}},coords={x=0.71,y=0.472,source="quest_giver",zoneID=6662},questType="standard"},
[34729] = {id=34729,name="Blood Oath of Na'Shra",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=6720,description="You have done me a great service. This blade is as much yours as it is mine. I offer you this blood oath: I shall serve your cause and lend my knowledge of blades and mining to your forces. Will you accept it?",ends={{npcID=76452,x=0.646,y=0.396,zoneID=6720}},questType="standard"},
[34730] = {id=34730,name="Blood Oath of Lokra",level=1,requiredLevel=1,faction="horde",expansion=5,zoneID=6720,description="You have done me a great service. This blade is as much yours as it is mine. I offer you this blood oath: I shall serve your cause and lend my knowledge of blades and mining to your forces. Will you accept it?",ends={{npcID=76487,x=0.734,y=0.588,zoneID=6720}},questType="standard"},
[34731] = {id=34731,name="Oath of Shadow Hunter Rala",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=6720,mapID=525,starts={{npcID=78208,x=0.526,y=0.404,mapID=525}},ends={{npcID=78208,x=0.526,y=0.404,mapID=525}},coords={x=0.526,y=0.404,source="quest_giver",mapID=525},questType="standard"},
[34732] = {id=34732,name="Mulverick's Offer of Service",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=6720,mapID=525,starts={{npcID=79047,x=0.306,y=0.414,mapID=525}},ends={{npcID=79047,x=0.306,y=0.414,mapID=525}},coords={x=0.306,y=0.414,source="quest_giver",mapID=525},questType="standard"},
[34733] = {id=34733,name="Services of Dagg",level=10,requiredLevel=10,faction="both",expansion=5,zoneID=7078,mapID=539,starts={{npcID=79492,x=0.486,y=0.172,mapID=525},{npcID=79492,x=0.614,y=0.748,mapID=539}},ends={{npcID=79492,x=0.486,y=0.172,mapID=525},{npcID=79492,x=0.614,y=0.748,mapID=539}},coords={x=0.486,y=0.172,source="quest_giver",mapID=539},questType="standard"},
[34735] = {id=34735,name="Thunderlord Invasion!",level=1,requiredLevel=1,faction="none",expansion=5,zoneID=7078,mapID=539,description="Sir! Scouts have spotted Thunderlords approaching from the east. The men are armed and ready. We'll mount defensive positions as soon as you take the field.",questType="standard"},
[34736] = {id=34736,name="We Be Needin' Supplies",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=6720,description="Commander, our forces are not prepared for frost fightin'. I took da liberty and sent some of our shadow hunters north to establish a supply base. Ya might want to be headin' up dere and see what they be up to. Look for a hollow between the Crackling Plains and the Savage Crag.",starts={{npcID=78487,x=0.456,y=0.432,zoneID=7004}},ends={{npcID=78208,x=0.526,y=0.404,zoneID=6720}},coords={x=0.456,y=0.432,source="quest_giver",zoneID=7004},questType="standard"},
[34737] = {id=34737,name="Masters of Shadow",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=4,description="The bad orcs tried to catch me, but I snuck away. I'm good at hiding. All of the bad orcs are bad, but I've remembered the names of the meanest ones, just in case anybody came to save me. Luuka takes a deep breath.> Ungra , Gurran, and... umm... oh! Ankova. Will you protect me from them?",starts={{npcID=79661,x=0.658,y=0.196,zoneID=7025},{npcID=79661,x=0.824,y=0.45,zoneID=7025}},ends={{npcID=79675,x=0.598,y=0.202,zoneID=7025},{npcID=79675,x=0.496,y=0.486,zoneID=7025},{npcID=79675,x=0.55,y=0.502,zoneID=4}},coords={x=0.658,y=0.196,source="quest_giver",zoneID=7025},questType="standard"},
[34739] = {id=34739,name="The Shadowmoon Clan",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=7025,description="We will protect the wounded prisoners and make sure Kargath doesn't get through the rubble. You go ahead and clear the cave, .",starts={{npcID=78553,x=0.55,y=0.502,zoneID=4},{npcID=78553,x=0.5,y=0.134,zoneID=7025},{npcID=78553,x=0.82,y=0.452,zoneID=7025}},ends={{npcID=79315,x=0.6,y=0.2,zoneID=7025},{npcID=79315,x=0.51,y=0.476,zoneID=7025}},coords={x=0.55,y=0.502,source="quest_giver",zoneID=4},questType="standard"},
[34740] = {id=34740,name="Yrel",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=7025,description="Forgive me if I'm a bit flustered - I've never killed anyone before. My name is Yrel , and I am a student of Karabor. You say you have an ARMY with you? The Light must truly be watching over me today. I will follow you, then. Lead the way, .",starts={{npcID=78994,x=0.588,y=0.14,zoneID=7025},{npcID=78994,x=0.456,y=0.154,zoneID=7025}},ends={{npcID=78994,x=0.588,y=0.14,zoneID=7025},{npcID=78994,x=0.456,y=0.154,zoneID=7025}},coords={x=0.588,y=0.14,source="quest_giver",zoneID=7025},questType="standard"},
[34741] = {id=34741,name="Keli'dan the Breaker",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=7025,description="One of Ner'zhul's lieutenants remains, up ahead. The exit to the cave isn't much farther past him. I will go back and tell Khadgar that the cave is clear. We will rendezvous once you've taken care of Keli'dan!",starts={{npcID=79675,x=0.55,y=0.502,zoneID=4},{npcID=79675,x=0.598,y=0.202,zoneID=7025},{npcID=79675,x=0.496,y=0.486,zoneID=7025}},ends={{npcID=78562,x=0.494,y=0.144,zoneID=7025}},coords={x=0.55,y=0.502,source="quest_giver",zoneID=4},questType="standard"},
[34743] = {id=34743,name="Vignette: The Crystal Blade of Torvath",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6719,mapID=539,questType="standard"},
[34746] = {id=34746,name="Shields Down!",level=35,requiredLevel=35,faction="alliance",expansion=5,zoneID=6755,description="Did you hear that? They got the shield up. There'll be no getting into Telaar now. You must get that shield down. The only way to do it is to destroy the Arkonite crystal . Don't worry about me. You're going to kill two birds with one stone; Packleader Kargora is the one who stole your blueprints.",starts={{npcID=79743,x=0.666,y=0.686,zoneID=6755}},ends={{npcID=79674,x=0.63,y=0.62,zoneID=6755}},coords={x=0.666,y=0.686,source="quest_giver",zoneID=6755},questType="standard"},
[34747] = {id=34747,name="The Honor of a Blademaster",level=35,requiredLevel=35,faction="alliance",expansion=5,zoneID=6755,mapID=550,starts={{npcID=81790,x=0.826,y=0.466,mapID=550}},ends={{npcID=81790,x=0.826,y=0.466,mapID=550}},coords={x=0.826,y=0.466,source="quest_giver",mapID=550},questType="standard"},
[34751] = {id=34751,name="Clear!",level=20,requiredLevel=20,faction="horde",expansion=5,zoneID=6662,description="You gotta help me fix this robot. I'm friggin' hungry! I built the Pleasure-Bot 8000 to locate Draenor truffles, and what does it do? It swims to this stupid island and shorts its power fluctuator. I got it hooked up to these batteries, but it ain't enough juice to jump it. Be a doll and get me the zapper sacs from the electric eels in the lake, would ya? They oughta be enough.",starts={{npcID=79870,x=0.642,y=0.478,zoneID=6662}},ends={{npcID=79870,x=0.642,y=0.478,zoneID=6662}},coords={x=0.642,y=0.478,source="quest_giver",zoneID=6662},questType="standard"},
[34756] = {id=34756,name="A Charming Deception",level=30,requiredLevel=30,faction="both",expansion=5,zoneID=6722,description="Reshad is more than he appears; a mottled old crow with his beak in a book, certainly, but we need him. Shadows gather beneath the lonely spire, in Veil Terokk. Reshad must make it there safely. Along the path you'll find charms primed with illusion spells. You need only touch them to take on Reshad 's image. Adherent assassins are on the prowl for an old outcast with scrolls on his back. They will fall upon you. Oh, but won't they be surprised when the illusion fades?! Kee-hee-hee!",starts={{npcID=79890,x=0.516,y=0.312,zoneID=6722}},ends={{npcID=81770,x=0.464,y=0.466,zoneID=6722}},coords={x=0.516,y=0.312,source="quest_giver",zoneID=6722},questType="standard"},
[34758] = {id=34758,name="Looking For Help",level=20,requiredLevel=20,faction="horde",expansion=5,zoneID=6720,description="We have an accessible fishing spot here, but no bait seems to work! We need to find a local fisherman with some knowledge of the area to help us out. Head southeast and see if you can find anyone on the shoreline.",starts={{npcID=79892,x=0.384,y=0.722,zoneID=7004}},ends={{npcID=79896,x=0.556,y=0.752,zoneID=6720}},coords={x=0.384,y=0.722,source="quest_giver",zoneID=7004},questType="standard"},
[34760] = {id=34760,name="Treasure: Warchest of Kull'krosh",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6755,mapID=550,ends={{npcID=230725,x=0.377,y=0.706,mapID=550}},questType="standard"},
[34761] = {id=34761,name="Clear!",level=20,requiredLevel=20,faction="alliance",expansion=5,zoneID=6662,description="Oh, the gnomanity! The Pleasure-Bot 8000 broke before it could bring me a single Draenor truffle. It swam here and shorted its power fluctuator. AGAIN! I have power going to it, but it isn't enough to override the fluctuator. Could you get me the sacs from the electric eels in the lake? I think that would be just the ticket!",starts={{npcID=79901,x=0.628,y=0.502,zoneID=6662}},ends={{npcID=79901,x=0.628,y=0.502,zoneID=6662}},coords={x=0.628,y=0.502,source="quest_giver",zoneID=6662},questType="standard"},
[34765] = {id=34765,name="The Den of Skog",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=7004,mapID=525,description="So this gronn infestation ain't gonna solve itself. You're gonna have to show them who's boss, Horde style! With this many gronnlings around there is bound to be a full grown, big mama of a gronn. Find him... it... her... or whatever, and take it out, and the rest of those gronnlings might lose interest in our little operation here.",starts={{npcID=78466,x=0.488,y=0.65,mapID=525},{npcID=78466,x=0.42,y=0.55,mapID=525}},ends={{npcID=78466,x=0.488,y=0.65,mapID=525},{npcID=78466,x=0.42,y=0.55,mapID=525}},coords={x=0.488,y=0.65,source="quest_giver",mapID=525},questType="standard"},
[34766] = {id=34766,name="Logistical Nightmare",level=20,requiredLevel=20,faction="horde",expansion=5,zoneID=6662,description="Commander, I am afraid I have... troubling... news. These saberon followed our encampment from Gorgrond, and have been stealing our supplies, ransacking our ledgers, and slaughtering our peons! I hate to ask of your time to deal with the matter, but all of our men are stationed guarding the camp from any further raids. We desperately need those supplies so we may enact your will!",starts={{npcID=79921,x=0.712,y=0.294,zoneID=6662}},ends={{npcID=79921,x=0.712,y=0.294,zoneID=6662}},coords={x=0.712,y=0.294,source="quest_giver",zoneID=6662},questType="standard"},
[34769] = {id=34769,name="A Choice to Make",level=35,requiredLevel=35,faction="alliance",expansion=5,zoneID=6755,description="We're just about ready to go here. All that's needed now is for you to make your choice. Take a look at the blueprints on the drafting table. Are we going to construct a corral or a tankworks?",starts={{npcID=79674,x=0.63,y=0.62,zoneID=6755}},ends={{npcID=79576,x=0.634,y=0.618,zoneID=6755}},coords={x=0.63,y=0.62,source="quest_giver",zoneID=6755},questType="standard"},
[34770] = {id=34770,name="The Honor of a Blademaster",level=35,requiredLevel=35,faction="horde",expansion=5,zoneID=6755,mapID=550,starts={{npcID=81790,x=0.826,y=0.466,mapID=550}},ends={{npcID=81790,x=0.826,y=0.466,mapID=550}},coords={x=0.826,y=0.466,source="quest_giver",mapID=550},questType="standard"},
[34771] = {id=34771,name="Good Stuff",level=1,requiredLevel=1,faction="both",expansion=5,questType="standard"},
[34772] = {id=34772,name="Morkeths Cage",level=1,requiredLevel=1,faction="horde",expansion=5,zoneID=6662,mapID=535,questType="standard"},
[34773] = {id=34773,name="Why Is The Brew Gone?",level=20,requiredLevel=20,faction="alliance",expansion=5,zoneID=6662,description="Commander, we have a bit of a... uh... problem. This group o' saberon followed us from Gorgrond, and they've been stealin' our footmen's swords an' slaughtering our peasants! I hate to ask fer your time, but all of yer men are guardin' the camp from any further raids. Plus... Quartermaster O'Riley lowers her voice to a whisper.> They took our beer!",starts={{npcID=79963,x=0.696,y=0.214,zoneID=6662}},ends={{npcID=79963,x=0.696,y=0.214,zoneID=6662}},coords={x=0.696,y=0.214,source="quest_giver",zoneID=6662},questType="standard"},
[34774] = {id=34774,name="Blingtron 5000",level=10,requiredLevel=10,faction="both",expansion=5,questType="standard"},
[34775] = {id=34775,name="Mission Probable",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=7004,description="Despite his recent captures, Olin Umberhide seems to be a tauren of some skill in combat. He certainly has learned how to get an enemy's attention. I have a mission available that might prove ideal for his skill sets. When you are ready, simply issue the order via the command table in front of me and we will dispatch him immediately.",starts={{npcID=79740,x=0.538,y=0.542,zoneID=7004}},ends={{npcID=79740,x=0.538,y=0.542,zoneID=7004}},coords={x=0.538,y=0.542,source="quest_giver",zoneID=7004},questType="standard"},
[34776] = {id=34776,name="Gatekeepers of Auchindoun",level=20,requiredLevel=20,faction="horde",expansion=5,zoneID=6662,description="I was taken captive by the Iron Horde when they raided our caravan en route to Auchindoun. I escaped, but these spirits won't let me through to join my fellow Sunsworn until someone defeats them in combat! Please, will you help me defeat them?",starts={{npcID=79978,x=0.58,y=0.53,zoneID=6662}},ends={{npcID=79978,x=0.58,y=0.53,zoneID=6662}},coords={x=0.58,y=0.53,source="quest_giver",zoneID=6662},questType="standard"},
[34777] = {id=34777,name="Gatekeepers of Auchindoun",level=20,requiredLevel=20,faction="alliance",expansion=5,zoneID=6662,description="Auchindoun is under attack, stranger, and I intend to help defend it. The only problem is the only armor I could find was my grandfather's old set, and it isn't nearly enough to defeat the spirits blocking the path toward Auchindoun. Would you defeat them and let me through the gate with you? I will find a way to repay you!",starts={{npcID=79979,x=0.574,y=0.512,zoneID=6662}},ends={{npcID=79979,x=0.574,y=0.512,zoneID=6662}},coords={x=0.574,y=0.512,source="quest_giver",zoneID=6662},questType="standard"},
[34778] = {id=34778,name="Migrant Workers",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=6719,description=", more recruits arrive at your garrison every hour. We will soon run out of food. I have made contact with Exarch Akama in hopes of securing rations from Elodor, the breadbasket of this valley. He has agreed, provided we supply labor for the harvest. Everyone wins. If you agree with my plan, speak with Foreman Zipfizzle here in the courtyard - he has gathered together available laborers. Akama and I will escort them and meet you at Elodor, far to the east!",starts={{npcID=79457,x=0.44,y=0.528,zoneID=7078}},ends={{npcID=81912,x=0.446,y=0.512,zoneID=7078},{npcID=81912,x=0.56,y=0.326,zoneID=6719}},coords={x=0.44,y=0.528,source="quest_giver",zoneID=7078},questType="standard"},
[34779] = {id=34779,name="Circle the Wagon",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=7078,description="One of our wagons fell behind, and disappeared somewhere in the woods to the northwest. Vindicator Maraad and several of your workers are stranded out there. Find them and bring them back!",starts={{npcID=81912,x=0.56,y=0.326,zoneID=6719},{npcID=81912,x=0.446,y=0.512,zoneID=7078}},ends={{npcID=80078,x=0.558,y=0.328,zoneID=6719}},coords={x=0.56,y=0.326,source="quest_giver",zoneID=6719},questType="standard"},
[34780] = {id=34780,name="Invisible Ramparts",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=6719,description="Exarch Akama is too cautious, but we shouldn't ignore a threat from the Shadowmoon clan. It is good you are here! Since we arrived on Draenor I have dedicated myself to recreating the technology we left behind. This large structure here is a defense ward. It should counter a Shadowmoon advance - provided we power it up. I have prepared resonance crystals at my workshop to the south. Carry one crystal at a time to the three pylons that surround the ward, then activate the control panel nearby!",starts={{npcID=80075,x=0.562,y=0.326,zoneID=6719}},ends={{npcID=230933,x=0.569,y=0.347,zoneID=6719}},coords={x=0.562,y=0.326,source="quest_giver",zoneID=6719},questType="standard"},
[34781] = {id=34781,name="Defenstrations",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=6719,description="No sooner does power rush to the crystal outside than you hear distant war cries and shouts of alarm. Elodor is being attacked! If you want your laborers to come home in one piece, you'd best help with the defense of the town. Defeat the invasion and then return to the control console to reset the defenses.",starts={{npcID=230933,x=0.569,y=0.347,zoneID=6719}},ends={{npcID=230933,x=0.569,y=0.347,zoneID=6719}},coords={x=0.569,y=0.347,source="quest_giver",zoneID=6719},questType="standard"},
[34782] = {id=34782,name="The Exarch Council",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=6719,description="Good work at the gates! The Shadowmoon orcs have been seeking prisoners for some reason. Their aggression helps our cause. Come with me. I would like to introduce you to the Exarch Council, \"The Hand of the Prophet.\" I have been trying to convince the Exarchs to support our cause and go on the offensive against the Iron Horde, but they are - as always - too cautious and slow to act. Come with me, I will introduce you to Exarch Othaar up the hill. Perhaps meeting an Alliance hero can sway the council.",starts={{npcID=82348,x=0.562,y=0.324,zoneID=6719}},ends={{npcID=80076,x=0.592,y=0.266,zoneID=6719}},coords={x=0.562,y=0.324,source="quest_giver",zoneID=6719},questType="standard"},
[34783] = {id=34783,name="Naielle, The Rangari",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=6719,description="I am calling the Exarch Council to order to hear your petition. None of us doubt that this \"Iron Horde\" is a threat, but few can agree on what we should do about it. It is up to you and Vindicator Maraad to gather the Exarchs together. Exarch Naielle is the leader of the Rangari, the \"Eyes of the Prophet.\" They are our scouts who silently stalk the farthest corners of Draenor. Seek her out in the Rangari Enclave northwest of here.",starts={{npcID=80076,x=0.592,y=0.266,zoneID=6719}},ends={{npcID=80079,x=0.624,y=0.262,zoneID=6719}},coords={x=0.592,y=0.266,source="quest_giver",zoneID=6719},questType="standard"},
[34784] = {id=34784,name="Fun with Fungus",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=6719,description="It is our mission as rangari to explore and understand this world. Around you is the Umberfen. Many draenei lost their lives when we first discovered this place. The volatile spores burst whenever anyone approaches. But we watched... and we learned. Around the swamp you'll notice \"Shimmershrooms,\" distinguished by their orange glowcaps. Their dust will make you invisible to the volatile spores. Grab the spores - gently! - and bring them to me. We will forge this savage world into a weapon.",starts={{npcID=80079,x=0.624,y=0.262,zoneID=6719}},ends={{npcID=80079,x=0.624,y=0.262,zoneID=6719}},coords={x=0.624,y=0.262,source="quest_giver",zoneID=6719},questType="standard"},
[34785] = {id=34785,name="Hataaru, the Artificer",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=6719,description="I will also need you to call upon Exarch Hataaru . I understand you were helping him with our defenses at the gate. Hataaru is our Chief Artificer - he understands our technology better than any other and has been working tirelessly to recreate the glory of the civilization we left behind. He has moved to his workstation outside of the Elodor Dig, our crystal mines located just to the Southeast. Look for him at the mine entrance.",starts={{npcID=80076,x=0.592,y=0.266,zoneID=6719}},ends={{npcID=80075,x=0.562,y=0.326,zoneID=6719}},coords={x=0.592,y=0.266,source="quest_giver",zoneID=6719},questType="standard"},
[34786] = {id=34786,name="Engorged Goren",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=6719,description="You must be the that so impressed Exarch Hataaru. Can you help? The Elodor Dig just behind me is overrun by strange stone creatures. These so-called goren actually devour minerals, metabolize them, and grow crystalline structures from their arms and back. Like most of the wildlife on this world, they completely baffle us. Please slay as many as you can and gather their crystal scales for me. You'll be protecting our earthworkers and aiding our research at the same time.",starts={{npcID=81140,x=0.618,y=0.292,zoneID=6719}},ends={{npcID=81140,x=0.618,y=0.292,zoneID=6719}},coords={x=0.618,y=0.292,source="quest_giver",zoneID=6719},questType="standard"},
[34787] = {id=34787,name="Exarch Maladaar",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=6719,description="The council is almost assembled: Othaar, myself, Hataaru and Naielle are ready. Only Exarch Maladaar remains. He has not been himself since he returned from his capture at the hands of the Iron Horde... but Vindicator Maraad was able to track him down. Find Maladaar at the Fey Landing, just south of the town center.",starts={{npcID=80078,x=0.558,y=0.328,zoneID=6719}},ends={{npcID=80073,x=0.624,y=0.262,zoneID=6719}},coords={x=0.558,y=0.328,source="quest_giver",zoneID=6719},questType="standard"},
[34788] = {id=34788,name="Friend of the Exarchs",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=6719,description="Only three members remain of the Exarch Council, but we are all deeply indebted to you. The vote is unanimous: Your Alliance will have our full support on Draenor. We are also going to place a draenei representative under your direct command. Three potential candidates are here in the courtyard. Speak to them and choose who you want - we will dispatch him or her immediately to your garrison!",starts={{npcID=80079,x=0.624,y=0.262,zoneID=6719}},ends={{npcID=80079,x=0.624,y=0.262,zoneID=6719}},coords={x=0.624,y=0.262,source="quest_giver",zoneID=6719},questType="standard"},
[34789] = {id=34789,name="Speaker for the Dead",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=6719,description="This was a betrayal from within. There's no other explanation for it. None of the Exarchs trust each other now - especially me. But Othaar and Akama can damn their laws. We've got to rout out the traitor and the only way to do it is to speak to the corpse! Join me just outside the Altar of Sha'tar atop the eastern cliffs. Soulbinder Nyami and I will perform an exorcism to save Hataaru's immortal soul... and maybe learn who did this to him. Do you trust me, ?",starts={{npcID=80073,x=0.624,y=0.262,zoneID=6719}},ends={{npcID=80073,x=0.624,y=0.262,zoneID=6719},{npcID=88972,x=0.664,y=0.262,zoneID=6719}},coords={x=0.624,y=0.262,source="quest_giver",zoneID=6719},questType="standard"},
[34790] = {id=34790,name="The Sting",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=6719,description="The exarchs seem to trust you, . Are you venturing into the Umbrafen? The Sporebats in this area are usually docile, but something's got them all riled up. When they attack, their stingers wrap around exposed limbs. I've seen them tear through reinforced leather like it was paper. How do they work, I wonder? Could you bring me a pristine sporebat stinger ? I'd love to study it.",starts={{npcID=82537,x=0.566,y=0.23,zoneID=6719}},ends={{npcID=82537,x=0.566,y=0.23,zoneID=6719}},coords={x=0.566,y=0.23,source="quest_giver",zoneID=6719},questType="standard"},
[34791] = {id=34791,name="Warning the Exarchs",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=6719,description="You set the book ablaze, but not before noting its contents. The demonic tome was dedicated to enchanting weapons with fel energy. It looked as though the goal was to ensnare the victim's soul. The Exarchs must be warned that traitors are among them! The Council should be meeting now just up the hill to the east.",starts={{npcID=233229,x=0.61,y=0.245,zoneID=6719}},ends={{npcID=80073,x=0.624,y=0.262,zoneID=6719}},coords={x=0.61,y=0.245,source="quest_giver",zoneID=6719},questType="standard"},
[34792] = {id=34792,name="The Traitor's True Name",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=6719,description="We must give the traitor no place to hide. I have a focusing lens that will illuminate cloaked fel energy. If it were placed on a high point, it could act like a beacon, lighting up anyone in town who reeks of the fel taint. There is a prayer circle atop the Exarch's Rise to the north that will serve our purpose. Plant the focusing lens, . If you reveal anything, deal with it. Then meet me below.",starts={{npcID=88972,x=0.664,y=0.262,zoneID=6719}},ends={{npcID=80073,x=0.624,y=0.262,zoneID=6719}},coords={x=0.664,y=0.262,source="quest_giver",zoneID=6719},questType="standard"},
[34793] = {id=34793,name="Auchenai Defenders Greeting",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6662,mapID=535,questType="standard"},
[34794] = {id=34794,name="Taking the Fight to Nagrand",level=35,requiredLevel=35,faction="horde",expansion=5,zoneID=6755,description="Boss-mon, good to see ya. Durotan recommended dat we be gettin' a foothold in Nagrand , so I taken the liberty of dispatchin' some of da boys. Thrall's already reportin' that the outside be nearly complete. He been askin' me to let ya know they be ready for ya. A windrider be waitin' to catch ya up with the latest caravan shipment whenever you be ready, .",starts={{npcID=78487,x=0.456,y=0.432,zoneID=7004}},ends={{npcID=80001,x=0.864,y=0.662,zoneID=6755}},coords={x=0.456,y=0.432,source="quest_giver",zoneID=7004},questType="standard"},
[34795] = {id=34795,name="The Might of the Warsong",level=35,requiredLevel=35,faction="horde",expansion=5,zoneID=6755,description="The Warsong. Surprise attack. Headed into... the Burning Blade.... They took the... blueprints....",starts={{npcID=80001,x=0.864,y=0.662,zoneID=6755}},ends={{npcID=80003,x=0.828,y=0.45,zoneID=6755}},coords={x=0.864,y=0.662,source="quest_giver",zoneID=6755},questType="standard"},
[34801] = {id=34801,name="A Pilgrimage Gone Awry",level=20,requiredLevel=20,faction="horde",expansion=5,zoneID=6662,description="I am a humble pilgrim, I swear. Please don't hurt me! My sister and I were traveling to Auchindoun to pay our respects to my grandmother when we hit an overturned rock and lost control of our caravan. I managed to survive, but my sister... Nadur cries.> Please, you have to help me. I'm desperate. If you could bring me some prowler blood , snapdragon flowers, and a riverhopper eye , I can fashion a potion to bring her back. I just know it....",starts={{npcID=80028,x=0.614,y=0.544,zoneID=6662}},ends={{npcID=80028,x=0.614,y=0.544,zoneID=6662}},coords={x=0.614,y=0.544,source="quest_giver",zoneID=6662},questType="standard"},
[34802] = {id=34802,name="A Pilgrimage Gone Awry",level=20,requiredLevel=20,faction="alliance",expansion=5,zoneID=6662,description="My sister and I were traveling to Auchindoun to pay our respects to my grandmother when we hit an overturned rock and lost control of our caravan. I managed to survive, but my sister... Nadur cries.> Please, I need your help. If you could bring me some prowler blood , snapdragon flowers, and a riverhopper eye , I can fashion a potion to bring her back... I just know I can...",starts={{npcID=80028,x=0.614,y=0.544,zoneID=6662}},ends={{npcID=80028,x=0.614,y=0.544,zoneID=6662}},coords={x=0.614,y=0.544,source="quest_giver",zoneID=6662},questType="standard"},
[34803] = {id=34803,name="Send Them Running",level=20,requiredLevel=20,faction="horde",expansion=5,zoneID=6662,description="Your scouts have located the saberon's alpha male just outside our gates! Commander, I believe that dispatching this target will send any of these remaining vermin running back to their caves. I do not wish to ask more of you, but you are the only one capable of this task, .",starts={{npcID=79921,x=0.712,y=0.294,zoneID=6662}},ends={{npcID=79921,x=0.712,y=0.294,zoneID=6662}},coords={x=0.712,y=0.294,source="quest_giver",zoneID=6662},questType="standard"},
[34804] = {id=34804,name="Not In Your House",level=20,requiredLevel=20,faction="alliance",expansion=5,zoneID=6662,description=", we have located the saberon's alpha male just outside our gates! We believe that slaying him will send any remaining saberon running with their tails between their legs, but the beast is positively massive! I do not wish to call upon you once more, but you are the only one capable of this task.",starts={{npcID=79963,x=0.696,y=0.214,zoneID=6662}},ends={{npcID=79963,x=0.696,y=0.214,zoneID=6662}},coords={x=0.696,y=0.214,source="quest_giver",zoneID=6662},questType="standard"},
[34805] = {id=34805,name="Echo Hunters",level=30,requiredLevel=30,faction="both",expansion=5,zoneID=6722,description="I am no sorcerer, but I've picked up a few spells in my time - enough for me to pass unseen by the naked eye. Unfortunately, the vampire bats in these woods don't use their eyes. They will hear my shuffling robes and Percy's incessant clucking a mile away. Clear them away from the path, would you?",starts={{npcID=79519,x=0.436,y=0.13,zoneID=6722},{npcID=80265,x=0.516,y=0.312,zoneID=6722}},ends={{npcID=81770,x=0.464,y=0.466,zoneID=6722}},coords={x=0.436,y=0.13,source="quest_giver",zoneID=6722},questType="standard"},
[34806] = {id=34806,name="Prune the Podlings",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=6719,description="The blood soaked body of Ryan is slumped up against the cave wall. Tiny teeth marks cover his body. The podlings clearly are a threat to you and your garrison. It's time to do a little pruning.",starts={{npcID=74547,x=0.47,y=0.144,zoneID=6719}},coords={x=0.47,y=0.144,source="quest_giver",zoneID=6719},questType="standard"},
[34808] = {id=34808,name="More Lazy Peons",level=35,requiredLevel=35,faction="horde",expansion=5,zoneID=6755,description="We have a rare opportunity to strike at the heart of the Warsong. But, we need your wisdom and leadership. The most important decision will be your choice between building a corral or a tankworks. This choice will setup our approach to the fight against the Warsong. Thazz'ril will head up our building efforts. Will you give him a hand? It looks like he's having trouble motivating his peons to work.",starts={{npcID=80003,x=0.828,y=0.45,zoneID=6755}},ends={{npcID=80140,x=0.828,y=0.442,zoneID=6755}},coords={x=0.828,y=0.45,source="quest_giver",zoneID=6755},questType="standard"},
[34809] = {id=34809,name="A Lesson in Mineralogy",level=35,requiredLevel=35,faction="both",expansion=5,zoneID=6755,description="I built this machine to break down elementium minerals into base elements. You see, it's not just what's buried within the ground that can be valuable; but also the ground itself! Take, for example, the earth elementals below us; inside every earth elemental is an earthen core , dense in precious metal!. Those elementals are going to make us rich! Collect several earthen cores , place them in the Gold-O-Matic 9000 , and I'll give you a cut!",starts={{npcID=79201,x=0.712,y=0.524,zoneID=6755}},ends={{npcID=230882,x=0.711,y=0.524,zoneID=6755}},coords={x=0.712,y=0.524,source="quest_giver",zoneID=6755},questType="standard"},
[34810] = {id=34810,name="Gazmolf Futzwangler and the Highmaul Crusade",level=35,requiredLevel=35,faction="both",expansion=5,zoneID=6755,description="I'm here in Nagrand recruiting for the Steamwheedle Preservation Society. We're the archaeological branch of the Steamwheedle Cartel. We're here to collect all of the artifacts, relics, antiquities and oddities that Nagrand has to offer! Currently, we're hiring surveyors, excavators, adventurers... you name it! If you're interested in getting your hands dirty, talk to Gazmolf Futzwangler over at Stonecrag Gorge. He's the goblin in charge of this expedition!",starts={{npcID=80184,x=0.798,y=0.488,zoneID=6755}},ends={{npcID=79201,x=0.712,y=0.524,zoneID=6755}},coords={x=0.798,y=0.488,source="quest_giver",zoneID=6755},questType="standard"},
[34811] = {id=34811,name="Good Help is Hard to Find",level=35,requiredLevel=35,faction="both",expansion=5,zoneID=6755,description="The excavation team is on strike! Foreman Thazwix and his cronies think they can squeeze the Steamwheedle Preservation Society for some extra dough by refusing to work. What I need is a scab, a strikebreaker; someone to put some pressure on them by doing the job they refuse to do! Go down into the gorge, dig up some antiquities for me, and I'll pay you what I would have payed those lazy numbskulls!",starts={{npcID=82658,x=0.71,y=0.524,zoneID=6755}},ends={{npcID=82658,x=0.71,y=0.524,zoneID=6755}},coords={x=0.71,y=0.524,source="quest_giver",zoneID=6755},questType="standard"},
[34812] = {id=34812,name="Horde Stables Tracking Event",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6755,mapID=550,questType="standard"},
[34813] = {id=34813,name="Horde Workshop Tracking Event",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6755,mapID=550,questType="standard"},
[34814] = {id=34814,name="Making Acquaintances",level=20,requiredLevel=20,faction="horde",expansion=5,zoneID=6662,description="It's nice to see someone else taking a vested interest in the arcane arts, you know. It's all too rare these days if you ask me! Unfortunately, I must meet Cordana to handle an important matter, but we're in luck! One of my good friends in the Kirin Tor has agreed to help you connect your arcane sanctum to the ley line network. He's waiting at my tower. Let's leave immediately and introduce you to one another.",starts={{npcID=80142,x=0.75,y=0.31,zoneID=6662}},ends={{npcID=79393,x=0.842,y=0.304,zoneID=6662}},coords={x=0.75,y=0.31,source="quest_giver",zoneID=6662},questType="standard"},
[34815] = {id=34815,name="Making Acquaintances",level=20,requiredLevel=20,faction="alliance",expansion=5,zoneID=6662,description="It's nice to see someone else taking a vested interest in the arcane arts, you know. It's all too rare these days if you ask me. Unfortunately, I must meet Cordana to handle an important matter, but we're in luck! One of my good friends in the Kirin Tor has agreed to help you connect your arcane sanctum to the ley line network. She's waiting at my tower. Let's leave immediately and introduce you to one another.",starts={{npcID=80142,x=0.75,y=0.31,zoneID=6662}},ends={{npcID=79392,x=0.848,y=0.31,zoneID=6662}},coords={x=0.75,y=0.31,source="quest_giver",zoneID=6662},questType="standard"},
[34818] = {id=34818,name="They Call Him Lantresor of the Blade",level=35,requiredLevel=35,faction="horde",expansion=5,zoneID=6755,description="The garrison blueprints were taken to the Burning Blade village when the Warsong sacked your caravan. I can't construct this building without those plans. There's been talk of a young blademaster who's been exiled from the clan for many years. They call him Lantresor of the Blade . Our scouts recently saw him return to Hallvalor to challenge the blademaster leadership. Instead, they clapped him in chains. Maybe he's still alive. Maybe he'll help you recover the blueprints?",starts={{npcID=80140,x=0.828,y=0.442,zoneID=6755}},ends={{npcID=80161,x=0.854,y=0.546,zoneID=6755}},coords={x=0.828,y=0.442,source="quest_giver",zoneID=6755},questType="standard"},
[34819] = {id=34819,name="Fruitful Ventures",level=35,requiredLevel=35,faction="both",expansion=5,zoneID=6755,description="Oh no! They must be vegetarians. What these elekk need is fruit and lots of it. There are cherries all over the place around here under the trees. You wouldn't mind grabbing me some, would ya?",starts={{npcID=81955,x=0.792,y=0.526,zoneID=6755}},ends={{npcID=81955,x=0.792,y=0.526,zoneID=6755}},coords={x=0.792,y=0.526,source="quest_giver",zoneID=6755},questType="standard"},
[34820] = {id=34820,name="Lost Lumberjacks",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=6719,description="Shelly and her crew haven't returned from Gloomshade Grove. It's been days... I hope everything is okay.",starts={{npcID=80163,x=0.382,y=0.642,zoneID=7078}},ends={{npcID=79966,x=0.396,y=0.296,zoneID=6719}},coords={x=0.382,y=0.642,source="quest_giver",zoneID=7078},questType="standard"},
[34821] = {id=34821,name="Khadgar Summon",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6662,mapID=535,questType="standard"},
[34822] = {id=34822,name="What We Need",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=15347,description="I heard you guys hijacked and wrecked a ship on your way out of Tanaan. It's like my daddy always said: One man's wreck is another goblin's workshop. You should head down to the coast west of the garrison and see if you can't find any materials we might salvage. Oh, and uh... should probably watch yourself. I hear there are ogre raiders in the area.",starts={{npcID=78466,x=0.488,y=0.65,zoneID=6720},{npcID=78466,x=0.42,y=0.55,zoneID=7004}},ends={{npcID=78466,x=0.488,y=0.65,zoneID=6720},{npcID=78466,x=0.42,y=0.55,zoneID=7004}},coords={x=0.488,y=0.65,source="quest_giver",zoneID=6720},questType="standard"},
[34823] = {id=34823,name="The Ogron Live?",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=6720,description="Commander, our Frostwolf allies reportin' dat the Bladespire ogres have an outpost to our west led by an ogron. I heard tales of da ogron but never seen one. Dey be brutes, creatures from a time that was best left forgotten. Dey say most were slain during the forming of the original horde. What dey lack in wisdom they make up for in violence, force, and greed. I counsel dispatchin' dis creature as soon as possible.",starts={{npcID=78487,x=0.456,y=0.432,zoneID=7004}},ends={{npcID=78487,x=0.456,y=0.432,zoneID=7004}},coords={x=0.456,y=0.432,source="quest_giver",zoneID=7004},questType="standard"},
[34824] = {id=34824,name="What We Got",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=7004,description="Every fortress needs three things. One: peons! Find Skaggit and have him get our peons back to work. Two: building materials. I had the peons set up a cache for you where they will store resources they create while you are away. You should check it out. And three: raw experienced muscle! Constructing buildings in a garrison can take some time but I think we can speed up your first building by hiring Skaggit 's recently promoted Senior Peon II . Find him and tell him I sent ya.",starts={{npcID=78466,x=0.488,y=0.65,zoneID=6720},{npcID=78466,x=0.42,y=0.55,zoneID=7004}},ends={{npcID=78466,x=0.488,y=0.65,zoneID=6720},{npcID=78466,x=0.42,y=0.55,zoneID=7004}},coords={x=0.488,y=0.65,source="quest_giver",zoneID=6720},questType="standard"},
[34825] = {id=34825,name="Vignette: Gruuk",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6720,mapID=525,questType="standard"},
[34826] = {id=34826,name="The Friend of My Enemy",level=35,requiredLevel=35,faction="horde",expansion=5,zoneID=6755,description="Hallvalor is the ancestral home of the Burning Blade clan. Since they're such fast friends, the Warsong have allowed the blademasters to remain in Nagrand . We are fierce, but we won't win if the Burning Blade attack us. It would be wise to strike first.",starts={{npcID=80003,x=0.828,y=0.45,zoneID=6755}},ends={{npcID=80003,x=0.828,y=0.45,zoneID=6755}},coords={x=0.828,y=0.45,source="quest_giver",zoneID=6755},questType="standard"},
[34827] = {id=34827,name="Last of the Talonpriests",level=30,requiredLevel=30,faction="both",expansion=5,zoneID=6722,description="Talonpriests live among us in secret, guarding the rites of the Talon King's return. The Adherent proclamation you acquired in Skettis revealed two of them living in the Shadowglade to the north. Orcs have moved into the region, and the Adherent's beam weapon left Veil Akraz a smoking crater. As you can see, my people are beset by enemies on all sides. Talonpriest Ishaal survived and is in hiding. Drink this elixir near his hut to peer into the shadows and make contact with him.",starts={{npcID=80153,x=0.458,y=0.456,zoneID=6722}},ends={{npcID=80232,x=0.48,y=0.346,zoneID=6722}},coords={x=0.458,y=0.456,source="quest_giver",zoneID=6722},questType="standard"},
[34828] = {id=34828,name="Ishaal's Orb",level=30,requiredLevel=30,faction="both",expansion=5,zoneID=6722,description="The Adherents came for me, but I was already hiding. I watched from the shadows as they ransacked my hut. Then I watched the Shattered Hand orcs arrive and butcher them like dinner fowl. Seems everyone is after us these days. One of those orc thugs made off with my scrying orb. I will be needing it back if I am to be of any use to Iskar.",starts={{npcID=80232,x=0.48,y=0.346,zoneID=6722}},ends={{npcID=80232,x=0.48,y=0.346,zoneID=6722}},coords={x=0.48,y=0.346,source="quest_giver",zoneID=6722},questType="standard"},
[34829] = {id=34829,name="New Neighbors",level=30,requiredLevel=30,faction="both",expansion=5,zoneID=6722,description="The Shattered Hand clan is made up of orcs who can call no other clan home. They are sadistic warriors who maim their bodies, perhaps in a show of solidarity or perhaps because they simply enjoy the pain. It does not matter. What matters is that they are expanding their territory, butchering anyone in their path. They must be dealt with.",starts={{npcID=80232,x=0.48,y=0.346,zoneID=6722}},ends={{npcID=80232,x=0.48,y=0.346,zoneID=6722}},coords={x=0.48,y=0.346,source="quest_giver",zoneID=6722},questType="standard"},
[34830] = {id=34830,name="Behind the Veil",level=30,requiredLevel=30,faction="both",expansion=5,zoneID=6722,description="Soon after the orcs swept in, Veil Akraz was laid to waste by a beam of light from Skyreach. It seems they missed their true target. Zellek is still there, hiding in the realm of shadow. And... someone else as well. The orc assassin who used my orb. Take this. Drink it in Veil Akraz and find Zellek. Oh, and be careful. It's a little more potent than the last one. You'll see...",starts={{npcID=80232,x=0.48,y=0.346,zoneID=6722}},ends={{npcID=80508,x=0.444,y=0.24,zoneID=6722}},coords={x=0.48,y=0.346,source="quest_giver",zoneID=6722},questType="standard"},
[34831] = {id=34831,name="Encounter Mushroom",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6662,mapID=535,questType="standard"},
[34833] = {id=34833,name="Prune Ancient",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6662,mapID=535,questType="standard"},
[34834] = {id=34834,name="General Commentary",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6662,mapID=535,questType="standard"},
[34835] = {id=34835,name="Gather Energy",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6662,mapID=535,questType="standard"},
[34836] = {id=34836,name="Lunarblossom",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=6719,mapID=539,description="How I long to hold Kat'la. No star or moon can compare to her beauty. Alas, I am but a simple boar farmer. If only I could find time to sneak away from this pathetic excuse for a job and pick some lunarblossoms for Kat'la. I wouldn't dare confess my love to her without a gift.",starts={{npcID=80248,x=0.464,y=0.252,mapID=539}},ends={{npcID=80248,x=0.464,y=0.252,mapID=539}},coords={x=0.464,y=0.252,source="quest_giver",mapID=539},questType="standard"},
[34837] = {id=34837,name="Going to the Gordunni",level=20,requiredLevel=20,faction="horde",expansion=5,zoneID=6662,description="We have a good supply of jovite in the arsenal now but there just isn't enough of the material in the mine to keep us in stock for long. Down south of here there's a mountain that's just full of the stuff but there's one problem; Ogres! The Gordunni live on top of that mountain and they have begun trading the jovite to the Iron Horde. We need to go down there and secure the minerals for ourselves. I'll pack some supplies and meet you near their fortress down south.",starts={{npcID=79356,x=0.708,y=0.304,zoneID=6662}},ends={{npcID=80229,x=0.622,y=0.692,zoneID=6662}},coords={x=0.708,y=0.304,source="quest_giver",zoneID=6662},questType="standard"},
[34838] = {id=34838,name="Ikky's Egg",level=30,requiredLevel=30,faction="both",expansion=5,zoneID=6722,description="A small tag has been lovingly tied around the base of the egg. It reads \" Ikky .\">",ends={{npcID=80469,x=0.454,y=0.366,zoneID=6722}},questType="standard"},
[34839] = {id=34839,name="Vignette: Skog",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6720,mapID=525,questType="standard"},
[34840] = {id=34840,name="Dropping Bombs",level=20,requiredLevel=20,faction="horde",expansion=5,zoneID=6723,description="The Gordunni have only a single path to their fortress and it is well-defended from a large attack. Thankfully they wont be expecting just the two of us to be attempting to break in. This is a great opportunity to take out their defenses and get some target practice for our artillery gunners back at the arsenal. Take these smoke grenades and use it to call in an artillery strike on their catapults as we head up.",starts={{npcID=80229,x=0.622,y=0.692,zoneID=6662}},ends={{npcID=80339,x=0.686,y=0.704,zoneID=6662}},coords={x=0.622,y=0.692,source="quest_giver",zoneID=6662},questType="standard"},
[34841] = {id=34841,name="Treasure: Ice-Covered Supplies",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6720,mapID=525,ends={{npcID=230909,x=0.437,y=0.556,mapID=525}},questType="standard"},
[34843] = {id=34843,name="Vignette: Chillfang",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6720,mapID=525,questType="standard"},
[34847] = {id=34847,name="Forbidden Love",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=6719,mapID=539,description="My son, Kral'za, is beyond stubborn. After we split from the Shadowmoon Clan he refused to let go of his relationship with a young Shadowmoon orc. I forbid him to see her anymore. He ran off earlier today and has not returned. I don't trust Dol'mak . Like the other Shadowmoon orcs she continues to dabble in the void.",starts={{npcID=77211,x=0.46,y=0.254,mapID=539}},ends={{npcID=77211,x=0.46,y=0.254,mapID=539}},coords={x=0.46,y=0.254,source="quest_giver",mapID=539},questType="standard"},
[34849] = {id=34849,name="The Blade Itself",level=35,requiredLevel=35,faction="horde",expansion=5,zoneID=6755,description="When they clapped me in irons, the Burning Blade instructor, Luhk the Keen-Eyed, took my blade. He's an honorable orc, even if his training techniques are counter-productive. I want my blade back, . Then, I'll break myself free.",starts={{npcID=80161,x=0.854,y=0.546,zoneID=6755}},ends={{npcID=80161,x=0.854,y=0.546,zoneID=6755}},coords={x=0.854,y=0.546,source="quest_giver",zoneID=6755},questType="standard"},
[34850] = {id=34850,name="Not Without My Honor",level=35,requiredLevel=35,faction="horde",expansion=5,zoneID=6755,description="The blade is not the only important item a blademaster carries. Once he has passed his final tests in the Masters' Caverns, the blademaster is given the honor of wearing the Burning Blade's banner. When my petition to reclaim my rightful place with the clan fell upon deaf and craven ears, I was stripped of that honor. No doubt, my banner has been stored away somewhere in Hallvalor. They'll give it to some other aspiring blademaster if they don't burn it first.",starts={{npcID=80161,x=0.854,y=0.546,zoneID=6755}},ends={{npcID=80161,x=0.854,y=0.546,zoneID=6755}},coords={x=0.854,y=0.546,source="quest_giver",zoneID=6755},questType="standard"},
[34851] = {id=34851,name="Vignette: Gruuk",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6720,mapID=525,description="Goren are dangerous, especially in large numbers, and especially when we have a blind, under powered shaman with us. Fortunately, they have very short lifespans. Unfortunately, they multiply fast and grow faster. If we are going to do this we need to find the brood mother. Slaying her and her eggs should slow down the onslaught of goren. Check the burrows near the Forge Gates and I will to keep them off of Drek'Thar's scent.",questType="standard"},
[34855] = {id=34855,name="Punching Through",level=20,requiredLevel=20,faction="horde",expansion=5,zoneID=6662,description="To secure the fortress we need to kill Witch Lord Morkurk, but I don't think we should go straight after him. His three lieutenants - Vorgorsh, Zulmork, and Cromaug - are all powerful mages, and all of them are fiercely loyal to Morkurk. I suspect that if we engage the Witch Lord that they will rush to his aid. Let's take them out so that cannot happen.",starts={{npcID=80339,x=0.686,y=0.704,zoneID=6662}},coords={x=0.686,y=0.704,source="quest_giver",zoneID=6662},questType="standard"},
[34857] = {id=34857,name="Tracking Flag: Orcs Kicked Out of Cave",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6662,mapID=535,questType="standard"},
[34858] = {id=34858,name="Prized Repossessions",level=20,requiredLevel=20,faction="horde",expansion=5,zoneID=6662,description="The Gordunni were given copies of my blades as a gift from the Iron Horde. But what do they use them for? Toothpicks! Sure the blades are low grade copies but it's still MY design and I can't stand to think of them in those ogre hands for a moment longer! , While we are in here can you do me a favor and get those blades out of their hands!",starts={{npcID=80339,x=0.686,y=0.704,zoneID=6662}},coords={x=0.686,y=0.704,source="quest_giver",zoneID=6662},questType="standard"},
[34859] = {id=34859,name="Vignette: No'losh",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6720,mapID=525,questType="standard"},
[34860] = {id=34860,name="Supply Recovery",level=20,requiredLevel=20,faction="horde",expansion=5,zoneID=6662,description="We seem to have arrived at just the right time! The Gordunni have been enchanting armaments for the Iron Horde and it looks like they haven't picked up the latest shipment. We could put that gear to far better use! Lets go hunt down their shipping containers. I brought some signal flares that we can use to call in an air pick-up when we've secured the shipment.",starts={{npcID=80339,x=0.686,y=0.704,zoneID=6662}},coords={x=0.686,y=0.704,source="quest_giver",zoneID=6662},questType="standard"},
[34861] = {id=34861,name="We Need An Army",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=7004,description="So the new warchief decided to send you Warmaster Zog to handle local operations. Zog! I heard that guy was notorious for organizing the Alliance AND the Horde to face off against the silithid at the Gates of Ahn'Qiraj. He was a general back then. Anyway, if you go let him know about the barracks being done I'm sure he'll have some thoughts on how to put it to good use. You can find Zog up at the town hall.",starts={{npcID=78466,x=0.488,y=0.65,zoneID=6720},{npcID=78466,x=0.42,y=0.55,zoneID=7004}},ends={{npcID=79740,x=0.538,y=0.542,zoneID=7004}},coords={x=0.488,y=0.65,source="quest_giver",zoneID=6720},questType="standard"},
[34862] = {id=34862,name="Vignette: Light the Braziers",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6755,mapID=550,questType="standard"},
[34865] = {id=34865,name="Vignette: Skog",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6720,mapID=525,questType="standard"},
[34866] = {id=34866,name="Meet Me in the Cavern",level=35,requiredLevel=35,faction="horde",expansion=5,zoneID=6755,description="It's time, . Time for you to get your blueprints. Time for us to face the masters.",questType="standard"},
[34867] = {id=34867,name="The Secrets of Gorgrond",level=15,requiredLevel=15,faction="horde",expansion=5,zoneID=6721,description="Commander, I will leave my forces to secure this pass, but I will not sit idle while our enemy prepares for another attack. I want to take the fight to the heart of the Iron Horde at Blackrock, and to do that we are going to need to go where few orcs dare tread. Gorgrond . It is a savage place, filled with giants and monsters of every sort. Will you dare these wilds with me so that we might strike at the foundries of the Iron Horde?",starts={{npcID=76484,x=0.75,y=0.558,zoneID=6720},{npcID=88120,x=0.78,y=0.548,zoneID=6720}},ends={{npcID=74594,x=0.372,y=0.77,zoneID=6721}},coords={x=0.75,y=0.558,source="quest_giver",zoneID=6720},questType="standard"},
[34868] = {id=34868,name="Challenge of the Masters",level=35,requiredLevel=35,faction="horde",expansion=5,zoneID=6755,description="The time has come to challenge the Burning Blade masters. Go to the back of the cavern. There you will find the challenge ring and the masters watching over it from above. Pull the blade from the middle of the ring to issue your challenge. My clan values honor above all else and will respect your claim to trial by combat. As reward, you will be allowed to walk away with your blueprints and your life. Or, you will be dead.",questType="standard"},
[34869] = {id=34869,name="Tastes Like Chicken",level=35,requiredLevel=35,faction="both",expansion=5,zoneID=6755,description="You got a moment, ? I've got an elekk-sized problem. Someone, um, sold me... yeah, sold me these two, but they're sick. I've tried everything, but nothing I do makes any difference! I think they must be starving. I heard that elekk like raw windroc . Gross if you ask me. Anyway, while you're out doing your thing, you mind picking me up some bird meat?",starts={{npcID=81955,x=0.792,y=0.526,zoneID=6755}},ends={{npcID=81955,x=0.792,y=0.526,zoneID=6755}},coords={x=0.792,y=0.526,source="quest_giver",zoneID=6755},questType="standard"},
[34870] = {id=34870,name="The Lord of the Gordunni",level=20,requiredLevel=20,faction="horde",expansion=5,zoneID=6662,description="Witch Lord Morkurk is the leader of the Gordunni. He's the one that set up the Iron Horde trade and, even worse, my former boss gave him one of my best maces! We got to get my mace back! I mean... we need to kill him to secure the jovite for your arsenal! Morkurk is an accomplished mage so you better be prepared. Here, take the rocket pack and use it if you need to dodge an attack quickly or something. Also, if you happen to find my mace I'd like to get it back.",ends={{npcID=80342,x=0.644,y=0.816,zoneID=6662}},questType="standard"},
[34871] = {id=34871,name="Supply Recovery Tracking",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6662,mapID=535,questType="standard"},
[34872] = {id=34872,name="Prized Repossessions Tracking",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6662,mapID=535,questType="standard"},
[34873] = {id=34873,name="Punching Through Tracking",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6662,mapID=535,questType="standard"},
[34874] = {id=34874,name="Next Steps",level=20,requiredLevel=20,faction="horde",expansion=5,zoneID=6662,description="You are positively on fire! We have everything I need to create the scroll. Your arcane sanctum will be brimming with arcane energy in no time. I will teleport to Vol'jin's Pride to combine the reagents and marshal your forces. Meet me there when you can.",starts={{npcID=80193,x=0.841,y=0.302,zoneID=6662}},ends={{npcID=80965,x=0.712,y=0.296,zoneID=6662}},coords={x=0.841,y=0.302,source="quest_giver",zoneID=6662},questType="standard"},
[34875] = {id=34875,name="Next Steps",level=20,requiredLevel=20,faction="alliance",expansion=5,zoneID=6662,description="We did it! We have all of the reagents for the scroll. Your arcane sanctum will be the talk of Draenor before long. I'll go back to Fort Wrynn to finish it and gather your men. Meet me there.",starts={{npcID=80260,x=0.849,y=0.309,zoneID=6662}},ends={{npcID=80966,x=0.696,y=0.21,zoneID=6662}},coords={x=0.849,y=0.309,source="quest_giver",zoneID=6662},questType="standard"},
[34876] = {id=34876,name="Loola's Lost Love",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=6719,description="Oh it was horrible. My husband and I were fishing in the marsh, I fell asleep and when I woke up he had been turned into a toad! I'm sure it was one of those Shadowmoon orcs I hear so much about. He jumped into the muddy waters before I could catch him. Will you help me find my lost love, ?",starts={{npcID=71641,x=0.412,y=0.55,zoneID=6719}},ends={{npcID=71641,x=0.412,y=0.55,zoneID=6719}},coords={x=0.412,y=0.55,source="quest_giver",zoneID=6719},questType="standard"},
[34877] = {id=34877,name="Removing the Reinforcements",level=35,requiredLevel=35,faction="alliance",expansion=5,zoneID=6755,description="My own investigations have uncovered a permanent arcane portal from here to Highmaul itself. It is guarded but shouldn't be too hard to disrupt once you've gotten some breathing room.",starts={{npcID=81144,x=0.84,y=0.768,zoneID=6755}},ends={{npcID=79576,x=0.634,y=0.618,zoneID=6755},{npcID=79674,x=0.63,y=0.62,zoneID=6755}},coords={x=0.84,y=0.768,source="quest_giver",zoneID=6755},questType="standard"},
[34878] = {id=34878,name="The Foot of the Fortress",level=20,requiredLevel=20,faction="horde",expansion=5,zoneID=6662,description="We've enkindled your forces and the scroll is ready. It's time for phase two - stealing a nexus crystal from a heavily fortified ogre compound. We'll save the scroll to bring in reinforcements in our confrontation with the Gordunni Witch Lord. Let's meet at the base of the Gordal Foothills and take what is more or less rightfully yours!",starts={{npcID=80965,x=0.712,y=0.296,zoneID=6662}},ends={{npcID=80396,x=0.622,y=0.682,zoneID=6662}},coords={x=0.712,y=0.296,source="quest_giver",zoneID=6662},questType="standard"},
[34879] = {id=34879,name="Dropping In",level=20,requiredLevel=20,faction="horde",expansion=5,zoneID=6662,description="Witch Lord Morkurk is no fool. He has catapults set up throughout the foothills leading into their compound. No matter, I have a way to handle them. Take out the ogres guarding the siege weapons and mark them once they're clear. I'm readying a vortex spell that will handle things from there. We'll meet just outside their gate afterwards.",starts={{npcID=80396,x=0.622,y=0.682,zoneID=6662}},ends={{npcID=80390,x=0.682,y=0.702,zoneID=6662}},coords={x=0.622,y=0.682,source="quest_giver",zoneID=6662},questType="standard"},
[34881] = {id=34881,name="Earth, Wind and Fire...and Water",level=35,requiredLevel=35,faction="both",expansion=5,zoneID=6755,description="The Elemental Plateau has become unstable, and so the cycle of rebirth must begin. It is a natural part of our life cycle that impurities are accumulated in the elemental body over time. When enough contamination has taken place, an elemental will become unstable and in some cases volatile. A necessary part of rebirth is pure, living essence which can be found atop the Elemental Plateau, as well as in the body of an elemental spirit. Return to me with the essence and we shall begin the rebirth.",starts={{npcID=80593,x=0.714,y=0.18,zoneID=6755}},ends={{npcID=80593,x=0.714,y=0.18,zoneID=6755}},coords={x=0.714,y=0.18,source="quest_giver",zoneID=6755},questType="standard"},
[34882] = {id=34882,name="Blades in the Dark",level=30,requiredLevel=30,faction="both",expansion=5,zoneID=6722,description="Those orcs got hold of Ishaal's orb, did they? That would explain the dangerous-looking fellow who crossed into this realm shortly before you. Not everyone handles the transition as... gracefully as you did. The oaf is still grappling with his own mind, stumbling about and muttering nonsense. Soon he will be drawn to the orb again, which would presumably lead him to Veil Terokk. Better to take him out now while he's still befuddled.",starts={{npcID=80508,x=0.444,y=0.24,zoneID=6722}},ends={{npcID=80508,x=0.444,y=0.24,zoneID=6722}},coords={x=0.444,y=0.24,source="quest_giver",zoneID=6722},questType="standard"},
[34883] = {id=34883,name="A Feast of Shadows",level=30,requiredLevel=30,faction="both",expansion=5,zoneID=6722,description="Many arakkoa died in Veil Akraz. From the outside, all seems still. Empty. But in this place between worlds, death never goes unnoticed. Stray life essence seeps through from the other side; a feast for the beings who prowl here. Slay the shadow creatures here, and gather from their corpses the fine dust they produce. I will need much of it to perform the rites of the Talon King.",starts={{npcID=80508,x=0.444,y=0.24,zoneID=6722}},ends={{npcID=80508,x=0.444,y=0.24,zoneID=6722}},coords={x=0.444,y=0.24,source="quest_giver",zoneID=6722},questType="standard"},
[34884] = {id=34884,name="The Kaliri Whisperer",level=30,requiredLevel=30,faction="both",expansion=5,zoneID=6722,description="An important contact lives in the nearby Shadowglade. He is meek, but trains kaliri of monstrous size which are quite dangerous. He once claimed they could knock a rylak out of the sky, but I'll believe that when I see it. Skizzik is holding a valuable treasure for me. Seek him out and get him back to Veil Terokk if you can. At the very least, recover the gavel I entrusted to him.",starts={{npcID=81770,x=0.464,y=0.466,zoneID=6722}},ends={{npcID=81770,x=0.464,y=0.466,zoneID=6722}},coords={x=0.464,y=0.466,source="quest_giver",zoneID=6722},questType="standard"},
[34885] = {id=34885,name="Mother of Thorns",level=30,requiredLevel=30,faction="both",expansion=5,zoneID=6722,description="Skizzik 's outstretched hand, letters are scrawled into the dirt: t h o r n m o t h e r Ravagers brought in by the Shattered Hand have taken over the aviary and are breeding fast. If left alone, they could be swarming the entire area - including Veil Terokk - in a matter of days.>",starts={{npcID=80233,x=0.454,y=0.364,zoneID=6722}},ends={{npcID=81770,x=0.464,y=0.466,zoneID=6722}},coords={x=0.454,y=0.364,source="quest_giver",zoneID=6722},questType="standard"},
[34886] = {id=34886,name="Baby Bird",level=30,requiredLevel=30,faction="both",expansion=5,zoneID=6722,description="Ikky cheeps again, then begins gnawing on his foot. Looking out across the nearby hillside, you spy tiny ravager grubs inching along the grass.>",starts={{npcID=80469,x=0.454,y=0.366,zoneID=6722}},ends={{npcID=80469,x=0.454,y=0.366,zoneID=6722}},coords={x=0.454,y=0.366,source="quest_giver",zoneID=6722},questType="standard"},
[34887] = {id=34887,name="While We're in the Neighborhood",level=20,requiredLevel=20,faction="horde",expansion=5,zoneID=6662,description="Ah, the hubris of ogres. It always backfires. Morkurk has been using enchanted bracelets to empower his minions with arcane strength. We can disenchant these bracelets into reagents that will no doubt be useful to your arcane sanctum. What do you think about collecting some while we're here?",starts={{npcID=80390,x=0.682,y=0.702,zoneID=6662}},ends={{npcID=80389,x=0.683,y=0.703,zoneID=6662}},coords={x=0.682,y=0.702,source="quest_giver",zoneID=6662},questType="standard"},
[34888] = {id=34888,name="Vicious Viziers",level=20,requiredLevel=20,faction="horde",expansion=5,zoneID=6662,description="We're after Witch Lord Morkurk, but we shouldn't charge straight at him. His three lieutenants - Vorgorsh, Zulmork, and Cromaug - are the only other capable mages left of the Gordunni, and are fiercely loyal to Morkurk. I suspect that if we engage the Witch Lord that they will rush to his aid. Let's take them out first.",starts={{npcID=80390,x=0.682,y=0.702,zoneID=6662}},ends={{npcID=80389,x=0.683,y=0.703,zoneID=6662}},coords={x=0.682,y=0.702,source="quest_giver",zoneID=6662},questType="standard"},
[34889] = {id=34889,name="Orbs of Power",level=20,requiredLevel=20,faction="horde",expansion=5,zoneID=6662,description="There's a minor fire we'll need to put out before we can enact my plan. Morkurk has placed powerful wards throughout Gordal Fortress that will prevent any sort of mass summoning - awfully detrimental to our scroll of mass teleportation. Thankfully, no ogre would ever consider that a single enemy or two would have the gall to breach their walls.",starts={{npcID=80390,x=0.682,y=0.702,zoneID=6662}},ends={{npcID=80389,x=0.683,y=0.703,zoneID=6662}},coords={x=0.682,y=0.702,source="quest_giver",zoneID=6662},questType="standard"},
[34890] = {id=34890,name="The Final Step",level=20,requiredLevel=20,faction="horde",expansion=5,zoneID=6662,description="It's time to fight fire with fire. We have Morkurk cornered. His protections gone. Use the scroll once you engage Morkurk... ...and enjoy the fireworks.",starts={{npcID=80389,x=0.683,y=0.703,zoneID=6662}},ends={{npcID=80389,x=0.683,y=0.703,zoneID=6662}},coords={x=0.683,y=0.703,source="quest_giver",zoneID=6662},questType="standard"},
[34891] = {id=34891,name="Elemental Attunement",level=35,requiredLevel=35,faction="horde",expansion=5,zoneID=6755,description="Many shaman have sought the favor of the Throne of Elements. Forming an elemental bond with the furies allows a shaman to not only know the will of the elements on Draenor, but also tap into a great font of elemental power. If you are to discover the truth behind Gordawg's disappearance, you will need to succeed where others have failed and undertake the Ritual of Binding. First, you must prepare yourself. Seek out the elemental pillars upon the plateau and attune your spirit with the elements.",starts={{npcID=80597,x=0.718,y=0.196,zoneID=6755}},ends={{npcID=80597,x=0.718,y=0.196,zoneID=6755}},coords={x=0.718,y=0.196,source="quest_giver",zoneID=6755},questType="standard"},
[34893] = {id=34893,name="Guardians of the Plateau",level=35,requiredLevel=35,faction="both",expansion=5,zoneID=6755,description="The Elemental Plateau is sanctuary to the elemental spirits of Nagrand . The greatest among the elementals on the plateau are the guardians; mighty elemental spirits that stand watch over their domain. The guardians are pure and mighty spirits but a disturbance in the natural balance has caused them to grow unstable, corrupting the lesser elementals around them. In order to restore balance to the plateau, the guardians must be destroyed. Only then will the cycle of rebirth begin.",starts={{npcID=80593,x=0.714,y=0.18,zoneID=6755}},ends={{npcID=80593,x=0.714,y=0.18,zoneID=6755}},coords={x=0.714,y=0.18,source="quest_giver",zoneID=6755},questType="standard"},
[34894] = {id=34894,name="A Rare Bloom",level=35,requiredLevel=35,faction="both",expansion=5,zoneID=6755,description="Many years ago I had a life-mate, Dahaka. We were only bound a short time before she was taken from me. I have lived long, but I have never known greater pain than that day. I was young and my grief was great; the earth quaked beneath my rage. I laid her to rest upon this cliff. It is here where I too will rest, but first a favor. A rare bloom grows in a cave within the fiery, molten earth of the plateau. It was her favorite. I would lay the flower upon her grave one last time before I die.",starts={{npcID=80434,x=0.75,y=0.228,zoneID=6755}},ends={{npcID=80434,x=0.75,y=0.228,zoneID=6755}},coords={x=0.75,y=0.228,source="quest_giver",zoneID=6755},questType="standard"},
[34895] = {id=34895,name="Dropping Bombs Tracking",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6662,mapID=535,questType="standard"},
[34896] = {id=34896,name="Tracking Quest - Stealthed Rangari",level=1,requiredLevel=1,faction="alliance",expansion=5,zoneID=6719,mapID=539,questType="standard"},
[34897] = {id=34897,name="Rangari Roundup",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=6719,description="You have a keen eye, . There are Rangari like myself hidden throughout the Nightmarsh. I need reports from each of them to ensure the area is safe. Perhaps you can help me?",starts={{npcID=80378,x=0.436,y=0.516,zoneID=6719}},ends={{npcID=73425,x=0.406,y=0.548,zoneID=6719}},coords={x=0.436,y=0.516,source="quest_giver",zoneID=6719},questType="standard"},
[34898] = {id=34898,name="Ikky",level=30,requiredLevel=30,faction="both",expansion=5,zoneID=6722,mapID=542,starts={{npcID=85320,x=0.462,y=0.456,mapID=542}},ends={{npcID=85320,x=0.462,y=0.456,mapID=542}},coords={x=0.462,y=0.456,source="quest_giver",mapID=542},questType="standard"},
[34899] = {id=34899,name="A Choice to Make",level=35,requiredLevel=35,faction="horde",expansion=5,zoneID=6755,description="We're ready to start building. All that we need is for you to make a choice. The blueprints are on the drafting table. Take a look. Then, let me know if we're going to construct a corral or a tankworks.",starts={{npcID=80140,x=0.828,y=0.442,zoneID=6755}},ends={{npcID=80003,x=0.828,y=0.45,zoneID=6755}},coords={x=0.828,y=0.442,source="quest_giver",zoneID=6755},questType="standard"},
[34900] = {id=34900,name="New Babies",level=35,requiredLevel=35,faction="both",expansion=5,zoneID=6755,description="That's better, but there's still something wrong. I'm getting desperate here, . Can I call ya, ? Great. Look, I think I have it now. I know what's wrong. They miss their babies. Yeah! When they first came here, the, uh... the bastard hunters that... abandoned them said they left the babies behind. If we're going to save them from a life of misery, if we're going to save those babies, and turn a tidy profit, we've got to get them some new babies!",starts={{npcID=81955,x=0.792,y=0.526,zoneID=6755}},ends={{npcID=81955,x=0.792,y=0.526,zoneID=6755}},coords={x=0.792,y=0.526,source="quest_giver",zoneID=6755},questType="standard"},
[34904] = {id=34904,name="Portal Vision",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6662,mapID=535,questType="standard"},
[34906] = {id=34906,name="Krelas Summoned",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6662,mapID=535,questType="standard"},
[34907] = {id=34907,name="Vignette/Treasure: Lagoon Pool/Giant Clam",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6720,mapID=525,questType="standard"},
[34908] = {id=34908,name="The Foot of the Fortress",level=20,requiredLevel=20,faction="alliance",expansion=5,zoneID=6662,description="Your forces are at the ready and the scroll is prepared. It's time for phase two - stealing a nexus crystal from a fortified ogre compound. We'll save the scroll to bring in reinforcements in our confrontation with the Gordunni Witch Lord. Let's meet at the base of the Gordal Foothills to head into the fortress proper.",starts={{npcID=80966,x=0.696,y=0.21,zoneID=6662}},ends={{npcID=80607,x=0.622,y=0.682,zoneID=6662}},coords={x=0.696,y=0.21,source="quest_giver",zoneID=6662},questType="standard"},
[34909] = {id=34909,name="While We're in the Neighborhood",level=20,requiredLevel=20,faction="alliance",expansion=5,zoneID=6662,description="Ogres from the empire are known for being cold and calculating. We are fortunate that their calculations are rarely spot on. Morkurk has been using enchanted bracelets to empower his minions with arcane strength. Since we're going to have to dispatch them anyways, we might as well get some reagents out of it.",starts={{npcID=80608,x=0.698,y=0.694,zoneID=6662}},ends={{npcID=80617,x=0.629,y=0.827,zoneID=6662}},coords={x=0.698,y=0.694,source="quest_giver",zoneID=6662},questType="standard"},
[34910] = {id=34910,name="Vicious Viziers",level=20,requiredLevel=20,faction="alliance",expansion=5,zoneID=6662,description="We can't just skate in, kill Witch Lord Morkurk, and leave. His three lieutenants - Vorgorsh, Zulmork, and Cromaug - are all fiercely loyal to Morkurk, and are all respectable mages in their own right. I suspect that if we attempt to engage the Witch Lord immediately that they will rush to his aid and overwhelm us. We need to take out his lieutenants first.",starts={{npcID=80608,x=0.698,y=0.694,zoneID=6662}},ends={{npcID=80617,x=0.629,y=0.827,zoneID=6662}},coords={x=0.698,y=0.694,source="quest_giver",zoneID=6662},questType="standard"},
[34911] = {id=34911,name="Orbs of Power",level=20,requiredLevel=20,faction="alliance",expansion=5,zoneID=6662,description="Minor issue, I'm afraid. Morkurk has placed powerful wards throughout Gordal Fortress that will prevent any sort of mass summoning - not wonderful considering our plan. Thankfully, no ogre would ever consider that a single enemy or two would attack, so we should be able to slip through their fortress relatively easily.",starts={{npcID=80608,x=0.698,y=0.694,zoneID=6662}},ends={{npcID=80617,x=0.629,y=0.827,zoneID=6662}},coords={x=0.698,y=0.694,source="quest_giver",zoneID=6662},questType="standard"},
[34912] = {id=34912,name="The Final Step",level=20,requiredLevel=20,faction="alliance",expansion=5,zoneID=6662,description="We have Morkurk cornered. He's all ours now. Use the scroll once you engage Morkurk... ...and enjoy the blizzard of your forces raining down on his head.",starts={{npcID=80617,x=0.629,y=0.827,zoneID=6662}},ends={{npcID=80617,x=0.629,y=0.827,zoneID=6662}},coords={x=0.629,y=0.827,source="quest_giver",zoneID=6662},questType="standard"},
[34913] = {id=34913,name="Dropping In",level=20,requiredLevel=20,faction="alliance",expansion=5,zoneID=6662,description="Witch Lord Morkurk, the leader of the fortress, has catapults set up along the road into their compound. That won't be a problem for us. Take out the ogres around the catapults and mark them for me. This vortex spell I have prepared will handle the rest. We'll meet at the gate to the fortress once the catapults are gone.",starts={{npcID=80607,x=0.622,y=0.682,zoneID=6662}},ends={{npcID=80608,x=0.698,y=0.694,zoneID=6662}},coords={x=0.622,y=0.682,source="quest_giver",zoneID=6662},questType="standard"},
[34914] = {id=34914,name="Target of Opportunity: Telaar",level=35,requiredLevel=35,faction="horde",expansion=5,zoneID=6755,description="We've received reports that the draenei enclave at Telaar has fallen to the Warsong. I sent a small group of shadow hunters to check on the situation. Kajassa is their leader. Will you meet her there?",starts={{npcID=81189,x=0.828,y=0.45,zoneID=6755}},ends={{npcID=80429,x=0.686,y=0.644,zoneID=6755}},coords={x=0.828,y=0.45,source="quest_giver",zoneID=6755},questType="standard"},
[34915] = {id=34915,name="I Help Ya Kill Dem",level=35,requiredLevel=35,faction="horde",expansion=5,zoneID=6755,description="Warsong come in an' kill de draenei rangers. No lettin' dem have dis place. You an' me, Commanda. We gonna kill dem all. You be distractin' dem an' I usin' me Loa ta finish dem off. You see.",starts={{npcID=80429,x=0.686,y=0.644,zoneID=6755}},ends={{npcID=80429,x=0.686,y=0.644,zoneID=6755}},coords={x=0.686,y=0.644,source="quest_giver",zoneID=6755},questType="standard"},
[34916] = {id=34916,name="The Blessing of Samedi",level=35,requiredLevel=35,faction="horde",expansion=5,zoneID=6755,description="Three of mah shadow huntas come here wit' me. De Warsong kill dem. We need ta help dey souls move on. Jus' in case ya find dem first, use dis on dere bodies. It send dere souls ta Samedi, Loa of de Grave.",starts={{npcID=80429,x=0.686,y=0.644,zoneID=6755}},ends={{npcID=80429,x=0.686,y=0.644,zoneID=6755}},coords={x=0.686,y=0.644,source="quest_giver",zoneID=6755},questType="standard"},
[34917] = {id=34917,name="Shields Up!",level=35,requiredLevel=35,faction="horde",expansion=5,zoneID=6755,description="The Warsong packleader is trying to raise Telaar's shield. If Kargora does that, the Warsong will have an impervious base. So far, they've only managed to initiate the shield. This has the undesirable side effect of protecting the packleader and her shaman at the main crystal. Activate the crystals on the perimeter of Telaar. That will force the shield to fully deploy. Once you do that, Kargora will be exposed.",starts={{npcID=80451,x=0.686,y=0.644,zoneID=6755}},ends={{npcID=80429,x=0.686,y=0.644,zoneID=6755}},coords={x=0.686,y=0.644,source="quest_giver",zoneID=6755},questType="standard"},
[34918] = {id=34918,name="Shields Down!",level=35,requiredLevel=35,faction="horde",expansion=5,zoneID=6755,description="De time has come, commanda. Packleader Kargora an' de Arkonite Shield no longa protected. We need ta kill her an' destroy de shield crystal.",starts={{npcID=80429,x=0.686,y=0.644,zoneID=6755}},ends={{npcID=80003,x=0.828,y=0.45,zoneID=6755}},coords={x=0.686,y=0.644,source="quest_giver",zoneID=6755},questType="standard"},
[34920] = {id=34920,name="Destroy Ward",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6662,mapID=535,questType="standard"},
[34921] = {id=34921,name="Cult of the Ravenspeakers",level=30,requiredLevel=30,faction="both",expansion=5,zoneID=6722,description="These outcasts are not the only cursed arakkoa holding their ground in Arak. A curious cult has formed in worship of Ka'alu, my consort and the keeper of my brood. They are considered to be quite... odd. Regardless, the outcasts will need their help. Without the wings of the ravens, Iskar can never take his fight to the spires. Take this feather and place it in the offering basket south of here. The so-called \"Ravenspeakers\" will surely take notice.",starts={{npcID=80648,x=0.468,y=0.46,zoneID=6722}},ends={{npcID=80639,x=0.49,y=0.49,zoneID=6722}},coords={x=0.468,y=0.46,source="quest_giver",zoneID=6722},questType="standard"},
[34922] = {id=34922,name="Words of the Raven Mother",level=30,requiredLevel=30,faction="both",expansion=5,zoneID=15347,description="We came here to perform the ritual of calling to bring the return of the Raven Mother. We had distributed parts of the scroll to everyone and had just begun when we were attacked by the Bloodmane. Now most of the flock has been killed and fragments lay scattered across our homeland. The ritual was a failure but we will not allow these mongrels to break our faith. We must continue our prayers here but we would be grateful if you can recover the scroll fragments for us.",starts={{npcID=80740,x=0.548,y=0.542,zoneID=6722}},ends={{npcID=80740,x=0.548,y=0.542,zoneID=6722}},coords={x=0.548,y=0.542,source="quest_giver",zoneID=6722},questType="standard"},
[34923] = {id=34923,name="The Bloodmane",level=30,requiredLevel=30,faction="both",expansion=5,zoneID=6722,description="We had just arrived and begun the service of the headless fowl when the Bloodmane attacked out of nowhere. Clearly, this means that the Raven Mother wishes to test the worthiness of her children. Fear not, we are steadfast and will fervently continue our prayers regardless of what may come! Although, if you can get rid of the Bloodmane and their leader that would be a blessing as well.",starts={{npcID=80740,x=0.548,y=0.542,zoneID=6722}},ends={{npcID=80740,x=0.548,y=0.542,zoneID=6722}},coords={x=0.548,y=0.542,source="quest_giver",zoneID=6722},questType="standard"},
[34924] = {id=34924,name="The Egg Thieves",level=30,requiredLevel=30,faction="both",expansion=5,zoneID=6722,description="The Bloodclaw are sadistic creatures. They have attacked the Ravenskar before and have stolen the eggs of the sacred ravens. While you are within the Bloodclaw lands keep an eye out for the eggs. I'll be waiting for you at the nest with as many baskets for them as I can gather.",starts={{npcID=80863,x=0.548,y=0.542,zoneID=6722}},ends={{npcID=80746,x=0.52,y=0.494,zoneID=6722}},coords={x=0.548,y=0.542,source="quest_giver",zoneID=6722},questType="standard"},
[34925] = {id=34925,name="Polishing the Iron Throne",level=10,requiredLevel=10,faction="both",expansion=5,zoneID=7025,description="These stinking Blackrock cowards think they're humiliating me. They're just making me angrier. Overseer Gotrigg, in the hut over there, carries my shackle key. If I'm going to get out of there, I'm going to need that key. Then... vengeance can begin.",starts={{npcID=79917,x=0.42,y=0.418,zoneID=7025}},ends={{npcID=79917,x=0.42,y=0.418,zoneID=7025}},coords={x=0.42,y=0.418,source="quest_giver",zoneID=7025},questType="standard"},
[34929] = {id=34929,name="Vignette: Gennadian",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6662,mapID=535,questType="standard"},
[34931] = {id=34931,name="Treasure: Frostwolf Cache 04",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6720,mapID=525,ends={{npcID=230611,x=0.216,y=0.507,mapID=525}},questType="standard"},
[34932] = {id=34932,name="Guise of the Deceiver",level=35,requiredLevel=35,faction="both",expansion=5,zoneID=6755,description="In a cave not far from here, there lives an old woman named Challe . I knew Challe many years ago when I was young; though as I have become old and grey, she has kept her youth and beauty. Challe was jealous of my love for Dahaka and I have long suspected that Challe had a part in her death. However, without evidence I could not bring justice against her. Meet with Challe and tell her that I am dying. Tell her that I wish to know the truth of Dahaka's fate before I leave this world.",starts={{npcID=80434,x=0.75,y=0.228,zoneID=6755}},ends={{npcID=80434,x=0.75,y=0.228,zoneID=6755}},coords={x=0.75,y=0.228,source="quest_giver",zoneID=6755},questType="standard"},
[34934] = {id=34934,name="Initial Defenders",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6662,mapID=535,questType="standard"},
[34935] = {id=34935,name="After Wall Greeting",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6662,mapID=535,questType="standard"},
[34936] = {id=34936,name="Treasure: Lady Sena's Extra Stash",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6720,mapID=525,questType="standard"},
[34937] = {id=34937,name="Treasure: Skaggit's Extra Stash",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=7004,mapID=525,ends={{npcID=231064,x=0.748,y=0.556,mapID=525}},questType="standard"},
[34938] = {id=34938,name="Ralshiara's Demise",level=30,requiredLevel=30,faction="both",expansion=5,zoneID=6722,description="It was said in the Journal of the Rising Sun that eating in the mornings cannot be done without harming a few eggs. The Bloodmane matron, Ralshiara , feasts upon sacred raven eggs for her snacks. How dare she! She must die for her sins! Take the path south over the mountains to reach the accursed home of the Bloodmane. Take this trinket, it fell to us from the heavens as a sign of the Raven Mother's favor and with it you might have a chance.",starts={{npcID=80481,x=0.52,y=0.498,zoneID=6722},{npcID=80740,x=0.548,y=0.542,zoneID=6722}},ends={{npcID=80481,x=0.52,y=0.498,zoneID=6722}},coords={x=0.52,y=0.498,source="quest_giver",zoneID=6722},questType="standard"},
[34939] = {id=34939,name="Declawing The Bloodmane",level=30,requiredLevel=30,faction="both",expansion=5,zoneID=6722,description="It is written in the Scroll of Sermons to \"Bite the claw that strikes you.\" Take the path south from here that leads over the mountain to the Bloodmane valley in the west. There you will find those of their tribe who can use a primitive form of magic. Slay them and remove their paws. Once you have obtained a few bring them back to me in the nest so that they may be offered to the Raven Mother!",starts={{npcID=80481,x=0.52,y=0.498,zoneID=6722},{npcID=80860,x=0.548,y=0.542,zoneID=6722}},ends={{npcID=80481,x=0.52,y=0.498,zoneID=6722}},coords={x=0.52,y=0.498,source="quest_giver",zoneID=6722},questType="standard"},
[34940] = {id=34940,name="Treasure: Spider Dagger",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6721,mapID=543,ends={{npcID=231069,x=0.53,y=0.8,mapID=543}},questType="standard"},
[34941] = {id=34941,name="The Debt We Share",level=35,requiredLevel=35,faction="both",expansion=5,zoneID=6755,description="These mortal shells that we call bodies are not ours to keep. The body is a gift of earth that must one day be returned from whence it came. The time has come for this body to return to the elements. Know that you have lifted the weight from an old heart, . As I pass on from this realm, I do so without regret. I have fought on behalf of my people and my land, I have served the elements, and I have loved. It would honor me if you would stay during these final moments, .",starts={{npcID=80434,x=0.75,y=0.228,zoneID=6755}},ends={{npcID=80595,x=0.726,y=0.196,zoneID=6755}},coords={x=0.75,y=0.228,source="quest_giver",zoneID=6755},questType="standard"},
[34942] = {id=34942,name="Back from Beyond",level=30,requiredLevel=30,faction="both",expansion=5,zoneID=6722,description="We must begin preparations for the Talon King's return. From within this realm, I can travel quickly to Veil Terokk. You, however, should be returned to the other side. You are powerful, and will attract unwanted attention.",starts={{npcID=80508,x=0.444,y=0.24,zoneID=6722}},ends={{npcID=80153,x=0.458,y=0.456,zoneID=6722}},coords={x=0.444,y=0.24,source="quest_giver",zoneID=6722},questType="standard"},
[34943] = {id=34943,name="An Old Friend",level=35,requiredLevel=35,faction="both",expansion=5,zoneID=6755,description="Since the beginning, a shaman has been called to serve the Throne of Elements as its keeper. It is a lifelong calling and a new keeper is only called after the last has passed on. Gar'rok has been our loyal keeper for many years, cleansing the Elemental Plateau during countless cycles of rebirth. Our keeper is dying, and soon another will be called in his place. When he passes, he should not be alone. Go to him, . Ease his pain.",starts={{npcID=80595,x=0.726,y=0.196,zoneID=6755}},ends={{npcID=80434,x=0.75,y=0.228,zoneID=6755}},coords={x=0.726,y=0.196,source="quest_giver",zoneID=6755},questType="standard"},
[34946] = {id=34946,name="Morkurk Greeting",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6662,mapID=535,questType="standard"},
[34947] = {id=34947,name="Shredder Manual",level=20,requiredLevel=20,faction="alliance",expansion=5,zoneID=6662,description="Hey! I hear there's a curious object nearby. Scouts say it's some kind of shredder manual. Go check it out for me, will ya? I wonder if it has to do with this new prototype I've been hearin' about...",starts={{npcID=75874,x=0.63,y=0.26,zoneID=6662}},ends={{npcID=225726,x=0.618,y=0.276,zoneID=6662}},coords={x=0.63,y=0.26,source="quest_giver",zoneID=6662},questType="standard"},
[34948] = {id=34948,name="Shredder Manual",level=20,requiredLevel=20,faction="horde",expansion=5,zoneID=6662,description="I've been hearing rumors of this new prototype shredder the Iron Horde's engineers have been working on. I think we ought to investigate. A shadow hunter spotted some sort of shredder manual, and it might have something to do with that prototype.",starts={{npcID=75924,x=0.59,y=0.206,zoneID=6662}},ends={{npcID=225726,x=0.618,y=0.276,zoneID=6662}},coords={x=0.59,y=0.206,source="quest_giver",zoneID=6662},questType="standard"},
[34949] = {id=34949,name="Joining the Ranks",level=20,requiredLevel=20,faction="horde",expansion=5,zoneID=6662,mapID=535,starts={{npcID=80553,x=0.712,y=0.298,mapID=535}},ends={{npcID=80553,x=0.712,y=0.298,mapID=535}},coords={x=0.712,y=0.298,source="quest_giver",mapID=535},questType="standard"},
[34950] = {id=34950,name="Dreadpiston",level=20,requiredLevel=20,faction="horde",expansion=5,zoneID=6662,description="Nearby, a group of Iron Horde took over a key strategic position with surprising alacrity. They used a machine they call Dreadpiston to terrible effect in the siege, and I believe we need to destroy that machine before moving against the Iron Horde in Tuurem.",starts={{npcID=75958,x=0.59,y=0.202,zoneID=6662}},ends={{npcID=75959,x=0.556,y=0.41,zoneID=6662}},coords={x=0.59,y=0.202,source="quest_giver",zoneID=6662},questType="standard"},
[34951] = {id=34951,name="They Call Him Lantresor of the Blade",level=35,requiredLevel=35,faction="alliance",expansion=5,zoneID=6755,description="The Burning Blade clan at Hallvalor is supplying the Warsong with weapons and warriors. We cannot let this continue. There's a young blademaster who's been exiled from the Burning Blade for many years. They call him Lantresor of the Blade . My rangari recently saw him return to Hallvalor to challenge the blademaster leadership. Instead, they clapped him in chains. Maybe he's still alive. Maybe he'll help you deal with the Burning Blade.",starts={{npcID=80624,x=0.634,y=0.618,zoneID=6755}},ends={{npcID=80161,x=0.854,y=0.546,zoneID=6755}},coords={x=0.634,y=0.618,source="quest_giver",zoneID=6755},questType="standard"},
[34952] = {id=34952,name="The Friend o' My Enemy",level=35,requiredLevel=35,faction="alliance",expansion=5,zoneID=6755,description="Hallvalor is the ancestral home o' the Burning Blade clan. Since they be such fast friends, the Warsong allow the blademasters an' their shaman to remain in Nagrand when all o' the other clans are forced out. Blah, blah, blah. I say, if they're the friend o' my enemy, then they're my enemy, and that's all I need to know!",starts={{npcID=79954,x=0.634,y=0.618,zoneID=6755}},ends={{npcID=79954,x=0.634,y=0.618,zoneID=6755}},coords={x=0.634,y=0.618,source="quest_giver",zoneID=6755},questType="standard"},
[34953] = {id=34953,name="Blood of the Burning Blade",level=35,requiredLevel=35,faction="alliance",expansion=5,zoneID=6755,description="Hallvalor is the ancestral home of my clan, the Burning Blade. When the new warlord and his family came to power, I was exiled for being a half-breed. I want justice. I suspect you won't mind killing along the way. Not that you'll have any choice.",starts={{npcID=80161,x=0.854,y=0.546,zoneID=6755}},ends={{npcID=79954,x=0.634,y=0.618,zoneID=6755}},coords={x=0.854,y=0.546,source="quest_giver",zoneID=6755},questType="standard"},
[34954] = {id=34954,name="The Blade Itself",level=35,requiredLevel=35,faction="alliance",expansion=5,zoneID=6755,description="When they clapped me in irons, the Burning Blade instructor, Luhk the Keen-Eyed, took my blade. He's an honorable orc, even if his training techniques are counter-productive. I want my blade back, .",starts={{npcID=80161,x=0.854,y=0.546,zoneID=6755}},ends={{npcID=80161,x=0.854,y=0.546,zoneID=6755}},coords={x=0.854,y=0.546,source="quest_giver",zoneID=6755},questType="standard"},
[34955] = {id=34955,name="Not Without My Honor",level=35,requiredLevel=35,faction="alliance",expansion=5,zoneID=6755,description="The blade is not the only important item a blademaster carries. Once he has passed his final tests in the Masters' Caverns, the blademaster is given the honor of wearing the Burning Blade's banner. When my petition to reclaim my rightful place with the clan fell upon deaf and craven ears, I was stripped of that honor. No doubt, my banner has been stored away somewhere in Hallvalor. They'll give it to some other aspiring blademaster if they don't burn it first.",starts={{npcID=80161,x=0.854,y=0.546,zoneID=6755}},ends={{npcID=80161,x=0.854,y=0.546,zoneID=6755}},coords={x=0.854,y=0.546,source="quest_giver",zoneID=6755},questType="standard"},
[34956] = {id=34956,name="Meet Me in the Cavern",level=35,requiredLevel=35,faction="alliance",expansion=5,zoneID=6755,description="It's time, . Time to face the masters.",questType="standard"},
[34957] = {id=34957,name="Challenge of the Masters",level=35,requiredLevel=35,faction="alliance",expansion=5,zoneID=6755,description="The time has come to challenge the Burning Blade masters. Go to the back of the cavern. There you will find the challenge ring and the masters watching over it from above. Pull the blade from the middle of the ring to issue your challenge. My clan values honor above all else and will respect your claim to trial by combat. As reward, you will be allowed to walk away with your life. Or, you will be dead.",questType="standard"},
[34958] = {id=34958,name="The Shadow of the Worldbreaker",level=10,requiredLevel=10,faction="both",expansion=5,zoneID=7025,description="Looks like we'll soon have another obstacle in our way: that ridiculously large tank that they have pointed at the Dark Portal. The Iron Worldbreaker, I think they call it. If I had some documentation on how it might work, then I might be able to figure out how to shut it down. Maybe some o' those machinists and laborers have some documentation on how it works?",starts={{npcID=78568,x=0.44,y=0.296,zoneID=7025}},ends={{npcID=78568,x=0.44,y=0.296,zoneID=7025}},coords={x=0.44,y=0.296,source="quest_giver",zoneID=7025},questType="standard"},
[34959] = {id=34959,name="Dreadpiston",level=20,requiredLevel=20,faction="alliance",expansion=5,zoneID=6662,description="The Iron Horde overtook a peaceful draenei outpost without mercy. They used a machine they call Dreadpiston to level the town in minutes. Destroy it.",starts={{npcID=75803,x=0.63,y=0.258,zoneID=6662}},ends={{npcID=75803,x=0.63,y=0.258,zoneID=6662}},coords={x=0.63,y=0.258,source="quest_giver",zoneID=6662},questType="standard"},
[34960] = {id=34960,name="The Land Provides",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=7004,description="The icevines of the Shivering Trench have developed a powerful resistance to cold temperatures. Integrating them into the construction materials of the garrison should prove useful.",starts={{npcID=231100,x=0.542,y=0.675,zoneID=6720}},ends={{npcID=78466,x=0.488,y=0.65,zoneID=6720},{npcID=78466,x=0.42,y=0.55,zoneID=7004}},coords={x=0.542,y=0.675,source="quest_giver",zoneID=6720},questType="standard"},
[34962] = {id=34962,name="Khadgar's Plan",level=20,requiredLevel=20,faction="horde",expansion=5,zoneID=6662,description="We have the Iron Horde backed into a corner now, thanks to you. It is almost time to enter the city of Shattrath and repel them. First, we must meet Khadgar and some new allies.",starts={{npcID=75959,x=0.556,y=0.41,zoneID=6662}},ends={{npcID=75805,x=0.542,y=0.364,zoneID=6662}},coords={x=0.556,y=0.41,source="quest_giver",zoneID=6662},questType="standard"},
[34963] = {id=34963,name="Khadgar's Plan",level=20,requiredLevel=20,faction="alliance",expansion=5,zoneID=6662,description="Shattrath must not fall into the hands of the Iron Horde. It is time again for me to get my hands bloody. We will tell Khadgar we are ready to enter the city and take back what is rightfully ours.",starts={{npcID=75803,x=0.63,y=0.258,zoneID=6662}},ends={{npcID=75805,x=0.542,y=0.364,zoneID=6662}},coords={x=0.63,y=0.258,source="quest_giver",zoneID=6662},questType="standard"},
[34964] = {id=34964,name="The Farseer Awaits",level=35,requiredLevel=35,faction="horde",expansion=5,zoneID=6755,description="Your presence has been requested at the Throne of Elements, . Farseer Drek'Thar heard the call of the furies upon the wind and made the journey to commune with the elements. The Farseer has sent word that you are to join him at the Throne of Elements. Go and see what the elements would have of you.",starts={{npcID=80003,x=0.828,y=0.45,zoneID=6755}},ends={{npcID=80597,x=0.718,y=0.196,zoneID=6755}},coords={x=0.828,y=0.45,source="quest_giver",zoneID=6755},questType="standard"},
[34965] = {id=34965,name="Called to the Throne",level=35,requiredLevel=35,faction="horde",expansion=5,zoneID=6755,description="It was not long after I arrived in Nagrand that the voice of Kalandrios called out to me upon the wind. It is a great honor to be called to the Throne of Elements, but my heart was heavy sensing the purpose. There is dark malaise in the air, it can be felt all around us. It surrounds all life here...enveloping...smothering... Come, it is time we commune with the furies and lend them our aid. An invisible shadow has been cast upon this valley and it may be up to us to remove it.",starts={{npcID=80597,x=0.718,y=0.196,zoneID=6755}},ends={{npcID=80597,x=0.718,y=0.196,zoneID=6755}},coords={x=0.718,y=0.196,source="quest_giver",zoneID=6755},questType="standard"},
[34967] = {id=34967,name="Treasure: Raided Loot",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6720,mapID=525,ends={{npcID=231103,x=0.372,y=0.592,mapID=525}},questType="standard"},
[34968] = {id=34968,name="Treasure: Ice-Covered Supplies",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6720,mapID=525,questType="standard"},
[34969] = {id=34969,name="Serena Summoned",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6662,mapID=535,questType="standard"},
[34971] = {id=34971,name="The Only Way to Travel",level=20,requiredLevel=20,faction="horde",expansion=5,zoneID=6662,description="Call me cautious but I kept a few flares just in case we needed to evac. I'm glad that wasn't needed but we could still use the ride back to the arsenal. Are you ready, ?",starts={{npcID=80342,x=0.644,y=0.816,zoneID=6662}},ends={{npcID=80623,x=0.712,y=0.298,zoneID=6662}},coords={x=0.644,y=0.816,source="quest_giver",zoneID=6662},questType="standard"},
[34972] = {id=34972,name="Armor Up",level=20,requiredLevel=20,faction="horde",expansion=5,zoneID=6662,mapID=535,starts={{npcID=80623,x=0.712,y=0.298,mapID=535}},ends={{npcID=80623,x=0.712,y=0.298,mapID=535}},coords={x=0.712,y=0.298,source="quest_giver",mapID=535},questType="standard"},
[34976] = {id=34976,name="Dropping Bombs",level=20,requiredLevel=20,faction="alliance",expansion=5,zoneID=6662,description="The Gordunni have only a single path to their fortress and it is well-defended from a large attack. Thankfully they wont be expecting just the two of us to be attempting to break in. This is a great opportunity to take out their defenses and get some target practice for our gunners back at the artillery tower. Take these smoke grenades and use it to call in an artillery strike on their catapults as we head up.",starts={{npcID=80627,x=0.624,y=0.678,zoneID=6662}},ends={{npcID=80628,x=0.696,y=0.698,zoneID=6662}},coords={x=0.624,y=0.678,source="quest_giver",zoneID=6662},questType="standard"},
[34977] = {id=34977,name="Supply Recovery",level=20,requiredLevel=20,faction="alliance",expansion=5,zoneID=6662,description="We seem to have arrived at just the right time! The Gordunni have been enchanting armaments for the Iron Horde and it looks like they haven't picked up the latest shipment. We could put that gear to far better use in our artillery tower! Lets go hunt down their shipping containers. I brought some signal flares that we can use to call in an air pick-up when we've secured the shipment.",starts={{npcID=80628,x=0.696,y=0.698,zoneID=6662}},coords={x=0.696,y=0.698,source="quest_giver",zoneID=6662},questType="standard"},
[34978] = {id=34978,name="Prized Repossessions",level=20,requiredLevel=20,faction="alliance",expansion=5,zoneID=6662,description="The Gordunni have plagued the people of Shattrath ever since the city was founded. Over time they amassed quite a hoard of weapons they captured from our defenders in raids. Getting these weapons in the hands of our soldiers would be practical and I personally would like to get them out of the hands of the ogres. While we are in here can you do me a favor and gather up any of those weapons you come across.",starts={{npcID=80628,x=0.696,y=0.698,zoneID=6662}},coords={x=0.696,y=0.698,source="quest_giver",zoneID=6662},questType="standard"},
[34979] = {id=34979,name="Punching Through",level=20,requiredLevel=20,faction="alliance",expansion=5,zoneID=6662,description="To secure the fortress we need to kill Witch Lord Morkurk, but I don't think we should go straight after him. His three lieutenants - Vorgorsh, Zulmork, and Cromaug - are all powerful mages, and all of them are fiercely loyal to Morkurk. I suspect that if we engage the Witch Lord that they will rush to his aid. Let's take them out so that cannot happen.",starts={{npcID=80628,x=0.696,y=0.698,zoneID=6662}},coords={x=0.696,y=0.698,source="quest_giver",zoneID=6662},questType="standard"},
[34980] = {id=34980,name="The Lord of the Gordunni",level=20,requiredLevel=20,faction="alliance",expansion=5,zoneID=6662,description="Witch Lord Morkurk is the leader of the Gordunni. We need to kill him to secure the jovite for use in our artillery tower. Morkurk is an accomplished mage so you better be prepared. Here, take the rocket pack and use it if you need to avoid any of his deadly magic. Archenon poros!",ends={{npcID=80630,x=0.644,y=0.816,zoneID=6662}},questType="standard"},
[34981] = {id=34981,name="The Only Way to Travel",level=20,requiredLevel=20,faction="alliance",expansion=5,zoneID=6662,description="Call me cautious but I kept a few flares just in case we needed to quickly escape. I'm glad that wasn't needed but we could still use the ride back to the artillery tower. Are you ready ?",starts={{npcID=80630,x=0.644,y=0.816,zoneID=6662}},ends={{npcID=80968,x=0.696,y=0.208,zoneID=6662}},coords={x=0.644,y=0.816,source="quest_giver",zoneID=6662},questType="standard"},
[34982] = {id=34982,name="Armor Up",level=20,requiredLevel=20,faction="alliance",expansion=5,zoneID=6662,mapID=535,starts={{npcID=80968,x=0.696,y=0.208,mapID=535}},ends={{npcID=80968,x=0.696,y=0.208,mapID=535}},coords={x=0.696,y=0.208,source="quest_giver",mapID=535},questType="standard"},
[34983] = {id=34983,name="Dropping Bombs Tracking",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6662,mapID=535,questType="standard"},
[34984] = {id=34984,name="Supply Recovery Tracking",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6662,mapID=535,questType="standard"},
[34985] = {id=34985,name="Prized Repossessions Tracking",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6662,mapID=535,questType="standard"},
[34986] = {id=34986,name="Punching Through Tracking",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6662,mapID=535,questType="standard"},
[34987] = {id=34987,name="The Gunpowder Plot",level=10,requiredLevel=10,faction="both",expansion=5,zoneID=7025,description="Ey, ! We got an issue, here. Me ol' pal Thaelin's rigged together this here plunger out of spare Blackrock parts - engineerin' whiz that he is - but we're gonna need some gunpowder if we really want ta' do any damage.",starts={{npcID=78569,x=0.44,y=0.296,zoneID=7025}},ends={{npcID=78569,x=0.44,y=0.296,zoneID=7025}},coords={x=0.44,y=0.296,source="quest_giver",zoneID=7025},questType="standard"},
[34991] = {id=34991,name="To the... Rescue?",level=30,requiredLevel=30,faction="both",expansion=5,zoneID=6722,description="The Parchment of Dust reads: \"Put the featherless against one another so that our claws remain unsullied!\" How wise the high Ravenspeaker is to foresee this day. There is a great beast on the hillside to the west by the name of Stonescale. It has abducted one of the flock and despite our many attempts we have been unable to defeat it. Go, prove yourself by slaying the beast and rescuing Tillik! Fulfill your destiny in the name of the Raven Mother!",starts={{npcID=80639,x=0.49,y=0.49,zoneID=6722}},ends={{npcID=80639,x=0.49,y=0.49,zoneID=6722}},coords={x=0.49,y=0.49,source="quest_giver",zoneID=6722},questType="standard"},
[34992] = {id=34992,name="Lumber Mill",level=1,requiredLevel=1,faction="horde",expansion=5,zoneID=6721,mapID=543,questType="standard"},
[34993] = {id=34993,name="Joining the Ranks",level=20,requiredLevel=20,faction="alliance",expansion=5,zoneID=6662,mapID=535,starts={{npcID=80672,x=0.696,y=0.208,mapID=535}},ends={{npcID=80672,x=0.696,y=0.208,mapID=535}},coords={x=0.696,y=0.208,source="quest_giver",mapID=535},questType="standard"},
[34994] = {id=34994,name="Forever Young",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=6719,description="All this sitting around is horrible for business. I have to find a way to recoup some of my lost profits. Those Draenei females are obsessed with the way their horns look. I overheard one of them talking about a root that grows in Blademoon Bloom that supposedly reduces horn shedding or something. I bet I could sell that root to them for a pretty nice profit. I'll give you a cut if you help me get a supply going.",starts={{npcID=80761,x=0.534,y=0.572,zoneID=6719}},ends={{npcID=80761,x=0.534,y=0.572,zoneID=6719}},coords={x=0.534,y=0.572,source="quest_giver",zoneID=6719},questType="standard"},
[34995] = {id=34995,name="Botani Beatdown",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=6719,description="Gidwin is doing much better. Thank you, . I can't believe the draenei have lived alongside those horrible monsters for so long. Maybe we should show these beasts what happens when you mess with an Azerothian.",starts={{npcID=80865,x=0.536,y=0.572,zoneID=6719}},ends={{npcID=80865,x=0.536,y=0.572,zoneID=6719}},coords={x=0.536,y=0.572,source="quest_giver",zoneID=6719},questType="standard"},
[34996] = {id=34996,name="Rotting Riverbeasts",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=6719,description="The botani are infecting the local riverbeasts with some kind of strange flesh-eating plant. I fear this infection could spread to our people. If you see any infested riverbeasts, kill the blooming plants that inhabit their bodies... before they kill you.",starts={{npcID=80859,x=0.526,y=0.596,zoneID=6719}},ends={{npcID=80859,x=0.526,y=0.596,zoneID=6719}},coords={x=0.526,y=0.596,source="quest_giver",zoneID=6719},questType="standard"},
[34997] = {id=34997,name="Slumberbloom",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=6719,description="Huh?... Oh my, I appear to have fallen asleep again. These slumberblooms are nothing but trouble. One second I'm fighting botani and the next I'm dreaming I'm an elekk dancing with riverbeasts. *Yawn* We really should do something about all these slumberbloo *Yawn* ... ZZZZzzzzzzzz",starts={{npcID=80707,x=0.53,y=0.654,zoneID=6719}},coords={x=0.53,y=0.654,source="quest_giver",zoneID=6719},questType="standard"},
[34998] = {id=34998,name="Talon Watch",level=30,requiredLevel=30,faction="both",expansion=5,zoneID=6722,description="By now you must be wondering about all of this curse business. What could distort a majestic arakkoa into... well, into this? Reshad drags a crooked hand through the mottled feathers about his face.> A raven is prepped and waiting to fly you to Talon Watch. There shall your eyes be opened to the origin of this curse. Present the Eye of Anzu to Talon Guard Kurekk . He will guide you from there.",starts={{npcID=81770,x=0.464,y=0.466,zoneID=6722}},ends={{npcID=80758,x=0.622,y=0.426,zoneID=6722}},coords={x=0.464,y=0.466,source="quest_giver",zoneID=6722},questType="standard"},
[34999] = {id=34999,name="Hatred Undying",level=30,requiredLevel=30,faction="both",expansion=5,zoneID=6722,description="The blood of the dead god, Sethe, lingers in the pools here. And with it, his hatred of Rukhmar and Anzu. So strong was this hate that it animates the blood even now, eons after he was slain by his fellow gods. I need the congealed blood that holds those spiteful creatures together. There is nothing the Adherents fear more than the power of this curse - what if we could brandish it against them?",starts={{npcID=81514,x=0.618,y=0.422,zoneID=6722}},ends={{npcID=81514,x=0.618,y=0.422,zoneID=6722}},coords={x=0.618,y=0.422,source="quest_giver",zoneID=6722},questType="standard"},
[35000] = {id=35000,name="Banished From the Sky",level=30,requiredLevel=30,faction="both",expansion=5,zoneID=6722,description="The Adherents have been casting their enemies into the hollow for generations. The pools carry Sethe's dying curse, crippling arakkoa with visions of darkness and intense pain. The mind reels, the body writhes, and the wings wither. Most arakkoa die or go insane. Only the strongest can resist - seek them out and use the Eye of Anzu to help them to their senses. Beware, for the worshippers of Sethe also prey on these survivors to fill their ranks.",starts={{npcID=80758,x=0.622,y=0.426,zoneID=6722}},ends={{npcID=80758,x=0.622,y=0.426,zoneID=6722}},coords={x=0.622,y=0.426,source="quest_giver",zoneID=6722},questType="standard"},
[35001] = {id=35001,name="Gaze of the Raven God",level=30,requiredLevel=30,faction="both",expansion=5,zoneID=6722,description="The Sethekk are breeding vile wind serpents from Sethe's blood and bones. With these creatures, they will tear apart the sky. The nests are protected by powerful magic, but Anzu's gaze should penetrate them with ease. Let us visit the nests and destroy them!",starts={{npcID=80758,x=0.622,y=0.426,zoneID=6722}},ends={{npcID=231183,x=0.666,y=0.516,zoneID=6722}},coords={x=0.622,y=0.426,source="quest_giver",zoneID=6722},questType="standard"},
[35002] = {id=35002,name="Sons of Sethe",level=30,requiredLevel=30,faction="both",expansion=5,zoneID=6722,description="Many years have passed since anyone has been in contact with Anzu. He faded away, as Terokk did, to take refuge in the shadows. If we are to coax him back, we should make an offering. Sethe took the sky from us all - it seems fitting to take the wings of his children.",starts={{npcID=80758,x=0.622,y=0.426,zoneID=6722},{npcID=86419,x=0.772,y=0.342,zoneID=6722}},ends={{npcID=231184,x=0.668,y=0.513,zoneID=6722}},coords={x=0.622,y=0.426,source="quest_giver",zoneID=6722},questType="standard"},
[35003] = {id=35003,name="Ritual Severance",level=30,requiredLevel=30,faction="both",expansion=5,zoneID=6722,description="I could not defeat this curse, and long ago resigned myself to rest in darkness. But the Sethekk are performing dark rituals to draw me back, slowly binding me to Sethe's will. Should they succeed, Sethe would have me draw a dark cloak across the horizon, and bathe the world in his blood. Disrupt their rituals, so that I may return with my own free will. Then, together, we shall bring an end to Sethe's return.",starts={{npcID=80648,x=0.468,y=0.46,zoneID=6722}},ends={{npcID=86355,x=0.642,y=0.37,zoneID=6722}},coords={x=0.468,y=0.46,source="quest_giver",zoneID=6722},questType="standard"},
[35004] = {id=35004,name="Servants of a Dead God",level=30,requiredLevel=30,faction="both",expansion=5,zoneID=6722,description="Even in death, Sethe exerts influence. The Sethekk cult was born of this influence: led by a false king in service of the dead god. Silence their prophets, for they seek a future of black seas and blighted skies. Defeat their chosen champions, for they have pledged themselves to a lie.",starts={{npcID=80648,x=0.468,y=0.46,zoneID=6722}},ends={{npcID=86355,x=0.642,y=0.37,zoneID=6722}},coords={x=0.468,y=0.46,source="quest_giver",zoneID=6722},questType="standard"},
[35005] = {id=35005,name="Prepare for Battle",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=14795,description="There's nowhere to hide up here. We need to keep moving, and to do that, we need to pass right through the heart of the Iron Horde. It's time to turn this unarmed group of prisoners into an army.",starts={{npcID=78553,x=0.55,y=0.502,zoneID=4},{npcID=78553,x=0.5,y=0.134,zoneID=7025},{npcID=78553,x=0.82,y=0.452,zoneID=7025}},ends={{npcID=78553,x=0.55,y=0.502,zoneID=4},{npcID=78553,x=0.5,y=0.134,zoneID=7025},{npcID=78553,x=0.82,y=0.452,zoneID=7025}},coords={x=0.55,y=0.502,source="quest_giver",zoneID=4},questType="standard"},
[35006] = {id=35006,name="Poison Paralysis",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=6719,description="There are others from the caravan that have gone missing. My guess is they have been taken into Blademoon Bloom by the botani. You have to rescue them, . You are our only hope. Here, take some of this elixir I just made, chances are you will need it.",starts={{npcID=76204,x=0.536,y=0.572,zoneID=6719}},ends={{npcID=76204,x=0.536,y=0.572,zoneID=6719}},coords={x=0.536,y=0.572,source="quest_giver",zoneID=6719},questType="standard"},
[35007] = {id=35007,name="Rendezvous with the Ritualists",level=30,requiredLevel=30,faction="both",expansion=5,zoneID=6722,description="Our dear brother Sekara went to the Ravenskar with some of the flock to enact the great ritual of purification. No one has been sent back to the nest for supplies in the past day; caught up in prayers I suppose. I would go check on him but I need to make sure the scribe didn't mess up her transcription of my latest sermon. Could you do it? I'll be there in... well, who knows...",starts={{npcID=80481,x=0.52,y=0.498,zoneID=6722}},ends={{npcID=80740,x=0.548,y=0.542,zoneID=6722}},coords={x=0.52,y=0.498,source="quest_giver",zoneID=6722},questType="standard"},
[35009] = {id=35009,name="Call of the Raven Mother",level=30,requiredLevel=30,faction="both",expansion=5,zoneID=6722,description="All is now in its place to begin the ritual of calling that will bring the Raven Mother back to the nest. You have fulfilled all of the tests we have put before you so it is only fitting that you join with us and participate in the ritual. Soon the Raven Mother herself will appear before us! Oh my feathers are tingling in excitement! Speak to me again when you are ready.",starts={{npcID=80481,x=0.52,y=0.498,zoneID=6722}},ends={{npcID=77857,x=0.512,y=0.504,zoneID=6722}},coords={x=0.52,y=0.498,source="quest_giver",zoneID=6722},questType="standard"},
[35010] = {id=35010,name="The High Ravenspeaker",level=30,requiredLevel=30,faction="both",expansion=5,zoneID=6722,description="Yes, I knew you were worthy! The Writ of Faith says that great doubt will come in time of crisis but one must put their trust in the Raven Mother and all will be as it should! Come, come, we must go to the High Ravenspeaker!",starts={{npcID=80639,x=0.49,y=0.49,zoneID=6722}},ends={{npcID=80481,x=0.52,y=0.498,zoneID=6722}},coords={x=0.49,y=0.49,source="quest_giver",zoneID=6722},questType="standard"},
[35011] = {id=35011,name="The False Talon King",level=30,requiredLevel=30,faction="both",expansion=5,zoneID=6722,description="Ikiss was once a respected sage among the Adherents, but his search for the truth of Terokk's fall led to his own banishment. Ikiss became obsessed with Terokk, even claiming to be the old hero reborn. He commands the Sethekk, promising untold power in a new age of darkness. Know this: Ikiss is no Talon King. Slay the delusional fool, and search him for anything useful. He is known to collect powerful trinkets.",starts={{npcID=86475,x=0.64,y=0.37,zoneID=6722}},ends={{npcID=86475,x=0.64,y=0.37,zoneID=6722}},coords={x=0.64,y=0.37,source="quest_giver",zoneID=6722},questType="standard"},
[35012] = {id=35012,name="Sethe, the Dead God",level=30,requiredLevel=30,faction="both",expansion=5,zoneID=6722,description="The time has come to put an end to Sethe . I killed him before, and with your help I shall do it again. Ready yourself for a fight - the cultists will not stand idly by while we stamp out their god.",starts={{npcID=86355,x=0.642,y=0.37,zoneID=6722}},ends={{npcID=80648,x=0.468,y=0.46,zoneID=6722}},coords={x=0.642,y=0.37,source="quest_giver",zoneID=6722},questType="standard"},
[35013] = {id=35013,name="Lithic's Gift",level=30,requiredLevel=30,faction="both",expansion=5,zoneID=6722,description="There is an inscription on the inside. \"To my father, may Rukhmar illuminate your path. With love, Lithic.\" It cannot be... This is Terokk's bangle! It was a gift from his daughter, he wore it for years until... Well, we had better return it. Terokk built a memorial to Lithic not far from Talon Watch. It should rest there.",starts={{npcID=86475,x=0.64,y=0.37,zoneID=6722}},ends={{npcID=80834,x=0.604,y=0.388,zoneID=6722}},coords={x=0.64,y=0.37,source="quest_giver",zoneID=6722},questType="standard"},
[35014] = {id=35014,name="Blademoon Bloom",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=6719,description="We are out of options. I'm going into the bloom to find out what's going on. I'll meet you inside. Goodluck, .",starts={{npcID=80727,x=0.536,y=0.572,zoneID=6719}},ends={{npcID=80635,x=0.556,y=0.72,zoneID=6719}},coords={x=0.536,y=0.572,source="quest_giver",zoneID=6719},questType="standard"},
[35015] = {id=35015,name="Gestating Genesaur",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=6719,description="This is bad. A genesaur is starting to sprout right here in the bloom. This is the first reported case of a genesaur being born in draenor in over three hundred years. No wonder the botani have been acting so crazy. They are bringing back bodies to fertilize that monstrosity. We have to kill it before it gets any larger. Once fully grown there is no stopping that beast.",starts={{npcID=80635,x=0.556,y=0.72,zoneID=6719}},ends={{npcID=80635,x=0.556,y=0.72,zoneID=6719}},coords={x=0.556,y=0.72,source="quest_giver",zoneID=6719},questType="standard"},
[35016] = {id=35016,name="Basic Skulltaking",level=15,requiredLevel=15,faction="horde",expansion=5,zoneID=6721,description="My hunters are all dead, you will be my hunting pack now. Find their bodies and take their skulls. I will choose which to honor and which to cast aside. It is our way. I will go further and see what other skulls may be found here.",starts={{npcID=81218,x=0.544,y=0.666,zoneID=6721}},ends={{npcID=80757,x=0.572,y=0.618,zoneID=6721}},coords={x=0.544,y=0.666,source="quest_giver",zoneID=6721},questType="standard"},
[35017] = {id=35017,name="Skulltaker's Revenge",level=15,requiredLevel=15,faction="horde",expansion=5,zoneID=6721,description="The others... gone or wandered into the haze. It called to me as well but I am too strong. I chose to kill until they crushed my body. I haven't killed enough of them yet $p, not enough! Go. Kill more of them and tell my hunt leader that I don't go alone into the dark.",starts={{npcID=81185,x=0.548,y=0.652,zoneID=6721}},ends={{npcID=80757,x=0.572,y=0.618,zoneID=6721}},coords={x=0.548,y=0.652,source="quest_giver",zoneID=6721},questType="standard"},
[35018] = {id=35018,name="Vignette: Felbark",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6662,mapID=535,questType="standard"},
[35019] = {id=35019,name="Prepare for Battle",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=14795,description="There's nowhere to hide up here. We need to keep moving, and to do that, we need to pass right through the heart of the Iron Horde. It's time to turn this unarmed group of prisoners into an army.",starts={{npcID=78554,x=0.548,y=0.502,zoneID=4},{npcID=78554,x=0.486,y=0.142,zoneID=7025},{npcID=78554,x=0.81,y=0.458,zoneID=7025}},ends={{npcID=78554,x=0.548,y=0.502,zoneID=4},{npcID=78554,x=0.486,y=0.142,zoneID=7025},{npcID=78554,x=0.81,y=0.458,zoneID=7025}},coords={x=0.548,y=0.502,source="quest_giver",zoneID=4},questType="standard"},
[35021] = {id=35021,name="Mysterious Pod",level=15,requiredLevel=15,faction="horde",expansion=5,zoneID=6721,description="This pod is similar to the ones growing on or near the bodies around here, except this one is pulsating weirdly. Grulkor might know more about this.",ends={{npcID=80757,x=0.572,y=0.618,zoneID=6721}},questType="standard"},
[35022] = {id=35022,name="Lighting The Darkness",level=35,requiredLevel=35,faction="both",expansion=5,zoneID=6755,description="The spirits of my ancestors have always been drawn to the mountain of Oshu'gun. Now, I too feel this pull deep within my soul...but something is not right. The presence that beckons us has grown dark and ominous. It consumes the souls of the dead, the souls of my ancestors, . Something must be done. Take hold of the spirit torch and light the ceremonial pyres in the Ancestral Grounds. The flame of the spirit torch upon the pyres will calm the restless spirits being drawn into the void.",starts={{npcID=80864,x=0.404,y=0.568,zoneID=6755}},ends={{npcID=80864,x=0.404,y=0.568,zoneID=6755}},coords={x=0.404,y=0.568,source="quest_giver",zoneID=6755},questType="standard"},
[35023] = {id=35023,name="Echoes of the Past",level=35,requiredLevel=35,faction="both",expansion=5,zoneID=6755,description="When a spirit is consumed by the void, an echo of the soul is all that is left behind. Neither in the physical or spiritual sense of the word would these echoes be considered 'alive.' The echo is merely a twisted reverberation of the anguish left behind by the soul as it is consumed. If left unchecked, the echoes will lash out against the living and stir the spirits of the dead from their graves. In order to restore peace to the Ancestral Grounds, these echoes must be put to rest.",starts={{npcID=80866,x=0.404,y=0.566,zoneID=6755}},ends={{npcID=80866,x=0.404,y=0.566,zoneID=6755}},coords={x=0.404,y=0.566,source="quest_giver",zoneID=6755},questType="standard"},
[35024] = {id=35024,name="Golmash Hellscream",level=35,requiredLevel=35,faction="both",expansion=5,zoneID=6755,description="Those who die in brutal combat often enter the spirit world in unrest. So it was with Golmash, father of Grommash Hellscream. Crushed within the jaws of a hulking gronn, Golmash still found the strength to bury his axe Gorehowl deep into the eye of the monster. When they fell, it was the gronn who died first. Such is the heroic death that every Warsong dreams of, yet few attain. But Golmash's mighty spirit lingers restlessly, stirring the other spirits into unrest. Put his mighty soul to rest, .",starts={{npcID=80864,x=0.404,y=0.568,zoneID=6755}},ends={{npcID=80864,x=0.404,y=0.568,zoneID=6755}},coords={x=0.404,y=0.568,source="quest_giver",zoneID=6755},questType="standard"},
[35025] = {id=35025,name="We Have Company",level=15,requiredLevel=15,faction="horde",expansion=5,zoneID=6721,description="Outsider, I've spotted Iron Horde soldiers nearby. It is bold, even for them, to venture into such deadly territory. If you do not deal with their presence, they will surely be a threat to your camp.",starts={{npcID=81202,x=0.436,y=0.65,zoneID=6721}},ends={{npcID=82832,x=0.442,y=0.616,zoneID=6721}},coords={x=0.436,y=0.65,source="quest_giver",zoneID=6721},questType="standard"},
[35026] = {id=35026,name="On the Mend",level=15,requiredLevel=15,faction="both",expansion=5,zoneID=6721,mapID=543,description="Nisha will heal. This ordeal has taken a toll on her. She needs water and rest. I will bring her to my camp and make her comfortable. Will you meet us there with some fresh water?",starts={{npcID=82832,x=0.442,y=0.616,mapID=543}},ends={{npcID=81674,x=0.458,y=0.55,mapID=543}},coords={x=0.442,y=0.616,source="quest_giver",mapID=543},questType="standard"},
[35027] = {id=35027,name="Clearing the Way",level=15,requiredLevel=15,faction="horde",expansion=5,zoneID=6721,description="The dead ones were the strong ones it seems. The weak ones wander about killing invaders to this marsh. It feels... wrong... to kill them, but they are worthless and get in our way. Kill these shambling fools so we can move further into the marsh easily.",starts={{npcID=80757,x=0.572,y=0.618,zoneID=6721}},ends={{npcID=80757,x=0.572,y=0.618,zoneID=6721}},coords={x=0.572,y=0.618,source="quest_giver",zoneID=6721},questType="standard"},
[35028] = {id=35028,name="Krikka and Vakora Tracking",level=11,requiredLevel=11,faction="both",expansion=5,zoneID=6722,mapID=542,questType="standard"},
[35029] = {id=35029,name="The Secret of the Fungus",level=15,requiredLevel=15,faction="horde",expansion=5,zoneID=6721,description="It smells here and there are whispers. I feel there is a connection between the plants and beasts here. Special mushrooms seem to focus the beasts' attention. Go and get some of these for me. I... need... them.",starts={{npcID=80757,x=0.572,y=0.618,zoneID=6721}},ends={{npcID=80757,x=0.572,y=0.618,zoneID=6721}},coords={x=0.572,y=0.618,source="quest_giver",zoneID=6721},questType="standard"},
[35030] = {id=35030,name="A Grim Harvest",level=15,requiredLevel=15,faction="horde",expansion=5,zoneID=6721,description="The larger monsters are the key to my destiny, I can feel it. The pods growing on them are even bigger than the one you brought me earlier. Get me a few of these, they will be... helpful... soon.",starts={{npcID=80757,x=0.572,y=0.618,zoneID=6721}},ends={{npcID=80757,x=0.572,y=0.618,zoneID=6721},{npcID=81241,x=0.588,y=0.624,zoneID=6721}},coords={x=0.572,y=0.618,source="quest_giver",zoneID=6721},questType="standard"},
[35031] = {id=35031,name="A Heartfelt Search",level=15,requiredLevel=15,faction="horde",expansion=5,zoneID=6721,description="I can feel a powerful presence in the marsh $p. I feel drawn to it. We must go and take what is there. Go on ahead, I must finish consuming these mushrooms.",starts={{npcID=80757,x=0.572,y=0.618,zoneID=6721}},ends={{npcID=81241,x=0.588,y=0.624,zoneID=6721}},coords={x=0.572,y=0.618,source="quest_giver",zoneID=6721},questType="standard"},
[35032] = {id=35032,name="Into Anguish",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=6719,description="Rulkan's gift to you, the Fragment of Anguish , will allow you to pass into the fortress unhindered. Go up these stairs to the doorway, then use the fragment to enter the compound. Once you are inside, you will find three altars powering the magical barrier around their stronghold. Destroy these runes, and Yrel and I will be able to join you in finding Ner'zhul.",starts={{npcID=77282,x=0.462,y=0.386,zoneID=6719}},ends={{npcID=77282,x=0.462,y=0.386,zoneID=6719}},coords={x=0.462,y=0.386,source="quest_giver",zoneID=6719},questType="standard"},
[35033] = {id=35033,name="Welcome to Gorgrond",level=15,requiredLevel=15,faction="alliance",expansion=5,zoneID=6721,description="Gorgrond is one of the most untamed landscapes in all of Draenor. Only the most skilled of rangari venture this deep into the wilds. It is their camp we are heading for. If you wish to travel ahead, it can be found down this path and to the right. Maraad and I shall follow after you momentarily. We still have some logistics to work out before we leave the landing.",starts={{npcID=80978,x=0.64,y=0.572,zoneID=6721}},ends={{npcID=80921,x=0.642,y=0.518,zoneID=6721}},coords={x=0.64,y=0.572,source="quest_giver",zoneID=6721},questType="standard"},
[35035] = {id=35035,name="Seedbearers of Bad News",level=15,requiredLevel=15,faction="horde",expansion=5,zoneID=6721,description="When these seedbearers are slain their seeds survive. From them spring new seedbearers, not over years, but hours. Leaving their remains here would soon cause your camp to be overrun. Burn them, outsider, if you wish your camp to endure.",starts={{npcID=81202,x=0.436,y=0.65,zoneID=6721}},ends={{npcID=81202,x=0.436,y=0.65,zoneID=6721}},coords={x=0.436,y=0.65,source="quest_giver",zoneID=6721},questType="standard"},
[35036] = {id=35036,name="Is This One of Yours?",level=15,requiredLevel=15,faction="horde",expansion=5,zoneID=6721,description="I found this one skulking nearby. He claims to be an ally of yours. Is this true? Or does he cook slowly over my fire?",starts={{npcID=83569,x=0.46,y=0.548,zoneID=6721}},ends={{npcID=84743,x=0.462,y=0.55,zoneID=6721}},coords={x=0.46,y=0.548,source="quest_giver",zoneID=6721},questType="standard"},
[35037] = {id=35037,name="Bad at Breaking",level=15,requiredLevel=15,faction="both",expansion=5,zoneID=6721,description="Screams and growls echo from the canyon below - even more than usual. I don't dare leave Nisha here alone yet. Will you investigate those noises, ?",starts={{npcID=80856,x=0.46,y=0.548,zoneID=6721}},ends={{npcID=80856,x=0.46,y=0.548,zoneID=6721}},coords={x=0.46,y=0.548,source="quest_giver",zoneID=6721},questType="standard"},
[35038] = {id=35038,name="What the Bony Xuk?",level=15,requiredLevel=15,faction="horde",expansion=5,zoneID=6721,description="Good to see your bones are still intact, . Xuk's too. When you set off into the heart of the canyon, Xuk came to offer my services. Xuk not letting you take all of the skulls! Xuk will share with you powerful spirit magics my clan has passed down for many generations. While Xuk make preparations, you must gather the reagents. First, we'll need crystals from husks of goren corpses. You can find their bodies in the canyon.",starts={{npcID=84743,x=0.462,y=0.55,zoneID=6721}},ends={{npcID=84743,x=0.462,y=0.55,zoneID=6721}},coords={x=0.462,y=0.55,source="quest_giver",zoneID=6721},questType="standard"},
[35040] = {id=35040,name="Heart of the Fen",level=15,requiredLevel=15,faction="horde",expansion=5,zoneID=6721,description="If only the trees here weren't screaming at me I could concentrate better. Never mind, they are only trees. This spot is used up but now I can feel a much stronger presence deeper in the marsh. I will go there now and take what is rightfully mine! Then I will share it... with everyone...",starts={{npcID=81241,x=0.588,y=0.624,zoneID=6721}},ends={{npcID=82732,x=0.462,y=0.7,zoneID=6721}},coords={x=0.588,y=0.624,source="quest_giver",zoneID=6721},questType="standard"},
[35041] = {id=35041,name="Xuk It!",level=15,requiredLevel=15,faction="horde",expansion=5,zoneID=6721,description="It is done. With this enchantment, not only can you roam amongst the goren freely, but you can move as they do. Your travels through Gorgrond are now made simple. You have safe access to places otherwise impossible to reach. Xuk's ancestors have made it so.",starts={{npcID=84743,x=0.462,y=0.55,zoneID=6721}},ends={{npcID=80856,x=0.46,y=0.548,zoneID=6721}},coords={x=0.462,y=0.55,source="quest_giver",zoneID=6721},questType="standard"},
[35044] = {id=35044,name="Cordana Summon",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6662,mapID=535,questType="standard"},
[35045] = {id=35045,name="In Ared's Memory",level=20,requiredLevel=20,faction="alliance",expansion=5,zoneID=6662,description="My master has gone on to the Light, but I will continue his work. Miall looks to Ared > Shanai ortar, Ared. I will have his body sent to Auchindoun. For now, show me this artillery tower of yours.",starts={{npcID=79159,x=0.692,y=0.192,zoneID=6662}},ends={{npcID=79329,x=0.7,y=0.2,zoneID=6662}},coords={x=0.692,y=0.192,source="quest_giver",zoneID=6662},questType="standard"},
[35047] = {id=35047,name="Dropping Bombs Tracking",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6662,mapID=535,questType="standard"},
[35049] = {id=35049,name="Lumber Mill",level=1,requiredLevel=1,faction="horde",expansion=5,zoneID=6721,mapID=543,questType="standard"},
[35050] = {id=35050,name="Rescue Rangari",level=15,requiredLevel=15,faction="alliance",expansion=5,zoneID=6721,description="Many of our rangari have not been accounted for. It would seem the followers of Iyu have taken captives. We will continue to search the area for survivors. In the meantime, follow the Wildwood Wash west toward Highpass and look for any signs of our rangari comrades. Our people are stout and capable survivors. You may find more than you expect. Have them stay near the road and we will follow as soon as this... dwarf creature... has fixed his mechanical vessel.",starts={{npcID=75146,x=0.632,y=0.522,zoneID=6721}},ends={{npcID=75146,x=0.632,y=0.522,zoneID=6721}},coords={x=0.632,y=0.522,source="quest_giver",zoneID=6721},questType="standard"},
[35051] = {id=35051,name="Mage Tower Complete",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6662,mapID=535,questType="standard"},
[35055] = {id=35055,name="Lost Mole Machines",level=15,requiredLevel=15,faction="alliance",expansion=5,zoneID=6721,description="Few people know the Blackrock clan better than Dark Iron dwarves. So after Tanaan, we sent a bunch of mole machines to Gorgrond to build a listenin' post to keep an eye on them. Me own mole machine got way off course an' I got separated. It didn't take long to figure out all the other mole machines got off course as well. Accordin' to the readin's in me tank, a mole machine surfaced somewhere way to the west of here. Mind scoutin' ahead while we get this tank operational?",starts={{npcID=75136,x=0.632,y=0.524,zoneID=6721}},ends={{npcID=75136,x=0.632,y=0.524,zoneID=6721}},coords={x=0.632,y=0.524,source="quest_giver",zoneID=6721},questType="standard"},
[35056] = {id=35056,name="Tracking Flag - Horned Skull",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6721,mapID=543,questType="standard"},
[35057] = {id=35057,name="Vignette XP reward - Frostfire",level=10,requiredLevel=10,faction="none",expansion=5,zoneID=6720,mapID=525,description="This quest is a placeholder until Task 67719 is complete.",questType="standard"},
[35058] = {id=35058,name="The Mysterious Flask",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=7004,mapID=525,description="The liquid swirling around inside the flask clearly has strong alchemical properties, but its nature is beyond your training. You have heard that one of the Stonefang refugees at your garrison has some knowledge of the alchemy of Draenor. Perhaps he could tell you more?",ends={{npcID=81166,x=0.454,y=0.504,mapID=525}},questType="standard"},
[35059] = {id=35059,name="Along the Riverside",level=35,requiredLevel=35,faction="alliance",expansion=5,zoneID=6755,description="Vindicator Yrel has taken most of our forces north. She's establishing a forward base along the Skysong River. She'll want to know that we're almost ready to move against Grommashar. I'm sure she can also use your help dealing with the Warsong orcs at Lok-rath.",starts={{npcID=79576,x=0.634,y=0.618,zoneID=6755}},ends={{npcID=81039,x=0.62,y=0.404,zoneID=6755}},coords={x=0.634,y=0.618,source="quest_giver",zoneID=6755},questType="standard"},
[35060] = {id=35060,name="Terms of Surrender",level=35,requiredLevel=35,faction="alliance",expansion=5,zoneID=6755,description="Believe it or not, I have good news: we've already taken Lok-rath. Our soldiers have captured most of the Warsong, including their leader, Uruk Foecleaver . I saved the honor of accepting his surrender for you. They're waiting for you inside, commander.",starts={{npcID=81039,x=0.62,y=0.404,zoneID=6755}},ends={{npcID=81086,x=0.554,y=0.422,zoneID=6755}},coords={x=0.62,y=0.404,source="quest_giver",zoneID=6755},questType="standard"},
[35061] = {id=35061,name="The Pride of Lok-rath",level=35,requiredLevel=35,faction="alliance",expansion=5,zoneID=6755,description="You think the Warsong are so easily defeated? I'm already tired of you Alliance, and you've just invaded my homeland. Uruk Foecleaver looks you straight in the eye.> There will be no surrender. The Warsong bow to no one!",starts={{npcID=81086,x=0.554,y=0.422,zoneID=6755}},ends={{npcID=81039,x=0.62,y=0.404,zoneID=6755}},coords={x=0.554,y=0.422,source="quest_giver",zoneID=6755},questType="standard"},
[35062] = {id=35062,name="Lok-rath is Secured",level=35,requiredLevel=35,faction="alliance",expansion=5,zoneID=6755,description="With their leader dead, the remaining Warsong will be easier to finish. As soon as that's done, I'll pull our soldiers out of Lok-rath and head for Grommashar. If you're heading back to Telaari Station, would you please inform D'kaan?",starts={{npcID=81039,x=0.62,y=0.404,zoneID=6755}},ends={{npcID=79576,x=0.634,y=0.618,zoneID=6755}},coords={x=0.62,y=0.404,source="quest_giver",zoneID=6755},questType="standard"},
[35063] = {id=35063,name="We Need An Outpost",level=15,requiredLevel=15,faction="alliance",expansion=5,zoneID=6721,description="Commander, we've gathered enough materials to build an outpost that will support our mission against the Iron Horde. How shall we proceed? A lumber yard would be valuable for gathering resources in the dense overgrowth to the south, and in confronting the plant monstrosities that defend it. On the other hand, a sparring arena would provide us the brutish forces we'd need to push through the magnaron wastelands to the north. When you're ready, make your choice on the table.",starts={{npcID=75136,x=0.632,y=0.524,zoneID=6721}},ends={{npcID=75136,x=0.632,y=0.524,zoneID=6721}},coords={x=0.632,y=0.524,source="quest_giver",zoneID=6721},questType="standard"},
[35064] = {id=35064,name="Sparring Arena",level=1,requiredLevel=1,faction="horde",expansion=5,zoneID=6721,mapID=543,questType="standard"},
[35065] = {id=35065,name="A Harvester Has Come",level=15,requiredLevel=15,faction="alliance",expansion=5,zoneID=6721,description="This is what happens when one stands in the path of a genesaur. And where a genesaur walks, the botani follow. I saw one entering our shelter cave along the northern side of the camp. It is commanding the podlings to gather the corpses of our fallen brethren and must be stopped. I must tend to our wounded, and gather supplies for our departure. If you are serious about being a hero, venture into the cave and slay this botani.",starts={{npcID=80921,x=0.642,y=0.518,zoneID=6721}},ends={{npcID=75146,x=0.632,y=0.522,zoneID=6721}},coords={x=0.642,y=0.518,source="quest_giver",zoneID=6721},questType="standard"},
[35066] = {id=35066,name="Fire Ammonite",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=7004,description="We need to stock the garrison pond with local fish. I need you to search the waters in Frostfire Ridge for fish that we can stock up with. Once you have the fish, you will need to slice them up and look for eggs inside.",starts={{npcID=79892,x=0.384,y=0.722,zoneID=7004}},ends={{npcID=79892,x=0.384,y=0.722,zoneID=7004}},coords={x=0.384,y=0.722,source="quest_giver",zoneID=7004},questType="standard"},
[35067] = {id=35067,name="Silence the War Machines",level=35,requiredLevel=35,faction="alliance",expansion=5,zoneID=6755,description="The Iron Horde supplied Lok-rath with war machines from Ironfist Harbor. It won't take long for them to level Yrel's Watch. Someone has to silence those war machines!",starts={{npcID=81097,x=0.554,y=0.422,zoneID=6755}},ends={{npcID=81123,x=0.62,y=0.404,zoneID=6755}},coords={x=0.554,y=0.422,source="quest_giver",zoneID=6755},questType="standard"},
[35068] = {id=35068,name="If They Won't Surrender...",level=35,requiredLevel=35,faction="alliance",expansion=5,zoneID=6755,description="This is the backbone of the army we intend to send against Garrosh Hellscream and Grommashar. If they won't surrender, we have no choice but to eliminate the Warsong.",starts={{npcID=81097,x=0.554,y=0.422,zoneID=6755}},ends={{npcID=81123,x=0.62,y=0.404,zoneID=6755}},coords={x=0.554,y=0.422,source="quest_giver",zoneID=6755},questType="standard"},
[35069] = {id=35069,name="Terror of Nagrand",level=35,requiredLevel=35,faction="alliance",expansion=5,zoneID=6755,starts={{npcID=81134,x=0.56,y=0.438,zoneID=6755}},ends={{npcID=81123,x=0.62,y=0.404,zoneID=6755}},coords={x=0.56,y=0.438,source="quest_giver",zoneID=6755},questType="standard"},
[35070] = {id=35070,name="Shut 'er Down",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=6719,description="Burrowing native creatures known as \"goren\" have tunneled into our crystal mines. Judging from our experience at the gates, I suspect my own experimental resonance crystal is whipping the native wildlife into a frenzy. Enter the Elodor Dig to the north and disable the malfunctioning resonance crystal! Be careful - my earthworkers report that the mine is crawling with those beasts.",starts={{npcID=80075,x=0.562,y=0.326,zoneID=6719}},ends={{npcID=80075,x=0.562,y=0.326,zoneID=6719}},coords={x=0.562,y=0.326,source="quest_giver",zoneID=6719},questType="standard"},
[35071] = {id=35071,name="Jawless Skulker",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=7004,description="We need to stock the garrison pond with local fish. I need you to search the waters in Gorgrond for fish that we can stock up with. Once you have the fish, you will need to slice them up and look for eggs inside.",starts={{npcID=79892,x=0.384,y=0.722,zoneID=7004}},ends={{npcID=79892,x=0.384,y=0.722,zoneID=7004}},coords={x=0.384,y=0.722,source="quest_giver",zoneID=7004},questType="standard"},
[35072] = {id=35072,name="Fat Sleeper",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=7004,description="We need to stock the garrison pond with local fish. I need you to search the waters in Nagrand for fish that we can stock up with. Once you have the fish, you will need to slice them up and look for eggs inside.",starts={{npcID=79892,x=0.384,y=0.722,zoneID=7004}},ends={{npcID=79892,x=0.384,y=0.722,zoneID=7004}},coords={x=0.384,y=0.722,source="quest_giver",zoneID=7004},questType="standard"},
[35073] = {id=35073,name="Blind Lake Sturgeon",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=7004,description="We need to stock the garrison pond with local fish. I need you to search the waters in Shadowmoon Valley for fish that we can stock up with. Once you have the fish, you will need to slice them up and look for eggs inside.",starts={{npcID=79892,x=0.384,y=0.722,zoneID=7004}},ends={{npcID=79892,x=0.384,y=0.722,zoneID=7004}},coords={x=0.384,y=0.722,source="quest_giver",zoneID=7004},questType="standard"},
[35074] = {id=35074,name="Blackwater Whiptail",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=7004,description="We need to stock the garrison pond with local fish. I need you to search the waters in Talador for fish that we can stock up with. Once you have the fish, you will need to slice them up and look for eggs inside.",starts={{npcID=79892,x=0.384,y=0.722,zoneID=7004}},ends={{npcID=79892,x=0.384,y=0.722,zoneID=7004}},coords={x=0.384,y=0.722,source="quest_giver",zoneID=7004},questType="standard"},
[35075] = {id=35075,name="Abyssal Gulper Eel",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=7004,description="We need to stock the garrison pond with local fish. I need you to search the waters in Spires of Arak for fish that we can stock up with. Once you have the fish, you will need to slice them up and look for eggs inside.",starts={{npcID=79892,x=0.384,y=0.722,zoneID=7004}},ends={{npcID=79892,x=0.384,y=0.722,zoneID=7004}},coords={x=0.384,y=0.722,source="quest_giver",zoneID=7004},questType="standard"},
[35077] = {id=35077,name="Defungination",level=30,requiredLevel=30,faction="both",expansion=5,zoneID=6722,description="Have you seen the fungus out there in the water? It's growing faster than a baby ravasaur from Un'goro, and if we don't get it under control, the Gearworks is gonna be ruined like our last village. Uncle Krixel used to tell me to burn away the red fungus because that's what makes it grow so fast. You could help us out by taking a flame blaster and clearing out some of those spores down in the shallows.",starts={{npcID=81109,x=0.614,y=0.728,zoneID=6722}},ends={{npcID=81109,x=0.614,y=0.728,zoneID=6722}},coords={x=0.614,y=0.728,source="quest_giver",zoneID=6722},questType="standard"},
[35079] = {id=35079,name="Spore-be-Gone",level=30,requiredLevel=30,faction="both",expansion=5,zoneID=6722,description="We got an emergency! A bunch of spore drifters have infested the shore and tore up our Spore-B-Gone turrets. We're caught with our armor off here! If we don't get those turrets back online then those spores are going to float right in to town and then we'll have another Pinchwhistle Point on our hands! We need to get out there and manually activate them. Well? Are you in?",starts={{npcID=81128,x=0.614,y=0.728,zoneID=6722}},ends={{npcID=81128,x=0.614,y=0.728,zoneID=6722}},coords={x=0.614,y=0.728,source="quest_giver",zoneID=6722},questType="standard"},
[35080] = {id=35080,name="The Mother Lode",level=30,requiredLevel=30,faction="both",expansion=5,zoneID=6722,description="Hey we got ourselves a crisis here! Our zeppelin \"The Mother Lode\" crashed onto the south mountain range. It was supposed to only be on an observation mission, what could have happened? We got to get down there quick and I'm going to need your help on this. Are you with me?",starts={{npcID=81109,x=0.614,y=0.728,zoneID=6722}},ends={{npcID=81773,x=0.59,y=0.792,zoneID=6722}},coords={x=0.614,y=0.728,source="quest_giver",zoneID=6722},questType="standard"},
[35081] = {id=35081,name="Clearing Out Before Cleaning Up",level=30,requiredLevel=30,faction="both",expansion=5,zoneID=6722,description="Here's the situation. We need to get this salvage operation moving ASAP, but the ship went down right in the middle of the wasp nests. The ugly bugs are all over the place, and I can't call my team in here to start work until they're taken care of. Go kill as many of 'em as you can and I'll cut you in on some of the haul.",starts={{npcID=81784,x=0.59,y=0.792,zoneID=6722}},ends={{npcID=81784,x=0.59,y=0.792,zoneID=6722}},coords={x=0.59,y=0.792,source="quest_giver",zoneID=6722},questType="standard"},
[35082] = {id=35082,name="Getting the Crew Back Together",level=30,requiredLevel=30,faction="both",expansion=5,zoneID=6722,description="Oh wow, the debris is all over the mountainside! The survivors won't make it if we don't do something quick. They need healing NOW! Here, take my bandages and go patch them up.",starts={{npcID=81773,x=0.59,y=0.792,zoneID=6722}},ends={{npcID=81773,x=0.59,y=0.792,zoneID=6722}},coords={x=0.59,y=0.792,source="quest_giver",zoneID=6722},questType="standard"},
[35083] = {id=35083,name="Disrupt the Rituals",level=35,requiredLevel=35,faction="both",expansion=5,zoneID=6755,description="No longer do the Warsong seek to be one with the elements; instead they abuse their power by using it to channel the darkness of the void. I will not tolerate these rituals to continue. Locate the ritual totems the Warsong use to channel the void and destroy them. The gift of the elements was not given to the orcs only to be defiled and used as a plaything.",starts={{npcID=233263,x=0.555,y=0.559,zoneID=6755}},ends={{npcID=233263,x=0.555,y=0.559,zoneID=6755}},coords={x=0.555,y=0.559,source="quest_giver",zoneID=6755},questType="standard"},
[35084] = {id=35084,name="Silence the Call",level=35,requiredLevel=35,faction="both",expansion=5,zoneID=6755,description="The Warsong clan, in their lust for dominance, have turned to the darkness of the void for power. Dark shamanism is a loathsome, dangerous practice that abuses the elemental gift I have bestowed upon them. There is one among the Warsong that calls out the loudest to the void, an elder shaman named Kuhlrath. Slay him and the rest of his dark shaman. I will not allow the Warsong to abuse the elements and desecrate tradition.",starts={{npcID=233263,x=0.555,y=0.559,zoneID=6755}},ends={{npcID=233263,x=0.555,y=0.559,zoneID=6755}},coords={x=0.555,y=0.559,source="quest_giver",zoneID=6755},questType="standard"},
[35085] = {id=35085,name="Through the Nether",level=35,requiredLevel=35,faction="both",expansion=5,zoneID=6755,description="The rituals have been disrupted, yet the nether beacons still glow with power.... This can only mean that the beacons are powered from within the Twisting Nether itself! The connection to the void must be severed! There is but one way to accomplish this; you must slay the void creature that maintains the connection with our world. Lay your hands upon a beacon and travel into the Twisting Nether. When you have arrived on the other side, locate a Shamanstone and use it to contact me.",starts={{npcID=233263,x=0.555,y=0.559,zoneID=6755}},ends={{npcID=233263,x=0.555,y=0.559,zoneID=6755}},coords={x=0.555,y=0.559,source="quest_giver",zoneID=6755},questType="standard"},
[35086] = {id=35086,name="The Void March",level=35,requiredLevel=35,faction="both",expansion=5,zoneID=6755,description="Hidden behind the veil of the Twisting Nether, the abominations of the void march upon Oshu'gun. The great void growing deep within the mountain has drawn them like moths to a flame. Wave upon wave, the creatures of the void march upon the mountain and sacrifice themselves to Invalidus. The void lord Invalidus cannot be allowed to feast upon the other void creatures, else it will become too powerful to stop.",starts={{npcID=233263,x=0.555,y=0.559,zoneID=6755}},ends={{npcID=233263,x=0.555,y=0.559,zoneID=6755}},coords={x=0.555,y=0.559,source="quest_giver",zoneID=6755},questType="standard"},
[35087] = {id=35087,name="The Nether Approaches",level=35,requiredLevel=35,faction="both",expansion=5,zoneID=6755,description="By connecting with the Twisting Nether, the Warsong shaman have created a ripple effect that they could not have anticipated. Look around and you will see countless portals beginning to open, signs that the Twisting Nether seeks to connect to Draenor. Should these portals successfully open, the path will be clear for all manner of demons and void creatures to rampage across this valley.",starts={{npcID=233263,x=0.555,y=0.559,zoneID=6755}},ends={{npcID=233263,x=0.555,y=0.559,zoneID=6755}},coords={x=0.555,y=0.559,source="quest_giver",zoneID=6755},questType="standard"},
[35088] = {id=35088,name="The Shadow of the Void",level=35,requiredLevel=35,faction="both",expansion=5,zoneID=6755,description="The moment has come to take on the void lord. Invalidus grows more powerful by the minute, so you must move with haste if you are to defeat the monster. At each of the Warsong ritual locations there is a void crystal; these crystals are used to channel the energy of the void from within the Twisting Nether. Disturb the crystal, and Invalidus will sense your presence below. Be ready, as soon as the crystal is disturbed, Invalidus will waste no time hunting you down.",starts={{npcID=233263,x=0.555,y=0.559,zoneID=6755}},ends={{npcID=233263,x=0.555,y=0.559,zoneID=6755}},coords={x=0.555,y=0.559,source="quest_giver",zoneID=6755},questType="standard"},
[35089] = {id=35089,name="Skimming Off the Top",level=30,requiredLevel=30,faction="both",expansion=5,zoneID=6722,description="That flying machine is our ticket out of here but its fuel tank is bone dry! We're right next to the oil fields but with the infected out there we don't have time to run a line up here so we need to improvise. The oil creatures moving next to the pumps out there are full of a highly potent mixture that I can drop right into the tank. Grab some of that oil for me and we'll be one step closer to getting out of here.",starts={{npcID=81972,x=0.584,y=0.922,zoneID=6722},{npcID=81978,x=0.588,y=0.928,zoneID=6722}},ends={{npcID=81978,x=0.588,y=0.928,zoneID=6722}},coords={x=0.584,y=0.922,source="quest_giver",zoneID=6722},questType="standard"},
[35090] = {id=35090,name="The Right Parts for the Job",level=30,requiredLevel=30,faction="both",expansion=5,zoneID=10416,description="Uncle Krixel's a tough one but he won't be going anywhere on foot with his leg broken. He has a flying machine he brought from Azeroth that can fly us out of here. Problem is, the engine's busted. I'll need some parts to fix the thing. My car's wasted but those broken shredders just outside of town should have what we need. We don't have time to break them down by hand so just use this rocket launcher and blow 'em apart. Anything that survives the blast should be strong enough to use on the engine.",starts={{npcID=81972,x=0.584,y=0.922,zoneID=6722}},ends={{npcID=81978,x=0.588,y=0.928,zoneID=6722}},coords={x=0.584,y=0.922,source="quest_giver",zoneID=6722},questType="standard"},
[35091] = {id=35091,name="Sporicide",level=30,requiredLevel=30,faction="both",expansion=5,zoneID=6722,description="It's revolting, absolutely disgusting, infuriating even! I'm talking about seeing those spore creatures walking around Pinchwhistle Point. While I'm working on the machine here how about you go out and kill off some of those spore creatures? I'll feel a bit better knowing there are less of those things moving around.",starts={{npcID=81978,x=0.588,y=0.928,zoneID=6722}},ends={{npcID=81978,x=0.588,y=0.928,zoneID=6722}},coords={x=0.588,y=0.928,source="quest_giver",zoneID=6722},questType="standard"},
[35093] = {id=35093,name="The Dark Side of the Moon",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=6719,description="Yrel and I have located Warlord Ner'zhul. He is meeting with Grommash Hellscream atop the highest altar overlooking Anguish Fortress. Meet us there. We must stop him.",starts={{npcID=77282,x=0.462,y=0.386,zoneID=6719}},ends={{npcID=73395,x=0.462,y=0.386,zoneID=6719}},coords={x=0.462,y=0.386,source="quest_giver",zoneID=6719},questType="standard"},
[35095] = {id=35095,name="Along the Riverside",level=35,requiredLevel=35,faction="horde",expansion=5,zoneID=6755,description="Durotan has taken most of our forces west. He's establishing a forward base along the Skysong River. He'll want to know that we're almost ready to move against Grommashar. I'm sure he'll also appreciate your help dealing with the Warsong orcs at Lok-rath.",starts={{npcID=80003,x=0.828,y=0.45,zoneID=6755}},ends={{npcID=81186,x=0.486,y=0.482,zoneID=6755}},coords={x=0.828,y=0.45,source="quest_giver",zoneID=6755},questType="standard"},
[35096] = {id=35096,name="Terms of Surrender",level=35,requiredLevel=35,faction="horde",expansion=5,zoneID=6755,description="I have good news, commander: we've already taken Lok-rath. The Horde's soldiers have captured most of the Warsong, including their leader, Uruk Foecleaver . I saved the honor of accepting his surrender for you. They're waiting for you inside, commander.",starts={{npcID=81186,x=0.486,y=0.482,zoneID=6755}},ends={{npcID=81086,x=0.554,y=0.422,zoneID=6755}},coords={x=0.486,y=0.482,source="quest_giver",zoneID=6755},questType="standard"},
[35097] = {id=35097,name="The Pride of Lok-rath",level=35,requiredLevel=35,faction="horde",expansion=5,zoneID=6755,description="You think the Warsong are so easily defeated? I'm already tired of you Horde, and you've just invaded my homeland. Uruk Foecleaver looks you straight in the eye.> There will be no surrender. The Warsong bow to no one!",starts={{npcID=81086,x=0.554,y=0.422,zoneID=6755}},ends={{npcID=81186,x=0.486,y=0.482,zoneID=6755}},coords={x=0.554,y=0.422,source="quest_giver",zoneID=6755},questType="standard"},
[35098] = {id=35098,name="Lok-rath is Secured",level=35,requiredLevel=35,faction="horde",expansion=5,zoneID=6755,description="With their leader dead, the remaining Warsong will be easy pickings. As soon as that's done, I'll pull our soldiers out of Lok-rath and head for Grommashar. If you're heading back to Wor'var, inform Thrall that we'll be ready soon.",starts={{npcID=81186,x=0.486,y=0.482,zoneID=6755}},ends={{npcID=80003,x=0.828,y=0.45,zoneID=6755}},coords={x=0.486,y=0.482,source="quest_giver",zoneID=6755},questType="standard"},
[35099] = {id=35099,name="Silence the War Machines",level=35,requiredLevel=35,faction="horde",expansion=5,zoneID=6755,description="The Iron Horde supplied Lok-rath with war machines from Ironfist Harbor. It won't take long for them to level Riverside Post. Someone has to silence those war machines!",starts={{npcID=81194,x=0.554,y=0.422,zoneID=6755}},ends={{npcID=81193,x=0.494,y=0.478,zoneID=6755}},coords={x=0.554,y=0.422,source="quest_giver",zoneID=6755},questType="standard"},
[35100] = {id=35100,name="If They Won't Surrender...",level=35,requiredLevel=35,faction="horde",expansion=5,zoneID=6755,description="This is the backbone of the army we intend to send against Garrosh Hellscream and Grommashar. If they won't surrender, we have no choice but to eliminate the Warsong.",starts={{npcID=81194,x=0.554,y=0.422,zoneID=6755}},ends={{npcID=81193,x=0.494,y=0.478,zoneID=6755}},coords={x=0.554,y=0.422,source="quest_giver",zoneID=6755},questType="standard"},
[35101] = {id=35101,name="Terror of Nagrand",level=35,requiredLevel=35,faction="horde",expansion=5,zoneID=6755,starts={{npcID=81195,x=0.56,y=0.438,zoneID=6755}},ends={{npcID=81193,x=0.494,y=0.478,zoneID=6755}},coords={x=0.56,y=0.438,source="quest_giver",zoneID=6755},questType="standard"},
[35102] = {id=35102,name="Unleashed Steel",level=20,requiredLevel=20,faction="horde",expansion=5,zoneID=6662,description="Thank you... boss. I won't let you down! I didn't even try to sneak one of those low quality blades here that one of your peons placed right next to the cage. Which by the way was a pretty terrible idea and that thing should be moved before you get anyone less honorable in here. Enough talk, lets check this place out!",starts={{npcID=79210,x=0.718,y=0.294,zoneID=6662}},ends={{npcID=79356,x=0.708,y=0.304,zoneID=6662}},coords={x=0.718,y=0.294,source="quest_giver",zoneID=6662},questType="standard"},
[35103] = {id=35103,name="The Alchemist",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=6720,description="I know a little about alchemy from my cousin Kadar . She is the alchemist at Stonefang Outpost. If you wish to learn more, she is the one with whom to speak. I only hope she has survived the attack.",starts={{npcID=81166,x=0.454,y=0.504,zoneID=7004}},ends={{npcID=81209,x=0.38,y=0.474,zoneID=6720}},coords={x=0.454,y=0.504,source="quest_giver",zoneID=7004},questType="standard"},
[35104] = {id=35104,name="The Apprentice",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=6720,description="Kadar 's last words... Is there someone still inside the hut?",starts={{npcID=81209,x=0.38,y=0.474,zoneID=6720}},ends={{npcID=81210,x=0.378,y=0.474,zoneID=6720}},coords={x=0.38,y=0.474,source="quest_giver",zoneID=6720},questType="standard"},
[35105] = {id=35105,name="Honor and Remember",level=1,requiredLevel=1,faction="none",expansion=5,description="So she is dead. She took me in when I had no one. She taught me everything I know. She gave me everything I have. And now, she is dead. I owe you my life, stranger, but I wish you had saved hers, not mine. Please, help me bury her.",questType="standard"},
[35106] = {id=35106,name="Avenge and Reclaim",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=6720,description="I will avenge my master and retrieve her life's work. Honor demands it. My heart yearns for it. If I die trying, so be it. The murderer will pay.",starts={{npcID=81210,x=0.378,y=0.474,zoneID=6720}},ends={{npcID=81210,x=0.378,y=0.474,zoneID=6720}},coords={x=0.378,y=0.474,source="quest_giver",zoneID=6720},questType="standard"},
[35128] = {id=35128,name="Fair Warning",level=15,requiredLevel=15,faction="both",expansion=5,zoneID=6721,description="The ogron here are far from brilliant, but they are more intelligent than the gronn. They're large, and even stronger than they look. Their leader, Borogahn , is especially formidable. Despite several fights, I have not yet managed to kill him. Heed my words, friend. Take caution as you explore their lair. Nisha is ready to move. Ask her to take you to the mouth of the cave, and I'm sure she would be happy to.",questType="standard"},
[35129] = {id=35129,name="Leave Every Soldier Behind",level=15,requiredLevel=15,faction="horde",expansion=5,zoneID=6721,description="Hmmm. The ogron possess something of value to the Iron Horde. I'm sure they're unaware, likely just bored and in need of something to torture. I'd be inclined to just let them be, it's a fate they deserve. But we can't afford not to follow up on this clue. With any luck, it will help us stop the Iron Horde from turning Gorgrond 's most fearsome creatures into weapons. Try to find this Corporal Thukmar and his notes. We'll meet you there.",questType="standard"},
[35136] = {id=35136,name="Chains of Iron",level=15,requiredLevel=15,faction="horde",expansion=5,zoneID=6721,description="The artifact we seek is within our grasp. Be prepared for a fight. If they truly have learned how to control gronn, this may be more difficult than I anticipated. I will join you in this battle as soon as you arrive.",starts={{npcID=84131,x=0.438,y=0.488,zoneID=6721}},ends={{npcID=74594,x=0.372,y=0.77,zoneID=6721}},coords={x=0.438,y=0.488,source="quest_giver",zoneID=6721},questType="standard"},
[35137] = {id=35137,name="The Sparring Arena",level=15,requiredLevel=15,faction="alliance",expansion=5,zoneID=6721,description="We owe you our freedom, and more. I have spoken to the others, we are willing to return with you to your garrison and teach those pitiful creatures you call \"soldiers\" how to properly fight. We will also do our best to impart our knowledge to you, Commander. Should you have need of us when in the wilds of Gorgrond , simply call us. You may wish to warn Rangari Jonaa of our coming.",starts={{npcID=79322,x=0.428,y=0.63,zoneID=6721}},ends={{npcID=81076,x=0.528,y=0.598,zoneID=6721}},coords={x=0.428,y=0.63,source="quest_giver",zoneID=6721},questType="standard"},
[35139] = {id=35139,name="Eye in the Sky",level=15,requiredLevel=15,faction="both",expansion=5,zoneID=6721,description="The notes you recovered tell of a device capable of subjugating even a magnaron. Ancient legends speak of such artifacts, crafted by the worldbuilders to keep these creatures in check. I had discounted them as silly stories, but if they are true... , Draenor is doomed. No army will be able to stop them if they harness this power. We must stop them or die trying. Here, I shall bind our sight to Nisha and hope she can locate this artifact.",starts={{npcID=84131,x=0.438,y=0.488,zoneID=6721}},ends={{npcID=84131,x=0.438,y=0.488,zoneID=6721}},coords={x=0.438,y=0.488,source="quest_giver",zoneID=6721},questType="standard"},
[35140] = {id=35140,name="THAELIN!",level=35,requiredLevel=35,faction="alliance",expansion=5,zoneID=6755,description="That little...! Thaelin Darkanvil sent us a shipment. It was supposed to be engineering parts. Instead, when we just opened one of the crates, out popped a baby goren . Do you know how destructive those things are? And, of course, the one baby immediately set about letting all the other ones loose. Want to help me get some revenge?",starts={{npcID=81039,x=0.62,y=0.404,zoneID=6755}},ends={{npcID=81039,x=0.62,y=0.404,zoneID=6755},{npcID=81412,x=0.668,y=0.338,zoneID=6755}},coords={x=0.62,y=0.404,source="quest_giver",zoneID=6755},questType="standard"},
[35141] = {id=35141,name="Carrier Has Arrived",level=35,requiredLevel=35,faction="alliance",expansion=5,zoneID=6755,description="We're going to get some payback on that little stinker. Put the baby goren into one of those carriers and then make a special delivery to Thaelin.",starts={{npcID=81039,x=0.62,y=0.404,zoneID=6755},{npcID=81412,x=0.668,y=0.338,zoneID=6755}},ends={{npcID=79674,x=0.63,y=0.62,zoneID=6755}},coords={x=0.62,y=0.404,source="quest_giver",zoneID=6755},questType="standard"},
[35142] = {id=35142,name="Goren Invasion!",level=40,requiredLevel=40,faction="horde",expansion=5,zoneID=7078,description="The earth quakes beneath us, Commander. Our scouts are not returning. I can feel an attack creeping up on us, but from where?",starts={{npcID=79774,x=0.44,y=0.476,zoneID=7004}},ends={{npcID=79774,x=0.44,y=0.476,zoneID=7004}},coords={x=0.44,y=0.476,source="quest_giver",zoneID=7004},questType="standard"},
[35143] = {id=35143,name="Blood of the Burning Blade",level=35,requiredLevel=35,faction="horde",expansion=5,zoneID=6755,description="Hallvalor is the ancestral home of my clan, the Burning Blade. When the new warlord and his family came to power, I was exiled for being a half-breed. I want justice. I suspect you won't mind killing along the way. Not that you'll have any choice.",starts={{npcID=80161,x=0.854,y=0.546,zoneID=6755}},ends={{npcID=80003,x=0.828,y=0.45,zoneID=6755}},coords={x=0.854,y=0.546,source="quest_giver",zoneID=6755},questType="standard"},
[35144] = {id=35144,name="Dark Binding",level=35,requiredLevel=35,faction="horde",expansion=5,zoneID=6755,description="Even as we speak, the pale within Shadowfall Canyon are enslaving the elements to their will. Many elemental spirits have already been enthralled, and more will follow. The pale must be stopped and the elementals they enslave set free. Journey into Shadowfall Canyon and set free those elemental spirits which are not fully enthralled by the pale. As for the elementals already enslaved by the pale, the only mercy we can give them now is to release their bonds through death.",questType="standard"},
[35145] = {id=35145,name="The Pale Threat",level=35,requiredLevel=35,faction="horde",expansion=5,zoneID=6755,description="The Pale are wretched creatures that hide beneath the ground, ever plotting against those who dwell upon the surface. They stalk the Underpale, a twisted and dark cavern beneath Oshu'gun. If we are to succeed in stopping Cho'gall we must fight our way through their ranks beneath the earth. Make your way into the cavern, slay the vile creatures within and take out the Pale leader... the one known as Greyseer .",questType="standard"},
[35146] = {id=35146,name="The Good Doctor",level=35,requiredLevel=35,faction="both",expansion=5,zoneID=6755,description="Our expedition biologist has been kidnapped by podlings! We came to Nagrand to explore, to slay the mightiest of beasts, and test our mettle alongside the great Hemet Nesingwary. As soon as we arrived, Hemet's hunting prowess was needed to combat the Warsong. Rather than sit around twiddling our thumbs, we decided to continue the expedition! We were exploring Spiteleaf Thicket when podlings ambushed us! In the chaos, Dr. Hadley Ricard was taken captive. Please, we can't just leave him there!",starts={{npcID=84632,x=0.774,y=0.474,zoneID=6755}},ends={{npcID=84861,x=0.866,y=0.284,zoneID=6755}},coords={x=0.774,y=0.474,source="quest_giver",zoneID=6755},questType="standard"},
[35147] = {id=35147,name="Fragments of the Past",level=35,requiredLevel=35,faction="both",expansion=5,zoneID=6755,mapID=550,starts={{npcID=87393,x=0.502,y=0.412,mapID=550}},ends={{npcID=87393,x=0.502,y=0.412,mapID=550}},coords={x=0.502,y=0.412,source="quest_giver",mapID=550},questType="standard"},
[35148] = {id=35148,name="Trouble at the Overwatch",level=35,requiredLevel=35,faction="alliance",expansion=5,zoneID=6755,description="Ya know, we sent a couple o' scouts ta check out those big, smelly, 'civilized' ogres at Mar'gok's Overwatch. Haven't heard from 'em in a bit. Matter o' fact, not since I saved yer bacon up at Telaar. Have some time ta ride over there and check up on 'em, ?",starts={{npcID=79954,x=0.634,y=0.618,zoneID=6755}},ends={{npcID=79282,x=0.788,y=0.692,zoneID=6755}},coords={x=0.634,y=0.618,source="quest_giver",zoneID=6755},questType="standard"},
[35149] = {id=35149,name="Sparring Arena",level=1,requiredLevel=1,faction="horde",expansion=5,zoneID=6721,mapID=543,questType="standard"},
[35150] = {id=35150,name="Trouble at the Overwatch",level=35,requiredLevel=35,faction="horde",expansion=5,zoneID=6755,description="Yesterday, I sent two of my best scouts to spy on the ogres at Mar'gok's Overwatch. I haven't heard back from them. , would you do me the honor of checking on them? I'm sure it's nothing; the Overwatch is a large fortification. I'd feel better knowing they're okay.",starts={{npcID=81319,x=0.828,y=0.45,zoneID=6755}},ends={{npcID=79281,x=0.83,y=0.678,zoneID=6755}},coords={x=0.828,y=0.45,source="quest_giver",zoneID=6755},questType="standard"},
[35151] = {id=35151,name="Your Base, Your Choice",level=15,requiredLevel=15,faction="horde",expansion=5,zoneID=6721,description="You have already constructed an impressive garrison in Frostfire. I believe I should defer this next choice to you. One region of Gorgrond is rich in resources. A lumber mill could help us make the most of them. Another region harbors hardened gladiators. A sparring arena would help persuade them to fight for our cause. Either path will strengthen us as we seek to find and weaken the Iron Horde. Which do you choose, Commander?",starts={{npcID=74594,x=0.372,y=0.77,zoneID=6721}},ends={{npcID=74594,x=0.372,y=0.77,zoneID=6721}},coords={x=0.372,y=0.77,source="quest_giver",zoneID=6721},questType="standard"},
[35152] = {id=35152,name="The Sparring Arena",level=15,requiredLevel=15,faction="horde",expansion=5,zoneID=6721,description="We owe you our freedom, and more. I have spoken to the others, we are willing to return with you to your garrison and teach those pitiful creatures you call \"soldiers\" how to properly fight. We will also do our best to impart our knowledge to you, Commander. Should you have need of us when in the wilds of Gorgrond , simply call us. You may wish to warn Limbflayer of our coming.",starts={{npcID=79320,x=0.428,y=0.63,zoneID=6721}},ends={{npcID=76688,x=0.462,y=0.696,zoneID=6721}},coords={x=0.428,y=0.63,source="quest_giver",zoneID=6721},questType="standard"},
[35153] = {id=35153,name="Vignette: Fungal Praetorian",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6755,mapID=550,questType="standard"},
[35154] = {id=35154,name="Things Are Not Goren Our Way",level=15,requiredLevel=15,faction="horde",expansion=5,zoneID=7078,description="The abandoned mine shaft has been overrun with goren! They seem to be responding to commands from a big one further down in the mine. If you can take him out, the rest will probably retreat. Once you have those goren cleared out, we can get that mine up and working!",questType="standard"},
[35155] = {id=35155,name="Obliterating Ogres",level=35,requiredLevel=35,faction="horde",expansion=5,zoneID=6755,description="We got more of those magic tossing ogres here which is never a good thing. These new ogres are especially bossy and have increased work being done here. Do you know what stops ogres from working hard? Dying. Kill some ogres here and get this camp back to its normal boring self.",starts={{npcID=79281,x=0.83,y=0.678,zoneID=6755}},ends={{npcID=81361,x=0.838,y=0.768,zoneID=6755}},coords={x=0.83,y=0.678,source="quest_giver",zoneID=6755},questType="standard"},
[35156] = {id=35156,name="Removing the Paper Trail",level=35,requiredLevel=35,faction="horde",expansion=5,zoneID=6755,description="This box is filled with writings and diagrams that oddly resemble research into the nullification of magic. It would be best to ruin these efforts by destroying any research found.",starts={{npcID=231901,x=0.813,y=0.703,zoneID=6755}},ends={{npcID=81361,x=0.838,y=0.768,zoneID=6755}},coords={x=0.813,y=0.703,source="quest_giver",zoneID=6755},questType="standard"},
[35157] = {id=35157,name="Obtaining Ogre Offensive Orders",level=35,requiredLevel=35,faction="horde",expansion=5,zoneID=6755,description="The upper bluff must be really important to the ogres. Two fancy looking ogre mages came down from there and starting ordering all the others around. Go get those orders and meet up with my scout Dalgorsh on the upper bluff. They will be more useful to him up there.",starts={{npcID=79281,x=0.83,y=0.678,zoneID=6755}},ends={{npcID=81361,x=0.838,y=0.768,zoneID=6755}},coords={x=0.83,y=0.678,source="quest_giver",zoneID=6755},questType="standard"},
[35158] = {id=35158,name="Reglakk's Research",level=35,requiredLevel=35,faction="horde",expansion=5,zoneID=6755,description="Okay so these orders say Reglakk is in charge of something called Breaker research, which makes super powerful ogres. I don't know about you but that sounds bad. I'm pretty hurt, do you think you can go up there alone and make Reglakk rethink his research?",starts={{npcID=81361,x=0.838,y=0.768,zoneID=6755}},ends={{npcID=80003,x=0.828,y=0.45,zoneID=6755}},coords={x=0.838,y=0.768,source="quest_giver",zoneID=6755},questType="standard"},
[35159] = {id=35159,name="Removing the Reinforcements",level=35,requiredLevel=35,faction="horde",expansion=5,zoneID=6755,description="Its not good $p, these smart ogres have got a portal working up there and they are bringing in more ogres from somewhere else. It looks like it takes a lot of effort to keep it open though. If you take it down I'm guessing they will be delayed quite a while.",starts={{npcID=81361,x=0.838,y=0.768,zoneID=6755}},ends={{npcID=80003,x=0.828,y=0.45,zoneID=6755},{npcID=80140,x=0.828,y=0.442,zoneID=6755}},coords={x=0.838,y=0.768,source="quest_giver",zoneID=6755},questType="standard"},
[35161] = {id=35161,name="Vignette XP reward - Talador",level=20,requiredLevel=20,faction="none",expansion=5,zoneID=6720,mapID=525,description="This quest is a placeholder until Task 67719 is complete.",questType="standard"},
[35162] = {id=35162,name="Treasure: Grovestrider Nest",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6662,mapID=535,ends={{npcID=230643,x=0.746,y=0.293,mapID=535}},questType="standard"},
[35166] = {id=35166,name="Ship Salvage",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=15716,description="Commander, we are running low on supplies. Maybe we can salvage materials from that ship you arrived on? At the rate folks are coming through the portal we are going to be out of everything by sundown... or moondown? I'm still getting used to this place.",starts={{npcID=77209,x=0.32,y=0.314,zoneID=7078}},ends={{npcID=77209,x=0.32,y=0.314,zoneID=7078}},coords={x=0.32,y=0.314,source="quest_giver",zoneID=7078},questType="standard"},
[35167] = {id=35167,name="Lost in Nagrand",level=35,requiredLevel=35,faction="horde",expansion=5,zoneID=6755,description="Hey, , could you help me? There's this girl I know. Her name's Olgra . Her and her parents went back to Wor'var yesterday. Only, they never got there and no one's seen them. If you're heading back out, would you look for her? She's kinda my girlfriend.",starts={{npcID=72822,x=0.492,y=0.48,zoneID=6755}},ends={{npcID=82688,x=0.74,y=0.376,zoneID=6755}},coords={x=0.492,y=0.48,source="quest_giver",zoneID=6755},questType="standard"},
[35168] = {id=35168,name="Your First Blacksmithing Work Order",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=7078,description="Now that the forge is complete, we can start producing truesteel ingots for you. When you have the ingredients, please speak with my assistant to start the first work order.",starts={{npcID=77359,x=0.502,y=0.574,zoneID=7078}},ends={{npcID=77792,x=0.502,y=0.574,zoneID=7078}},coords={x=0.502,y=0.574,source="quest_giver",zoneID=7078},questType="standard"},
[35169] = {id=35169,name="And Justice for Thrall",level=35,requiredLevel=35,faction="alliance",expansion=5,zoneID=6755,description="The time has come, commander. You've dealt with all of the Warsong's allies and holdings. Our troops are massing at the gates of Grommashar. The rangari have reliable intel that Garrosh is holed up inside the Warsong fortress. All of our efforts have led to this moment. Let's take out Garrosh.",starts={{npcID=79576,x=0.634,y=0.618,zoneID=6755}},ends={{npcID=81412,x=0.668,y=0.338,zoneID=6755}},coords={x=0.634,y=0.618,source="quest_giver",zoneID=6755},questType="standard"},
[35170] = {id=35170,name="Consumed by Vengeance",level=35,requiredLevel=35,faction="horde",expansion=5,zoneID=6755,description="They... they came out of nowhere. From that direction. They were on their nasty wolves. Please, commander, my family's honor is at stake. Will you get vengeance for me?",starts={{npcID=82688,x=0.74,y=0.376,zoneID=6755}},ends={{npcID=72822,x=0.492,y=0.48,zoneID=6755}},coords={x=0.74,y=0.376,source="quest_giver",zoneID=6755},questType="standard"},
[35171] = {id=35171,name="And Justice for Thrall",level=35,requiredLevel=35,faction="horde",expansion=5,zoneID=7545,description="The time has come, commander. You've dealt with all of the Warsong's allies and holdings. Our troops are massing at the gates of Grommashar. The shadow hunters have reliable intel that Garrosh is holed up inside the Warsong fortress. All of our efforts have led to this moment. Let's put an end to this once and for all.",starts={{npcID=80003,x=0.828,y=0.45,zoneID=6755}},ends={{npcID=81415,x=0.668,y=0.338,zoneID=6755}},coords={x=0.828,y=0.45,source="quest_giver",zoneID=6755},questType="standard"},
[35172] = {id=35172,name="Your Second Blacksmithing Work Order",level=10,requiredLevel=10,faction="both",expansion=5,zoneID=7004,mapID=525,description="Place another work order with my assistant. Once it is complete, we will leave it out here for you to collect.",ends={{npcID=77792,x=0.502,y=0.574,mapID=539},{npcID=79817,x=0.534,y=0.364,mapID=525}},questType="standard"},
[35174] = {id=35174,name="Pale Moonlight",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=6719,description="We are getting strange reports of an orc attack on a nearby draenei settlement called Eventide Landing. I'm hearing these particular orcs are unlike any we have encountered before. They seem... sickly, and are pale in color. The locals could use our help, commander. This seems like the perfect opportunity to test our garrison's capabilities.",starts={{npcID=79457,x=0.44,y=0.528,zoneID=7078}},ends={{npcID=79457,x=0.44,y=0.528,zoneID=7078}},coords={x=0.44,y=0.528,source="quest_giver",zoneID=7078},questType="standard"},
[35176] = {id=35176,name="Keeping it Together",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=7078,description="So much work to do... I don't even know where to start. Making sure this garrison is operational is not an easy task. Shelly still hasn't reported back to me, my assistant Brightstone and her crew are who knows where, ugh... I'm so caught up I haven't even had time to check our cache for resources. If I were a mage, do you think I could use mirror images to do all of this at once?",starts={{npcID=77209,x=0.32,y=0.314,zoneID=7078}},ends={{npcID=77209,x=0.32,y=0.314,zoneID=7078}},coords={x=0.32,y=0.314,source="quest_giver",zoneID=7078},questType="standard"},
[35185] = {id=35185,name="Garrison Campaign: The Sargerei",level=40,requiredLevel=40,faction="alliance",expansion=5,zoneID=6719,description="Greetings, . Archmage Khadgar wishes you to hear an important message. The draenei suffered a great betrayal when one of their leaders, Exarch Othaar, revealed himself to be working with the Legion. In the hills above Shadowmoon Valley, Othaar, who now goes by the name Socrethar, gathers new recruits to his cause. Archmage Modera is in charge of this covert operation, which we need your help carrying out. Meet her in the field, and she will give you the details.",starts={{npcID=83858,x=0.528,y=0.51,zoneID=7004},{npcID=83858,x=0.378,y=0.396,zoneID=7078}},ends={{npcID=88276,x=0.436,y=0.772,zoneID=6719}},coords={x=0.528,y=0.51,source="quest_giver",zoneID=7004},questType="standard"},
[35186] = {id=35186,name="Garrison Campaign: The Sargerei",level=40,requiredLevel=40,faction="horde",expansion=5,zoneID=6719,description="Greetings, . Archmage Khadgar wishes you to hear an important message. The draenei suffered a great betrayal when one of their leaders, Exarch Othaar, revealed himself to be working with the Legion. In the hills above Shadowmoon Valley, Othaar, who now goes by the name Socrethar, gathers new recruits to his cause. Archmage Modera is in charge of this covert operation, which we need your help carrying out. Meet her in the field, and she will give you the details.",starts={{npcID=83858,x=0.528,y=0.51,zoneID=7004},{npcID=83858,x=0.378,y=0.396,zoneID=7078}},ends={{npcID=88276,x=0.436,y=0.772,zoneID=6719}},coords={x=0.528,y=0.51,source="quest_giver",zoneID=7004},questType="standard"},
[35187] = {id=35187,name="Infiltrating the Sargerei",level=40,requiredLevel=40,faction="alliance",expansion=5,zoneID=6719,description="One of my men has already infiltrated the Sargerei's ranks, but I need you to help him. In order to protect his cover, you will need to disguise yourself as one of the enemy. Kill Sargerei until you collect a cowl, robe, and slippers to create a disguise. After donning the disguise, introduce yourself to Soulbinder Zamaya as a new student, then tell Anchorite Laanda that 'the rain falls on Shadowmoon.' The secret phrase will identify yourself as an ally.",starts={{npcID=88276,x=0.436,y=0.772,zoneID=6719}},ends={{npcID=81530,x=0.5,y=0.812,zoneID=6719}},coords={x=0.436,y=0.772,source="quest_giver",zoneID=6719},questType="standard"},
[35188] = {id=35188,name="Pesky Podlings",level=40,requiredLevel=40,faction="both",expansion=5,zoneID=6719,description="Ah, initiate. Are you ready for your first task? The woods to the south are filled with pesky podlings. The filthy things dig up our farms, steal supplies, and prey on unwitting trainees. They are disgusting, horrible creatures which need to be eliminated. I will require their spears as proof that you finished this task.",starts={{npcID=81499,x=0.498,y=0.814,zoneID=6719}},ends={{npcID=81499,x=0.498,y=0.814,zoneID=6719}},coords={x=0.498,y=0.814,source="quest_giver",zoneID=6719},questType="standard"},
[35189] = {id=35189,name="The Word of Socrethar",level=40,requiredLevel=40,faction="both",expansion=5,zoneID=6719,description="The Sargerei follow Socrethar zealously. From what I can gather, he is a persuasive and compelling leader. Many of the initiates carry books of his writings. I need you to read these works and report back to me. If we can understand the Sargerei's motivations, perhaps we can undermine them. I last saw these books near the lake, on a table near the fountain, and in the house near the gardens.",starts={{npcID=81530,x=0.5,y=0.812,zoneID=6719}},ends={{npcID=81530,x=0.5,y=0.812,zoneID=6719}},coords={x=0.5,y=0.812,source="quest_giver",zoneID=6719},questType="standard"},
[35190] = {id=35190,name="An Ancient Threat",level=40,requiredLevel=40,faction="both",expansion=5,zoneID=6719,description="To the northwest, an Ancient has settled into a forest glade. I need someone to take care of this nuisance. This should be a simple matter, even for an initiate like you.",starts={{npcID=81499,x=0.498,y=0.814,zoneID=6719}},ends={{npcID=81499,x=0.498,y=0.814,zoneID=6719}},coords={x=0.498,y=0.814,source="quest_giver",zoneID=6719},questType="standard"},
[35191] = {id=35191,name="Shattering the Enemy",level=40,requiredLevel=40,faction="both",expansion=5,zoneID=6719,description="While you carry out the pretense of obeying Zamaya's orders, we're going to sabotage the Sargerei under their very noses. All around this village, you can find Felstorm Crystals . The enemy uses these objects to magnify their power. Destroy these crystals, and we'll slow their operations.",starts={{npcID=81530,x=0.5,y=0.812,zoneID=6719}},ends={{npcID=81530,x=0.5,y=0.812,zoneID=6719}},coords={x=0.5,y=0.812,source="quest_giver",zoneID=6719},questType="standard"},
[35192] = {id=35192,name="See Reinforcements Teleport",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6662,mapID=535,questType="standard"},
[35194] = {id=35194,name="Facing Demons",level=40,requiredLevel=40,faction="both",expansion=5,zoneID=6719,description="Time is running out, . The Sargerei have opened a summoning portal on the hill to the west. I believe they are going to use this portal to bring an army of demons here, to Shadowmoon Valley. We must stop them before this happens, no matter what the cost. Use this arcane bomb to destroy the portal. We may blow our cover, but stopping the portal is more important right now.",starts={{npcID=81530,x=0.5,y=0.812,zoneID=6719}},ends={{npcID=231918,x=0.5,y=0.812,zoneID=6719}},coords={x=0.5,y=0.812,source="quest_giver",zoneID=6719},questType="standard"},
[35195] = {id=35195,name="Socrethar's Fury",level=40,requiredLevel=40,faction="both",expansion=5,zoneID=6719,description="Anchorite Laanda .> I write this message hastily. I've been discovered. I'm being taken in front of Socrethar. You must carry on our mission. I've learned that Soulbinder Zamaya holds a detailed plan of Socrethar's next attack. She still trusts you, so you should be able to enter the main building. Please, find those plans, !",starts={{npcID=231918,x=0.5,y=0.812,zoneID=6719}},ends={{npcID=81530,x=0.5,y=0.812,zoneID=6719}},coords={x=0.5,y=0.812,source="quest_giver",zoneID=6719},questType="standard"},
[35196] = {id=35196,name="Forging Ahead",level=40,requiredLevel=40,faction="alliance",expansion=5,zoneID=7078,description="Anchorite Laanda 's voice is barely a whisper.> You must report back... to Khadgar. Socrethar means to take Shattrath. He will... continue to recruit followers... to his side... Thank you for... helping me... in my final hour... Leave me... I would like to rest...",starts={{npcID=81530,x=0.5,y=0.812,zoneID=6719}},ends={{npcID=83858,x=0.528,y=0.51,zoneID=7004},{npcID=83858,x=0.378,y=0.396,zoneID=7078}},coords={x=0.5,y=0.812,source="quest_giver",zoneID=6719},questType="standard"},
[35197] = {id=35197,name="Forging Ahead",level=40,requiredLevel=40,faction="horde",expansion=5,zoneID=7078,description="Anchorite Laanda 's voice is barely a whisper.> You must report back... to Khadgar. Socrethar means to take Shattrath. He will... continue to recruit followers... to his side... Thank you for... helping me... in my final hour... Leave me... I would like to rest...",starts={{npcID=81530,x=0.5,y=0.812,zoneID=6719}},ends={{npcID=83858,x=0.528,y=0.51,zoneID=7004},{npcID=83858,x=0.378,y=0.396,zoneID=7078}},coords={x=0.5,y=0.812,source="quest_giver",zoneID=6719},questType="standard"},
[35201] = {id=35201,name="Krixel",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6722,mapID=542,questType="standard"},
[35202] = {id=35202,name="Shells for Xuk",level=15,requiredLevel=15,faction="horde",expansion=5,zoneID=9786,description="The magics Xuk is weaving will let you perform great acts, but preparations must be made before the spirits will bless us with their power. Xuk needs many shells from the pesky goren. To gather them, Xuk will share a secret. Approach their tunnel craters and the goren will pour out. This way, you kill many at once.",starts={{npcID=84743,x=0.462,y=0.55,zoneID=6721}},ends={{npcID=84743,x=0.462,y=0.55,zoneID=6721}},coords={x=0.462,y=0.55,source="quest_giver",zoneID=6721},questType="standard"},
[35204] = {id=35204,name="Pollen Power",level=15,requiredLevel=15,faction="alliance",expansion=5,zoneID=6721,description="The botani use monstrous insect-like creatures to pollinate their bloom. The pollen they carry has a number of powerful properties that would be of use to your garrison forces. If you bring me a reserve of this pollen I should be able to convert it to something of value.",starts={{npcID=81589,x=0.46,y=0.766,zoneID=6721}},ends={{npcID=81589,x=0.46,y=0.766,zoneID=6721}},coords={x=0.46,y=0.766,source="quest_giver",zoneID=6721},questType="standard"},
[35205] = {id=35205,name="Burn the Bodies",level=15,requiredLevel=15,faction="alliance",expansion=5,zoneID=6721,description="You don't understand. Anythin' these plant people don't infest they fatten up and then turn inta mulch. I say we take out their food source. These botani got a few corpses lying around that I saw. Might be a good idea to burn those bodies. Let's find out if they can infest ash.",starts={{npcID=81601,x=0.42,y=0.834,zoneID=6721}},ends={{npcID=81601,x=0.42,y=0.834,zoneID=6721}},coords={x=0.42,y=0.834,source="quest_giver",zoneID=6721},questType="standard"},
[35206] = {id=35206,name="Bushwhacker",level=15,requiredLevel=15,faction="alliance",expansion=5,zoneID=6721,description="We are continuing the search for Thaelin's people, but these botani, they are a larger threat than we ever realized. To infest their victims... monstrous. Please, commander, if you find yourself in Evermorn Springs to our west, slay as many of those creatures as you can. Stop them from committing such acts of horror. Bring them to justice.",starts={{npcID=81590,x=0.46,y=0.766,zoneID=6721}},ends={{npcID=81590,x=0.46,y=0.766,zoneID=6721}},coords={x=0.46,y=0.766,source="quest_giver",zoneID=6721},questType="standard"},
[35207] = {id=35207,name="Coalpart's Revenge",level=15,requiredLevel=15,faction="alliance",expansion=5,zoneID=6721,description="I'm so full I can't swing an axe even if I had one. Tell ya what, we got a mutual interest here. I need yer help to get a little vengeance on the big botani at the back of this bloom. In return, I'll point ya in the right direction fer gettin' a secret weapon the botani keep.",starts={{npcID=81601,x=0.42,y=0.834,zoneID=6721}},ends={{npcID=81601,x=0.42,y=0.834,zoneID=6721}},coords={x=0.42,y=0.834,source="quest_giver",zoneID=6721},questType="standard"},
[35208] = {id=35208,name="Dark Iron Down",level=15,requiredLevel=15,faction="alliance",expansion=5,zoneID=6721,description="While you were away our rangari here found more clues leadin' to some of me other friends. Burrian Coalpart and Scorchbrow. Problem is, their trail heads right for Evermorn Springs to the west. Please Commander, will ya get in there and save them from mulching?",starts={{npcID=81588,x=0.46,y=0.768,zoneID=6721}},ends={{npcID=81600,x=0.42,y=0.834,zoneID=6721}},coords={x=0.46,y=0.768,source="quest_giver",zoneID=6721},questType="standard"},
[35209] = {id=35209,name="The Life Spring",level=15,requiredLevel=15,faction="alliance",expansion=5,zoneID=6721,description="So we came here cause we needed a weapon we saw the botani using. Hansel grabbed the artifact an' Scorchbrow an' I were supposed to grab the special water the thing runs on. We didn't know that water so full of life forms an elemental. If ya mosey up to the cauldron at the base of that fancy lookin' ancient artifact in Evermorn Springs, you'll be findin' this beast. If ya can kill it and get its water, we can use it when we get the rest of the artifact.",starts={{npcID=81601,x=0.42,y=0.834,zoneID=6721}},ends={{npcID=81590,x=0.46,y=0.766,zoneID=6721}},coords={x=0.42,y=0.834,source="quest_giver",zoneID=6721},questType="standard"},
[35210] = {id=35210,name="A Great Escape",level=15,requiredLevel=15,faction="both",expansion=5,zoneID=6721,description="A goren tunnel ! Once the cap is cleared, it's certain to lead outside of this Light-forsaken pit.",questType="standard"},
[35211] = {id=35211,name="Preventing the Worst",level=30,requiredLevel=30,faction="both",expansion=5,zoneID=6722,description="Have you seen all the fungus on the buildings in Pinchwhistle Point? It's only a matter of time 'til it releases enough spores to infest the whole coastline! The remaining infected that are in Pinchwhistle Point will be too far gone for us to save later on, so let's do the right thing and put them out of their misery and prevent an even worse outbreak. I made some firebombs that will burn the fungus down, but I'll need you to place them while I set up the detonator. Are you up for it?",starts={{npcID=81443,x=0.584,y=0.922,zoneID=6722}},ends={{npcID=81443,x=0.584,y=0.922,zoneID=6722}},coords={x=0.584,y=0.922,source="quest_giver",zoneID=6722},questType="standard"},
[35212] = {id=35212,name="Deeproot",level=15,requiredLevel=15,faction="alliance",expansion=5,zoneID=6721,description="Since yer all set up to take on trees and bushes now, I need ta ask for a favor. I came to Gorgrond in search of an expedition of me fellow Dark Irons that were headed this way. Sadly I lost 'em. I am goin' south to look for them. Thing is, south is nothing but botani, podlings, giant trees, and other mean, angry plants. Yer lumber camp resources would be mighty appreciated. If ya help me look for me friends I swear we'll help ya in any way we can.",starts={{npcID=75136,x=0.632,y=0.524,zoneID=6721}},ends={{npcID=81588,x=0.46,y=0.768,zoneID=6721}},coords={x=0.632,y=0.524,source="quest_giver",zoneID=6721},questType="standard"},
[35213] = {id=35213,name="The Razorbloom",level=15,requiredLevel=15,faction="alliance",expansion=5,zoneID=6721,description="Kaalya thinks she picked up a trail. Seems a bunch of dwarves went north to Razorbloom by the signs. Problem is that place is filled with plant people. I ain't much use against plant people. Are you willing to investigate?",starts={{npcID=81588,x=0.46,y=0.768,zoneID=6721}},ends={{npcID=81588,x=0.46,y=0.768,zoneID=6721}},coords={x=0.46,y=0.768,source="quest_giver",zoneID=6721},questType="standard"},
[35214] = {id=35214,name="The Infested",level=15,requiredLevel=15,faction="alliance",expansion=5,zoneID=6721,description="D'kaan did not say it, but there were more rangari taken by the botani than the ones you found. He believes they were slain. I fear worse. You might dare to venture into the Razorbloom. If you do, you may discover what the botani do to their... \"prisoners.\" Give these poor souls a proper release.",starts={{npcID=81589,x=0.46,y=0.766,zoneID=6721}},ends={{npcID=81589,x=0.46,y=0.766,zoneID=6721}},coords={x=0.46,y=0.766,source="quest_giver",zoneID=6721},questType="standard"},
[35215] = {id=35215,name="The Voice of Iyu",level=15,requiredLevel=15,faction="alliance",expansion=5,zoneID=6721,description="Journal Entry 25 - The botani got themselves a leader who calls himself... er... herself... er... itself the Voice of Iyu . Seems the botani see the genesaur as gods and only the most bossy of the botani get to speak on behalf of the genesaur. When we tried askin' it about the artifact we found back at the base it got all angry and sent off Lera and Nori and I ain't seen either of them since. I got a bad feelin' about this thing.",starts={{npcID=231903,x=0.476,y=0.728,zoneID=6721}},ends={{npcID=81588,x=0.46,y=0.768,zoneID=6721}},coords={x=0.476,y=0.728,source="quest_giver",zoneID=6721},questType="standard"},
[35216] = {id=35216,name="Super Seeds",level=15,requiredLevel=15,faction="alliance",expansion=5,zoneID=6721,description="These seeds have been shielded with care by the botani. Great power can be felt surging out of these tiny vessels of life. These may prove useful.",starts={{npcID=235129,x=0.494,y=0.709,zoneID=6721}},ends={{npcID=81588,x=0.46,y=0.768,zoneID=6721}},coords={x=0.494,y=0.709,source="quest_giver",zoneID=6721},questType="standard"},
[35218] = {id=35218,name="Iron Horde Orders",level=15,requiredLevel=15,faction="both",expansion=5,zoneID=6721,description="Spirit spotted some orders at the Iron Horde camp on the nearby bluff. You must have missed them when you were there. Could you look into it?",starts={{npcID=80856,x=0.46,y=0.548,zoneID=6721}},ends={{npcID=233391,x=0.478,y=0.521,zoneID=6721}},coords={x=0.46,y=0.548,source="quest_giver",zoneID=6721},questType="standard"},
[35219] = {id=35219,name="Vignette: Burning Front",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6662,mapID=535,questType="standard"},
[35220] = {id=35220,name="Vignette: Kharazos the Triumphant",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6662,mapID=535,questType="standard"},
[35225] = {id=35225,name="A Heavy Helping Hand",level=15,requiredLevel=15,faction="alliance",expansion=5,zoneID=6721,description="Burrian gave us the coordinates of the Dark Iron base. They named it Moira's Reach. But half way through buildin' it the base got infested with goren. If you head south you should come to the structure. Just look for a big ol' cannon. We will follow as soon as we get this bloody tank untangled.",starts={{npcID=81588,x=0.46,y=0.768,zoneID=6721}},ends={{npcID=75710,x=0.476,y=0.94,zoneID=6721}},coords={x=0.46,y=0.768,source="quest_giver",zoneID=6721},questType="standard"},
[35226] = {id=35226,name="Old Friends, New Enemies",level=20,requiredLevel=20,faction="horde",expansion=5,zoneID=6662,description="I cannot believe Orgrim would continue to do Blackhand's bidding after all the destruction he has wrought. We must confront him. Join me at the village along Orunai Coast and we will confront my oldest friend.",starts={{npcID=75806,x=0.614,y=0.108,zoneID=6662}},ends={{npcID=75958,x=0.59,y=0.202,zoneID=6662}},coords={x=0.614,y=0.108,source="quest_giver",zoneID=6662},questType="standard"},
[35227] = {id=35227,name="Ogre Diplomacy",level=20,requiredLevel=20,faction="alliance",expansion=5,zoneID=6662,description="Ogres are ogres. Spirits or not, the Ango'rosh are not different. Even with their ritual books, they won't relinquish their power to you until you prove yourself. I've fought ogres my entire life, and there's only one way to earn that. Killing them outright. The more Ango'rosh spirits and their pets as you take out while you're there, the more respect you'll command among them.",starts={{npcID=75392,x=0.43,y=0.76,zoneID=6662}},ends={{npcID=75392,x=0.43,y=0.76,zoneID=6662}},coords={x=0.43,y=0.76,source="quest_giver",zoneID=6662},questType="standard"},
[35229] = {id=35229,name="Down the Goren Hole",level=15,requiredLevel=15,faction="alliance",expansion=5,zoneID=6721,description="These beasts came at us so fast we didn't have time to mount a proper defense. They went right for the metal and chewed through any wall we had. If we don't kill some of them soon they'll bring the whole fortress down on us.",questType="standard"},
[35231] = {id=35231,name="Spiritual Matters",level=35,requiredLevel=35,faction="horde",expansion=5,zoneID=6755,description="The spirits of the dead have long been drawn to Oshu'gun. As long as I can remember, the woods have been filled with ancestral spirits making a ghostly pilgrimage to the heart of the mountain. However, I fear that what is transpiring here is not the normal spirit walk I have seen before. Make your way to the Ancestral Grounds and commune with the spirits there for guidance on this matter.",starts={{npcID=81335,x=0.556,y=0.558,zoneID=6755}},ends={{npcID=80864,x=0.404,y=0.568,zoneID=6755}},coords={x=0.556,y=0.558,source="quest_giver",zoneID=6755},questType="standard"},
[35232] = {id=35232,name="The Call of Oshu'gun",level=35,requiredLevel=35,faction="horde",expansion=5,zoneID=6755,description="The elements have spoken and a vision has been revealed, . Together we shall travel to the great mountain Oshu'gun and put an end to the dark disturbance there. If what you saw in the vision is to be believed, then great danger awaits us. I will meet you in the Spirit Woods at the foot of Oshu'gun. When you are ready to depart, speak with Gixmo Moneycash and he will fly you there.",starts={{npcID=80597,x=0.718,y=0.196,zoneID=6755}},ends={{npcID=81335,x=0.556,y=0.558,zoneID=6755}},coords={x=0.718,y=0.196,source="quest_giver",zoneID=6755},questType="standard"},
[35233] = {id=35233,name="Just In Case",level=15,requiredLevel=15,faction="alliance",expansion=5,zoneID=6721,description="When we set up shop the first thing we built was the cannon. Seemed like a good place fer it. We started buildin' the base up around it when them chompin' acid spittin' varmints came crawlin' out of the ground. The upside though is the cannon is built, just not loaded. We have to go down to the bottom floor of this thing anyway so may as well grab some Doomshot if you see any on your way down. Better to load the cannon and not need it than to need it and not have it loaded.",questType="standard"},
[35234] = {id=35234,name="Will of the Genesaur",level=15,requiredLevel=15,faction="alliance",expansion=5,zoneID=6721,description="When the goren attacked we threw everything we had at them but they just kept comin'. So some of the lads went and stole a fancy artifact from the botani. Problem was we couldn't get it to work. Now the artifact is sitting at the bottom of the bastion. To get to it you got to go all the way to the back of the tunnels past all them goren and find the wee tunnel that takes you farther underground. If you retrieve it, it is yours.",questType="standard"},
[35235] = {id=35235,name="Iyu",level=15,requiredLevel=15,faction="alliance",expansion=5,zoneID=6721,description="Did ya hear that? Sounds like that genesaur wants its 'will' back. I told ya this place is nuthin' but bad luck. I'll git that shot ya gave me loaded properly and see if I can't weaken that thing up. You better get up there and deal with it though...",questType="standard"},
[35238] = {id=35238,name="New Owner",level=20,requiredLevel=20,faction="horde",expansion=5,zoneID=6662,mapID=535,starts={{npcID=79853,x=0.628,y=0.504,mapID=535}},ends={{npcID=79853,x=0.628,y=0.504,mapID=535}},coords={x=0.628,y=0.504,source="quest_giver",mapID=535},questType="standard"},
[35239] = {id=35239,name="New Owner",level=20,requiredLevel=20,faction="alliance",expansion=5,zoneID=6662,mapID=535,starts={{npcID=79853,x=0.628,y=0.504,mapID=535}},ends={{npcID=79853,x=0.628,y=0.504,mapID=535}},coords={x=0.628,y=0.504,source="quest_giver",mapID=535},questType="standard"},
[35240] = {id=35240,name="Bled Dry",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=7025,description="They kept us in cages. They... drain our blood, for... rituals... ...many left -- -- my... people...",starts={{npcID=81762,x=0.622,y=0.53,zoneID=7025}},ends={{npcID=78559,x=0.602,y=0.562,zoneID=7025}},coords={x=0.622,y=0.53,source="quest_giver",zoneID=7025},questType="standard"},
[35241] = {id=35241,name="Vengeance for the Fallen",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=4,description="Too many of my people have fallen at the hands of the Bleeding Hollow. Their cruelty cannot be forgiven. Make them pay.",starts={{npcID=81761,x=0.622,y=0.53,zoneID=7025}},ends={{npcID=78553,x=0.5,y=0.134,zoneID=7025},{npcID=78553,x=0.82,y=0.452,zoneID=7025},{npcID=78553,x=0.55,y=0.502,zoneID=4}},coords={x=0.622,y=0.53,source="quest_giver",zoneID=7025},questType="standard"},
[35242] = {id=35242,name="Vengeance for the Fallen",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=4,description="Too many of my people have fallen at the hands of the Bleeding Hollow. Their cruelty cannot be forgiven. Make them pay.",starts={{npcID=81763,x=0.622,y=0.53,zoneID=7025}},ends={{npcID=78554,x=0.486,y=0.142,zoneID=7025},{npcID=78554,x=0.81,y=0.458,zoneID=7025},{npcID=78554,x=0.548,y=0.502,zoneID=4}},coords={x=0.622,y=0.53,source="quest_giver",zoneID=7025},questType="standard"},
[35243] = {id=35243,name="The Dark Lady's Gift",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=7333,starts={{npcID=81765,x=0.536,y=0.518,mapID=525},{npcID=81765,x=0.618,y=0.232,zoneID=7333}},ends={{npcID=81765,x=0.536,y=0.518,mapID=525},{npcID=81765,x=0.618,y=0.232,zoneID=7333}},coords={x=0.536,y=0.518,source="quest_giver",zoneID=7004},questType="standard"},
[35244] = {id=35244,name="Vignette: Skagg",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6662,mapID=535,questType="standard"},
[35245] = {id=35245,name="A Sentimental Relic",level=30,requiredLevel=30,faction="both",expansion=5,zoneID=6722,description="My father's bangle sat here for ages before that imposter Ikiss stole it away. I thank you for returning it, but I have no need for keepsakes. Take it, with my blessing. If there are still Talonpriests loyal to the true Talon King, please bring it to them.",starts={{npcID=80834,x=0.604,y=0.388,zoneID=6722}},ends={{npcID=81770,x=0.464,y=0.466,zoneID=6722}},coords={x=0.604,y=0.388,source="quest_giver",zoneID=6722},questType="standard"},
[35247] = {id=35247,name="Zero Xuks Given",level=15,requiredLevel=15,faction="horde",expansion=5,zoneID=6721,description="The spirits have spoken to me. They believe the magnaron, Gro the Uncreator, will join our fight and lead his underlings against the Iron Horde. This is an honor beyond any bestowed upon a Laughing Skull, at least in my time. I will commune with the magnaron, and together we shall destroy the Iron Horde.",starts={{npcID=84748,x=0.438,y=0.488,zoneID=6721}},ends={{npcID=85980,x=0.44,y=0.488,zoneID=6721}},coords={x=0.438,y=0.488,source="quest_giver",zoneID=6721},questType="standard"},
[35248] = {id=35248,name="A Harsh Reminder",level=15,requiredLevel=15,faction="horde",expansion=5,zoneID=6721,description="Welcome to the front lines, outsider, where the wastelands and the jungle collide. When their forces forget about the ferocity of the Laughing Skull, this is where we come to make them remember. By fierce and merciless destruction we survive. This is the way of Gorgrond . Join in! Let us see if you can withstand the brutality of our land.",starts={{npcID=81202,x=0.436,y=0.65,zoneID=6721}},ends={{npcID=81202,x=0.436,y=0.65,zoneID=6721}},coords={x=0.436,y=0.65,source="quest_giver",zoneID=6721},questType="standard"},
[35249] = {id=35249,name="Powering the Defenses",level=20,requiredLevel=20,faction="horde",expansion=5,zoneID=6662,description="It's good to see a Horde champion joining the fight. Auchindoun's defenses are faltering quickly. The few Auchenai soulpriests not on the front are working fervently to maintain them. Soulbinder Tuulani went inside the nearby Tomb of Lights to retrieve a backup power pylon and hasn't returned. If you can find her and get her and the pylon back here safely it would help greatly.",questType="standard"},
[35252] = {id=35252,name="Chest Reward Tracking Quest",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6720,mapID=525,questType="standard"},
[35253] = {id=35253,name="FLAG: Thaelin Event Complete",level=1,requiredLevel=1,faction="both",expansion=5,questType="standard"},
[35254] = {id=35254,name="Retribution for the Light",level=20,requiredLevel=20,faction="alliance",expansion=5,zoneID=6662,description="There are agents of darkness everywhere, fighting tooth and nail to envelop the world. The Light relies on us to balance the scale. You have the power needed to destroy Teron'gor's demonic minions once and for all. Send them to the Twisting Nether in pieces!",starts={{npcID=75392,x=0.43,y=0.76,zoneID=6662}},ends={{npcID=75392,x=0.43,y=0.76,zoneID=6662},{npcID=77581,x=0.456,y=0.74,zoneID=6662}},coords={x=0.43,y=0.76,source="quest_giver",zoneID=6662},questType="standard"},
[35255] = {id=35255,name="Power of the Genesaur",level=15,requiredLevel=15,faction="alliance",expansion=5,zoneID=6721,description="Commander, you now have the Will of the Genesaur along with the genesis water and enough seeds to grow an army. Not to mention the lives of the dwarves you saved. I would call this mission a success. I can help the dwarves mop up their operation here and see what we can salvage. In the meantime, you may want to bring the artifact to Maraad back at the outpost.",starts={{npcID=75878,x=0.476,y=0.932,zoneID=6721}},ends={{npcID=75127,x=0.528,y=0.596,zoneID=6721}},coords={x=0.476,y=0.932,source="quest_giver",zoneID=6721},questType="standard"},
[35257] = {id=35257,name="Power Unearthed",level=30,requiredLevel=30,faction="both",expansion=5,zoneID=6722,description="What power could reduce a village to ashes in the blink of an eye? The Adherents claim it is the will of Rukhmar. A lie, obviously. They did nothing to earn such power - in truth, they stumbled upon it rather unwittingly, in a hole in the ground. Come and visit me near the excavation site just west of here. We must understand their technology if we are to defeat it.",starts={{npcID=85598,x=0.444,y=0.24,zoneID=6722}},ends={{npcID=80157,x=0.368,y=0.246,zoneID=6722}},coords={x=0.444,y=0.24,source="quest_giver",zoneID=6722},questType="standard"},
[35258] = {id=35258,name="Legacy of the Apexis",level=30,requiredLevel=30,faction="both",expansion=5,zoneID=6722,description="The Apexis are long gone, but their legacy lies preserved in ancient chambers beneath Arak. Legions of dormant constructs; crystals flush with solar energy; magical techniques lost to the ages - the Apexis left behind caches of immense power, which the Adherents of Rukhmar have begun to unearth. Bring me the cores of the re-activated constructs patrolling the excavation site. Those crystals are the basis of Apexis technology, and the key to our enemy's devastating power.",starts={{npcID=80157,x=0.368,y=0.246,zoneID=6722}},ends={{npcID=80157,x=0.368,y=0.246,zoneID=6722}},coords={x=0.368,y=0.246,source="quest_giver",zoneID=6722},questType="standard"},
[35259] = {id=35259,name="Sol Sisters",level=30,requiredLevel=30,faction="both",expansion=5,zoneID=6722,description="When I was still a guard in Skyreach, I was tasked with protecting the sisters Veoryx and Krashyx. They were prodigies. At an age when most sun acolytes could barely read, the sisters conjured familiars of pure sunlight to illuminate their textbooks in the small hours. Now they unravel the secrets of Apexis technology, and their excavation has just breached two ancient chambers. Enter those chambers and cut down the sisters before they reap the terrible rewards of their discovery.",starts={{npcID=80155,x=0.368,y=0.244,zoneID=6722}},ends={{npcID=82123,x=0.326,y=0.29,zoneID=6722}},coords={x=0.368,y=0.244,source="quest_giver",zoneID=6722},questType="standard"},
[35260] = {id=35260,name="Hardly Working",level=30,requiredLevel=30,faction="both",expansion=5,zoneID=6722,description="Those who were not incinerated at Veil Akraz are forced to help the Adherents excavate the very weapons aimed at their heads. Anyone trying to escape is vaporized by the overseer's Apexis turret. With these effigies, they won't know anyone has left! Place one near an enslaved worker and observe as it creates a perfect copy. It even cloaks the subject in shadow, so they can slip away safely!",starts={{npcID=80157,x=0.368,y=0.246,zoneID=6722}},ends={{npcID=80157,x=0.368,y=0.246,zoneID=6722}},coords={x=0.368,y=0.246,source="quest_giver",zoneID=6722},questType="standard"},
[35261] = {id=35261,name="Shot-Caller",level=30,requiredLevel=30,faction="both",expansion=5,zoneID=6722,description="Outside, an arakkoa overseer bellows commands, each answered by the buzz of an Apexis beam carving away at the mountain. That turret would make short work of the constructs - if you can command it.>",starts={{npcID=82123,x=0.326,y=0.29,zoneID=6722}},ends={{npcID=232353,x=0.355,y=0.321,zoneID=6722}},coords={x=0.326,y=0.29,source="quest_giver",zoneID=6722},questType="standard"},
[35262] = {id=35262,name="Service of Rangari Kaalya",level=15,requiredLevel=15,faction="alliance",expansion=5,zoneID=6721,mapID=543,starts={{npcID=81772,x=0.476,y=0.932,mapID=543}},ends={{npcID=80987,x=0.632,y=0.522,mapID=543},{npcID=81589,x=0.46,y=0.766,mapID=543},{npcID=81772,x=0.476,y=0.932,mapID=543}},coords={x=0.476,y=0.932,source="quest_giver",mapID=543},questType="standard"},
[35264] = {id=35264,name="A Bunch of Artifact Fragments",level=40,requiredLevel=40,faction="alliance",expansion=5,zoneID=8485,starts={{npcID=81870,x=0.458,y=0.762,zoneID=6941},{npcID=81870,zoneID=8485}},ends={{npcID=81870,x=0.458,y=0.762,zoneID=6941},{npcID=81870,zoneID=8485}},coords={x=0.458,y=0.762,source="quest_giver",zoneID=6941},questType="standard"},
[35265] = {id=35265,name="The Ritual of Binding",level=35,requiredLevel=35,faction="horde",expansion=5,zoneID=6755,description="The time has come for you to undertake the Ritual of Binding, . This ancient, shamanic rite has been practiced since long before I was born. To be chosen is a great honor. Many shaman see vivid elemental visions during the rite; experiencing this world through the very elemental bonds that hold it together. When you are ready, speak with Kalandrios to begin the rite.",starts={{npcID=80597,x=0.718,y=0.196,zoneID=6755}},ends={{npcID=80597,x=0.718,y=0.196,zoneID=6755}},coords={x=0.718,y=0.196,source="quest_giver",zoneID=6755},questType="standard"},
[35271] = {id=35271,name="The Warsong Threat",level=35,requiredLevel=35,faction="horde",expansion=5,zoneID=6755,description="To all outrider stations: The warlord has commanded that all outriders prepare for a full assault upon the Horde invaders in our land. Plans for the attack have been delivered to several of the remote outrider posts. Blood and glory shall be ours as we trample the Horde invaders beneath our feet! The warlord commands and the Warsong obey! Lok'tar ogar!",starts={{npcID=232024,x=0.519,y=0.62,zoneID=6755}},ends={{npcID=81193,x=0.494,y=0.478,zoneID=6755}},coords={x=0.519,y=0.62,source="quest_giver",zoneID=6755},questType="standard"},
[35272] = {id=35272,name="One of Our Own",level=30,requiredLevel=30,faction="horde",expansion=5,zoneID=6722,description="Da bird-men captured me while I was gettin' da lay a da land. We been workin' on an outpost for you just round dis mountain so your will be spreadin' all over da continent. Things not be goin' well. I be needin' your assistance, commander. Can you tell dem that I mean no harm so I can be showin' you da outpost?",starts={{npcID=81890,x=0.46,y=0.464,zoneID=6722}},ends={{npcID=81890,x=0.46,y=0.464,zoneID=6722}},coords={x=0.46,y=0.464,source="quest_giver",zoneID=6722},questType="standard"},
[35273] = {id=35273,name="Hot Seat",level=30,requiredLevel=30,faction="both",expansion=5,zoneID=6722,description="The interface and the turret hum in soft resonance.>",starts={{npcID=232353,x=0.355,y=0.321,zoneID=6722}},ends={{npcID=80155,x=0.368,y=0.244,zoneID=6722}},coords={x=0.355,y=0.321,source="quest_giver",zoneID=6722},questType="standard"},
[35274] = {id=35274,name="One of Our Own",level=30,requiredLevel=30,faction="alliance",expansion=5,zoneID=6722,description="These wretched creatures captured me while I was scouting the area. Now that you're here, commander, we could really use your help back at base. Oh, and any way you could convince your... friends... to let me go? They, uh... won't let me leave.",starts={{npcID=81891,x=0.458,y=0.464,zoneID=6722}},ends={{npcID=81891,x=0.458,y=0.464,zoneID=6722}},coords={x=0.458,y=0.464,source="quest_giver",zoneID=6722},questType="standard"},
[35275] = {id=35275,name="Inspecting the Troops",level=30,requiredLevel=30,faction="horde",expansion=5,zoneID=6722,mapID=542,description="Axefall be just a moment's ride from here. I be markin' da location on your map and meet you dere.",starts={{npcID=81890,x=0.46,y=0.464,mapID=542}},ends={{npcID=81913,x=0.4,y=0.44,mapID=542}},coords={x=0.46,y=0.464,source="quest_giver",mapID=542},questType="standard"},
[35276] = {id=35276,name="Inspecting the Troops",level=30,requiredLevel=30,faction="alliance",expansion=5,zoneID=6722,description="Southport lies not far from here to the southwest. No time for chit-chat. I will meet you there, commander.",starts={{npcID=81891,x=0.458,y=0.464,zoneID=6722}},ends={{npcID=81915,x=0.4,y=0.604,zoneID=6722}},coords={x=0.458,y=0.464,source="quest_giver",zoneID=6722},questType="standard"},
[35277] = {id=35277,name="Orders, Commander?",level=30,requiredLevel=30,faction="horde",expansion=5,zoneID=6722,description="Commander, our status report is... regrettable. We'll be out of supplies in a few days' time, and that's assuming we have any troops left by then. There's just enough material left to put up an inn or a trading post. The inn would allow us to station fresh troops here, but the trading post would open up potential supply routes with the outcasts nearby. I've left out Gazlowe's blueprints on the drafting table . We await your will.",starts={{npcID=81920,x=0.402,y=0.434,zoneID=6722}},ends={{npcID=81920,x=0.402,y=0.434,zoneID=6722}},coords={x=0.402,y=0.434,source="quest_giver",zoneID=6722},questType="standard"},
[35279] = {id=35279,name="Treasure: Shadowmoon Treasure 01",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6719,mapID=539,ends={{npcID=232066,x=0.288,y=0.071,mapID=539}},questType="standard"},
[35280] = {id=35280,name="Treasure: Shadowmoon Treasure 02",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6719,mapID=539,ends={{npcID=232067,x=0.271,y=0.025,mapID=539}},questType="standard"},
[35281] = {id=35281,name="Vignette: Bahameye",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6721,mapID=543,questType="standard"},
[35282] = {id=35282,name="Treasure - Glowing Blue Mushroom",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6720,mapID=525,questType="standard"},
[35283] = {id=35283,name="Inn",level=11,requiredLevel=11,faction="horde",expansion=5,zoneID=6722,mapID=542,questType="standard"},
[35284] = {id=35284,name="Trading Post",level=11,requiredLevel=11,faction="horde",expansion=5,zoneID=6722,mapID=542,questType="standard"},
[35285] = {id=35285,name="Follow that Hotrod!",level=30,requiredLevel=30,faction="both",expansion=5,zoneID=6722,description="Miss Kimzee is one tough nugget but Pinchwhistle Point is too dangerous for her to handle alone. It'll be a catastrophe for morale if our boss gets infected. I need to get these crewmen back to the Gearworks so I need you to go and make sure she is alright. Her uncle's place is the tower just on the other side of the oil fields; I think you should look for her around there.",starts={{npcID=81784,x=0.59,y=0.792,zoneID=6722}},ends={{npcID=81972,x=0.584,y=0.922,zoneID=6722}},coords={x=0.59,y=0.792,source="quest_giver",zoneID=6722},questType="standard"},
[35286] = {id=35286,name="Orders, Commander?",level=30,requiredLevel=30,faction="alliance",expansion=5,zoneID=6722,description="Commander , it's an honor. We're barely holding on, . We have a week's supplies at best, assuming we have any troops left to supply in that time. We have just enough material left to put up an inn or a trading post. The inn would allow us to station reinforcements here, while the trading post would allow supply routes with the outcasts nearby. We need your authorization for the project, commander. It's your decision.",starts={{npcID=81929,x=0.398,y=0.608,zoneID=6722}},ends={{npcID=81929,x=0.398,y=0.608,zoneID=6722}},coords={x=0.398,y=0.608,source="quest_giver",zoneID=6722},questType="standard"},
[35289] = {id=35289,name="Treasure: Shadowmoon Treasure 04",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=7078,mapID=539,ends={{npcID=232090,x=0.514,y=0.017,mapID=539}},questType="standard"},
[35290] = {id=35290,name="Inn",level=11,requiredLevel=11,faction="alliance",expansion=5,zoneID=6722,mapID=542,questType="standard"},
[35291] = {id=35291,name="Trading Post",level=11,requiredLevel=11,faction="alliance",expansion=5,zoneID=6722,mapID=542,questType="standard"},
[35292] = {id=35292,name="Ang'kra, the Alchemist",level=10,requiredLevel=10,faction="none",expansion=5,zoneID=6720,mapID=525,questType="standard"},
[35293] = {id=35293,name="Old Friends",level=30,requiredLevel=30,faction="alliance",expansion=5,zoneID=6722,description="Admiral Taylor was ordered to establish a garrison inland while we erected yours in Shadowmoon Valley. He settled just a short ways north of here. The two of us could go there and borrow some supplies to tide us over before our next shipment. What do you say, commander? I'm sure the admiral will be thrilled to see you again.",starts={{npcID=81949,x=0.398,y=0.606,zoneID=6722}},ends={{npcID=81960,x=0.392,y=0.49,zoneID=6722}},coords={x=0.398,y=0.606,source="quest_giver",zoneID=6722},questType="standard"},
[35295] = {id=35295,name="What's Theirs is Ours",level=30,requiredLevel=30,faction="horde",expansion=5,zoneID=6722,description="I found somethin' else while I was scoutin', boss. Da Alliance have a garrison just across da way, and der been no movement in or out of da place in a good while. Dis be a golden opportunity to sack da place and bolster your coffers, commander. What do ya say? We do it together.",starts={{npcID=81959,x=0.402,y=0.434,zoneID=6722}},ends={{npcID=81961,x=0.392,y=0.488,zoneID=6722}},coords={x=0.402,y=0.434,source="quest_giver",zoneID=6722},questType="standard"},
[35296] = {id=35296,name="Tainted Garden",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=7078,mapID=539,description="The abandonded mine shaft has been overrun with Goren! They seem to be responding to commands from a big one further down in the mine. If you can take him out, the rest will probably retreat. Once you have those Goren cleared out, we can get that mine up and working!",questType="standard"},
[35297] = {id=35297,name="FLAG: Army Pushed",level=1,requiredLevel=1,faction="both",expansion=5,questType="standard"},
[35298] = {id=35298,name="Flame On",level=30,requiredLevel=30,faction="both",expansion=5,zoneID=6722,description="Alright , we've saved as many as we could but now we need to make sure this disaster doesn't spread any further. The firebombs are wired up and ready to go. Kimzee just finished work on the flying machine so we're ready to ride back to the Gearworks as soon as we're finished. You've done all the hard work so I think you should get the honors of triggering it.",starts={{npcID=81443,x=0.584,y=0.922,zoneID=6722}},ends={{npcID=82468,x=0.616,y=0.728,zoneID=6722}},coords={x=0.584,y=0.922,source="quest_giver",zoneID=6722},questType="standard"},
[35317] = {id=35317,name="The Dark Heart of Oshu'gun",level=35,requiredLevel=35,faction="horde",expansion=5,zoneID=6755,description="We are not far from the inner chamber, . The truth behind the evil here awaits us. I can project my spirit into the chamber to guide you, but it will be up to you to defeat the evil that lays within. May the wind of Kalandrios guide your arm, the wisdom of Aborius enlighten your faculties, and the flame of Incineratus burn your enemies. May the memory of Gordawg be your shield.",questType="standard"},
[35322] = {id=35322,name="I See Dead People",level=30,requiredLevel=30,faction="horde",expansion=5,zoneID=6722,description="Everybody here be... dead. Dis architect's spirit not be wantin' to fight us. Even in death he only be wantin' to work. Maybe we can break da haze over him and get to da bottom of dis. I bet one of da spectral laborers be havin' one of his schematics we can show to him to clear his mind.",starts={{npcID=81961,x=0.392,y=0.488,zoneID=6722}},ends={{npcID=82100,x=0.39,y=0.488,zoneID=6722},{npcID=82101,x=0.39,y=0.488,zoneID=6722}},coords={x=0.392,y=0.488,source="quest_giver",zoneID=6722},questType="standard"},
[35329] = {id=35329,name="I See Dead People",level=30,requiredLevel=30,faction="alliance",expansion=5,zoneID=6722,description="Th... they're ghosts! All of them! Bryan was one of my best friends. Something is clouding his mind; we need to snap him out of it and get to the bottom of this! He was always obsessed with his work. Maybe showing him one of his schematics would help. One of the spectral laborers might have one.",starts={{npcID=81960,x=0.392,y=0.49,zoneID=6722}},ends={{npcID=82100,x=0.39,y=0.488,zoneID=6722}},coords={x=0.392,y=0.49,source="quest_giver",zoneID=6722},questType="standard"},
[35330] = {id=35330,name="The Ritual of Binding",level=35,requiredLevel=35,faction="alliance",expansion=5,zoneID=6755,description="It is time for you to undergo the Ritual of Binding, . I will wait here as you speak with Kalandrios to begin the rite. During the ritual, you will experience the vision of the elements. Return to me when the ritual is complete, and we will speak more.",starts={{npcID=82138,x=0.718,y=0.196,zoneID=6755}},ends={{npcID=82138,x=0.718,y=0.196,zoneID=6755}},coords={x=0.718,y=0.196,source="quest_giver",zoneID=6755},questType="standard"},
[35331] = {id=35331,name="Called to the Throne",level=35,requiredLevel=35,faction="alliance",expansion=5,zoneID=6755,description="I was far from here in Talador when the voice called out to me. I looked around but found myself alone. Again, I heard the voice as if it were a breeze in my mind. \"You are needed at the throne,\" it whispered. The voice called itself Kalandrios, and it guided me to this place. I had never been here before, nor had I yet beheld these furies with my eyes; yet this feels strangely familiar to me as if it happened long ago in a forgotten dream. We should greet the furies and hear them out.",starts={{npcID=82138,x=0.718,y=0.196,zoneID=6755}},ends={{npcID=82138,x=0.718,y=0.196,zoneID=6755}},coords={x=0.718,y=0.196,source="quest_giver",zoneID=6755},questType="standard"},
[35332] = {id=35332,name="Nobundo Sends Word",level=35,requiredLevel=35,faction="alliance",expansion=5,zoneID=6755,description="Your presence has been requested at the Throne of Elements, . Vindicator Nobundo has heard the call of the furies upon the wind and made the journey to commune with the elements. I know not what the intentions of the furies are, but they are revered as noble and powerful spirits by the orcs.",starts={{npcID=79576,x=0.634,y=0.618,zoneID=6755}},ends={{npcID=82138,x=0.718,y=0.196,zoneID=6755}},coords={x=0.634,y=0.618,source="quest_giver",zoneID=6755},questType="standard"},
[35333] = {id=35333,name="Elemental Attunement",level=35,requiredLevel=35,faction="alliance",expansion=5,zoneID=6755,description="Even now, as we speak, the voice of Kalandrios continues to whisper to my mind. \"The Hero of Azeroth must attune to the elements of the plateau.\" Upon the Elemental Plateau are four great pillars carved of living rock. Lay your hands upon the stone pillars and your soul will be attuned with the elements. I will continue to commune with the great furies and attempt to further understand their will while you journey to the plateau.",starts={{npcID=82138,x=0.718,y=0.196,zoneID=6755}},ends={{npcID=82138,x=0.718,y=0.196,zoneID=6755}},coords={x=0.718,y=0.196,source="quest_giver",zoneID=6755},questType="standard"},
[35334] = {id=35334,name="Vignette: The Egg of Varasha",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6722,mapID=542,questType="standard"},
[35335] = {id=35335,name="Vignette: Bashiok",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6721,mapID=543,questType="standard"},
[35337] = {id=35337,name="That Pounding Sound",level=35,requiredLevel=35,faction="alliance",expansion=5,zoneID=6755,description="Commander. The rangari and I were just discussing the merits of various 'hunting' approaches. I assured her that the SI:7 are well-equipped to deal with any situation, even ones out in the wild. She seems to think that we don't know what we're doing when it comes to bringing down game in 'her land.' We're not going to let her get away with saying that, right? Let's take down some clefthoof.",starts={{npcID=82092,x=0.634,y=0.614,zoneID=6755}},ends={{npcID=82092,x=0.634,y=0.614,zoneID=6755}},coords={x=0.634,y=0.614,source="quest_giver",zoneID=6755},questType="standard"},
[35338] = {id=35338,name="Shooting the Breeze",level=35,requiredLevel=35,faction="alliance",expansion=5,zoneID=6755,description="Kia and I are having a spirited debate over who kills more efficiently: SI:7 or rangari. Care to get in on the wager, commander? I've been focusing on talbuk because of their fierce majesty. They truly encapsulate the grandeur of Nagrand as any native of Draenor knows.",starts={{npcID=82094,x=0.634,y=0.614,zoneID=6755}},ends={{npcID=82094,x=0.634,y=0.614,zoneID=6755}},coords={x=0.634,y=0.614,source="quest_giver",zoneID=6755},questType="standard"},
[35339] = {id=35339,name="A Parting Favor",level=30,requiredLevel=30,faction="alliance",expansion=5,zoneID=6722,description="I don't know what happened. My crew and I must have been the first to fall. My wife, the innkeeper, is in the same stupor you found me in. I can feel it... and there are others with her. Please, give the townsfolk peace and show their essences to my wife. That should bring her back from that cold abyss.",starts={{npcID=82100,x=0.39,y=0.488,zoneID=6722},{npcID=82101,x=0.39,y=0.488,zoneID=6722}},ends={{npcID=82124,x=0.376,y=0.51,zoneID=6722}},coords={x=0.39,y=0.488,source="quest_giver",zoneID=6722},questType="standard"},
[35341] = {id=35341,name="Defection of Gronnstalker Rokash",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=6720,description="You have done me a great service. This blade is as much yours as it is mine. I offer you this blood oath: I shall serve your cause and lend my knowledge of blades and mining to your forces. Will you accept it?",ends={{npcID=79229,x=0.594,y=0.318,zoneID=6720}},questType="standard"},
[35342] = {id=35342,name="The Mysterious Flask",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=7078,mapID=539,description="The liquid swirling around inside the flask clearly has strong alchemical properties, but its nature is beyond your training. You have heard that one of the Eventide villagers at your garrison has some knowledge of the alchemy of Draenor. Perhaps he could tell you more?",ends={{npcID=82466,x=0.472,y=0.458,mapID=539}},questType="standard"},
[35343] = {id=35343,name="The Young Alchemist",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=6719,description="I learned a little about alchemy from my aunt. If you want to know more, though, you should speak with my cousin Abatha . She was apprenticing under my aunt before she passed away. Abatha lives near the Verdant Mire with her father and sister.",starts={{npcID=82466,x=0.472,y=0.458,zoneID=7078}},ends={{npcID=82497,x=0.558,y=0.412,zoneID=6719}},coords={x=0.472,y=0.458,source="quest_giver",zoneID=7078},questType="standard"},
[35344] = {id=35344,name="The Missing Father",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=6719,description="I would be happy to help with your alchemical inquiries, but right now I am worried about my father. It's been quite some time since he went hunting down by the river, but he still hasn't returned home. I need to watch Lumiel. Will you please find him?",starts={{npcID=82497,x=0.558,y=0.412,zoneID=6719}},ends={{npcID=82496,x=0.54,y=0.456,zoneID=6719}},coords={x=0.558,y=0.412,source="quest_giver",zoneID=6719},questType="standard"},
[35345] = {id=35345,name="Shocking Assistance",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=6719,description="It's been a struggle to support the family since my wife died, and I got too ambitious when I got a contract for shockscales . Alas, there is no way I will hunt enough eels to fulfill it in time now.",starts={{npcID=82496,x=0.54,y=0.456,zoneID=6719}},ends={{npcID=82497,x=0.558,y=0.412,zoneID=6719}},coords={x=0.54,y=0.456,source="quest_giver",zoneID=6719},questType="standard"},
[35346] = {id=35346,name="Abatha, the Alchemist",level=10,requiredLevel=10,faction="none",expansion=5,zoneID=6720,mapID=525,questType="standard"},
[35347] = {id=35347,name="Treasure: Ogre Booty 000",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6720,mapID=525,questType="standard"},
[35350] = {id=35350,name="Queen of the Clefthoof",level=35,requiredLevel=35,faction="alliance",expansion=5,zoneID=6755,description="Laara told me that they have Banthar here! Or rather, that she's still alive back now. Did what I just said make any sense? This is our chance, commander. We can defeat a younger, more powerful version of Banthar and really stick it to these rangari. We'll show Laara how a true professional works.",starts={{npcID=82092,x=0.634,y=0.614,zoneID=6755}},ends={{npcID=82092,x=0.634,y=0.614,zoneID=6755}},coords={x=0.634,y=0.614,source="quest_giver",zoneID=6755},questType="standard"},
[35353] = {id=35353,name="A Piece of the Puzzle",level=30,requiredLevel=30,faction="alliance",expansion=5,zoneID=6722,description="I... I remember now. Watch Commander Branson told us to stay in the inn... he said we would be safe here. Then... Then that THING broke through and slaughtered everyone! The last thing I remember seeing was it descending into the larder.",starts={{npcID=82124,x=0.376,y=0.51,zoneID=6722}},ends={{npcID=82126,x=0.376,y=0.508,zoneID=6722}},coords={x=0.376,y=0.51,source="quest_giver",zoneID=6722},questType="standard"},
[35356] = {id=35356,name="Someone's Missing Arrow",level=35,requiredLevel=35,faction="alliance",expansion=5,zoneID=6755,description="Rangari Laara will be interested in your find.>",ends={{npcID=82094,x=0.634,y=0.614,zoneID=6755}},questType="standard"},
[35357] = {id=35357,name="King of the Breezestriders",level=35,requiredLevel=35,faction="alliance",expansion=5,zoneID=6755,description="Let me guess, you found it in a talbuk's flank? That arrow was intended for Tall Buck, king of the Breezestriders. Another talbuk - the one you killed - jumped in the way as I was taking my shot. I suggest you go after the king. When I was hunting him, he seemed fond of the pond at Lonely Falls to the south.",starts={{npcID=82094,x=0.634,y=0.614,zoneID=6755}},ends={{npcID=82094,x=0.634,y=0.614,zoneID=6755}},coords={x=0.634,y=0.614,source="quest_giver",zoneID=6755},questType="standard"},
[35367] = {id=35367,name="Treasure: Ogre Booty 001",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6720,mapID=525,questType="standard"},
[35368] = {id=35368,name="Treasure: Ogre Booty 002",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6720,mapID=525,questType="standard"},
[35369] = {id=35369,name="Treasure: Ogre Booty 003",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6720,mapID=525,questType="standard"},
[35370] = {id=35370,name="Treasure: Ogre Booty 004",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6720,mapID=525,questType="standard"},
[35371] = {id=35371,name="Treasure: Ogre Booty 005",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6720,mapID=525,questType="standard"},
[35372] = {id=35372,name="The Call of Oshu'gun",level=35,requiredLevel=35,faction="alliance",expansion=5,zoneID=6755,description="The elements have spoken and a vision has been revealed, . Together we shall travel to the great mountain Oshu'gun and put an end to the dark disturbance there. If what you saw in the vision is to be believed, then great danger awaits us. I will meet you in the Spirit Woods at the foot of Oshu'gun. When you are ready to depart, speak with Gixmo Moneycash and he will fly you to there.",starts={{npcID=82138,x=0.718,y=0.196,zoneID=6755}},ends={{npcID=82179,x=0.556,y=0.558,zoneID=6755}},coords={x=0.718,y=0.196,source="quest_giver",zoneID=6755},questType="standard"},
[35373] = {id=35373,name="Treasure: Ogre Booty 006",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6720,mapID=525,questType="standard"},
[35374] = {id=35374,name="That Pounding Sound",level=35,requiredLevel=35,faction="horde",expansion=5,zoneID=6755,description="Commander. The frostwolf and I were just discussing the merits of various 'hunting' approaches. I assured her that the shadow hunters are well-equipped to deal with any situation, even ones out in the wild. She seems to think that we don't know what we're doing when it comes to bringing down game in 'her land.' We're not going to let her get away with saying that, right? Let's take down some clefthoof.",starts={{npcID=82078,x=0.826,y=0.44,zoneID=6755}},ends={{npcID=82078,x=0.826,y=0.44,zoneID=6755}},coords={x=0.826,y=0.44,source="quest_giver",zoneID=6755},questType="standard"},
[35375] = {id=35375,name="Queen of the Clefthoof",level=35,requiredLevel=35,faction="horde",expansion=5,zoneID=6755,description="Ogka told me that they have Banthar here! Or rather, that she's still alive back now. Did what I just said make any sense? This is our chance, commander. We can defeat a younger, more powerful version of Banthar and really stick it to these frostwolves. We'll show Ogka how a true professional works.",starts={{npcID=82078,x=0.826,y=0.44,zoneID=6755}},ends={{npcID=82078,x=0.826,y=0.44,zoneID=6755}},coords={x=0.826,y=0.44,source="quest_giver",zoneID=6755},questType="standard"},
[35376] = {id=35376,name="Shooting the Breeze",level=35,requiredLevel=35,faction="horde",expansion=5,zoneID=6755,description="Taz and I are having a spirited debate over who kills more efficiently: shadow hunters or frostwolves. Care to get in on the wager, commander? I've been focusing on talbuk because of their fierce majesty. They truly encapsulate the grandeur of Nagrand as any native of Draenor knows.",starts={{npcID=82080,x=0.826,y=0.44,zoneID=6755}},ends={{npcID=82080,x=0.826,y=0.44,zoneID=6755}},coords={x=0.826,y=0.44,source="quest_giver",zoneID=6755},questType="standard"},
[35377] = {id=35377,name="Someone's Missing Axe",level=35,requiredLevel=35,faction="horde",expansion=5,zoneID=6755,description="Stalker Ogka will be interested in your find.>",ends={{npcID=82080,x=0.826,y=0.44,zoneID=6755}},questType="standard"},
[35378] = {id=35378,name="King of the Breezestriders",level=35,requiredLevel=35,faction="horde",expansion=5,zoneID=6755,description="Let me guess, you found it in a talbuk's flank? That axe was intended for Tall Buck, king of the Breezestriders. Another talbuk - the one you killed - jumped in the way as I was taking my shot. I suggest you go after the king. When I was hunting him, he seemed fond of the pond at Lonely Falls to the south.",starts={{npcID=82080,x=0.826,y=0.44,zoneID=6755}},ends={{npcID=82080,x=0.826,y=0.44,zoneID=6755}},coords={x=0.826,y=0.44,source="quest_giver",zoneID=6755},questType="standard"},
[35380] = {id=35380,name="Second in Command",level=30,requiredLevel=30,faction="alliance",expansion=5,zoneID=6722,description="Wait... I remember something else. Sir Edward ... he was shouting... looking for someone. I... I can't remember who. There were so many screams...",starts={{npcID=82126,x=0.376,y=0.508,zoneID=6722}},ends={{npcID=82194,x=0.376,y=0.538,zoneID=6722}},coords={x=0.376,y=0.508,source="quest_giver",zoneID=6722},questType="standard"},
[35381] = {id=35381,name="Treasure: Shadowmoon Treasure 05",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=7078,mapID=539,ends={{npcID=232248,x=0.427,y=0.544,mapID=539}},questType="standard"},
[35382] = {id=35382,name="Treasure: Shadowmoon Treasure 06",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=7078,mapID=539,ends={{npcID=232250,x=0.508,y=0.488,mapID=539}},questType="standard"},
[35383] = {id=35383,name="Treasure: Shadowmoon Treasure 07",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=7078,mapID=539,ends={{npcID=232251,x=0.31,y=0.283,mapID=539}},questType="standard"},
[35384] = {id=35384,name="Treasure: Shadowmoon Treasure 08",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=7078,mapID=539,ends={{npcID=232252,x=0.494,y=0.763,mapID=539}},questType="standard"},
[35386] = {id=35386,name="The Warsong Threat",level=35,requiredLevel=35,faction="alliance",expansion=5,zoneID=6755,description="To all outrider stations: The warlord has commanded that all outriders prepare for a full assault upon the Alliance invaders in our land. Plans for the attack have been delivered to several of the remote outrider posts. Blood and glory shall be ours as we trample the Alliance invaders beneath our feet! The warlord commands and the Warsong obey! Lok'tar ogar!",starts={{npcID=232024,x=0.519,y=0.62,zoneID=6755}},ends={{npcID=82252,x=0.62,y=0.62,zoneID=6755}},coords={x=0.519,y=0.62,source="quest_giver",zoneID=6755},questType="standard"},
[35393] = {id=35393,name="Spiritual Matters",level=35,requiredLevel=35,faction="alliance",expansion=5,zoneID=6755,description="The spirits of the dead have long been drawn to the mountain of Oshu'gun. As long as I can remember, the woods have been filled with ancestral spirits making a ghostly pilgrimage to the heart of the mountain. I fear that the souls drawn to Oshu'gun are being consumed by the growing void within the mountain. Make your way to the Ancestral Grounds and commune with the spirits there for guidance.",starts={{npcID=82179,x=0.556,y=0.558,zoneID=6755}},ends={{npcID=80864,x=0.404,y=0.568,zoneID=6755}},coords={x=0.556,y=0.558,source="quest_giver",zoneID=6755},questType="standard"},
[35395] = {id=35395,name="The Fate of Gordawg",level=35,requiredLevel=35,faction="alliance",expansion=5,zoneID=6755,description="Looming monstrously between us and the inner chamber is the great fury we have sought to return to the Throne of Elements. Gordawg stands before us enthralled; a slave to Cho'gall. My heart is heavy with grief to see such a great creature mindless and enslaved by evil. There is no going back, in order to push forward you must go through Gordawg. It pains me, but Gordawg must be slain. Slay Gordawg and return the fury's heart to the Throne of Elements where it belongs.",questType="standard"},
[35396] = {id=35396,name="The Dark Heart of Oshu'gun",level=35,requiredLevel=35,faction="alliance",expansion=5,zoneID=6755,description="Amongst the timeworn wreckage of the Genedar is the entrance to the vessel's inner chamber. The void energy appears to be most concentrated in that place. You must enter the inner chamber and face whatever evil lurks within. I fear whatever fate may have befallen the great naaru K'ure in that place, but regardless the evil there must be purged. May the Light be with you, .",questType="standard"},
[35397] = {id=35397,name="The Pale Threat",level=35,requiredLevel=35,faction="alliance",expansion=5,zoneID=6755,description="If we are to succeed in stopping Cho'gall from destroying the naaru, we will need to fight our way through the Underpale; a dark, winding cavern infested with the Pale. The Pale are fallen orcs that despise all that is good and holy. The longer they are left to their devices beneath the ground, the further their dark plots progress. Make your way into the Underpale, slay the vile creatures within and take out their leader, Greyseer .",questType="standard"},
[35398] = {id=35398,name="Dark Binding",level=35,requiredLevel=35,faction="alliance",expansion=5,zoneID=6755,description="Even as we speak, the pale are enslaving an army of elementals in Shadowfall Canyon. Many have already been enslaved and if we do not lend our aid, more will follow. Go to Shadowfall Canyon and set free the elemental spirits which are not yet fully enthralled by the pale. As for those already enslaved, the only mercy we can give them now is a swift death.",questType="standard"},
[35399] = {id=35399,name="Mossy Fate",level=15,requiredLevel=15,faction="horde",expansion=5,zoneID=6721,description="Your wolf queen will not let me out of her sight. The children of the magnaron may have destroyed my village but it was the children of the genesaur who took my people. The botani and their minions drag our people to the Razorbloom, and if we see them again, it is not as they were in life. You have already helped the Skulls, so I ask your help again. Enter the Razorbloom and search for my people that were recently taken. Perhaps they may even be alive.",starts={{npcID=74606,x=0.414,y=0.74,zoneID=6721}},ends={{npcID=74606,x=0.414,y=0.74,zoneID=6721}},coords={x=0.414,y=0.74,source="quest_giver",zoneID=6721},questType="standard"},
[35400] = {id=35400,name="The Infested",level=15,requiredLevel=15,faction="horde",expansion=5,zoneID=6721,description="I understand Kaz's desire to rescue her people, but her plan is reckless and she is not telling us everything. I came along to make sure she wasn't devising a plan against us and now I see this... this... horror. What did the botani do to these orcs? These infested souls need to be put to rest. Give them peace.",starts={{npcID=74593,x=0.466,y=0.714,zoneID=6721}},ends={{npcID=74593,x=0.466,y=0.714,zoneID=6721}},coords={x=0.466,y=0.714,source="quest_giver",zoneID=6721},questType="standard"},
[35402] = {id=35402,name="The Voice of Iyu",level=15,requiredLevel=15,faction="horde",expansion=5,zoneID=6721,description="The botani and their wretched minions take and take and take. They want food, they take our land. They want an army, they take our people. It is important to strike fear into the shrubby hearts of these plant people. Look for their leader, the Voice of Iyu . It is a botani who speaks on behalf of their genesaur master. Kill their precious leader in the safety of his precious bloom.",starts={{npcID=74606,x=0.414,y=0.74,zoneID=6721}},ends={{npcID=74606,x=0.414,y=0.74,zoneID=6721}},coords={x=0.414,y=0.74,source="quest_giver",zoneID=6721},questType="standard"},
[35406] = {id=35406,name="Super Seeds",level=15,requiredLevel=15,faction="horde",expansion=5,zoneID=6721,description="These seeds have been shielded with care by the botani. Great power can be felt surging out of these tiny vessels of life. These may prove useful.",starts={{npcID=235129,x=0.494,y=0.709,zoneID=6721}},ends={{npcID=74606,x=0.414,y=0.74,zoneID=6721}},coords={x=0.494,y=0.709,source="quest_giver",zoneID=6721},questType="standard"},
[35407] = {id=35407,name="Punishable by Death",level=30,requiredLevel=30,faction="alliance",expansion=5,zoneID=6722,description="Traitors, the lot! You're looking at the last bastion of forces still loyal to Admiral Taylor and the Alliance. I'll be damned if the defectors get away clean. You look like you're ready. Show them how we deal with their kind during times of war.",starts={{npcID=82194,x=0.376,y=0.538,zoneID=6722}},ends={{npcID=82194,x=0.376,y=0.538,zoneID=6722}},coords={x=0.376,y=0.538,source="quest_giver",zoneID=6722},questType="standard"},
[35408] = {id=35408,name="Prime the Cannons",level=30,requiredLevel=30,faction="alliance",expansion=5,zoneID=6722,description="The armory is lost to the traitors. All we have left are these few cannons with no ammunition. Soldier, I need you to recover cannonballs so we can get these things running. Actually, one more cannon wouldn't hurt, either.",starts={{npcID=82212,x=0.376,y=0.538,zoneID=6722}},ends={{npcID=82212,x=0.376,y=0.538,zoneID=6722}},coords={x=0.376,y=0.538,source="quest_giver",zoneID=6722},questType="standard"},
[35416] = {id=35416,name="Power of the Genesaur",level=15,requiredLevel=15,faction="horde",expansion=5,zoneID=6721,description="Commander, you now have the Will of the Genesaur along with the genesis water and enough seeds to grow an army. Not to mention the Laughing Skulls you helped save. I would call this mission a success. I will investigate this fortress further and see if there are more materials we might glean from it. In the meantime, you may want to bring these artifacts you have obtained to Durotan back at the outpost. I will catch up once we have finished here.",starts={{npcID=82337,x=0.476,y=0.932,zoneID=6721}},ends={{npcID=74594,x=0.372,y=0.77,zoneID=6721}},coords={x=0.476,y=0.932,source="quest_giver",zoneID=6721},questType="standard"},
[35429] = {id=35429,name="Pollen Power",level=15,requiredLevel=15,faction="horde",expansion=5,zoneID=6721,description="Those of us who grew up in Gorgrond have long learned a few secrets of the botani that can be used to grow our own plants. There is no such thing as a hungry Laughing Skull for this reason. The ravagers are the key. Outside of Evermorn Springs you will find ravagers of every type. Slay them and bring me the pollen they carry, and I can cultivate it to be of use to your garrison.",starts={{npcID=74606,x=0.414,y=0.74,zoneID=6721}},ends={{npcID=82228,x=0.42,y=0.858,zoneID=6721}},coords={x=0.414,y=0.74,source="quest_giver",zoneID=6721},questType="standard"},
[35430] = {id=35430,name="Cutter",level=15,requiredLevel=15,faction="horde",expansion=5,zoneID=6721,description="You found many Laughing Skulls. All friends, all loved, all dead. But you did not find my precious Cutter . They must have taken him to Evermorn Springs. Find him, and rescue him. He is a good boy, and deserves a better death than infesting. I am going to round up some ravagers and take the place by air. Look for me in Evermorn if you find Cutter before I do.",starts={{npcID=74606,x=0.414,y=0.74,zoneID=6721},{npcID=82228,x=0.42,y=0.858,zoneID=6721}},ends={{npcID=82254,x=0.436,y=0.84,zoneID=6721}},coords={x=0.414,y=0.74,source="quest_giver",zoneID=6721},questType="standard"},
[35432] = {id=35432,name="Bushwhacker",level=15,requiredLevel=15,faction="horde",expansion=5,zoneID=6721,description="Kaz is using us, I am sure of it. She is a Laughing Skull and must NOT be trusted. For now, I am willing to play along until we can learn more. Kaz is going to ask for you to travel to Evermorn Springs. When there, I recommend you slay any botani you encounter. Culling the numbers of these horrific casters will hopefully save future orcs from such a infested fate. I will stay with Kaz and keep a close eye on her.",starts={{npcID=74593,x=0.466,y=0.714,zoneID=6721},{npcID=82233,x=0.42,y=0.858,zoneID=6721}},ends={{npcID=82233,x=0.42,y=0.858,zoneID=6721}},coords={x=0.466,y=0.714,source="quest_giver",zoneID=6721},questType="standard"},
[35433] = {id=35433,name="Cut Them Down",level=15,requiredLevel=15,faction="horde",expansion=5,zoneID=6721,description="They steal children? Children?! Had you not rescued Kaz's child, he would be reduced to mulch just like the others. You should send them a message they will understand. Cut down their great dew casters. Rip them apart. Let them know that it is not okay to take our children.",starts={{npcID=82233,x=0.42,y=0.858,zoneID=6721}},ends={{npcID=82233,x=0.42,y=0.858,zoneID=6721}},coords={x=0.42,y=0.858,source="quest_giver",zoneID=6721},questType="standard"},
[35434] = {id=35434,name="The Life Spring",level=15,requiredLevel=15,faction="horde",expansion=5,zoneID=6721,description="It sounds like these... \"dwarves\"... you found managed to steal a powerful botani artifact. But the fools didn't know they need a special water to power it. To the north is a well along the Evermorn Rise. There you will find a guardian, a creature of water we have named Utrophis. Slay it and take its essence and you will be one step closer to claiming the power of the botani and their genesaur.",starts={{npcID=82228,x=0.42,y=0.858,zoneID=6721}},ends={{npcID=82228,x=0.42,y=0.858,zoneID=6721}},coords={x=0.42,y=0.858,source="quest_giver",zoneID=6721},questType="standard"},
[35444] = {id=35444,name="The Southern Wilds",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=6719,description="First the Iron Horde, then the Shadowmoon orcs, and now there's trouble brewing to the south! My brother is a feyrider to the south, at the Draakorium. He says that creatures from the swamp are venturing onto our lands. What is this world coming to? Anyway, you look like a seasoned adventurer. If you are heading that way, would you mind checking in over there?",starts={{npcID=82256,x=0.49,y=0.386,zoneID=6719}},ends={{npcID=76200,x=0.57,y=0.574,zoneID=6719}},coords={x=0.49,y=0.386,source="quest_giver",zoneID=6719},questType="standard"},
[35448] = {id=35448,name="Vignette: Darkmaster Go'vid",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6719,mapID=539,questType="standard"},
[35450] = {id=35450,name="The Southern Wilds",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=6719,description="I've heard disturbing news from our friends at The Draakorium, to the south. The town lies near a swamp, and recently, dangerous creatures have been venturing near its borders. You seem like a seasoned adventurer. If you are heading that way, would you mind checking in with our people there? I would feel much better if I knew they were safe.",starts={{npcID=81126,x=0.458,y=0.374,zoneID=6719}},ends={{npcID=76200,x=0.57,y=0.574,zoneID=6719}},coords={x=0.458,y=0.374,source="quest_giver",zoneID=6719},questType="standard"},
[35459] = {id=35459,name="The Southern Wilds",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=6719,description="Posted by: Prelate Reenu Noble friends of the Alliance, the draenei of The Draakorium greet you peacefully. The Draakorium is being attacked by enemies from the nearby swamps. An Azerothian caravan passed through recently, and may have ventured into dangerous territory. Any capable adventurer who can assist us with this problem will be rewarded handsomely.",starts={{npcID=232397,x=0.43,y=0.45,zoneID=7078},{npcID=232398,x=0.424,y=0.453,zoneID=7078},{npcID=232400,x=0.428,y=0.452,zoneID=7078}},ends={{npcID=76200,x=0.57,y=0.574,zoneID=6719}},coords={x=0.43,y=0.45,source="quest_giver",zoneID=7078},questType="standard"},
[35460] = {id=35460,name="Attack of the Iron Horde",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=4,description="We received reports of the Dark Portal turning red right before the attack. They call themselves the Iron Horde, yet they seem to have no affiliation with the Horde we know. Their army is extremely well equipped, and their numbers appear to be unending. They have already taken Nethergarde Keep. Our troops on the frontlines could use your help, .",starts={{npcID=82270,x=0.666,y=0.282,zoneID=4},{npcID=84929,x=0.52,y=0.286,zoneID=4}},ends={{npcID=82270,x=0.666,y=0.282,zoneID=4}},coords={x=0.666,y=0.282,source="quest_giver",zoneID=4},questType="standard"},
[35462] = {id=35462,name="Under Siege",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=4,description="Those Iron Horde cannons are laying waste to our troops. I'm not sure how much more of this we can handle. Our forces are already spread too thin. There has to be a way to stop those war machines.",starts={{npcID=82270,x=0.666,y=0.282,zoneID=4},{npcID=84929,x=0.52,y=0.286,zoneID=4}},ends={{npcID=82270,x=0.666,y=0.282,zoneID=4}},coords={x=0.666,y=0.282,source="quest_giver",zoneID=4},questType="standard"},
[35463] = {id=35463,name="Subversive Scouts",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=4,description="We have been unable to execute a vast majority of our battleplans. We are definitely being watched. The Iron Horde must have scouts planted throughout the Blasted Lands . Victory is slipping away from us.",starts={{npcID=82270,x=0.666,y=0.282,zoneID=4}},ends={{npcID=82270,x=0.666,y=0.282,zoneID=4}},coords={x=0.666,y=0.282,source="quest_giver",zoneID=4},questType="standard"},
[35464] = {id=35464,name="Ending Executions",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=4,description="We arrived as soon as we could... but we are too late. Nethergarde has fallen. The Iron Horde has taken a number of Nethergarde warriors prisoner. No doubt they are trying to squeeze vital information out of our troops. I fear once they are done with their interrogation they will not hesitate to execute their prisoners. Time is running out.",starts={{npcID=85213,x=0.668,y=0.28,zoneID=4}},ends={{npcID=85213,x=0.668,y=0.28,zoneID=4}},coords={x=0.668,y=0.28,source="quest_giver",zoneID=4},questType="standard"},
[35481] = {id=35481,name="Vignette: Nizzix",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6722,mapID=542,questType="standard"},
[35482] = {id=35482,name="Admiral Taylor",level=30,requiredLevel=30,faction="alliance",expansion=5,zoneID=6722,description="Admiral Taylor had figured out who was behind all this. He told us to save who we could... he wanted to handle matters himself. We never heard from him again, but we have our orders. Please... please find him. He went towards the farm.",starts={{npcID=82278,x=0.376,y=0.538,zoneID=6722},{npcID=82293,x=0.376,y=0.538,zoneID=6722}},ends={{npcID=82375,x=0.368,y=0.57,zoneID=6722}},coords={x=0.376,y=0.538,source="quest_giver",zoneID=6722},questType="standard"},
[35486] = {id=35486,name="Lunatic Lieutenants",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=4,description="It is time we learned more about our new enemy. Our scouts have identified a number of the Iron Horde's lieutenants. Their attack is too organized to be run by tribal knowledge alone. Surely their lieutenants have access to secret battleplans. You are the only soldier I can trust with this mission, .",starts={{npcID=84929,x=0.52,y=0.286,zoneID=4}},ends={{npcID=84929,x=0.52,y=0.286,zoneID=4}},coords={x=0.52,y=0.286,source="quest_giver",zoneID=4},questType="standard"},
[35487] = {id=35487,name="We Burn the Dead",level=15,requiredLevel=15,faction="horde",expansion=5,zoneID=6721,description="I saw lots of bodies here. Kaz always said to burn the bodies. That way they can't come back as the mean greens. We should burn the bodies.",starts={{npcID=82254,x=0.436,y=0.84,zoneID=6721},{npcID=82274,x=0.436,y=0.84,zoneID=6721}},ends={{npcID=82274,x=0.436,y=0.84,zoneID=6721}},coords={x=0.436,y=0.84,source="quest_giver",zoneID=6721},questType="standard"},
[35488] = {id=35488,name="Death to the Dreadmaul",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=4,description="The stupidity of the Dreadmaul ogres never ceases to amaze me. The Iron Horde is clearly using them to further their own nefarious agenda. Regardless, we must show the ogres what happens when you confront the Alliance. I think it's time we send the Dreadmaul ogres a message.",starts={{npcID=84929,x=0.52,y=0.286,zoneID=4}},ends={{npcID=84929,x=0.52,y=0.286,zoneID=4}},coords={x=0.52,y=0.286,source="quest_giver",zoneID=4},questType="standard"},
[35492] = {id=35492,name="For Nethergarde!",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=4,description="The Iron Horde controls Nethergarde Keep, but they are fools if they think we will not return to claim our land. My best troops are more than eager to spill the blood of those savages, but we need a champion like yourself to lead the charge.",starts={{npcID=84929,x=0.52,y=0.286,zoneID=4}},ends={{npcID=84929,x=0.52,y=0.286,zoneID=4}},coords={x=0.52,y=0.286,source="quest_giver",zoneID=4},questType="standard"},
[35494] = {id=35494,name="Mementos of the Fallen",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=4,description="There were so many of them. The guards couldn't stop them... nobody could stop them. So many souls stripped of their bodies by those savages. We must not forget those that gave their lives to try and defend Nethergarde. Please, if you find any mementos of the fallen, bring them back to me.",starts={{npcID=82447,x=0.52,y=0.286,zoneID=4}},ends={{npcID=82447,x=0.52,y=0.286,zoneID=4}},coords={x=0.52,y=0.286,source="quest_giver",zoneID=4},questType="standard"},
[35495] = {id=35495,name="Toothsmash the Annihilator",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=4,description="If the battleplans you brought back are true, the Dreadmaul ogres are as much to blame for this devastation as the Iron Horde. It's time we send those ogres a message. It looks like the Iron Horde's main contact is a large ogre in Dreadmaul named Toothsmash. Killing him will put a dent in their battleplans.",starts={{npcID=84929,x=0.52,y=0.286,zoneID=4}},ends={{npcID=84929,x=0.52,y=0.286,zoneID=4}},coords={x=0.52,y=0.286,source="quest_giver",zoneID=4},questType="standard"},
[35496] = {id=35496,name="Enohar's Revenge",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=4,description="They... they killed my sister. Those beasts marched right through the front gates and... it was horrible. The Dreadmaul ogres stood beside them during the attack. They will all suffer. Here take this poison, place a couple drops in their rat stew. The poison will slowly eat away at their insides. Causing a prolonged and painful death, just like they deserve. Please, for my sister.",starts={{npcID=76111,x=0.518,y=0.286,zoneID=4}},ends={{npcID=76111,x=0.518,y=0.286,zoneID=4}},coords={x=0.518,y=0.286,source="quest_giver",zoneID=4},questType="standard"},
[35500] = {id=35500,name="Gar'mak Bladetwist",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=4,description="With the intelligence you have gathered we have learned this assault is being led by a powerful Iron Horde orc named Gar'mak Bladetwist . He is hunkered down inside Okril'lon Hold. Killing him will not win this war, but it will surely break down the Iron Horde's communication. This will buy us valuable time while we gather more forces and outline a battleplan to deal with this new threat.",starts={{npcID=84929,x=0.52,y=0.286,zoneID=4}},ends={{npcID=84929,x=0.52,y=0.286,zoneID=4}},coords={x=0.52,y=0.286,source="quest_giver",zoneID=4},questType="standard"},
[35501] = {id=35501,name="Doomshot",level=15,requiredLevel=15,faction="horde",expansion=5,zoneID=6721,description="This ominously large explosive appears to be ammunition for the primary cannon that the Bastion is built around. The loading assembly must be on a lower floor, but this ammo did not make it that far.",questType="standard"},
[35504] = {id=35504,name="Iron Joker",level=1,requiredLevel=1,faction="none",expansion=5,questType="standard"},
[35505] = {id=35505,name="Lost Lumberjack",level=15,requiredLevel=15,faction="none",expansion=5,zoneID=6721,description="Me friend was in the mole machine wit' me. Good ol' Frenna tried to make the best of it by writin' all o' her observations down in a journal. Penny here wants me to tell ya where she is. I cannae say for sure, but she was followin' me outta here and I don't think she made it.",starts={{npcID=84811,x=0.558,y=0.714,zoneID=6721}},ends={{npcID=82569,x=0.57,y=0.718,zoneID=6721}},coords={x=0.558,y=0.714,source="quest_giver",zoneID=6721},questType="standard"},
[35506] = {id=35506,name="Growing Wood",level=15,requiredLevel=15,faction="horde",expansion=5,zoneID=6721,description="I found this dwarf, Thuldren, runnin' out of Tangleheart like his boots were on fire. Says his mole machine showed up here and he barely made it out alive. And another called Frenna might still be inside. One useful thing he told me is that the creatures in there have sap that can be used to grow things real fast. By the way, I'm gonna go lookin' for Thuldren's mole machine. Find me in Tangleheart when you're done.",starts={{npcID=82574,x=0.558,y=0.714,zoneID=6721},{npcID=85077,x=0.464,y=0.696,zoneID=6721}},ends={{npcID=82574,x=0.558,y=0.714,zoneID=6721}},coords={x=0.558,y=0.714,source="quest_giver",zoneID=6721},questType="standard"},
[35507] = {id=35507,name="Down the Goren Hole",level=15,requiredLevel=15,faction="horde",expansion=5,zoneID=6721,description="Dwarves are dumb. Don't they know that if you dig a deep hole you are going to have goren attack? If you are going to go into that iron fort you better kill a bunch of goren otherwise they are going to chew the walls enough to cause a cave-in. I would do it myself but I'm still stuffed from all that fruit the botani made me eat.",questType="standard"},
[35508] = {id=35508,name="Chapter I: Plant Food",level=15,requiredLevel=15,faction="horde",expansion=5,zoneID=6721,description="There are strange, glowing objects within Tangleheart, seemingly pollinated by a variety of stinging creature. The botani sometimes collect whatever the pods produce. I can't be sure what it is, but it might be dangerous to us. - Frenna",starts={{npcID=82569,x=0.57,y=0.718,zoneID=6721}},ends={{npcID=82574,x=0.558,y=0.714,zoneID=6721}},coords={x=0.57,y=0.718,source="quest_giver",zoneID=6721},questType="standard"},
[35509] = {id=35509,name="Will of the Genesaur",level=15,requiredLevel=15,faction="horde",expansion=5,zoneID=6721,description="I am pretty sure those dwarves took the artifact in that iron fort there. Are you going to go get it?",questType="standard"},
[35510] = {id=35510,name="Iyu",level=15,requiredLevel=15,faction="horde",expansion=5,zoneID=6721,description="There is a genesaur here! It wants its artifact back. Kaz and Draka are fighting it now on the surface but they need you. Draka said I could fire the big gun. So I will stay here and do that.",questType="standard"},
[35511] = {id=35511,name="Kaz the Shrieker",level=15,requiredLevel=15,faction="horde",expansion=5,zoneID=6721,mapID=543,starts={{npcID=82338,x=0.476,y=0.932,mapID=543}},ends={{npcID=74606,x=0.414,y=0.74,mapID=543},{npcID=82338,x=0.476,y=0.932,mapID=543}},coords={x=0.476,y=0.932,source="quest_giver",mapID=543},questType="standard"},
[35523] = {id=35523,name="Vignette: Morva Soultwister",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6719,mapID=539,questType="standard"},
[35524] = {id=35524,name="Chapter III: Ritual of the Charred",level=15,requiredLevel=15,faction="horde",expansion=5,zoneID=6721,description="I have seen a strange ritual performed by ancients. They step into fire, burning the leaves from their branches and charring their bark. I call it the Ritual of the Charred. If we want to weaken the ancients, we can get rid of them before they become even stronger. - Frenna",starts={{npcID=82569,x=0.57,y=0.718,zoneID=6721}},ends={{npcID=82574,x=0.558,y=0.714,zoneID=6721}},coords={x=0.57,y=0.718,source="quest_giver",zoneID=6721},questType="standard"},
[35527] = {id=35527,name="Chapter II: The Harvest",level=15,requiredLevel=15,faction="horde",expansion=5,zoneID=6721,description="I have seen a creature working with the ancient saplings, imbuing them with anger and hatred toward creatures unlike them. Perhaps it is this botani who is responsible for the unusually aggressive nature of ancients here in Tangleheart. Would killing this botani do us good? I fear I would be no match for it alone. - Frenna",starts={{npcID=82569,x=0.57,y=0.718,zoneID=6721}},ends={{npcID=82574,x=0.558,y=0.714,zoneID=6721}},coords={x=0.57,y=0.718,source="quest_giver",zoneID=6721},questType="standard"},
[35530] = {id=35530,name="Treasure: Shadowmoon Treasure 38",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=7078,mapID=539,ends={{npcID=232507,x=0.303,y=0.199,mapID=539},{npcID=232507,x=0.495,y=0.439,mapID=539}},questType="standard"},
[35536] = {id=35536,name="Secrets of the Botani",level=15,requiredLevel=15,faction="horde",expansion=5,zoneID=6721,description="The botani must have stuck that big ogron there to protect something fancy. And what was that stumpy looking creature that it killed? The botani are mean, but they have some fun toys. Maybe Kaz might know what it was. Can we go find Kaz now? I saw a compost heap up the south hill. If Kaz came looking for me I bet she would start there.",starts={{npcID=82274,x=0.436,y=0.84,zoneID=6721}},ends={{npcID=82228,x=0.42,y=0.858,zoneID=6721}},coords={x=0.436,y=0.84,source="quest_giver",zoneID=6721},questType="standard"},
[35537] = {id=35537,name="News from Spires of Arak",level=20,requiredLevel=20,faction="horde",expansion=5,zoneID=7004,description="Commander, scouts from Spires of Arak have brought back news to the garrison. There's word of a brewin' war between bird-men and the Shattered Hand orcs. Rokhan 's askin' for your presence when your work is done here, should ya be willin' sir.",starts={{npcID=79627,x=0.712,y=0.298,zoneID=6662}},ends={{npcID=78487,x=0.456,y=0.432,zoneID=7004}},coords={x=0.712,y=0.298,source="quest_giver",zoneID=6662},questType="standard"},
[35549] = {id=35549,name="Honoring a Hero",level=30,requiredLevel=30,faction="alliance",expansion=5,zoneID=6722,description="By the Light... I can't believe this happened to Taylor and his men when they had a full garrison. It's going to take everything we have to keep your outpost safe, commander. We should get out of here. We can honor the fallen when we're safe.",starts={{npcID=82403,x=0.368,y=0.568,zoneID=6722}},ends={{npcID=81929,x=0.398,y=0.608,zoneID=6722}},coords={x=0.368,y=0.568,source="quest_giver",zoneID=6722},questType="standard"},
[35550] = {id=35550,name="Surviving in a Savage Land",level=30,requiredLevel=30,faction="horde",expansion=5,zoneID=6722,description="Dey may be Alliance, but Admiral Taylor and his men fought with honor on da battlefield. Dey deserve our respect, warchief be praised. If an entire garrison be fallin' to dark magic, our work be cut out for us, eh commander? We should be goin' back to base. It safe there. Safer, anyway.",starts={{npcID=82402,x=0.368,y=0.568,zoneID=6722}},ends={{npcID=81920,x=0.402,y=0.434,zoneID=6722}},coords={x=0.368,y=0.568,source="quest_giver",zoneID=6722},questType="standard"},
[35552] = {id=35552,name="Trust No One",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=6719,description="Nothing is the same since I returned. There is always whispering - everywhere, whispering. Maraad cannot see it, but there are even traces of fel energy here in Elodor. We have been infiltrated! I must attend to the Exarch Council, but I need you to investigate. Follow the traces of fel energy that I will illuminate. If there are truly traitors in our midst, they will have to have some sort of hideout. Find it! I will wait for you with the other Exarchs.",starts={{npcID=80073,x=0.624,y=0.262,zoneID=6719}},ends={{npcID=233229,x=0.61,y=0.245,zoneID=6719}},coords={x=0.624,y=0.262,source="quest_giver",zoneID=6719},questType="standard"},
[35553] = {id=35553,name="Vignette: Rai'vosh",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6719,mapID=539,questType="standard"},
[35554] = {id=35554,name="News from Spires of Arak",level=20,requiredLevel=20,faction="alliance",expansion=5,zoneID=7078,description="While you were gone, a rather shady looking human arrived at the outpost asking for you. He said he worked for... Grey was it?... and had some information regarding Spires of Arak that you would be interested in. He was heading back to your garrison and asked that I passed along the message, and so I have. And before you go, thank you for all you've done for us here, truly. You and your army have turned the tides of a war that you could have just as easily walked away from. We will not forget.",starts={{npcID=79618,x=0.696,y=0.216,zoneID=6662}},ends={{npcID=81492,x=0.378,y=0.368,zoneID=7078}},coords={x=0.696,y=0.216,source="quest_giver",zoneID=6662},questType="standard"},
[35555] = {id=35555,name="Vignette: Darktalon",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6719,mapID=539,questType="standard"},
[35556] = {id=35556,name="The Secrets of Gorgrond",level=15,requiredLevel=15,faction="alliance",expansion=5,zoneID=6721,description="Commander, Yrel and Maraad have a tactical suggestion. They recommend a small expedition group be sent into the savage wastelands of Gorgrond far to the north. Reports from their rangari suggest that land may hold ancient secrets or primal knowledge that we might use to exploit weaknesses in the Iron Horde that our enemy would not expect. If you wish to go I will have a gryphon prepared for you at once.",starts={{npcID=81492,x=0.378,y=0.368,zoneID=7078},{npcID=232397,x=0.43,y=0.45,zoneID=7078},{npcID=232398,x=0.424,y=0.453,zoneID=7078},{npcID=232400,x=0.428,y=0.452,zoneID=7078}},ends={{npcID=80978,x=0.64,y=0.572,zoneID=6721}},coords={x=0.378,y=0.368,source="quest_giver",zoneID=7078},questType="standard"},
[35557] = {id=35557,name="The Secrets of Gorgrond",level=15,requiredLevel=15,faction="horde",expansion=5,zoneID=6721,description="Commander, Durotan calls for aid in leading a small strike team into Gorgrond to launch a counter attack against the Iron Horde strongholds there. The land is home to the Blackrock clan, industrial arm of the Iron Horde. It is also home to some of the most savage giants and monsters in all of Draenor. If you wish to answer this call to action, Gorgrond can be reached through the eastern side of Frostfire Ridge through Thunder Pass.",starts={{npcID=232416,x=0.493,y=0.413,zoneID=7004},{npcID=233291,x=0.493,y=0.415,zoneID=7004},{npcID=237022,x=0.493,y=0.413,zoneID=7004}},ends={{npcID=74594,x=0.372,y=0.77,zoneID=6721}},coords={x=0.493,y=0.413,source="quest_giver",zoneID=7004},questType="standard"},
[35558] = {id=35558,name="Vignette: Hypnocroak",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6719,mapID=539,questType="standard"},
[35567] = {id=35567,name="Treasure: Ogre Booty 007",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6720,mapID=525,questType="standard"},
[35568] = {id=35568,name="Treasure: Ogre Booty 008",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6720,mapID=525,questType="standard"},
