[35577] = {id=35577,name="Nagrand - Treasure 031 - Steamwheedle Supplies",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6755,mapID=550,ends={{npcID=232584,x=0.501,y=0.822,mapID=550}},questType="standard"},
