[35603] = {id=35603,name="Treasure: Mikkal's Chest",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6719,mapID=539,ends={{npcID=232624,x=0.589,y=0.22,mapID=539}},questType="standard"},
[35611] = {id=35611,name="Return to Veil Terokk",level=30,requiredLevel=30,faction="both",expansion=5,zoneID=6722,description="\" Percy should have brought with him a basket of goods, assuming he didn't dump it off somewhere along the way. The contents are a token of my gratitude and an apology for the altercation with your scout. I must urge you to return to Veil Terokk so we may press forward with our plans. - Reshad \"",starts={{npcID=79748,x=0.4,y=0.602,zoneID=6722}},ends={{npcID=81770,x=0.464,y=0.466,zoneID=6722}},coords={x=0.4,y=0.602,source="quest_giver",zoneID=6722},questType="standard"},
