[35629] = {id=35629,name="Vindicator Onaala",level=1,requiredLevel=1,faction="alliance",expansion=5,zoneID=6719,mapID=539,questType="standard"},
[35631] = {id=35631,name="Rulkan",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=6719,mapID=539,starts={{npcID=75884,x=0.456,y=0.262,mapID=539}},ends={{npcID=75884,x=0.456,y=0.262,mapID=539}},coords={x=0.456,y=0.262,source="quest_giver",mapID=539},questType="standard"},
[35632] = {id=35632,name="A Lesson in Archaeology",level=35,requiredLevel=35,faction="both",expansion=5,zoneID=6755,description="As an archaeologist, it's important to make great discoveries and contributions to the field. Why? Because that's how you make a name for yourself! Even that hack Harrison Jones has a somewhat reputable name. If he can do it, then you can too! The Highmaul are hiding something big in that cave of theirs and we need to get in there and take it! Take this teleportation beacon and make your way to the back of the cave. Once you find the relic, place the beacon and my team will take care of the rest!",starts={{npcID=79201,x=0.712,y=0.524,zoneID=6755}},ends={{npcID=79201,x=0.712,y=0.524,zoneID=6755}},coords={x=0.712,y=0.524,source="quest_giver",zoneID=6755},questType="standard"},
[35633] = {id=35633,name="Scout Forensics",level=15,requiredLevel=15,faction="alliance",expansion=5,zoneID=6721,description="My entire squad is gone. Some are dead; that much is obvious. The others though... they must be further in. Go and search the bodies of my squad that you find, each will carry a small pouch of personal items. I would like to return these to their families. I will go ahead and meet you inside the marsh.",starts={{npcID=80762,x=0.592,y=0.562,zoneID=6721}},ends={{npcID=82476,x=0.582,y=0.598,zoneID=6721}},coords={x=0.592,y=0.562,source="quest_giver",zoneID=6721},questType="standard"},
[35634] = {id=35634,name="Control is King",level=30,requiredLevel=30,faction="both",expansion=5,zoneID=6722,description="Apexis technology is fascinating, isn't it? Machines powered by solar energy. Energy which itself has been imbued with magic! Simply brilliant! Ah, but there's always a catch. And I think you may have found it. Bring the interface device back to Veil Terokk, will you? I'll be along shortly with the Apexis cores. If my theory is right, we may be able to turn the Adherents' own weapon against them!",starts={{npcID=80157,x=0.368,y=0.246,zoneID=6722}},ends={{npcID=82509,x=0.47,y=0.458,zoneID=6722}},coords={x=0.368,y=0.246,source="quest_giver",zoneID=6722},questType="standard"},
[35636] = {id=35636,name="All Due Respect",level=30,requiredLevel=30,faction="both",expansion=5,zoneID=6722,description="A group of Adherents came 'round just before the attack on Skettis. Disguised myself as a mushroom, I did. The fools walked right past me. My neighbor up the road was not so lucky. He had a fondness for texts, if I recall. Might be valuable information in his hut, if you give Reshad a moment to rummage around. Oh, and bring one of his feathers to the shrine near Veil Terokk, would you? He was such a dear, and I know it's what he'd want.",starts={{npcID=79890,x=0.516,y=0.312,zoneID=6722}},ends={{npcID=82621,x=0.502,y=0.366,zoneID=6722}},coords={x=0.516,y=0.312,source="quest_giver",zoneID=6722},questType="standard"},
[35638] = {id=35638,name="A Few Artifact Fragments",level=40,requiredLevel=40,faction="alliance",expansion=5,zoneID=8485,starts={{npcID=81870,x=0.458,y=0.762,zoneID=6941},{npcID=81870,zoneID=8485}},ends={{npcID=81870,x=0.458,y=0.762,zoneID=6941},{npcID=81870,zoneID=8485}},coords={x=0.458,y=0.762,source="quest_giver",zoneID=6941},questType="standard"},
[35639] = {id=35639,name="A TON of Artifact Fragments",level=40,requiredLevel=40,faction="alliance",expansion=5,zoneID=8485,starts={{npcID=81870,x=0.458,y=0.762,zoneID=6941},{npcID=81870,zoneID=8485}},ends={{npcID=81870,x=0.458,y=0.762,zoneID=6941},{npcID=81870,zoneID=8485}},coords={x=0.458,y=0.762,source="quest_giver",zoneID=6941},questType="standard"},
[35640] = {id=35640,name="Vengeance for the Fallen",level=15,requiredLevel=15,faction="alliance",expansion=5,zoneID=6721,description="I... almost made it out. Most of us... dead. The others... they are no longer themselves. These lurching spore beasts are the cause, dragging us further into the marsh... stop them.",starts={{npcID=82499,x=0.594,y=0.578,zoneID=6721}},ends={{npcID=82476,x=0.582,y=0.598,zoneID=6721}},coords={x=0.594,y=0.578,source="quest_giver",zoneID=6721},questType="standard"},
[35642] = {id=35642,name="Mysterious Pod",level=15,requiredLevel=15,faction="alliance",expansion=5,zoneID=6721,description="This pod is similar to the ones growing on or near the bodies around here, except this one is pulsating weirdly. This is something Khaano would be interested in.",ends={{npcID=82476,x=0.582,y=0.598,zoneID=6721}},questType="standard"},
[35643] = {id=35643,name="Nagrand - Treasure 062 - Mountain Climber's Pack",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6755,mapID=550,ends={{npcID=233032,x=0.705,y=0.139,mapID=550}},questType="standard"},
[35644] = {id=35644,name="Mercy for the Living",level=15,requiredLevel=15,faction="alliance",expansion=5,zoneID=6721,description="You can see that the dead were the lucky ones. Those that live wander about attacking anything not infected with these vile spores. I cannot bring myself to slay them, but if you could bring mercy to those poor people I would be very grateful.",starts={{npcID=82476,x=0.582,y=0.598,zoneID=6721}},ends={{npcID=82476,x=0.582,y=0.598,zoneID=6721}},coords={x=0.582,y=0.598,source="quest_giver",zoneID=6721},questType="standard"},
[35645] = {id=35645,name="The Secret of the Fungus",level=15,requiredLevel=15,faction="alliance",expansion=5,zoneID=6721,description="I'm beginning to sense a strong... connection... between the fungus and the creatures that inhabit it. There are certain mushrooms that are stronger than others. I believe if I had some samples of these I could use them, track the source of this foul fungus and... deal with it.",starts={{npcID=82476,x=0.582,y=0.598,zoneID=6721}},ends={{npcID=82476,x=0.582,y=0.598,zoneID=6721}},coords={x=0.582,y=0.598,source="quest_giver",zoneID=6721},questType="standard"},
[35646] = {id=35646,name="Nagrand - Treasure 006 - Steamwheedle Supplies",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6755,mapID=550,ends={{npcID=233033,x=0.706,y=0.186,mapID=550}},questType="standard"},
[35647] = {id=35647,name="A Grim Harvest",level=15,requiredLevel=15,faction="alliance",expansion=5,zoneID=6721,description="The spores grow thick further into the marsh, but those larger fungus beasts are the key. Yes, kill them and take their spore sacs. I will need them to refine my... search.",starts={{npcID=82476,x=0.582,y=0.598,zoneID=6721}},ends={{npcID=82476,x=0.582,y=0.598,zoneID=6721},{npcID=82477,x=0.59,y=0.624,zoneID=6721}},coords={x=0.582,y=0.598,source="quest_giver",zoneID=6721},questType="standard"},
[35648] = {id=35648,name="Nagrand - Treasure 005 - Steamwheedle Supplies",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6755,mapID=550,ends={{npcID=233034,x=0.646,y=0.176,mapID=550}},questType="standard"},
[35650] = {id=35650,name="Chapter III: Ritual of the Charred",level=15,requiredLevel=15,faction="alliance",expansion=5,zoneID=6721,description="I have seen a strange ritual performed by ancients. They step into fire, burning the leaves from their branches and charring their bark. I call it the Ritual of the Charred. If we want to weaken the ancients, we can get rid of them before they become even stronger. - Frenna",starts={{npcID=82569,x=0.57,y=0.718,zoneID=6721}},ends={{npcID=85130,x=0.606,y=0.648,zoneID=6721}},coords={x=0.57,y=0.718,source="quest_giver",zoneID=6721},questType="standard"},
[35651] = {id=35651,name="Chapter II: The Harvest",level=15,requiredLevel=15,faction="alliance",expansion=5,zoneID=6721,description="I have seen a creature working with the ancient saplings, imbuing them with anger and hatred toward creatures unlike them. Perhaps it is this botani who is responsible for the unusually aggressive nature of ancients here in Tangleheart. Would killing this botani do us good? I fear I would be no match for it alone. - Frenna",starts={{npcID=82569,x=0.57,y=0.718,zoneID=6721}},ends={{npcID=85130,x=0.606,y=0.648,zoneID=6721}},coords={x=0.57,y=0.718,source="quest_giver",zoneID=6721},questType="standard"},
[35652] = {id=35652,name="Growing Wood",level=15,requiredLevel=15,faction="alliance",expansion=5,zoneID=6721,description="We got the lumber mill good an' built, but we be needin' more wood! The Rangari tol' me there's botani usin' some kinda sap to grow ancients fast as you like. Get yer hands on some o' that sap and I betcha I can put it work. What? Oh, Glyza here? Found 'er crashed here and she knows a thing or two about lumberjackin'. I'll take her back to the outpost later. I'll meet ya inside Tangleheart if I can find it.",starts={{npcID=82575,x=0.558,y=0.714,zoneID=6721}},ends={{npcID=85130,x=0.606,y=0.648,zoneID=6721}},coords={x=0.558,y=0.714,source="quest_giver",zoneID=6721},questType="standard"},
[35653] = {id=35653,name="Wood is Wood",level=35,requiredLevel=35,faction="alliance",expansion=5,zoneID=6721,mapID=543,description="Them ancients in Bracken Tangle be crazier than a dwarf who don't like gold. The burn their leaves right off their 'eads and make their bark hard to fire. Ya know, that bark might come in 'andy 'round here. Chop down a few ancients and I'll send a lackey to gather their wood.",questType="standard"},
[35654] = {id=35654,name="Chapter I: Plant Food",level=15,requiredLevel=15,faction="alliance",expansion=5,zoneID=6721,description="There are strange, glowing objects within Tangleheart, seemingly pollinated by a variety of stinging creature. The botani sometimes collect whatever the pods produce. I can't be sure what it is, but it might be dangerous to us. - Frenna",starts={{npcID=82569,x=0.57,y=0.718,zoneID=6721}},ends={{npcID=85130,x=0.606,y=0.648,zoneID=6721}},coords={x=0.57,y=0.718,source="quest_giver",zoneID=6721},questType="standard"},
[35656] = {id=35656,name="A Heartfelt Search",level=15,requiredLevel=15,faction="alliance",expansion=5,zoneID=6721,description="I can feel a powerful presence in the marsh $p, it is not far from here. Go see what is there while I finish my grim feast. I will catch up...",starts={{npcID=82476,x=0.582,y=0.598,zoneID=6721}},ends={{npcID=82477,x=0.59,y=0.624,zoneID=6721}},coords={x=0.582,y=0.598,source="quest_giver",zoneID=6721},questType="standard"},
[35659] = {id=35659,name="Heart of the Fen",level=15,requiredLevel=15,faction="alliance",expansion=5,zoneID=6721,description="The pounding in my head is almost unbearable but I must see this through. With all the spore samples I've taken I know where to go and what to do. I will find the source and spread... no! Destroy it! I will do what needs to be done!",starts={{npcID=82477,x=0.59,y=0.624,zoneID=6721}},ends={{npcID=75146,x=0.632,y=0.522,zoneID=6721}},coords={x=0.59,y=0.624,source="quest_giver",zoneID=6721},questType="standard"},
[35660] = {id=35660,name="Nagrand - Treasure 052 - Fungus-Covered Chest",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6755,mapID=550,ends={{npcID=233044,x=0.889,y=0.182,mapID=550}},questType="standard"},
[35661] = {id=35661,name="Nagrand - Treasure 054 - Dreamflower",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6755,mapID=550,ends={{npcID=233048,x=0.811,y=0.372,mapID=550}},questType="standard"},
[35662] = {id=35662,name="Nagrand - Treasure 053 - Steamwheedle Supplies",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6755,mapID=550,ends={{npcID=233052,x=0.876,y=0.203,mapID=550}},questType="standard"},
[35663] = {id=35663,name="A Lesson in Teamwork",level=35,requiredLevel=35,faction="both",expansion=5,zoneID=6755,description="One of the most important skills an archaeology team needs is good teamwork. The key to teamwork is knowing when to give and when to take. The Highmaul ogres have been excavating mysterious artifacts from the gorge. I want you to team up with the Highmaul ogres in the name of good archaeology! Remember what I said about giving and taking? The ogres have given us their hard work to excavate the artifacts. Now I want you to take those artifacts from them and bring them here! It's teamwork!",questType="standard"},
[35664] = {id=35664,name="Seedbearers of Bad News",level=15,requiredLevel=15,faction="alliance",expansion=5,zoneID=6721,description="When these seedbearers are slain their seeds survive. From them spring new seedbearers, not over years, but hours. Leaving their remains here would soon cause the outpost to be overrun. We have learned that burning their remains prevents this from happening.",starts={{npcID=82610,x=0.462,y=0.55,zoneID=6721}},ends={{npcID=82610,x=0.462,y=0.55,zoneID=6721}},coords={x=0.462,y=0.55,source="quest_giver",zoneID=6721},questType="standard"},
[35665] = {id=35665,name="We Have Company",level=15,requiredLevel=15,faction="alliance",expansion=5,zoneID=6721,description="Commander, I've spotted Iron Horde soldiers nearby. It is bold, even for them, to venture into such deadly territory. If we do not deal with their presence, they will surely be a threat to your camp. While I scout deeper into the canyons, may I request your help in investigating the camp?",starts={{npcID=82610,x=0.462,y=0.55,zoneID=6721}},ends={{npcID=82832,x=0.442,y=0.616,zoneID=6721}},coords={x=0.462,y=0.55,source="quest_giver",zoneID=6721},questType="standard"},
[35666] = {id=35666,name="Rangari in the Red",level=15,requiredLevel=15,faction="alliance",expansion=5,zoneID=6721,description="Gorgrond is a very dangerous place and I've sent scouting squads out to investigate various regions. I've sent one squad to the marsh called the Crimson Fen and they've not come back yet. I'd like you to find the missing squad and get a report if possible.",starts={{npcID=75146,x=0.632,y=0.522,zoneID=6721}},ends={{npcID=80762,x=0.592,y=0.562,zoneID=6721}},coords={x=0.632,y=0.522,source="quest_giver",zoneID=6721},questType="standard"},
[35667] = {id=35667,name="Skulltakers in Crimson Fen",level=15,requiredLevel=15,faction="horde",expansion=5,zoneID=6721,description="Grulkor and his group are often not seen for weeks, returning only when they can carry no more trophies and supplies. He has been gone too long this time. He mentioned hunting in the Crimson Fen for the first time, see if he still lives.",starts={{npcID=82732,x=0.462,y=0.7,zoneID=6721}},ends={{npcID=81218,x=0.544,y=0.666,zoneID=6721}},coords={x=0.462,y=0.7,source="quest_giver",zoneID=6721},questType="standard"},
[35668] = {id=35668,name="Syth's Secret",level=30,requiredLevel=30,faction="both",expansion=5,zoneID=6722,description="Our deceased friend here was hiding more than a love of old scrolls and erotic sorcery-fiction. He had something truly valuable. If I'm reading his notes correctly, he claims to have found the Eye of Anzu - Terokk's scrying orb from the days after his fall. We need that orb! The notes say he stashed it in a ravager den just up the road.",starts={{npcID=82621,x=0.502,y=0.366,zoneID=6722}},ends={{npcID=81770,x=0.464,y=0.466,zoneID=6722}},coords={x=0.502,y=0.366,source="quest_giver",zoneID=6722},questType="standard"},
[35669] = {id=35669,name="WANTED: Keeho's Severed Paw",level=30,requiredLevel=30,faction="horde",expansion=5,zoneID=6722,description="Posted by: Taskmaster Gornek The saberon known as Keeho poses a serious threat to Axefall. He has taken to slaughtering peons on the night shift and dragging their corpses to his den in the pridelands. Anyone who can bring me his severed paw as proof of his demise will be rewarded greatly.",starts={{npcID=233099,x=0.401,y=0.431,zoneID=6722}},ends={{npcID=81920,x=0.402,y=0.434,zoneID=6722}},coords={x=0.401,y=0.431,source="quest_giver",zoneID=6722},questType="group"},
[35670] = {id=35670,name="WANTED: Spineslicer's Husk",level=30,requiredLevel=30,faction="horde",expansion=5,zoneID=6722,description="Posted by: Killga I will greatly reward anyone who brings me Spineslicer's husk . I wish to fashion fine ravager armor, but do not have the skills to take down such a beast. Don't tear too many holes in it.",starts={{npcID=233099,x=0.401,y=0.431,zoneID=6722}},ends={{npcID=82622,x=0.41,y=0.428,zoneID=6722}},coords={x=0.401,y=0.431,source="quest_giver",zoneID=6722},questType="group"},
[35671] = {id=35671,name="A Gathering of Shadows",level=30,requiredLevel=30,faction="both",expansion=5,zoneID=6722,description="Veil Terokk is just ahead. Let us hope the others have made the journey safely.",starts={{npcID=81770,x=0.464,y=0.466,zoneID=6722}},ends={{npcID=80153,x=0.458,y=0.456,zoneID=6722},{npcID=82720,x=0.464,y=0.456,zoneID=6722}},coords={x=0.464,y=0.466,source="quest_giver",zoneID=6722},questType="standard"},
[35672] = {id=35672,name="WANTED: Venombarb",level=30,requiredLevel=30,faction="horde",expansion=5,zoneID=6722,description="Posted by: Hutou Featherwind Venombarb is feared in the skies above Arak, even by the high arakkoa. She has made air travel difficult for our riders, preventing vital supplies from reaching Axefall. I require no proof of her demise, simply ensure her screech never again echoes among the spires. She nests above the howling crag to the northeast.",starts={{npcID=233099,x=0.401,y=0.431,zoneID=6722}},ends={{npcID=82612,x=0.394,y=0.432,zoneID=6722}},coords={x=0.401,y=0.431,source="quest_giver",zoneID=6722},questType="group"},
[35673] = {id=35673,name="Nagrand - Treasure 014 - Appropriated Warsong Supplies",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6755,mapID=550,ends={{npcID=233079,x=0.731,y=0.755,mapID=550}},questType="standard"},
[35674] = {id=35674,name="WANTED: Keeho's Severed Paw",level=30,requiredLevel=30,faction="alliance",expansion=5,zoneID=6722,description="Posted by: Lieutenant Willem Keeho, a monstrous saberon, has taken to raiding Southport at night. We're losing men left and right. I offer a hefty bounty to anyone able to track down Kreeho and bring his severed paw to me.",starts={{npcID=233100,x=0.395,y=0.616,zoneID=6722}},ends={{npcID=81929,x=0.398,y=0.608,zoneID=6722}},coords={x=0.395,y=0.616,source="quest_giver",zoneID=6722},questType="group"},
[35675] = {id=35675,name="WANTED: Spineslicer's Husk",level=30,requiredLevel=30,faction="alliance",expansion=5,zoneID=6722,description="Posted by: Quartermaster Jolie We're running out of supplies to repair our troops' armor. I'll pay handsomely for the husk of the mighty ravager Spineslicer. It would provide us with repair materials for weeks.",starts={{npcID=233100,x=0.395,y=0.616,zoneID=6722}},ends={{npcID=82664,x=0.394,y=0.598,zoneID=6722}},coords={x=0.395,y=0.616,source="quest_giver",zoneID=6722},questType="group"},
[35676] = {id=35676,name="WANTED: Venombarb",level=30,requiredLevel=30,faction="alliance",expansion=5,zoneID=6722,description="Posted by: Falrogh Venombarb taunts me every day. Screeching and killing me buzz. Somebody, anybody, kill the beast. I don't want proof, I want peace and quiet.",starts={{npcID=233100,x=0.395,y=0.616,zoneID=6722}},ends={{npcID=82669,x=0.392,y=0.628,zoneID=6722}},coords={x=0.395,y=0.616,source="quest_giver",zoneID=6722},questType="group"},
[35677] = {id=35677,name="Treasure: Sunken Fishing Boat",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6719,mapID=539,ends={{npcID=233101,x=0.372,y=0.26,mapID=539}},questType="standard"},
[35678] = {id=35678,name="Nagrand - Treasure 015 - Warsong Lockbox",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6755,mapID=550,ends={{npcID=233103,x=0.731,y=0.704,mapID=550}},questType="standard"},
[35679] = {id=35679,name="Garrison Campaign: The Fall of Shattrath",level=40,requiredLevel=40,faction="alliance",expansion=5,zoneID=6662,description="Greetings, . I bring another message from Archmage Khadgar. We can no longer ignore Socrethar's presence at Shattrath. He spreads dangerous beliefs, converting more draenei to his \"new order\" with each passing day. The time has come for us to confront him. Exarch Maladaar should be expecting you at the Spire of Light in Talador. Good luck, .",starts={{npcID=83858,x=0.528,y=0.51,zoneID=7004},{npcID=83858,x=0.378,y=0.396,zoneID=7078}},ends={{npcID=75028,x=0.498,y=0.486,zoneID=6662}},coords={x=0.528,y=0.51,source="quest_giver",zoneID=7004},questType="standard"},
[35680] = {id=35680,name="Garrison Campaign: The Fall of Shattrath",level=40,requiredLevel=40,faction="horde",expansion=5,zoneID=6662,description="Greetings, . I bring another message from Archmage Khadgar. We can no longer ignore Socrethar's presence at Shattrath. He spreads dangerous beliefs, converting more draenei to his \"new order\" with each passing day. The time has come for us to confront him. Lady Liadrin should be expecting you at the Spire of Light in Talador. Good luck, .",starts={{npcID=83858,x=0.528,y=0.51,zoneID=7004},{npcID=83858,x=0.378,y=0.396,zoneID=7078}},ends={{npcID=76804,x=0.5,y=0.484,zoneID=6662}},coords={x=0.528,y=0.51,source="quest_giver",zoneID=7004},questType="standard"},
[35682] = {id=35682,name="Nagrand - Treasure 016 - Warsong Spear",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6755,mapID=550,ends={{npcID=233113,x=0.761,y=0.7,mapID=550}},questType="standard"},
[35683] = {id=35683,name="Reclaiming the City",level=40,requiredLevel=40,faction="alliance",expansion=5,zoneID=6662,description="The Shattrath offensive is going well, but Socrethar refuses to show himself. Despite our best efforts, we are unable to break into the inner city of Shattrath. The dome's defenses are simply too strong. However, we think we can lure Socrethar out of hiding. Defeat his lieutenants and warriors, and gather their medallions of service. When we show him proof of their demise, his pride will surely force him to face us.",starts={{npcID=75028,x=0.498,y=0.486,zoneID=6662}},ends={{npcID=75028,x=0.498,y=0.486,zoneID=6662}},coords={x=0.498,y=0.486,source="quest_giver",zoneID=6662},questType="standard"},
[35684] = {id=35684,name="Reclaiming the City",level=40,requiredLevel=40,faction="horde",expansion=5,zoneID=6662,description="The Shattrath offensive is going well, but Socrethar refuses to show himself. And despite our best efforts, we are unable to break into the inner city, where he resides. However, we think we can lure Socrethar out of hiding. Defeat his lieutenants and warriors, then gather their medallions of service. When we show him proof of their demise, his pride will surely force him to face us.",starts={{npcID=76804,x=0.5,y=0.484,zoneID=6662}},ends={{npcID=76804,x=0.5,y=0.484,zoneID=6662}},coords={x=0.5,y=0.484,source="quest_giver",zoneID=6662},questType="standard"},
[35685] = {id=35685,name="Socrethar's Demise",level=40,requiredLevel=40,faction="alliance",expansion=5,zoneID=6662,description="Meet me down by the entrance to the Shattrath dome. There, we will issue our challenge to the Sargerei leader. If he accepts our challenge, it is there that he shall meet his end. The creature that calls himself Socrethar was once my brethren. I can only hope that there is still some Light left within him.",starts={{npcID=75028,x=0.498,y=0.486,zoneID=6662}},ends={{npcID=75028,x=0.498,y=0.486,zoneID=6662}},coords={x=0.498,y=0.486,source="quest_giver",zoneID=6662},questType="standard"},
[35686] = {id=35686,name="Rage and Wisdom",level=15,requiredLevel=15,faction="alliance",expansion=5,zoneID=6721,description="An endless war wages between the creatures of the eastern wilds and the beasts of the western wasteland. Should one side overwhelm the other, all of Draenor would fall at the hand of the victor. I sent Rangari Erdanii to the heart of the battle between these two forces. It is likely that she will need your help, commander.",starts={{npcID=75127,x=0.528,y=0.596,zoneID=6721}},ends={{npcID=82610,x=0.462,y=0.55,zoneID=6721}},coords={x=0.528,y=0.596,source="quest_giver",zoneID=6721},questType="standard"},
[35687] = {id=35687,name="Socrethar's Demise",level=40,requiredLevel=40,faction="horde",expansion=5,zoneID=6662,description="Meet me down by the entrance to the Shattrath dome. There, we shall issue our challenge to the Sargerei leader. If he accepts, it is there that he shall meet his end. I must admit, , I am looking forward to this.",starts={{npcID=76804,x=0.5,y=0.484,zoneID=6662}},ends={{npcID=76804,x=0.5,y=0.484,zoneID=6662}},coords={x=0.5,y=0.484,source="quest_giver",zoneID=6662},questType="standard"},
[35688] = {id=35688,name="Vignette: Enavra Varandi",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6719,mapID=539,questType="standard"},
[35689] = {id=35689,name="A Few Artifact Fragments",level=40,requiredLevel=40,faction="alliance",expansion=5,zoneID=8485,starts={{npcID=82660,x=0.446,y=0.746,zoneID=6941},{npcID=82660,zoneID=8485}},ends={{npcID=82660,x=0.446,y=0.746,zoneID=6941},{npcID=82660,zoneID=8485}},coords={x=0.446,y=0.746,source="quest_giver",zoneID=6941},questType="standard"},
[35690] = {id=35690,name="A Bunch of Artifact Fragments",level=40,requiredLevel=40,faction="alliance",expansion=5,zoneID=8485,starts={{npcID=82660,x=0.446,y=0.746,zoneID=6941},{npcID=82660,zoneID=8485}},ends={{npcID=82660,x=0.446,y=0.746,zoneID=6941},{npcID=82660,zoneID=8485}},coords={x=0.446,y=0.746,source="quest_giver",zoneID=6941},questType="standard"},
[35691] = {id=35691,name="A TON of Artifact Fragments",level=40,requiredLevel=40,faction="alliance",expansion=5,zoneID=8485,starts={{npcID=82660,x=0.446,y=0.746,zoneID=6941},{npcID=82660,zoneID=8485}},ends={{npcID=82660,x=0.446,y=0.746,zoneID=6941},{npcID=82660,zoneID=8485}},coords={x=0.446,y=0.746,source="quest_giver",zoneID=6941},questType="standard"},
[35692] = {id=35692,name="Nagrand - Treasure 010 - Freshwater Clam",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6755,mapID=550,ends={{npcID=233132,x=0.731,y=0.216,mapID=550}},questType="standard"},
[35693] = {id=35693,name="A Harsh Reminder",level=15,requiredLevel=15,faction="alliance",expansion=5,zoneID=6721,description="Welcome to the front lines, commander, where the wastelands and the jungle collide. The battle below rages on, but I believe one side is beginning to overwhelm the other. This cannot be allowed to happen. The gronnlings are gaining an upper hand and must be stopped before they pose a threat to Highpass. I will get closer to the battle while you thin their ranks. Meet me within Affliction Ridge when you are done.",starts={{npcID=82610,x=0.462,y=0.55,zoneID=6721}},ends={{npcID=82610,x=0.462,y=0.55,zoneID=6721}},coords={x=0.462,y=0.55,source="quest_giver",zoneID=6721},questType="standard"},
[35694] = {id=35694,name="Nagrand - Treasure 011 - Golden Kaliri Egg - TSH",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6755,mapID=550,ends={{npcID=233134,x=0.582,y=0.526,mapID=550}},questType="standard"},
[35695] = {id=35695,name="Nagrand - Treasure 022 - Warsong Cache",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6755,mapID=550,ends={{npcID=233135,x=0.517,y=0.604,mapID=550}},questType="standard"},
[35696] = {id=35696,name="Nagrand - Treasure 048 - Burning Blade Cache",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6755,mapID=550,ends={{npcID=233137,x=0.854,y=0.534,mapID=550}},questType="standard"},
[35697] = {id=35697,name="Peace Offering",level=30,requiredLevel=30,faction="horde",expansion=5,zoneID=6722,description="We need allies amongst these spires, and quickly. Commander, I believe it would be wise if you sought out aid. There is a lone arakkoa outcast southeast of here living near a ravager nest. The ravagers do not attack him - I suspect he has information on the beasts we may be able to use. I have our last crate of cactus apple surprise ready for you. It is our best shot, .",starts={{npcID=82691,x=0.4,y=0.432,zoneID=6722}},ends={{npcID=83463,x=0.438,y=0.488,zoneID=6722}},coords={x=0.4,y=0.432,source="quest_giver",zoneID=6722},questType="standard"},
[35699] = {id=35699,name="Peace Offering",level=30,requiredLevel=30,faction="alliance",expansion=5,zoneID=6722,description="We could really use an ally to trade with, commander. There's an arakkoa outcast living in the middle of a ravager nest northeast of here... do you think he might ally with us? He must have some sort of secret to keeping those ravagers at bay. I have one last crate of my Northshire Port. Maybe that will help convince him that we're friendly.",starts={{npcID=82709,x=0.396,y=0.612,zoneID=6722}},ends={{npcID=83463,x=0.438,y=0.488,zoneID=6722}},coords={x=0.396,y=0.612,source="quest_giver",zoneID=6722},questType="standard"},
[35701] = {id=35701,name="Tracking: Mill Treasure 1",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6721,mapID=543,questType="standard"},
[35702] = {id=35702,name="Chains of Iron",level=15,requiredLevel=15,faction="alliance",expansion=5,zoneID=6721,description="The artifact we seek is within our grasp. Be prepared for a fight. If they truly have learned how to control gronn, this may be more difficult than I anticipated. I will join you in this battle as soon as you arrive.",starts={{npcID=84131,x=0.438,y=0.488,zoneID=6721}},ends={{npcID=75127,x=0.528,y=0.596,zoneID=6721}},coords={x=0.438,y=0.488,source="quest_giver",zoneID=6721},questType="standard"},
[35703] = {id=35703,name="Tracking: Mill Treasure Barrier 1",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6721,mapID=543,questType="standard"},
[35704] = {id=35704,name="When All Is Aligned",level=30,requiredLevel=30,faction="both",expansion=5,zoneID=6722,description="The ravenspeaker acolytes have been equipped with Apexis interfaces, they just need to get close enough. Come, let us take to the skies and secure the Terrace of Dawn. When all is aligned, we shall turn the false suns against one another and the spires shall burn like torches! I look forward to penning your actions into history.",starts={{npcID=84262,x=0.464,y=0.542,zoneID=6722}},ends={{npcID=81770,x=0.464,y=0.466,zoneID=6722}},coords={x=0.464,y=0.542,source="quest_giver",zoneID=6722},questType="standard"},
[35705] = {id=35705,name="Best Deals Anywhere",level=30,requiredLevel=30,faction="horde",expansion=5,zoneID=6722,description="Commander, two goblin smugglers - Mixxy and Trixxy Weldblast - came through here recently and went off towards the bog to the east. They had drilling equipment but weren't carrying any weapons, . I'd bet anything that they'll have materials we'd want, and that they could use some protection in return. Commander, I think seeking them out would be a good idea.",starts={{npcID=82691,x=0.4,y=0.432,zoneID=6722}},ends={{npcID=82713,x=0.56,y=0.408,zoneID=6722}},coords={x=0.4,y=0.432,source="quest_giver",zoneID=6722},questType="standard"},
[35706] = {id=35706,name="Sticky Situation",level=30,requiredLevel=30,faction="horde",expansion=5,zoneID=6722,description="We were hauling batteries to the excavation site and I crashed my freakin' car! My sister didn't even look back. I took the turn a little fast, so what? It happens! Point is, the batteries went flying everywhere and I'm in no condition to lift them out. So what do you say? Wanna help me out?",starts={{npcID=82713,x=0.56,y=0.408,zoneID=6722}},ends={{npcID=82713,x=0.56,y=0.408,zoneID=6722}},coords={x=0.56,y=0.408,source="quest_giver",zoneID=6722},questType="standard"},
[35707] = {id=35707,name="Tangleheart",level=15,requiredLevel=15,faction="horde",expansion=5,zoneID=6721,description="Hey there, peach. We've got the lumber mill good and ready, but we gotta find a way of choppin' wood fast out here. The Laughing Skull talked about Tangleheart, where the botani grow things quick as a quark. I'm headin' there now.",starts={{npcID=85077,x=0.464,y=0.696,zoneID=6721}},ends={{npcID=82574,x=0.558,y=0.714,zoneID=6721}},coords={x=0.464,y=0.696,source="quest_giver",zoneID=6721},questType="standard"},
[35708] = {id=35708,name="Tangleheart",level=15,requiredLevel=15,faction="alliance",expansion=5,zoneID=6721,description="The Rangari have been here for a tick, and they hear tell from the Laughing Skull o' a place called Tangleheart. Seems some really bad ancients come from there, and botani use a kind o' sap to grow them quickly. I think we could use that for yer outpost. Hey, wood is wood, right? I'll meet ya there.",starts={{npcID=85119,x=0.53,y=0.598,zoneID=6721}},ends={{npcID=82575,x=0.558,y=0.714,zoneID=6721}},coords={x=0.53,y=0.598,source="quest_giver",zoneID=6721},questType="standard"},
[35709] = {id=35709,name="Treasure: Laughing Skull Cache I",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6721,mapID=543,ends={{npcID=233149,x=0.442,y=0.742,mapID=543}},questType="standard"},
[35711] = {id=35711,name="Nagrand - Treasure 059 - Abu'gar's Tenacity",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6755,mapID=550,ends={{npcID=233157,x=0.658,y=0.611,mapID=550}},questType="standard"},
[35713] = {id=35713,name="The Tinkertoss Twins",level=30,requiredLevel=30,faction="alliance",expansion=5,zoneID=6722,description="Commander, two gnomish smugglers passed by while you were out - Filbert and Dilbert Tinkertoss. They were headed towards the bog to the east. They had all sorts of drilling equipment but didn't seem to have any weapons. What do you think of offering them protection in exchange for some of their materials? I'll jot down where they were headed in case you decide to go.",starts={{npcID=82709,x=0.396,y=0.612,zoneID=6722}},ends={{npcID=82759,x=0.562,y=0.424,zoneID=6722}},coords={x=0.396,y=0.612,source="quest_giver",zoneID=6722},questType="standard"},
[35716] = {id=35716,name="Sticky Situation",level=30,requiredLevel=30,faction="alliance",expansion=5,zoneID=6722,description="A squadron of arakkoa spotted us while we were en route to the excavation site and took out our caravan. My brother made it to safety in the chaos. Lucky son of a tinker. I can't leave without the batteries for our drill, but they all fell into the bog and I can't even get them to budge. Any chance you could retrieve them for me?",starts={{npcID=82759,x=0.562,y=0.424,zoneID=6722}},ends={{npcID=82759,x=0.562,y=0.424,zoneID=6722}},coords={x=0.562,y=0.424,source="quest_giver",zoneID=6722},questType="standard"},
[35718] = {id=35718,name="Back on Track",level=30,requiredLevel=30,faction="horde",expansion=5,zoneID=6722,description="You're a lifesaver, I'll tell you what. Say, how about you go on ahead to the excavation site and let my sister know I'm on my way. I'll get everything neat and tidy and go get a new cart to lug these over.",starts={{npcID=82713,x=0.56,y=0.408,zoneID=6722}},ends={{npcID=82786,x=0.602,y=0.532,zoneID=6722}},coords={x=0.56,y=0.408,source="quest_giver",zoneID=6722},questType="standard"},
[35719] = {id=35719,name="Back on Track",level=30,requiredLevel=30,faction="alliance",expansion=5,zoneID=6722,description="Now that the batteries are out of the bog I can radio in some more copters to take them to camp. I'll stay here until they arrive, but you should go ahead to my brother Dilbert and let him know what happened. He must be worried sick!",starts={{npcID=82759,x=0.562,y=0.424,zoneID=6722}},ends={{npcID=82788,x=0.602,y=0.532,zoneID=6722}},coords={x=0.562,y=0.424,source="quest_giver",zoneID=6722},questType="standard"},
[35725] = {id=35725,name="Vignette: Faebright",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6719,mapID=539,questType="standard"},
[35730] = {id=35730,name="Cauterizing Wounds",level=15,requiredLevel=15,faction="both",expansion=5,zoneID=6721,description="You have saved my most precious companion, Nisha . I owe you a great debt. The Iron Horde lured me away to separate us. I shall not make the same mistake again. They have inflicted grievous wounds, and I fear we must cause her even more pain before the healing process can begin. Please use a burning log from the nearby fire to cauterize her wounds. I will hold her down.",starts={{npcID=82832,x=0.442,y=0.616,zoneID=6721}},ends={{npcID=82832,x=0.442,y=0.616,zoneID=6721}},coords={x=0.442,y=0.616,source="quest_giver",zoneID=6721},questType="standard"},
[35731] = {id=35731,name="Vignette: Ba'ruun",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6719,mapID=539,questType="standard"},
[35732] = {id=35732,name="Vignette: Shinri",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6719,mapID=539,questType="standard"},
[35733] = {id=35733,name="Rites of the Talonpriests",level=30,requiredLevel=30,faction="both",expansion=5,zoneID=6722,description="That gavel was once known as Beakbreaker. In his final, darkest days, Terokk used it to perform grim, damnable acts of sacrifice. It is best not to dwell on those days. Terokk was sealed away deep within the shadows to rest, and perhaps to heal. Making contact with him will take a great deal of effort, so in the meantime, allow me to tell you of his more glorious exploits. Before this wretched curse took hold. Please, place the gavel upon the effigy.",starts={{npcID=81770,x=0.464,y=0.466,zoneID=6722}},ends={{npcID=82813,x=0.466,y=0.466,zoneID=6722}},coords={x=0.464,y=0.466,source="quest_giver",zoneID=6722},questType="standard"},
[35734] = {id=35734,name="The Talon King",level=30,requiredLevel=30,faction="both",expansion=5,zoneID=6722,description="Reshad begins reciting a tale of Terokk's glory days, your eyes fall to the twin swords at the effigy's belt. They had seemed so plain in Skettis, but now they thrum with power, as if reacting to the scrollkeeper's words.>",starts={{npcID=82813,x=0.466,y=0.466,zoneID=6722}},ends={{npcID=81770,x=0.464,y=0.466,zoneID=6722}},coords={x=0.466,y=0.466,source="quest_giver",zoneID=6722},questType="standard"},
[35736] = {id=35736,name="Writing in the Snow",level=40,requiredLevel=40,faction="horde",expansion=5,zoneID=7004,description="This is a worn page from Shadow Hunter Bwu'ja's journal. It appears to be a sketch of the entrance of the Bloodmaul Slave Mines. Rokhan , in your garrison, would be very interested in this.",ends={{npcID=78487,x=0.456,y=0.432,zoneID=7004}},questType="standard"},
[35737] = {id=35737,name="Writing in the Snow",level=40,requiredLevel=40,faction="alliance",expansion=5,zoneID=7078,description="This is a worn page from Owynn Graddock's journal. It appears to be a sketch of the entrance of the Bloodmaul Slave Mines. Bodrick Grey , in your garrison, would be very interested in this.",ends={{npcID=81492,x=0.378,y=0.368,zoneID=7078}},questType="standard"},
[35738] = {id=35738,name="All Natural",level=30,requiredLevel=30,faction="horde",expansion=5,zoneID=6722,description="So you have a smuggler's den, huh? I'd love to trade with ya, toots, I really would, but my laser cannon isn't even functional right now. I'll tell you what. See all the ancients around here? They got toasted good by the arakkoa's weapon, and they're practically walking piles of charcoal. Bring me some charcoal to power this thing and you've got a deal.",starts={{npcID=82786,x=0.602,y=0.532,zoneID=6722}},ends={{npcID=82786,x=0.602,y=0.532,zoneID=6722}},coords={x=0.602,y=0.532,source="quest_giver",zoneID=6722},questType="standard"},
[35739] = {id=35739,name="All Natural",level=30,requiredLevel=30,faction="alliance",expansion=5,zoneID=6722,description="Oh, you have a trading post? Fantastic! Let's make a deal. You help me power up my laser cannon, and I'll trade some of this... thermo... ultra... obsidiglass with you for some weapons. The ancients all around here are practically made of charcoal after the arakkoa weapon hit, you should go get some of that!",starts={{npcID=82788,x=0.602,y=0.532,zoneID=6722}},ends={{npcID=82788,x=0.602,y=0.532,zoneID=6722}},coords={x=0.602,y=0.532,source="quest_giver",zoneID=6722},questType="standard"},
[35744] = {id=35744,name="Ending Executions",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=4,description="We arrived as soon as we could... but we be too late. Da Iron Horde has taken our warriors prisoner. No doubt they be trying ta squeeze info out of da troops. I fear once they are done with da interrogation they gonna execute their prisoners. Time be running out.",starts={{npcID=85247,x=0.718,y=0.488,zoneID=4}},ends={{npcID=85247,x=0.718,y=0.488,zoneID=4}},coords={x=0.718,y=0.488,source="quest_giver",zoneID=4},questType="standard"},
[35745] = {id=35745,name="Attack of the Iron Horde",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=4,description="We received reports of the Dark Portal turning red right before the attack. They call themselves the Iron Horde. Their army is extremely well equipped, and their numbers appear to be unending. They have already taken Okril'lon Hold and Nethergarde Keep. Our troops on the frontlines could use your help, .",starts={{npcID=82851,x=0.718,y=0.478,zoneID=4},{npcID=84928,x=0.486,y=0.318,zoneID=4}},ends={{npcID=82851,x=0.718,y=0.478,zoneID=4}},coords={x=0.718,y=0.478,source="quest_giver",zoneID=4},questType="standard"},
[35746] = {id=35746,name="Under Siege",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=4,description="Those Iron Horde cannons are laying waste to our troops. I'm not sure how much more of this we can handle. Our forces are already spread too thin. There has to be a way to stop those war machines.",starts={{npcID=82851,x=0.718,y=0.478,zoneID=4},{npcID=84928,x=0.486,y=0.318,zoneID=4}},ends={{npcID=82851,x=0.718,y=0.478,zoneID=4}},coords={x=0.718,y=0.478,source="quest_giver",zoneID=4},questType="standard"},
[35747] = {id=35747,name="Taking a Trip to the Top of the Tank",level=10,requiredLevel=10,faction="both",expansion=5,zoneID=7025,description="We cannot risk the reactivation of the Dark Portal. Now is the time for the deathblow. Thaelin should have figured out how to get that tank working by now. Take him with you, and turn that tank against the Dark Portal itself. We will follow behind you.",starts={{npcID=78563,x=0.444,y=0.808,zoneID=7025}},ends={{npcID=80521,x=0.4,y=0.482,zoneID=7025}},coords={x=0.444,y=0.808,source="quest_giver",zoneID=7025},questType="standard"},
[35748] = {id=35748,name="Subversive Scouts",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=4,description="We have been unable to execute a vast majority of our battleplans. We are definitely being watched. The Iron Horde must have scouts planted throughout the Blasted Lands . Victory is slipping away from us.",starts={{npcID=82851,x=0.718,y=0.478,zoneID=4}},ends={{npcID=82851,x=0.718,y=0.478,zoneID=4}},coords={x=0.718,y=0.478,source="quest_giver",zoneID=4},questType="standard"},
[35750] = {id=35750,name="Lunatic Lieutenants",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=4,mapID=17,description="It is time we learned more about our new enemy. Our scouts have identified a number of the Iron Horde's lieutenants. Their attack is too organized to be run by tribal knowledge alone. Surely their lieutenants have access to secret battleplans. You are the only soldier I can trust with this mission, .",starts={{npcID=84928,x=0.486,y=0.318,mapID=17}},ends={{npcID=84928,x=0.486,y=0.318,mapID=17}},coords={x=0.486,y=0.318,source="quest_giver",mapID=17},questType="standard"},
[35751] = {id=35751,name="Attack on Nethergarde",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=4,description="The Iron Horde controls Nethergarde Keep, but they are fools if they think we will let them retain such a strategic position. My best troops are more than eager to spill the blood of those savages, but we need a champion like yourself to lead the charge.",starts={{npcID=84928,x=0.486,y=0.318,zoneID=4}},ends={{npcID=84928,x=0.486,y=0.318,zoneID=4}},coords={x=0.486,y=0.318,source="quest_giver",zoneID=4},questType="standard"},
[35759] = {id=35759,name="Nagrand - Treasure 065 - Abandoned Cargo",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6755,mapID=550,ends={{npcID=233206,x=0.676,y=0.598,mapID=550}},questType="standard"},
[35760] = {id=35760,name="Toothsmash the Annihilator",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=4,description="If the battleplans you brought back are true, the Dreadmaul ogres are as much to blame for this devastation as the Iron Horde. It's time we send those ogres a message. It looks like the Iron Horde's main contact is a large ogre in Dreadmaul named Toothsmash. Killing him will put a dent in their battleplans.",starts={{npcID=84928,x=0.486,y=0.318,zoneID=4}},ends={{npcID=84928,x=0.486,y=0.318,zoneID=4}},coords={x=0.486,y=0.318,source="quest_giver",zoneID=4},questType="standard"},
[35761] = {id=35761,name="Ransacking Nethergarde",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=4,description="After the Iron Horde took Nethergarde we attacked. While we killed the Iron Horde at Nethergarde they brought more forces through the portal and took Okril'lon Hold. So many souls stripped of their bodies by those savages. We must not forget those that gave their lives at Nethergarde. If you find any mementos of the fallen, bring them back to me.",starts={{npcID=76609,x=0.486,y=0.318,zoneID=4}},ends={{npcID=76609,x=0.486,y=0.318,zoneID=4}},coords={x=0.486,y=0.318,source="quest_giver",zoneID=4},questType="standard"},
[35762] = {id=35762,name="Death to the Dreadmaul",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=4,description="The stupidity of the Dreadmaul ogres never ceases to amaze me. The Iron Horde is clearly using them to further their own nefarious agenda. Regardless, we must show the ogres what happens when you confront the true Horde. I think it's time we send the Dreadmaul ogres a message.",starts={{npcID=84928,x=0.486,y=0.318,zoneID=4}},ends={{npcID=84928,x=0.486,y=0.318,zoneID=4}},coords={x=0.486,y=0.318,source="quest_giver",zoneID=4},questType="standard"},
[35763] = {id=35763,name="Gar'mak Bladetwist",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=4,description="With the intelligence you have gathered we have learned this assault is being led by a powerful Iron Horde orc named Gar'mak Bladetwist . He is hunkered down inside Okril'lon Hold. Killing him will not win this war, but it will surely break down the Iron Horde's communication. This will buy us valuable time while we gather more forces and outline a battleplan to deal with this new threat.",starts={{npcID=84928,x=0.486,y=0.318,zoneID=4}},ends={{npcID=84928,x=0.486,y=0.318,zoneID=4}},coords={x=0.486,y=0.318,source="quest_giver",zoneID=4},questType="standard"},
[35764] = {id=35764,name="Okrilla's Revenge",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=4,description="The Dreadmaul ogres think they have bested us? They will all suffer. Here take this poison, place a couple drops in their rat stew. The poison will slowly eat away at their insides. Causing a prolonged and painful death, just like they deserve.",starts={{npcID=76609,x=0.486,y=0.318,zoneID=4}},ends={{npcID=76609,x=0.486,y=0.318,zoneID=4}},coords={x=0.486,y=0.318,source="quest_giver",zoneID=4},questType="standard"},
[35765] = {id=35765,name="Nagrand - Treasure 049 - Adventurer's Pack",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6755,mapID=550,ends={{npcID=233218,x=0.823,y=0.566,mapID=550}},questType="standard"},
[35766] = {id=35766,name="I See Dead Arakkoa",level=30,requiredLevel=30,faction="horde",expansion=5,zoneID=6722,description="I've got a strange problem and I'm hoping you might be able to help. I don't know who else could help, to be honest. My workers keep saying they're seeing the ghost of the arakkoa that used to head up this place. I know, I know, it's crazy but could you take my Ghostogrifier 12000 to her body and check? If there's a ghost around here, it'll find it. If there's not, then my workers are trying to slack off on the clock.",starts={{npcID=82786,x=0.602,y=0.532,zoneID=6722}},ends={{npcID=82786,x=0.602,y=0.532,zoneID=6722}},coords={x=0.602,y=0.532,source="quest_giver",zoneID=6722},questType="standard"},
[35782] = {id=35782,name="I See Dead Arakkoa",level=30,requiredLevel=30,faction="alliance",expansion=5,zoneID=6722,description="Say, while you're here would you mind helping me out with a major problem? The workers keep saying that they're seeing the ghost of the head arakkoa that used to be here. I don't believe it for a second but could you take my Ghostogrifier 12000 to her body and check? If they're not crazy, it'll prove it.",starts={{npcID=82788,x=0.602,y=0.532,zoneID=6722}},ends={{npcID=82788,x=0.602,y=0.532,zoneID=6722}},coords={x=0.602,y=0.532,source="quest_giver",zoneID=6722},questType="standard"},
[35786] = {id=35786,name="Bronze Victory",level=40,requiredLevel=40,faction="horde",expansion=5,zoneID=7004,mapID=525,starts={{npcID=88395,x=0.404,y=0.562,mapID=525}},ends={{npcID=88395,x=0.404,y=0.562,mapID=525}},coords={x=0.404,y=0.562,source="quest_giver",mapID=525},questType="standard"},
[35787] = {id=35787,name="Silver Victory",level=40,requiredLevel=40,faction="horde",expansion=5,zoneID=7004,mapID=525,starts={{npcID=88395,x=0.404,y=0.562,mapID=525}},ends={{npcID=88395,x=0.404,y=0.562,mapID=525}},coords={x=0.404,y=0.562,source="quest_giver",mapID=525},questType="standard"},
[35788] = {id=35788,name="Gold Victory",level=40,requiredLevel=40,faction="horde",expansion=5,zoneID=7004,mapID=525,starts={{npcID=88395,x=0.404,y=0.562,mapID=525}},ends={{npcID=88395,x=0.404,y=0.562,mapID=525}},coords={x=0.404,y=0.562,source="quest_giver",mapID=525},questType="standard"},
[35797] = {id=35797,name="The Ebon Hunter",level=30,requiredLevel=30,faction="horde",expansion=5,zoneID=6722,description="The laser should be good to go once we get it set up, there's just one more thing I need. There's a spore walker that hunts on the delta just southeast from here. It has an apparatus on its face that can fire a powerful laser - way more powerful than what we have hooked up. I want it. We'll be mining faster than you can imagine once we get that bad boy hooked up!",starts={{npcID=82786,x=0.602,y=0.532,zoneID=6722}},ends={{npcID=82786,x=0.602,y=0.532,zoneID=6722}},coords={x=0.602,y=0.532,source="quest_giver",zoneID=6722},questType="standard"},
[35798] = {id=35798,name="Treasure: Glowing Cave Blossom",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6719,mapID=539,ends={{npcID=233241,x=0.487,y=0.476,mapID=539}},questType="standard"},
[35807] = {id=35807,name="Trophy of Glory: Erosian",level=15,requiredLevel=15,faction="horde",expansion=5,zoneID=6721,description="Defeating Erosian has yielded you a trophy worthy of acclaim. Take this to Durotan at Beastwatch.",ends={{npcID=74594,x=0.372,y=0.77,zoneID=6721}},questType="standard"},
[35808] = {id=35808,name="Trophy of Glory: Erosian",level=15,requiredLevel=15,faction="alliance",expansion=5,zoneID=6721,description="Defeating Erosian has yielded you a trophy worthy of acclaim. Take this to Maraad at Highpass.",ends={{npcID=75127,x=0.528,y=0.596,zoneID=6721}},questType="standard"},
