[35944] = {id=35944,name="Proof of Strength: Goren Tooth",level=15,requiredLevel=15,faction="alliance",expansion=5,zoneID=6721,description="This tooth is proof of your strength at slaying goren and your gladiator friend has born witness! Take the tooth back to Jonaa and claim your accolades!",ends={{npcID=81076,x=0.528,y=0.598,zoneID=6721}},questType="standard"},
[35945] = {id=35945,name="Greblin Fastfizzle",level=40,requiredLevel=40,faction="both",expansion=5,zoneID=6755,description="I've been hanging here forever! I was flying around, surveying the area for Nixxie when -- blamo! One of those stupid ogres throws a rock right at me! My glider busted and here I am... and boy is this uncomfortable. Help me down will ya? I'll make it worth your while.",starts={{npcID=83686,x=0.396,y=0.246,zoneID=6755}},ends={{npcID=83734,x=0.396,y=0.244,zoneID=6755}},coords={x=0.396,y=0.246,source="quest_giver",zoneID=6755},questType="standard"},
[35946] = {id=35946,name="Peckers the Majestic",level=0,requiredLevel=0,faction="horde",expansion=5,zoneID=6721,mapID=543,description="You have done me a great service. This blade is as much yours as it is mine. I offer you this blood oath: I shall serve your cause and lend my knowledge of blades and mining to your forces. Will you accept it?",questType="standard"},
[35947] = {id=35947,name="The Power of Poison",level=30,requiredLevel=30,faction="horde",expansion=5,zoneID=6722,description="G.V.? We need a name and a location. Not damned initials. This is my last vial of wracking poison . We use it to extract information from prisoners. It is... potent. Coat your weapon with it and head into the Shattered Hand camp just ahead. Engage them as normal and demand answers - the poison will take care of the rest. I've had enough of these orcs.",starts={{npcID=83772,x=0.536,y=0.274,zoneID=6722}},ends={{npcID=83772,x=0.536,y=0.274,zoneID=6722}},coords={x=0.536,y=0.274,source="quest_giver",zoneID=6722},questType="standard"},
[35948] = {id=35948,name="Proof of Strength: Goren Tooth",level=15,requiredLevel=15,faction="horde",expansion=5,zoneID=6721,description="This tooth is proof of your strength at slaying goren and your gladiator friend has born witness! Take the tooth back to Limbflayer and claim your accolades!",ends={{npcID=76688,x=0.462,y=0.696,zoneID=6721}},questType="standard"},
