[35959] = {id=35959,name="The Power of Poison",level=30,requiredLevel=30,faction="alliance",expansion=5,zoneID=6722,description="G.V.? We need a full name. A location! I have an idea fer how we can find those out. This is my last vial o' wracking poison. We use it when we need tae extract information from prisoners. Coat yer weapon wi' it and head into the Shattered Hand camp just ahead. Engage them as normal and demand answers - the poison will take care o' the rest.",starts={{npcID=83773,x=0.536,y=0.274,zoneID=6722}},ends={{npcID=83773,x=0.536,y=0.274,zoneID=6722}},coords={x=0.536,y=0.274,source="quest_giver",zoneID=6722},questType="standard"},
