[35969] = {id=35969,name="Nagrand - Treasure 018 - Adventurer's Pack",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6755,mapID=550,ends={{npcID=233511,x=0.456,y=0.52,mapID=550}},questType="standard"},
[35970] = {id=35970,name="Preservation Capitalization",level=40,requiredLevel=40,faction="both",expansion=5,zoneID=6755,description="I'm looking for precious artifacts. The kind of artifacts that can help solve some of the greatest mysteries of Draenor, and make the Steamwheedle Preservation Society a ton of moolah. And ladies love the moolah, know what I'm sayin? So, get me the artifacts, I'll get the ladies, and you get... wait, what are you looking for again?",starts={{npcID=83734,x=0.396,y=0.244,zoneID=6755}},ends={{npcID=83734,x=0.396,y=0.244,zoneID=6755}},coords={x=0.396,y=0.244,source="quest_giver",zoneID=6755},questType="standard"},
[35971] = {id=35971,name="Tracking: Mill Treasure 7",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6721,mapID=543,questType="standard"},
[35972] = {id=35972,name="Ogre Onslaught",level=40,requiredLevel=40,faction="both",expansion=5,zoneID=6755,description="Those ogres are standing in the way of a full Steamwheedle Preservation excavation. They are brutal, violent, horrible smelling beasts. And if I'm being completely honest with myself, I'm pretty mad they broke my glider. Do me a favor will ya? Wipe 'em off the face of Draenor. It will make everyone's life easier, or at the very least, it will make my life easier.",starts={{npcID=83734,x=0.396,y=0.244,zoneID=6755}},ends={{npcID=83734,x=0.396,y=0.244,zoneID=6755}},coords={x=0.396,y=0.244,source="quest_giver",zoneID=6755},questType="standard"},
[35973] = {id=35973,name="Brokyo Beatdown",level=40,requiredLevel=40,faction="both",expansion=5,zoneID=6755,description="I'm almost done here, but I can't leave in good conscience. I spotted an ogron named Brokyo that is wearing a priceless ring. Priceless as in crazy expensive. I'm sure Nixxie will give me a promotion if I bring that ring back to her.",starts={{npcID=76508,x=0.406,y=0.13,zoneID=6755}},ends={{npcID=76508,x=0.406,y=0.13,zoneID=6755}},coords={x=0.406,y=0.13,source="quest_giver",zoneID=6755},questType="standard"},
[35975] = {id=35975,name="Tracking: Mill Treasure 8",level=0,requiredLevel=0,faction="none",expansion=5,zoneID=6721,mapID=543,questType="standard"},
