[35985] = {id=35985,name="Garrison Campaign: The Broken Precipice",level=40,requiredLevel=40,faction="alliance",expansion=5,zoneID=6755,description="Hey there! You're the commander of this keep, right? I represent the Steamwheedle Preservation Society. We've been trying to get a very important excavation up and running in Nagrand. Unfortunately, we've had trouble with ogres in the area. In fact, one of our best preservationists recently went missing while surveying the area. He's the third society member we've lost up there this week! We aren't really equipped for a rescue mission... so whad'ya say? We could really use the help.",starts={{npcID=88892,x=0.548,y=0.148,zoneID=7004},{npcID=88892,x=0.606,y=0.79,zoneID=7078}},ends={{npcID=83686,x=0.396,y=0.246,zoneID=6755}},coords={x=0.548,y=0.148,source="quest_giver",zoneID=7004},questType="standard"},
[35986] = {id=35986,name="Nagrand - Treasure 021 - Bone-Carved Dagger",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6755,mapID=550,ends={{npcID=233532,x=0.773,y=0.281,mapID=550}},questType="standard"},
[35987] = {id=35987,name="Nagrand - Treasure 025 - Genedar Debris",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6755,mapID=550,ends={{npcID=233539,x=0.433,y=0.575,mapID=550}},questType="standard"},
[35996] = {id=35996,name="Vignette: Depthroot",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6721,mapID=543,questType="standard"},
[35997] = {id=35997,name="Empire's Fall",level=40,requiredLevel=40,faction="both",expansion=5,zoneID=6996,description="The Ogre Sorcerer King, Imperator Mar'gok, has mastered magical techniques we would consider on the fringe of arcane science. His felbreakers, among others, can actively dampen or nullify magic. Even fel magic! If we're to locate Gul'dan, we need to figure out how it's done. Acquire a felbreaker's tome from his felbreaker captain and acquire the sigil of the sorcerer king himself - I must know what he knows. Yes, , this means I expect you to storm Highmaul and defeat everyone inside. Get to it!",starts={{npcID=83823,x=0.852,y=0.316,zoneID=6662}},ends={{npcID=83823,x=0.852,y=0.316,zoneID=6662}},coords={x=0.852,y=0.316,source="quest_giver",zoneID=6662},questType="standard"},
[35998] = {id=35998,name="Legacy of the Sorcerer Kings",level=40,requiredLevel=40,faction="both",expansion=5,zoneID=6662,description="For over a thousand years, the ogre sorcerer kings maintained an iron grip over their empire using a variety of artifacts. Trusted lieutenants were given magical gems that allowed them to enforce the emperor's will out in the field. These \" Abrogator Stones \" still maintain their power even today, and can be found scattered throughout the Highmaul complex. Sometimes in clusters. Collect $1oa of these Abrogator Stones for me!",starts={{npcID=83823,x=0.852,y=0.316,zoneID=6662}},ends={{npcID=83823,x=0.852,y=0.316,zoneID=6662}},coords={x=0.852,y=0.316,source="quest_giver",zoneID=6662},questType="standard"},
[35999] = {id=35999,name="Nagrand - Treasure 071 - Genedar Debris",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6755,mapID=550,ends={{npcID=233549,x=0.481,y=0.601,mapID=550}},questType="standard"},
[36001] = {id=36001,name="Tracking: Mill Treasure 14",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6721,mapID=543,questType="standard"},
[36002] = {id=36002,name="Nagrand - Treasure 072 - Genedar Debris",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6755,mapID=550,ends={{npcID=233551,x=0.446,y=0.675,mapID=550}},questType="standard"},
[36003] = {id=36003,name="Tracking: Mill Treasure 15",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6721,mapID=543,questType="standard"},
[36004] = {id=36004,name="Power Unleashed",level=40,requiredLevel=40,faction="both",expansion=5,zoneID=6662,description="You've more than earned a reward, commander. I'll wrap things up here and meet you back at my tower - you can use my portal as a shortcut. Speak to me when you arrive and I will use Kairoz's power with the crystals you gathered earlier to upgrade your ring!",starts={{npcID=84702,x=0.772,y=0.368,zoneID=6755}},ends={{npcID=83823,x=0.852,y=0.316,zoneID=6662}},coords={x=0.772,y=0.368,source="quest_giver",zoneID=6755},questType="standard"},
[36005] = {id=36005,name="The Scrying Game",level=40,requiredLevel=40,faction="both",expansion=5,zoneID=6662,description="We've learned everything we need from the ogres, . Thanks to your efforts, I believe I can pierce the veil of secrecy that's cloaking Gul'dan. I WILL find him, . Once my spell is finished we should be ready to leap into action. I won't begin until you let me know you're ready.",starts={{npcID=83823,x=0.852,y=0.316,zoneID=6662}},ends={{npcID=83929,x=0.848,y=0.314,zoneID=6662}},coords={x=0.852,y=0.316,source="quest_giver",zoneID=6662},questType="standard"},
[36006] = {id=36006,name="Hunter: Hunted",level=40,requiredLevel=40,faction="both",expansion=5,zoneID=6662,description="The weapon that stabbed the archmage was imbued with fel magic. He's slowly being poisoned! , we don't have any time. Khadgar will be dead in minutes. I need you to track down Garona before she gets away - find that murder weapon and maybe we can find a cure! Follow the traces of fel energy she left behind. Track her down into the Zangarra lowlands and capture her with this Violet Hold Incarceration rune. Hurry!",starts={{npcID=83929,x=0.848,y=0.314,zoneID=6662}},ends={{npcID=83929,x=0.848,y=0.314,zoneID=6662}},coords={x=0.848,y=0.314,source="quest_giver",zoneID=6662},questType="standard"},
[36007] = {id=36007,name="Touch of the Kirin-Tor",level=40,requiredLevel=40,faction="both",expansion=5,zoneID=6662,description="You saved me, . Once again I underestimated Gul'dan, and it nearly cost me everything. Come, help me up. While Jaina is here, the two of us can work together to upgrade your ring. You've earned it! Let me know when you're ready.",starts={{npcID=83823,x=0.852,y=0.316,zoneID=6662}},ends={{npcID=83823,x=0.852,y=0.316,zoneID=6662}},coords={x=0.852,y=0.316,source="quest_giver",zoneID=6662},questType="standard"},
[36008] = {id=36008,name="Nagrand - Treasure 073 - Genedar Debris",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6755,mapID=550,ends={{npcID=233555,x=0.486,y=0.727,mapID=550}},questType="standard"},
[36009] = {id=36009,name="Heart of the Fury",level=40,requiredLevel=40,faction="both",expansion=5,zoneID=6662,description="It is foolish to pursue Gul'dan with magical means alone. But thanks to you we have a prisoner: Garona. If we can break Gul'dan's mind-control over her, we will learn all his secrets. I can do it, but I'll need some powerful spell components. First on the list is the heart of an elemental fury. There's one imprisoned in the center of the Blackrock Foundry. Fight your way in, destroy the furnace, and slay the elemental within.",starts={{npcID=83823,x=0.852,y=0.316,zoneID=6662}},ends={{npcID=83823,x=0.852,y=0.316,zoneID=6662}},coords={x=0.852,y=0.316,source="quest_giver",zoneID=6662},questType="standard"},
[36010] = {id=36010,name="Flamebender's Tome",level=40,requiredLevel=40,faction="both",expansion=5,zoneID=6967,description="The Iron Horde, and the Burning Blade clan in particular, have forged a unique relationship with Draenor's ancient elementals. They can work with iron and flame in ways that even I don't fully understand. Yet. , slay the Burning Blade's highest-ranking artisan: Flamebender Ka'graz. She is down in the very heart of the Black Forge of the Blackrock Foundry, an area known as the Burning Font. If we're lucky, her secrets are codified in a Flamebender's Tome .",starts={{npcID=83823,x=0.852,y=0.316,zoneID=6662}},ends={{npcID=83823,x=0.852,y=0.316,zoneID=6662}},coords={x=0.852,y=0.316,source="quest_giver",zoneID=6662},questType="standard"},
[36011] = {id=36011,name="Nagrand - Treasure 074 - Genedar Debris",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6755,mapID=550,ends={{npcID=233557,x=0.553,y=0.682,mapID=550}},questType="standard"},
[36012] = {id=36012,name="Reverse Piracy",level=40,requiredLevel=40,faction="both",expansion=5,zoneID=6662,description=", during the attack on Karabor Iron Horde dreadnaughts looted or sank most of the draenei eastern fleet. A priceless artifact was captured: A genuine Draenic Thaumaturgical Orb . I must have it! Those orcs don't know what they've got! My sources indicate that the orb was aboard a ship that's being retrofitted down in the Dread Grotto beneath the Blackrock Foundry. Search the ship and the area nearby for the Sha'tari Vault that contained the orb. We've got to get it back!",starts={{npcID=83823,x=0.852,y=0.316,zoneID=6662}},ends={{npcID=83823,x=0.852,y=0.316,zoneID=6662}},coords={x=0.852,y=0.316,source="quest_giver",zoneID=6662},questType="standard"},
[36013] = {id=36013,name="Might of the Elemental Lords",level=40,requiredLevel=40,faction="both",expansion=5,zoneID=6662,description="Somehow, the Blackrock Clan has forged an alliance with the creatures of fire and stone. I must know how! Search the entirety of the Blackrock Foundry. We are looking for stone tablets dating back to the prehistory of Draenor. They will likely be broken apart into fragments that you'll need to assemble by hand. Look for elemental runes carried by high-ranking members of the Iron Horde. Assemble them and bring me those tablets, . I will use their power to augment the powers of your ring!",starts={{npcID=83823,x=0.852,y=0.316,zoneID=6662}},ends={{npcID=83823,x=0.852,y=0.316,zoneID=6662}},coords={x=0.852,y=0.316,source="quest_giver",zoneID=6662},questType="standard"},
[36014] = {id=36014,name="Blackhand's Secret",level=40,requiredLevel=40,faction="both",expansion=5,zoneID=6967,description=", you've given me a lot to think about. There's a section of the Flamebender's Tome that speaks about a \"sacrifice,\" and a more recent notation referring to \"the chieftain.\" I think it's talking about Warlord Blackhand. Did Blackhand sacrifice someone? Himself? A piece of himself? Is that why his hand is deformed? Before I risk channeling these elements into a spell, I need to know. And there's only one way to find out. Kill Warlord Blackhand. And bring me his severed arm.",starts={{npcID=83823,x=0.852,y=0.316,zoneID=6662}},ends={{npcID=83823,x=0.852,y=0.316,zoneID=6662}},coords={x=0.852,y=0.316,source="quest_giver",zoneID=6662},questType="standard"},
[36015] = {id=36015,name="Tracking: Mill Treasure 16",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6721,mapID=543,questType="standard"},
[36016] = {id=36016,name="The Unbroken Circle",level=40,requiredLevel=40,faction="both",expansion=5,zoneID=6662,description="Reading these tablets is like stepping back in time to the moment of Draenor's creation. There is a power here greater than any I have dealt with since I was Medivh's apprentice. I believe I can control it, but - can you handle it? If you think you are ready, prepare yourself. Hold your ring close to your heart. I will channel pure elemental energies into it. Speak with me to begin!",starts={{npcID=83823,x=0.852,y=0.316,zoneID=6662}},ends={{npcID=83823,x=0.852,y=0.316,zoneID=6662}},coords={x=0.852,y=0.316,source="quest_giver",zoneID=6662},questType="standard"},
[36017] = {id=36017,name="Prisoner of the Mind",level=40,requiredLevel=40,faction="both",expansion=5,zoneID=6662,description="I'd had some time to compare the Flamebinder's tome with the elemental tablets you collected. Where it gets interesting is when I cross-reference the incantations you obtained from the ogre felbreakers... I can see I'm losing you. I will get to the point: I believe I can cast a spell that will nullify Gul'dan's mind control over his assassin Garona. Mind-controlled or not, she may be dangerous, so I won't begin the spell until you're with me. Let me know when you're ready!",starts={{npcID=83823,x=0.852,y=0.316,zoneID=6662}},ends={{npcID=83823,x=0.852,y=0.316,zoneID=6662}},coords={x=0.852,y=0.316,source="quest_giver",zoneID=6662},questType="standard"},
[36018] = {id=36018,name="We're Not Finished...",level=40,requiredLevel=40,faction="both",expansion=5,zoneID=6662,description=", I'm going to have to hit the books and do more research to figure out how to locate Gul'dan or untangle his mind control of Garona. It's not glamorous, but the life of a mage is often spent in long hours of grueling study. As for you, there's much to do. Ensure that your garrison is fully upgraded, locate the best possible equipment, and continue fighting the Iron Horde. I will summon you when the next step of our journey is ready.",starts={{npcID=83823,x=0.852,y=0.316,zoneID=6662}},ends={{npcID=83823,x=0.852,y=0.316,zoneID=6662}},coords={x=0.852,y=0.316,source="quest_giver",zoneID=6662},questType="standard"},
[36019] = {id=36019,name="Tracking: Mill Treasure 17",level=0,requiredLevel=0,faction="none",expansion=5,zoneID=6721,mapID=543,questType="standard"},
[36020] = {id=36020,name="Nagrand - Treasure 026 - Oshu'gun Fragment",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6755,mapID=550,ends={{npcID=233560,x=0.458,y=0.663,mapID=550}},questType="standard"},
[36021] = {id=36021,name="Nagrand - Treasure 036 - Pokhar's Thirteenth Axe",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6755,mapID=550,ends={{npcID=233561,x=0.583,y=0.594,mapID=550}},questType="standard"},
[36022] = {id=36022,name="Extrinsic Motivation",level=30,requiredLevel=30,faction="horde",expansion=5,zoneID=6722,description="The Shattered Hand aren't strangers to pain. They each cut off their own hand as a sign of their allegiance to Kargath. If you're going to get them to talk, it might take more than my poison. Slaughter them all. We'll see how far they're willing to go for their beloved warlord.",starts={{npcID=83772,x=0.536,y=0.274,zoneID=6722}},ends={{npcID=83772,x=0.536,y=0.274,zoneID=6722}},coords={x=0.536,y=0.274,source="quest_giver",zoneID=6722},questType="standard"},
[36023] = {id=36023,name="Extrinsic Motivation",level=30,requiredLevel=30,faction="alliance",expansion=5,zoneID=6722,description="The Shattered Hand are nae strangers tae pain. They each cut off their own hand as a sign o' their allegiance to Kargath. If you're going tae get the information we need, it might take more than my poison. Slaughter them all. We'll see how far they're willing tae go fer their beloved warlord.",starts={{npcID=83773,x=0.536,y=0.274,zoneID=6722}},ends={{npcID=83773,x=0.536,y=0.274,zoneID=6722}},coords={x=0.536,y=0.274,source="quest_giver",zoneID=6722},questType="standard"},
