[36028] = {id=36028,name="Gardul Venomshiv",level=30,requiredLevel=30,faction="horde",expansion=5,zoneID=6722,description="We need to take out Gardul and take his poison recipe while we still have the element of surprise on our side. We need it to craft the antidote. This may be our only opportunity. If what you learned is true, his camp is just south of here. You take him down, and I'll make sure none of his guards interfere. Let's get moving.",starts={{npcID=83772,x=0.536,y=0.274,zoneID=6722}},ends={{npcID=83899,x=0.57,y=0.344,zoneID=6722},{npcID=83903,x=0.57,y=0.344,zoneID=6722}},coords={x=0.536,y=0.274,source="quest_giver",zoneID=6722},questType="standard"},
[36029] = {id=36029,name="Gardul Venomshiv",level=30,requiredLevel=30,faction="alliance",expansion=5,zoneID=6722,description="We need tae take out Gardul and take his poison recipe while we still have the element o' surprise on our side. We need the recipe tae figure out the antidote. This may be our only opportunity. If what ye learned is true, his camp is just south of here. Ye take him down, and I'll make sure none of his guards interfere.",starts={{npcID=83773,x=0.536,y=0.274,zoneID=6722}},ends={{npcID=83900,x=0.57,y=0.344,zoneID=6722},{npcID=83904,x=0.57,y=0.344,zoneID=6722}},coords={x=0.536,y=0.274,source="quest_giver",zoneID=6722},questType="standard"},
