[36047] = {id=36047,name="We Have Him Now",level=30,requiredLevel=30,faction="horde",expansion=5,zoneID=6722,description="We have Gardul right where we want him, commander. You're far more equipped to face him than I am. Dispose of him, take his formula from his corpse, and grab as many barrels of poison as you can. I'll guard this ramp and make sure no reinforcements come to his aid.",starts={{npcID=83899,x=0.57,y=0.344,zoneID=6722},{npcID=83903,x=0.57,y=0.344,zoneID=6722}},ends={{npcID=83903,x=0.57,y=0.344,zoneID=6722}},coords={x=0.57,y=0.344,source="quest_giver",zoneID=6722},questType="standard"},
[36048] = {id=36048,name="We Have Him Now",level=30,requiredLevel=30,faction="alliance",expansion=5,zoneID=6722,description="We have Gardul right cornered, commander. Ye have a much better chance against him than me. Take him out, grab the formula from his corpse, and grab as many barrels o' poison as ye can carry. I'll stay here and make sure nae reinforcements come to Gardul's aid.",starts={{npcID=83900,x=0.57,y=0.344,zoneID=6722}},ends={{npcID=83900,x=0.57,y=0.344,zoneID=6722},{npcID=83904,x=0.57,y=0.344,zoneID=6722}},coords={x=0.57,y=0.344,source="quest_giver",zoneID=6722},questType="standard"},
