[36059] = {id=36059,name="A Worthy Vessel",level=30,requiredLevel=30,faction="both",expansion=5,zoneID=6722,description="The time has come, $p. Awaken the Talon King from his long slumber. Call him into this world so that he may destroy our enemies!",starts={{npcID=80153,x=0.458,y=0.456,zoneID=6722}},ends={{npcID=84122,x=0.466,y=0.466,zoneID=6722}},coords={x=0.458,y=0.456,source="quest_giver",zoneID=6722},questType="standard"},
