[36085] = {id=36085,name="On Ebon Wings",level=30,requiredLevel=30,faction="both",expansion=5,zoneID=6722,description="Now we bring our fight to the Adherents. Raastok is certain his new invention will give us control of the Apexis weapons, but we must get close - very close. Ka'alu and her ravens will fly us to the Windswept Terrace. We shall gain a foothold there before pressing on to the Terrace of Dawn.",starts={{npcID=84276,x=0.514,y=0.502,zoneID=6722}},ends={{npcID=84262,x=0.464,y=0.542,zoneID=6722}},coords={x=0.514,y=0.502,source="quest_giver",zoneID=6722},questType="standard"},
