[36364] = {id=36364,name="Spires - Treasure 041 - Toxicfang Venom",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6722,mapID=542,ends={{npcID=234461,x=0.543,y=0.325,mapID=542}},questType="standard"},
