[36366] = {id=36366,name="Spires - Treasure 046 - Goblin Rum",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6722,mapID=542,ends={{npcID=234473,x=0.555,y=0.908,mapID=542}},questType="standard"},
[36368] = {id=36368,name="Lost Lumberjack",level=15,requiredLevel=15,faction="alliance",expansion=5,zoneID=6721,description="All o' them mole machines got mighty unreliable here in Gorgrond . I hear tell that one of 'em might've crashed here in Tangleheart. See if you can find Frenna . She would've been on the one we tracked to this location. I'll go lookin' for the mole machine to see if it can be repaired.",starts={{npcID=82575,x=0.558,y=0.714,zoneID=6721},{npcID=85119,x=0.53,y=0.598,zoneID=6721}},ends={{npcID=82569,x=0.57,y=0.718,zoneID=6721}},coords={x=0.558,y=0.714,source="quest_giver",zoneID=6721},questType="standard"},
[36375] = {id=36375,name="Spires - Treasure 026 - Sethekk Idol",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6722,mapID=542,ends={{npcID=85190,x=0.682,y=0.388,mapID=542}},questType="standard"},
[36376] = {id=36376,name="Goren Invasion!",level=40,requiredLevel=40,faction="alliance",expansion=5,zoneID=7004,description="Quakes have been shaking the garrison, and our scouts haven't reported in hours.",starts={{npcID=78564,x=0.382,y=0.32,zoneID=7078}},ends={{npcID=78564,x=0.382,y=0.32,zoneID=7078}},coords={x=0.382,y=0.32,source="quest_giver",zoneID=7078},questType="standard"},
[36377] = {id=36377,name="Spires - Treasure 049 - Rukhmar's Image",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6722,mapID=542,ends={{npcID=85206,x=0.444,y=0.12,mapID=542}},questType="standard"},
[36378] = {id=36378,name="No Pressure, No Diamonds",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=6720,description="You wish to understand the secrets of our gems, ? In exchange for returning my pendant, I am willing to help. I must warn you, however, that the materials will not be easy to obtain. To the north, you will find magma pools that give birth to living lava creatures. Contained within these, you may find magnificent diamonds. Please return to me with a few of these diamonds...",starts={{npcID=85106,x=0.2,y=0.564,zoneID=6720}},ends={{npcID=85106,x=0.2,y=0.564,zoneID=6720}},coords={x=0.2,y=0.564,source="quest_giver",zoneID=6720},questType="standard"},
[36379] = {id=36379,name="Peeking into the Portal",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=4,description="I sent Scout Pazerp to get a better look at the portal. She should have reported back by now; what could be taking her so long? She is one of my best scouts, I hope she is alright.",starts={{npcID=85213,x=0.668,y=0.28,zoneID=4}},ends={{npcID=85213,x=0.668,y=0.28,zoneID=4}},coords={x=0.668,y=0.28,source="quest_giver",zoneID=4},questType="standard"},
[36380] = {id=36380,name="Diamonds Are Forever",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=6720,description="Please watch closely . I shall craft this jewel into a fine pendant for you. Hopefully you will learn a bit of true jewelcrafting in the process.",starts={{npcID=85106,x=0.2,y=0.564,zoneID=6720}},ends={{npcID=85106,x=0.2,y=0.564,zoneID=6720}},coords={x=0.2,y=0.564,source="quest_giver",zoneID=6720},questType="standard"},
[36382] = {id=36382,name="Peeking into the Portal",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=4,description="I sent Scout Pazaztick to be gettin' a better look at da portal. He shoulda reported back by dis time; what be taking him so long? Dis is what happens when you hire da goblins as help.",starts={{npcID=85247,x=0.718,y=0.488,zoneID=4}},ends={{npcID=85247,x=0.718,y=0.488,zoneID=4}},coords={x=0.718,y=0.488,source="quest_giver",zoneID=4},questType="standard"},
[36384] = {id=36384,name="Field Trial",level=30,requiredLevel=30,faction="both",expansion=5,zoneID=6722,description="Look, I didn't tell Kimzee about this because I don't want to hurt her feelings, I chose not to leave Pinchwhistle Point. See, I've been working on a serum that I think should be able to cure the infected, but when I tried to test it I got surrounded and I injured my leg during the escape. I know I'm on the right track but I need to test it. Do me a favor and take this vial and go try it out on one of the infected outside.",starts={{npcID=81443,x=0.584,y=0.922,zoneID=6722}},ends={{npcID=81443,x=0.584,y=0.922,zoneID=6722}},coords={x=0.584,y=0.922,source="quest_giver",zoneID=6722},questType="standard"},
[36385] = {id=36385,name="Legacy of the Ancients",level=10,requiredLevel=10,faction="both",expansion=5,zoneID=6755,mapID=550,description="Opening the ancient tome you see that it's not actually a tome at all, but a container. Inside are four empty slots. Upon closer inspection each slot has next to it a carving of what appears to be a unique Draenor ancient, some glyphs and a receptacle used to hold a piece of the pictured ancient. There also appear to be directions to where these ancients may be found: medium timber -- Shadowmoon, Gorgrond, the Spires of Arak and Nagrand. These are assassination instructions. From trees to kill trees.",ends={{npcID=84247,x=0.518,y=0.61,mapID=525},{npcID=84248,x=0.348,y=0.496,mapID=539}},questType="standard"},
[36395] = {id=36395,name="Spires - Treasure 003 - Elixir of Shadow Sight 01",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6722,mapID=542,ends={{npcID=234703,x=0.439,y=0.15,mapID=542}},questType="standard"},
