[36401] = {id=36401,name="Spires - Treasure 048 - Elixir of Shadow Sight 06",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6722,mapID=542,ends={{npcID=234736,x=0.531,y=0.845,mapID=542}},questType="standard"},
