[36446] = {id=36446,name="Spires - Treasure 016 - Outcast's Pouch",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6722,mapID=542,ends={{npcID=235168,x=0.469,y=0.34,mapID=542}},questType="standard"},
[36447] = {id=36447,name="Spires - Treasure 020 - Outcast's Basket",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6722,mapID=542,ends={{npcID=235172,x=0.421,y=0.217,mapID=542}},questType="standard"},
[36448] = {id=36448,name="Reduction in Force",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=6755,description="I was a fool to trust him after the fiasco over the Barov family fortune! What I should have done is killed him the first chance I had. And now he thinks he's going to plumb this land for all that it's worth and cut me out?! No, dear brother, not this time! There can only be one CEO of Barov Industries and it will be me. My peasant friend, you must do me this service. Find my brother, Alexi, and serve him a notice of termination! You will likely find him out in the wilds, near small timber.",starts={{npcID=85413,x=0.35,y=0.492,zoneID=7078}},ends={{npcID=85413,x=0.35,y=0.492,zoneID=7078}},coords={x=0.35,y=0.492,source="quest_giver",zoneID=7078},questType="standard"},
[36449] = {id=36449,name="Reduction in Force",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=6755,description="I was a fool to trust him after the fiasco over the Barov family fortune! What I should have done is killed him the first chance I had. And now he thinks he's going to plumb this land for all that it's worth and cut me out?! No, dear brother, not this time! There can only be one CEO of Barov Industries and it will be me. My peasant friend, you must do me this service. Find my brother, Weldon, and serve him a notice of termination! You will likely find him out in the wilds, near small timber.",starts={{npcID=85414,x=0.546,y=0.484,zoneID=7004}},ends={{npcID=85414,x=0.546,y=0.484,zoneID=7004}},coords={x=0.546,y=0.484,source="quest_giver",zoneID=7004},questType="standard"},
