[36452] = {id=36452,name="Spawn Tracking & Spell Visuals: Do They Work?",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=22,description="Here's some text.",questType="standard"},
[36453] = {id=36453,name="Spires - Treasure 038 - Coinbender's Payment",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6722,mapID=542,ends={{npcID=235299,x=0.684,y=0.89,mapID=542}},questType="standard"},
