[36455] = {id=36455,name="Spires - Treasure 040 - Waterlogged Satchel",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6722,mapID=542,ends={{npcID=235307,x=0.665,y=0.565,mapID=542}},questType="standard"},
[36456] = {id=36456,name="Spires - Treasure 045 - Shredder Parts",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6722,mapID=542,ends={{npcID=235310,x=0.609,y=0.846,mapID=542}},questType="standard"},
[36457] = {id=36457,name="Bypassing Security",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=6720,description="Oh, my goodness! This is a list of captives, it appears they may be awaiting transfer... or possibly even execution. There is one name on this list that I do recognize: my master! I have been awaiting his return, but now it appears that he may have fallen into enemy hands. This is a disaster! Please, , we must rescue him. According to the notes, he has been taken to Grom'gar, located far east of here. One moment... I think I may have just the thing to help you break in undetected...",starts={{npcID=85439,x=0.21,y=0.56,zoneID=6720}},ends={{npcID=85440,x=0.612,y=0.712,zoneID=6720}},coords={x=0.21,y=0.56,source="quest_giver",zoneID=6720},questType="standard"},
[36458] = {id=36458,name="Spires - Treasure 055 - Abandoned Mining Pick",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6722,mapID=542,ends={{npcID=235313,x=0.406,y=0.55,mapID=542}},questType="standard"},
[36460] = {id=36460,name="Just Another Stick in the Wall",level=15,requiredLevel=15,faction="horde",expansion=5,zoneID=6721,description="So, get this. As I was flyin' in, I took the opportunity to scope out what might be a defensible position. Just on the other side o' these boulders is an ideal clearing to hole up in. I even brought a set of blueprints to get us all settled in! That's not too presumptuous, is it? Anyway, whenever you're ready just hit this plunger!",starts={{npcID=85147,x=0.456,y=0.706,zoneID=6721}},ends={{npcID=74594,x=0.372,y=0.77,zoneID=6721}},coords={x=0.456,y=0.706,source="quest_giver",zoneID=6721},questType="standard"},
[36462] = {id=36462,name="Spires - Treasure 012 - Admiral Taylor's Coffer",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6722,mapID=542,ends={{npcID=235365,x=0.362,y=0.544,mapID=542}},questType="standard"},
