[36468] = {id=36468,name="Tracking Quest: Treasure Map",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6720,mapID=525,questType="standard"},
[36469] = {id=36469,name="Pets Versus Pests",level=35,requiredLevel=35,faction="horde",expansion=5,zoneID=7004,description="I been tryin' ta get dis place ready for your pets, but we uncovered some rude pests while buildin' da garrison. I tried takin' care o' dem myself, but they be too tough for my little friends. Beat da angry carrot in da garden, da rat eatin' our food, and da ornery water creature harassing da fishermen. If you can do it, I be free to finish up da work on your menagerie.",starts={{npcID=79858,x=0.324,y=0.424,zoneID=7004}},ends={{npcID=79858,x=0.324,y=0.424,zoneID=7004}},coords={x=0.324,y=0.424,source="quest_giver",zoneID=7004},questType="standard"},
[36471] = {id=36471,name="A New Darkmoon Challenger!",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=5861,description="Look at me, now look at my horse, now look back at me, are I not the most impressive battler of pets that you have ever seen? Look now at my compatriot over there. Is he on a horse? Of course not! Is his hat made of fireworks? Not in a million years! Everything about me is more impressive, from my coat color to my last name, which I made myself. Dare you step up to the might of Christoph Willikens Dennis Ragnaros VonFeasel the First? I can see you trembling!",starts={{npcID=85519,x=0.474,y=0.622,zoneID=5861}},ends={{npcID=85519,x=0.474,y=0.622,zoneID=5861}},coords={x=0.474,y=0.622,source="quest_giver",zoneID=5861},questType="standard"},
[36474] = {id=36474,name="The Razorbloom",level=15,requiredLevel=15,faction="horde",expansion=5,zoneID=6721,description="The Laughing Skull shaman Kaz ran off while we were coming here. She claimed to be looking for more of her people in the jungles to the south. Draka insisted on following her to safeguard us against betrayal. Commander, if Kaz is telling the truth, then she and Draka are going to need all the help they can get. Will you join them? They could not have gotten far. This could prove to be the perfect test for your new shredder and lumber mill resources.",starts={{npcID=74594,x=0.372,y=0.77,zoneID=6721}},ends={{npcID=74593,x=0.466,y=0.714,zoneID=6721}},coords={x=0.372,y=0.77,source="quest_giver",zoneID=6721},questType="standard"},
[36475] = {id=36475,name="Stealing the Declaration",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=6720,description="Commander, you and Raleigh did a great job finding me, but I'm exactly where I need to be. We've been working tirelessly since we got here, trying to crack these Draenic texts. I really thought I was gonna get the scrolls, but they nabbed me at the last possible second! Please, you've gotta help me out... up the hill to the east, you'll find the Master Siegesmith's tent. If you can grab the documents out of his chest, possibly this key too, I'll finally have enough to translate their languages.",starts={{npcID=85440,x=0.612,y=0.712,zoneID=6720}},ends={{npcID=85440,x=0.612,y=0.712,zoneID=6720}},coords={x=0.612,y=0.712,source="quest_giver",zoneID=6720},questType="standard"},
[36477] = {id=36477,name="Broken Promises",level=40,requiredLevel=40,faction="both",expansion=5,zoneID=5861,description="A heavily-scratched ring, faintly stained with blood. Someone at the Darkmoon Faire might be able to provide more information about this item.",ends={{npcID=85484,x=0.512,y=0.75,zoneID=5861}},questType="standard"},
[36481] = {id=36481,name="Firebird's Challenge",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=5861,description="You're ready to fly high and give the Firebird's challenge a shot? That's great! Simply collect 15 rings to win! Speak to me when you're ready for takeoff!",starts={{npcID=85546,x=0.484,y=0.714,zoneID=5861}},ends={{npcID=85546,x=0.484,y=0.714,zoneID=5861}},coords={x=0.484,y=0.714,source="quest_giver",zoneID=5861},questType="standard"},
[36482] = {id=36482,name="A Green Ogron?",level=15,requiredLevel=15,faction="horde",expansion=5,zoneID=6721,description="Kaz always told me green ogron are bad. The botani here have a green ogron and it is mean. It was strong enough to take out my dad's entire hunting party. Are you strong enough to kill it?",starts={{npcID=82254,x=0.436,y=0.84,zoneID=6721},{npcID=82274,x=0.436,y=0.84,zoneID=6721}},ends={{npcID=82274,x=0.436,y=0.84,zoneID=6721}},coords={x=0.436,y=0.84,source="quest_giver",zoneID=6721},questType="standard"},
[36483] = {id=36483,name="Battle Pet Roundup",level=1,requiredLevel=1,faction="alliance",expansion=5,zoneID=7078,description="Looks like we've got some visitors in the battle pen today, and they're looking for a fight. Why don't you show 'em how a master of pet battles handles ?",starts={{npcID=85418,x=0.288,y=0.392,zoneID=7078}},ends={{npcID=85418,x=0.288,y=0.392,zoneID=7078}},coords={x=0.288,y=0.392,source="quest_giver",zoneID=7078},questType="standard"},
[36488] = {id=36488,name="Thieving Dwarves",level=15,requiredLevel=15,faction="horde",expansion=5,zoneID=6721,description="Cutter is on the trail of the artifact the dwarves stole. He has the nose of a wolf when it comes to hunting in the jungle. Follow the canyons south until you find him. It would seem the wolf queen and I are going to do more damage here before we leave. We will follow as quickly as we can.",starts={{npcID=82228,x=0.42,y=0.858,zoneID=6721}},ends={{npcID=85601,x=0.464,y=0.934,zoneID=6721}},coords={x=0.42,y=0.858,source="quest_giver",zoneID=6721},questType="standard"},
[36492] = {id=36492,name="Garrison Pet Battle",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6941,mapID=588,questType="standard"},
[36493] = {id=36493,name="Tracking Quest: Can Open Othaar's Door",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6719,mapID=539,questType="standard"},
[36494] = {id=36494,name="News from Talador",level=20,requiredLevel=20,faction="horde",expansion=5,zoneID=7004,description="Rokhan sends word that you are needed at Frostwall. The Iron Horde have landed on the shores of Talador .",starts={{npcID=74594,x=0.372,y=0.77,zoneID=6721}},ends={{npcID=78487,x=0.456,y=0.432,zoneID=7004}},coords={x=0.372,y=0.77,source="quest_giver",zoneID=6721},questType="standard"},
[36495] = {id=36495,name="News from Talador",level=20,requiredLevel=20,faction="alliance",expansion=5,zoneID=7078,description="Bodrick Grey sends word from your garrison that they have spotted a fleet of Iron Horde at the shores of Talador . We must not allow them to destroy Shattrath.",starts={{npcID=75127,x=0.528,y=0.596,zoneID=6721}},ends={{npcID=81492,x=0.378,y=0.368,zoneID=7078}},coords={x=0.528,y=0.596,source="quest_giver",zoneID=6721},questType="standard"},
[36498] = {id=36498,name="Iron Horde Invasion",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=4,description="By order of his royal highness, King Varian Wrynn, all able-bodied citizens of the Alliance are to report to Vindicator Maraad at the Shattered Beachhead in Blasted Lands . Use the portal at the Wizard's Sanctum in Stormwind to head directly to the front line. This new threat is known only as the Iron Horde. They have taken over the Dark Portal and must be stopped. For the glory and honor of the Alliance!",starts={{npcID=206111,x=0.629,y=0.717,zoneID=1519},{npcID=206294,x=0.623,y=0.301,zoneID=1519}},ends={{npcID=82270,x=0.666,y=0.282,zoneID=4}},coords={x=0.629,y=0.717,source="quest_giver",zoneID=1519},questType="standard"},
[36502] = {id=36502,name="Trophy of Glory: Biolante",level=15,requiredLevel=15,faction="alliance",expansion=5,zoneID=6721,description="Defeating Biolante has yielded you a trophy worthy of showing off at your outpost. Return this to Maraad to increase your glory!",ends={{npcID=75127,x=0.528,y=0.596,zoneID=6721}},questType="standard"},
[36503] = {id=36503,name="Trophy of Glory: Biolante",level=15,requiredLevel=15,faction="horde",expansion=5,zoneID=6721,description="Defeating Biolante has yielded you a trophy worthy of acclaim. Take this to Durotan at Beastwatch.",ends={{npcID=74594,x=0.372,y=0.77,zoneID=6721}},questType="standard"},
[36505] = {id=36505,name="A Warrior's Shroud",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=6720,description="Although this cloak has seen better days, the workmanship is still quite impressive. Any normal cloak would have most certainly fallen apart by now. Perhaps one of the Frostwolf orcs within Wor'gol would be willing to help you repair it.",ends={{npcID=85751,x=0.206,y=0.602,zoneID=6720}},questType="standard"},
[36506] = {id=36506,name="Treasure: Orc Super Caster Loot",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6721,mapID=543,ends={{npcID=235859,x=0.417,y=0.529,mapID=543}},questType="standard"},
