[36516] = {id=36516,name="Cut 'Em Out!",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=6720,mapID=525,description="After all that you've done for us, I would love to help you. Regrettably, I don't have the materials I would need to repair this perfectly. Use my knife to gather a few hides from the clefthoof that roam near the spire and find some sootweed pitch to properly cure them. Unfortunately, those miserable ogres have taken up residence in the only place that I know of sootweed to grow. You may be in for a fight . Return to me if you can obtain these and I will gladly help you repair your cloak.",starts={{npcID=85751,x=0.206,y=0.602,mapID=525}},ends={{npcID=85751,x=0.206,y=0.602,mapID=525}},coords={x=0.206,y=0.602,source="quest_giver",mapID=525},questType="standard"},
[36517] = {id=36517,name="Abyssal Gulper Eel",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=7078,description="We need to stock the garrison pond with local fish. I need you to search the waters in Spires of Arak for fish that we can stock up with. Once you have the fish, you will need to slice them up and look for eggs inside.",starts={{npcID=77733,x=0.54,y=0.134,zoneID=7078}},ends={{npcID=77733,x=0.54,y=0.134,zoneID=7078}},coords={x=0.54,y=0.134,source="quest_giver",zoneID=7078},questType="standard"},
