[36741] = {id=36741,name="Vintage Free Action Potion",level=40,requiredLevel=40,faction="alliance",expansion=5,zoneID=8485,description="I hear our heroes in the front line are becoming victim to massive amounts of snares, roots and stuns! Luckily I have just the potion for them. The recipe is a little old, but it'll work. A key ingredient I need can be found here in Ashran , at the beach near that Ogre Tower.",ends={{npcID=85749,x=0.442,y=0.742,zoneID=6941},{npcID=85749,zoneID=8485}},questType="standard"},
[36742] = {id=36742,name="Vintage Free Action Potion",level=40,requiredLevel=40,faction="horde",expansion=5,zoneID=8485,description="The Alliance have increased their usage of snares, roots and stuns on our melee forces. Luckily I have just the potion for them. The recipe is a little old, but it'll work. A key ingredient I need can be found here in Ashran , at the beach near that Ogre Tower.",ends={{npcID=86366,x=0.456,y=0.284,zoneID=6941},{npcID=86366,zoneID=8485}},questType="standard"},
