[36790] = {id=36790,name="The Initiate's Revenge",level=30,requiredLevel=30,faction="both",expansion=5,zoneID=6722,description="I... I'm finished. My spirit will be with the Raven Mother soon. I beg of you, stranger... avenge me! Slay these filthy beasts.",starts={{npcID=86381,x=0.508,y=0.558,zoneID=6722}},ends={{npcID=80746,x=0.52,y=0.494,zoneID=6722}},coords={x=0.508,y=0.558,source="quest_giver",zoneID=6722},questType="standard"},
[36791] = {id=36791,name="Phantom Potion",level=40,requiredLevel=40,faction="alliance",expansion=5,zoneID=8485,description="Every turn you take in Ashran you run into danger. But don't fret , I've developed the perfect solution. It's my very own riff on the popular Invisibility Potion. I'm just missing one of the ingredients: cave mushrooms. Luckily, a variety grows right here in Ashran .",ends={{npcID=85749,x=0.442,y=0.742,zoneID=6941},{npcID=85749,zoneID=8485}},questType="standard"},
