[36801] = {id=36801,name="One Step Ahead",level=20,requiredLevel=20,faction="alliance",expansion=5,zoneID=6662,description="Commander, Vindicator Maraad set off with Yrel and Thaelin Darkanvil to track the Iron Horde's movements in the nearby forest. They await your arrival on a small rise to the southwest.",starts={{npcID=86442,x=0.696,y=0.208,zoneID=6662}},ends={{npcID=75803,x=0.63,y=0.258,zoneID=6662}},coords={x=0.696,y=0.208,source="quest_giver",zoneID=6662},questType="standard"},
