[36813] = {id=36813,name="Subversive Infestation",level=35,requiredLevel=35,faction="both",expansion=5,zoneID=7109,description="As lord of the Everbloom my charge was the weaponization of nature. You have likely seen the fruits of my labor in your journeys across my world. My discoveries have allowed my kind to control the invasive species of Draenor through subversive infestation. I speak of total systemic control of the invading organism - the mind and the body. Now that you are my master I offer these gifts to you, but first you must retrieve my research and tools from the Everbloom . Do this and great power is yours.",starts={{npcID=84889,x=0.582,y=0.258,zoneID=7004},{npcID=84889,x=0.342,y=0.494,zoneID=7078}},ends={{npcID=84889,x=0.582,y=0.258,zoneID=7004},{npcID=84889,x=0.342,y=0.494,zoneID=7078}},coords={x=0.582,y=0.258,source="quest_giver",zoneID=7004},questType="dungeon"},
[36814] = {id=36814,name="Assault on the Everbloom Wilds",level=40,requiredLevel=40,faction="horde",expansion=5,zoneID=6721,questType="standard"},
[36815] = {id=36815,name="Assault on the Everbloom Wilds",level=40,requiredLevel=40,faction="alliance",expansion=5,zoneID=6721,questType="standard"},
[36828] = {id=36828,name="Lumber, I Hardly Knew 'Er",level=15,requiredLevel=15,faction="alliance",expansion=5,zoneID=6721,mapID=543,starts={{npcID=85119,x=0.53,y=0.598,mapID=543}},ends={{npcID=85119,x=0.53,y=0.598,mapID=543}},coords={x=0.53,y=0.598,source="quest_giver",mapID=543},questType="standard"},
[36830] = {id=36830,name="Shadow Council Invasion!",level=40,requiredLevel=40,faction="alliance",expansion=5,zoneID=7004,description="The demons are at our heels, Commander. Cow's milk is sour. A crone gave me an evil look this morning. The sky just doesn't seem... right.",starts={{npcID=78564,x=0.382,y=0.32,zoneID=7078}},ends={{npcID=78564,x=0.382,y=0.32,zoneID=7078}},coords={x=0.382,y=0.32,source="quest_giver",zoneID=7078},questType="standard"},
[36831] = {id=36831,name="Shadow Council Invasion!",level=40,requiredLevel=40,faction="horde",expansion=5,zoneID=7078,description="There's a cold fire in my blood, Commander. Like a warlock has my heart in his claw. Let the Shadow Council show themselves!",starts={{npcID=79774,x=0.44,y=0.476,zoneID=7004}},ends={{npcID=79774,x=0.44,y=0.476,zoneID=7004}},coords={x=0.44,y=0.476,source="quest_giver",zoneID=7004},questType="standard"},
