[36843] = {id=36843,name="They Came From Above",level=20,requiredLevel=20,faction="both",expansion=5,zoneID=6662,description="Please, traveler, I need your help. Aruuna, my home, has been destroyed by the arakkoa. They swooped down from their spires and killed anyone who tried to escape. My family... did not make it out. My brother Barum stayed behind to find his daughter amidst the chaos. I beseech you, please, go to Aruuna and find Barum. He is the only family I have left.",starts={{npcID=86522,x=0.674,y=0.422,zoneID=6662}},ends={{npcID=75896,x=0.73,y=0.386,zoneID=6662}},coords={x=0.674,y=0.422,source="quest_giver",zoneID=6662},questType="standard"},
[36844] = {id=36844,name="Your Second Leatherworking Work Order",level=10,requiredLevel=10,faction="both",expansion=5,zoneID=7004,mapID=525,description="Place another work order with my assistant. Once it is complete, we will leave it out here for you to collect.",ends={{npcID=78207,x=0.502,y=0.574,mapID=539},{npcID=79833,x=0.538,y=0.366,mapID=525}},questType="standard"},
[36845] = {id=36845,name="Your Second Tailoring Work Order",level=10,requiredLevel=10,faction="both",expansion=5,zoneID=7004,mapID=525,description="Place another work order with my assistant. Once it is complete, we will leave it out here for you to collect.",ends={{npcID=77778,x=0.502,y=0.578,mapID=539},{npcID=79863,x=0.534,y=0.364,mapID=525}},questType="standard"},
[36848] = {id=36848,name="Ogre Waygates",level=10,requiredLevel=10,faction="both",expansion=5,zoneID=7004,description="Six unique gates exist in Draenor, built by ogre magi in ages past. We've discovered their potency has not diminished over the millennia. If you can collect enough ogre waystones to activate one of these ancient waygates, we can build a portal from your garrison to that location.",starts={{npcID=77367,x=0.39,y=0.588,zoneID=7078},{npcID=79836,x=0.62,y=0.354,zoneID=7004}},ends={{npcID=77367,x=0.39,y=0.588,zoneID=7078},{npcID=79836,x=0.62,y=0.354,zoneID=7004}},coords={x=0.39,y=0.588,source="quest_giver",zoneID=7078},questType="standard"},
