[36861] = {id=36861,name="Pinchwhistle Gearworks",level=30,requiredLevel=30,faction="alliance",expansion=5,zoneID=6722,description="Commander, a goblin courier arrived this morning. He mentioned that he is from a settlement in the Spires of Arak called the Pinchwhistle Gearworks. They have requested our assistance with some sort of ecological disaster. If we can earn their trust it'll be worth the effort. Head down there and see what sort of assistance we can provide. I've already spoken to the flight master and he's set up a special flight to get you out there.",starts={{npcID=86589,x=0.458,y=0.46,zoneID=7078}},ends={{npcID=81109,x=0.614,y=0.728,zoneID=6722}},coords={x=0.458,y=0.46,source="quest_giver",zoneID=7078},questType="standard"},
[36862] = {id=36862,name="Pinchwhistle Gearworks",level=30,requiredLevel=30,faction="horde",expansion=5,zoneID=6722,description="Commander, a courier arrived this morning. He said he's from a goblin settlement in Spires of Arak called the Pinchwhistle Gearworks. They've asked for our assistance with some sort of ecological disaster. We're spread thin but if we can earn their trust then we might be able to gain a valuable ally. Head down there and see what sort of assistance we can provide. I've already spoken to the flight master and he's set up a special flight to get you out there.",starts={{npcID=86614,x=0.466,y=0.462,zoneID=7004}},ends={{npcID=81109,x=0.614,y=0.728,zoneID=6722}},coords={x=0.466,y=0.462,source="quest_giver",zoneID=7004},questType="standard"},
[36863] = {id=36863,name="Treasure: Iron Horde Munitions",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6720,mapID=525,ends={{npcID=236693,x=0.567,y=0.718,mapID=525}},questType="standard"},
[36864] = {id=36864,name="Three Feet Under",level=30,requiredLevel=30,faction="horde",expansion=5,zoneID=6722,mapID=542,starts={{npcID=86597,x=0.358,y=0.522,mapID=542}},ends={{npcID=86597,x=0.358,y=0.522,mapID=542}},coords={x=0.358,y=0.522,source="quest_giver",mapID=542},questType="standard"},
[36865] = {id=36865,name="UBRS Event Dungeon Reward Quest",level=10,requiredLevel=10,faction="none",expansion=5,questType="standard"},
[36870] = {id=36870,name="Luring Nat",level=20,requiredLevel=20,faction="alliance",expansion=5,zoneID=7078,description="Now that you are experienced enough with Draenor fishing, we might have a shot at convincing Nat Pagle to join us out here. If we want Nat to actually come all the way out here, we are going to have to show him real proof of the incredible catches on Draenor. Head out to local waters here in Shadowmoon Valley and see what you can do. All that time you spend honing your skill here in Draenor should pay off now.",starts={{npcID=85708,x=0.54,y=0.134,zoneID=7078}},ends={{npcID=85708,x=0.54,y=0.134,zoneID=7078}},coords={x=0.54,y=0.134,source="quest_giver",zoneID=7078},questType="standard"},
[36874] = {id=36874,name="Warlord of Draenor",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=7004,description="Durotan... Raza'kul spits.> He cowers behind the white flag of peace, relying upon diplomacy to win over our sworn enemies. Enemies that have taken our homes and driven us from our ancestral lands. There is only one way to deal with the draenei and their newfound alliance of cowards - blood for blood. Join me in crushing our enemies. Together we will flood this hallowed ground with the bones of the Alliance and earn tributes fit for a warchief! Return here when your bloodthirst is sated.",starts={{npcID=86629,x=0.516,y=0.584,zoneID=7004}},ends={{npcID=86629,x=0.516,y=0.584,zoneID=7004}},coords={x=0.516,y=0.584,source="quest_giver",zoneID=7004},questType="pvp"},
[36876] = {id=36876,name="Warlord of Draenor",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=7078,description="The Exarchs do nothing but squabble amongst themselves over petty issues while our people are slaughtered in their homes by orc filth. If they will not raise a fist of defiance against our enemies, I will. I wish to join your Alliance and rid this world of Horde. ALL HORDE - \"Iron\" or otherwise. This Altar of Bones that I stand upon represents glory in battle against our Horde enemy. Place an offering upon it and earn a conqueror's tribute worthy of your unrelenting bloodthirst. Kill. Them. All.",starts={{npcID=86677,x=0.344,y=0.496,zoneID=7078}},ends={{npcID=86677,x=0.344,y=0.496,zoneID=7078}},coords={x=0.344,y=0.496,source="quest_giver",zoneID=7078},questType="pvp"},
[36880] = {id=36880,name="Vignette: Sneevel",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6719,mapID=539,questType="standard"},
[36881] = {id=36881,name="Warlords of Draenor: The Dark Portal",level=10,requiredLevel=10,faction="both",expansion=5,zoneID=7025,description=", is it? I'm glad you're here. We can use every able-bodied that we can get. I am assembling a coalition of Azeroth's strongest to step through this Dark Portal and stop the Iron Horde invasion. This may be the only way to save Azeroth. Will you join us?",starts={{npcID=78423,x=0.548,y=0.502,zoneID=4},{npcID=78423,x=0.864,y=0.638,zoneID=5840}},ends={{npcID=78558,x=0.548,y=0.482,zoneID=7025}},coords={x=0.548,y=0.502,source="quest_giver",zoneID=4},questType="standard"},
[36882] = {id=36882,name="The Great Angler Returns",level=20,requiredLevel=20,faction="alliance",expansion=5,zoneID=7078,description="What's this species, an arcane trout you say? I have never even heard of a fish like this, much less seen one in person! I have to find more fish like this, it's what I live for! And if the fishing is as good as you say it is, there is just no way I can pass this opportunity up. Take this page from my journal as proof that you found me and I will meet you back at your Garrison.",starts={{npcID=63721,x=0.684,y=0.434,zoneID=6134}},ends={{npcID=85708,x=0.54,y=0.134,zoneID=7078}},coords={x=0.684,y=0.434,source="quest_giver",zoneID=6134},questType="standard"},
[36884] = {id=36884,name="Worgen Snout",level=40,requiredLevel=40,faction="horde",expansion=5,zoneID=8485,starts={{npcID=83869,x=0.458,y=0.288,zoneID=6941},{npcID=83869,zoneID=8485}},ends={{npcID=83869,x=0.458,y=0.288,zoneID=6941},{npcID=83869,zoneID=8485}},coords={x=0.458,y=0.288,source="quest_giver",zoneID=6941},questType="standard"},
[36889] = {id=36889,name="Nemesis: Hunter - Hunted",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=7004,description="Our enemies surround us, and with each passing day their numbers grow. It is time to make a decisive strike against their armies, champion. Around me stand effigies of our most hated adversaries. You will be their downfall, . You will become nemesis and they will run in fear at the sight of you. Now select the target of your rage and burn in effigy that race which you mean to eradicate. Speak to me when you have made your selection.",starts={{npcID=86629,x=0.516,y=0.584,zoneID=7004}},ends={{npcID=86629,x=0.516,y=0.584,zoneID=7004}},coords={x=0.516,y=0.584,source="quest_giver",zoneID=7004},questType="pvp"},
[36890] = {id=36890,name="Nemesis Flag, Human/Orc",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6720,mapID=525,questType="pvp"},
