[36961] = {id=36961,name="Nemesis: Becoming Death",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=7078,description="You have chosen your quarry and surely soon they will feel your merciless wrath, but first you must venture out into the wilds of Draenor and rip out the still-beating heart of a tauren in mortal combat. Return here with your prize. Through the heart of your enemy the spirits will attune your senses, granting you second sight and keenness in hearing - all to stalk your prey and claim dominance.",starts={{npcID=86677,x=0.344,y=0.496,zoneID=7078}},ends={{npcID=86677,x=0.344,y=0.496,zoneID=7078}},coords={x=0.344,y=0.496,source="quest_giver",zoneID=7078},questType="pvp"},
[36962] = {id=36962,name="Nemesis: The Butcher",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=7078,description="Kuros hands you the bloody heart.> The ritual is complete. Your nemesis is marked for death. Now your work to rid this world of the enemy truly begins. Kill all tauren that stand defiantly against the Alliance. Let their deaths serve as a warning to the rest of the Horde: they will leave Draenor or they will die. Return when you have quenched your rage with the blood of tauren. Conquer our enemy and be known as the butcher. Fail and be nothing.",starts={{npcID=86677,x=0.344,y=0.496,zoneID=7078}},ends={{npcID=86677,x=0.344,y=0.496,zoneID=7078}},coords={x=0.344,y=0.496,source="quest_giver",zoneID=7078},questType="pvp"},
[36963] = {id=36963,name="Nemesis: Becoming Death",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=7078,description="You have chosen your quarry and surely soon they will feel your merciless wrath, but first you must venture out into the wilds of Draenor and rip out the still-beating heart of an orc in mortal combat. Return here with your prize. Through the heart of your enemy the spirits will attune your senses, granting you second sight and keenness in hearing - all to stalk your prey and claim dominance.",starts={{npcID=86677,x=0.344,y=0.496,zoneID=7078}},ends={{npcID=86677,x=0.344,y=0.496,zoneID=7078}},coords={x=0.344,y=0.496,source="quest_giver",zoneID=7078},questType="pvp"},
