[36965] = {id=36965,name="Nemesis: Becoming Death",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=7078,description="You have chosen your quarry and surely soon they will feel your merciless wrath, but first you must venture out into the wilds of Draenor and rip out the still-beating heart of a troll in mortal combat. Return here with your prize. Through the heart of your enemy the spirits will attune your senses, granting you second sight and keenness in hearing - all to stalk your prey and claim dominance.",starts={{npcID=86677,x=0.344,y=0.496,zoneID=7078}},ends={{npcID=86677,x=0.344,y=0.496,zoneID=7078}},coords={x=0.344,y=0.496,source="quest_giver",zoneID=7078},questType="pvp"},
