[37014] = {id=37014,name="Auctioning for Parts",level=30,requiredLevel=30,faction="horde",expansion=5,zoneID=7004,starts={{npcID=86806,x=0.512,y=0.612,zoneID=7004}},ends={{npcID=86806,x=0.512,y=0.612,zoneID=7004}},coords={x=0.512,y=0.612,source="quest_giver",zoneID=7004},questType="standard"},
[37015] = {id=37015,name="Elekk Training: Cruel Ogres",level=35,requiredLevel=35,faction="alliance",expansion=5,zoneID=7078,description="This beast is surely at home in Nagrand , and I bet ye after all of the years of domestication by Draenei, it's going to be a snap to train. Let's set it loose against the ogres of the region that yer familiar with. That Gorian Beast-Lasher , the one that smells of blood and fear, go on and see how your elekk reacts to that.",questType="standard"},
[37016] = {id=37016,name="Elekk Training: Darkwing Roc",level=38,requiredLevel=38,faction="alliance",expansion=5,zoneID=7078,description="The windrocs of Nagrand are a smart predator, often swooping down on unwary prey in packs. If your beast doesn't keep an eye on the sky, it's likely to lose both of em.' Head on out to Nagrand and take on the fiercest windroc of the bunch, the Darkwing Roc . That'll be a good test for the both of ye.",questType="standard"},
