[37022] = {id=37022,name="Wolf Training: Cruel Ogres",level=35,requiredLevel=35,faction="alliance",expansion=5,zoneID=7078,description="The wolves of Draenor are some of the most savage beasts around, but they've also gotten used to the sights and smells of the orcs and ogres that live here. It shouldn't take us much time at all to train this little ball of fur and death. Let's set it loose against the ogres of the region that yer familiar with. That Gorian Beast-Lasher , the one that smells of blood and fear, go on and see how your wolf reacts to that.",starts={{npcID=86974,x=0.398,y=0.592,zoneID=7078}},ends={{npcID=86974,x=0.398,y=0.592,zoneID=7078}},coords={x=0.398,y=0.592,source="quest_giver",zoneID=7078},questType="standard"},
