[37070] = {id=37070,name="Power of the Nether",level=40,requiredLevel=40,faction="horde",expansion=5,zoneID=7004,mapID=525,starts={{npcID=86945,x=0.296,y=0.264,mapID=535},{npcID=86945,x=0.518,y=0.775,mapID=539},{npcID=86945,x=0.481,y=0.726,mapID=525},{npcID=86945,x=0.159,y=0.448,mapID=534},{npcID=86945,x=0.67,y=0.336,mapID=550},{npcID=86945,x=0.468,y=0.493,mapID=525}},ends={{npcID=86945,x=0.296,y=0.264,mapID=535},{npcID=86945,x=0.518,y=0.775,mapID=539},{npcID=86945,x=0.481,y=0.726,mapID=525},{npcID=86945,x=0.159,y=0.448,mapID=534},{npcID=86945,x=0.67,y=0.336,mapID=550},{npcID=86945,x=0.468,y=0.493,mapID=525}},coords={x=0.296,y=0.264,source="quest_giver",mapID=525},questType="standard"},
[37071] = {id=37071,name="Riverbeast Training: Gezz'ran",level=20,requiredLevel=20,faction="horde",expansion=5,zoneID=7004,description="This bulbous beast has spent a number of years in the wilds of Talador . We will begin the training there. It is already docile, as well, so I do not think it will take as long to train as the others. As you know, stalkers can blend into their environments, allowing them to sneak in and steal the eggs of nearby prey. See if you and your riverbeast can't overcome this natural defense mechanism.",starts={{npcID=87242,x=0.622,y=0.362,zoneID=7004}},ends={{npcID=87242,x=0.622,y=0.362,zoneID=7004}},coords={x=0.622,y=0.362,source="quest_giver",zoneID=7004},questType="standard"},
[37072] = {id=37072,name="Riverbeast Training: Bulbapore",level=30,requiredLevel=30,faction="horde",expansion=5,zoneID=7004,description="In the far south, in the Spires of Arak , the land is being swallowed by the mushrooms that grow underwater, and strange fungal creatures grow uninhibited. Taking on a strange creature, like the fungal giant Bulbapore , will grant you a chance to expose your mount to unfamiliar predators.",starts={{npcID=87242,x=0.622,y=0.362,zoneID=7004}},ends={{npcID=87242,x=0.622,y=0.362,zoneID=7004}},coords={x=0.622,y=0.362,source="quest_giver",zoneID=7004},questType="standard"},
[37073] = {id=37073,name="Riverbeast Training: Cruel Ogres",level=35,requiredLevel=35,faction="horde",expansion=5,zoneID=7004,description="Nagrand is home to the mightiest beasts in Draenor, and the ogres of the region have learned to tame them using brutal techniques. There is one ogre in particular, the Gorian Beast-Lasher , that smells of blood and fear. Go on and see how your beast reacts to that.",starts={{npcID=87242,x=0.622,y=0.362,zoneID=7004}},ends={{npcID=87242,x=0.622,y=0.362,zoneID=7004}},coords={x=0.622,y=0.362,source="quest_giver",zoneID=7004},questType="standard"},
[37074] = {id=37074,name="Riverbeast Training: Darkwing Roc",level=38,requiredLevel=38,faction="horde",expansion=5,zoneID=7004,description="The windrocs of Nagrand are a smart predator, often swooping down on unwary prey in packs. If your beast doesn't keep an eye on the sky, it's likely to lose both. Travel to Nagrand and take on the fiercest windroc of the bunch, the Darkwing Roc . It will be a good test for your mount.",starts={{npcID=87242,x=0.622,y=0.362,zoneID=7004}},ends={{npcID=87242,x=0.622,y=0.362,zoneID=7004}},coords={x=0.622,y=0.362,source="quest_giver",zoneID=7004},questType="standard"},
[37075] = {id=37075,name="Riverbeast Training: Moth of Wrath",level=40,requiredLevel=40,faction="horde",expansion=5,zoneID=7004,description="Deep in the forests of Nagrand are some beasts capable of evading almost any predator. The greatest of them all, the Moth of Wrath , is coated with a foul-smelling dust. If the moth dust is enough to keep wolves at bay, it will probably be a pretty good test for your riverbeast. See if you can keep it focused and defeat the moth.",starts={{npcID=87242,x=0.622,y=0.362,zoneID=7004}},ends={{npcID=87242,x=0.622,y=0.362,zoneID=7004}},coords={x=0.622,y=0.362,source="quest_giver",zoneID=7004},questType="standard"},
[37076] = {id=37076,name="Riverbeast Training: Thundercall",level=40,requiredLevel=40,faction="horde",expansion=5,zoneID=7004,description="The elements can sometimes pose a problem for some beasts. Even the mightiest wolf will often cower at the sound of thunder in the distance. In Nagrand , off on a windswept cliff high above the shore, is a creature made of pure thunderstorms. Hop atop your beast and face off against Thundercall , and we will see how your mount fares.",starts={{npcID=87242,x=0.622,y=0.362,zoneID=7004}},ends={{npcID=87242,x=0.622,y=0.362,zoneID=7004}},coords={x=0.622,y=0.362,source="quest_giver",zoneID=7004},questType="standard"},
[37077] = {id=37077,name="Riverbeast Training: Ironbore",level=40,requiredLevel=40,faction="horde",expansion=5,zoneID=7004,description="You have defeated foes in the sky and on land, and even in the rain. Next, you face beasts beneath your very feet. The rockworm is a cunning predator, striking at prey from below the sands. Many beasts of Nagrand have grown wary of the rumbling of the earth. Take your mount on out to the sandy shores test it against the elder worm Ironbore .",starts={{npcID=87242,x=0.622,y=0.362,zoneID=7004}},ends={{npcID=87242,x=0.622,y=0.362,zoneID=7004}},coords={x=0.622,y=0.362,source="quest_giver",zoneID=7004},questType="standard"},
[37078] = {id=37078,name="Riverbeast Training: Orc Hunters",level=40,requiredLevel=40,faction="horde",expansion=5,zoneID=7004,description="The Warsong Clan of Nagrand are some of the finest hunters the world of Draenor has ever known. Their beast-killers will aid us in putting this mount to the test. Out in Nagrand , you will find an orc by the name of Karak, the Great Hunter. He has slain more fierce beasts than any other in the clan. Face him astride your mount, and avenge the slain.",starts={{npcID=87242,x=0.622,y=0.362,zoneID=7004}},ends={{npcID=87242,x=0.622,y=0.362,zoneID=7004}},coords={x=0.622,y=0.362,source="quest_giver",zoneID=7004},questType="standard"},
[37079] = {id=37079,name="Riverbeast Training: The Garn",level=40,requiredLevel=40,faction="horde",expansion=5,zoneID=7004,description="The last test for your mount will pit it against one of the great terrors of this land. The garn. Wolves as black as night, and twice the size of a normal wolf, they can tear an orc apart in mere moments. The beasts here wisely fear them. There is a lone garn that calls Nagrand its home. Take your riverbeast, mount up, and bring it down. If the two of you survive, your riverbeast will truly be ready.",starts={{npcID=87242,x=0.622,y=0.362,zoneID=7004}},ends={{npcID=87242,x=0.622,y=0.362,zoneID=7004}},coords={x=0.622,y=0.362,source="quest_giver",zoneID=7004},questType="standard"},
[37080] = {id=37080,name="Glorious Slaughter",level=40,requiredLevel=40,faction="alliance",expansion=5,zoneID=6722,mapID=542,starts={{npcID=86927,x=0.181,y=0.263,mapID=539},{npcID=86927,x=0.772,y=0.342,mapID=542}},ends={{npcID=86927,x=0.181,y=0.263,mapID=539},{npcID=86927,x=0.772,y=0.342,mapID=542}},coords={x=0.181,y=0.263,source="quest_giver",mapID=542},questType="standard"},
[37081] = {id=37081,name="Burning Rage",level=40,requiredLevel=40,faction="horde",expansion=5,zoneID=6755,mapID=550,starts={{npcID=86933,x=0.544,y=0.284,mapID=542},{npcID=86933,x=0.786,y=0.272,mapID=550}},ends={{npcID=86933,x=0.544,y=0.284,mapID=542},{npcID=86933,x=0.786,y=0.272,mapID=550}},coords={x=0.544,y=0.284,source="quest_giver",mapID=550},questType="standard"},
[37082] = {id=37082,name="Call of the Gladiator",level=40,requiredLevel=40,faction="both",expansion=5,zoneID=6755,description="Your merciless rampage has not gone unnoticed, gladiator. So many of your enemies have fallen before your might. It is because of your unrelenting savagery that Imperator Mar'gok himself has requested your presence at the grand Highmaul Coliseum. It is at Highmaul that a battle of epic proportions awaits. Should you heed the call of the gladiator, present this sigil to my brother, Kharg . He is the arena master residing outside of the Coliseum in Nagrand .",starts={{npcID=87247,x=0.556,y=0.14,zoneID=7004},{npcID=87247,x=0.58,y=0.802,zoneID=7078}},ends={{npcID=87311,x=0.33,y=0.384,zoneID=6755}},coords={x=0.556,y=0.14,source="quest_giver",zoneID=7004},questType="pvp"},
[37083] = {id=37083,name="Fight, Kill, Salute!",level=40,requiredLevel=40,faction="both",expansion=5,zoneID=6755,description="The greatest gladiators on Draenor have fought for glory and honor inside the Coliseum. Will you become a legend like Kargath Bladefist or will you be nothing more than bone dust beneath the boots of a more savage gladiator? There is only one way to find out. You must enter the competition and fight! The price of victory is 100 lives! I will admit you without cost once per day, but if you fail and wish to fight again you must pay the price of admission in blood and bone!",starts={{npcID=87311,x=0.33,y=0.384,zoneID=6755}},ends={{npcID=87311,x=0.33,y=0.384,zoneID=6755}},coords={x=0.33,y=0.384,source="quest_giver",zoneID=6755},questType="pvp"},
[37085] = {id=37085,name="Fury of the Clan",level=40,requiredLevel=40,faction="both",expansion=5,zoneID=6722,mapID=542,starts={{npcID=86964,x=0.772,y=0.342,mapID=542}},ends={{npcID=86964,x=0.772,y=0.342,mapID=542}},coords={x=0.772,y=0.342,source="quest_giver",mapID=542},questType="standard"},
[37086] = {id=37086,name="Salvaging the Situation",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=7078,description="Here at the Salvage Yard we inspect any extra material your followers bring back from the field, preserving anything that may be useful. I have an extra pack of material our people brought in that I've yet to go through. Why don't you take it over to the incinerator and see if it contains anything useful?",starts={{npcID=77378,x=0.516,y=0.632,zoneID=7078}},ends={{npcID=77378,x=0.516,y=0.632,zoneID=7078}},coords={x=0.516,y=0.632,source="quest_giver",zoneID=7078},questType="standard"},
[37087] = {id=37087,name="Lost in Transition",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=7078,description=", the storehouse is fully operational and I've seen to it that your supplies are safely stored away and accounted for. Unfortunately, during the rest of my audit I found that we are missing a few crates of surplus material - probably misplaced by one of the porters. If you happen to come across any of the surplus crates while making your rounds, please bring them to me and I'll update our ledger.",starts={{npcID=84857,x=0.47,y=0.592,zoneID=7078}},ends={{npcID=84857,x=0.47,y=0.592,zoneID=7078}},coords={x=0.47,y=0.592,source="quest_giver",zoneID=7078},questType="standard"},
[37088] = {id=37088,name="Tricks of the Trade",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=7078,description="To pass the time, traders have been known to consume beverages of an inspired nature, if you know what I mean. Sometimes, they drink a bit too much. Your trader might have stumbled beyond the gates and passed out under a tree. It's been known to happen from time to time. Luckily, I have a brew that I use to rouse groggy traders. One splash and I find they're more willing to work.",starts={{npcID=87207,x=0.338,y=0.506,zoneID=7078},{npcID=87208,x=0.338,y=0.506,zoneID=7078},{npcID=87209,x=0.338,y=0.506,zoneID=7078},{npcID=87210,x=0.338,y=0.506,zoneID=7078},{npcID=87211,x=0.338,y=0.506,zoneID=7078},{npcID=87212,x=0.338,y=0.506,zoneID=7078},{npcID=87213,x=0.338,y=0.506,zoneID=7078},{npcID=87214,x=0.338,y=0.506,zoneID=7078},{npcID=87215,x=0.338,y=0.506,zoneID=7078},{npcID=87216,x=0.338,y=0.506,zoneID=7078},{npcID=87217,x=0.338,y=0.506,zoneID=7078},{npcID=91071,x=0.338,y=0.506,zoneID=7078}},ends={{npcID=87207,x=0.338,y=0.506,zoneID=7078},{npcID=87208,x=0.338,y=0.506,zoneID=7078},{npcID=87209,x=0.338,y=0.506,zoneID=7078},{npcID=87210,x=0.338,y=0.506,zoneID=7078},{npcID=87211,x=0.338,y=0.506,zoneID=7078},{npcID=87212,x=0.338,y=0.506,zoneID=7078},{npcID=87213,x=0.338,y=0.506,zoneID=7078},{npcID=87214,x=0.338,y=0.506,zoneID=7078},{npcID=87215,x=0.338,y=0.506,zoneID=7078},{npcID=87216,x=0.338,y=0.506,zoneID=7078},{npcID=87217,x=0.338,y=0.506,zoneID=7078},{npcID=91071,x=0.338,y=0.506,zoneID=7078}},coords={x=0.338,y=0.506,source="quest_giver",zoneID=7078},questType="standard"},
[37091] = {id=37091,name="Unconventional Inventions",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=7078,description="The workshop is bustling with the whir of minds and motors. We're coming up with new inventions all the time. Try out today's glorious invention on the workbench behind me.",starts={{npcID=84286,x=0.404,y=0.606,zoneID=7078}},ends={{npcID=84286,x=0.404,y=0.606,zoneID=7078}},coords={x=0.404,y=0.606,source="quest_giver",zoneID=7078},questType="standard"},
[37092] = {id=37092,name="Scraps of Iron",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=7078,mapID=539,description="At the Dwarven Bunker, we can take scraps of Iron Horde armor that you collect and turn them into new gear. It's not the strongest stuff in the world, but it looks good. Get some Iron Horde scraps and come back my way. I'll set you up with a nice tabard for your troubles.",starts={{npcID=77377,x=0.362,y=0.628,mapID=539}},ends={{npcID=77377,x=0.362,y=0.628,mapID=539}},coords={x=0.362,y=0.628,source="quest_giver",mapID=539},questType="standard"},
[37093] = {id=37093,name="Talbuk Training: Great-Tusk",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=7004,description="The talbuk is ready for more training, and for this, we will return to its home in Shadowmoon Valley . One of the great beasts of this land, Great-Tusk , has taken the valley for his own. Pit your beast against him in combat, and if you should survive, it will have greater confidence in its own abilities.",starts={{npcID=87242,x=0.622,y=0.362,zoneID=7004}},ends={{npcID=87242,x=0.622,y=0.362,zoneID=7004}},coords={x=0.622,y=0.362,source="quest_giver",zoneID=7004},questType="standard"},
[37094] = {id=37094,name="Talbuk Training: Rakkiri",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=7004,description="We shall start training the talbuk here, on the icy plains of Frostfire Ridge . We must train it rigorously, or else it may become afraid at the sight of combat, and run. Find the great blood-sucker, Rakkiri , out on the frozen plains, and bring him down astride your talbuk. That will give it a taste for combat.",starts={{npcID=87242,x=0.622,y=0.362,zoneID=7004}},ends={{npcID=87242,x=0.622,y=0.362,zoneID=7004}},coords={x=0.622,y=0.362,source="quest_giver",zoneID=7004},questType="standard"},
[37095] = {id=37095,name="Talbuk Training: Riplash",level=15,requiredLevel=15,faction="horde",expansion=5,zoneID=7004,description="Many beasts will cower in fear at the sight of a mighty predator. In the desolate cliffs of Gorgrond lives one of the most fierce. It will prove your next challenge. Take your beast to the nest of the great Riplash , and see if you cannot emerge victorious.",starts={{npcID=87242,x=0.622,y=0.362,zoneID=7004}},ends={{npcID=87242,x=0.622,y=0.362,zoneID=7004}},coords={x=0.622,y=0.362,source="quest_giver",zoneID=7004},questType="standard"},
[37096] = {id=37096,name="Talbuk Training: Gezz'ran",level=20,requiredLevel=20,faction="horde",expansion=5,zoneID=7004,description="Many of the creatures of Draenor have grown and thrived in a most hostile environment. One of the most cunning is the stalker. Stalkers can blend into their environments, allowing them to sneak in and steal the eggs of nearby prey. See if you and your beast can overcome this natural defense mechanism. You will find a proper predator in Talador .",starts={{npcID=87242,x=0.622,y=0.362,zoneID=7004}},ends={{npcID=87242,x=0.622,y=0.362,zoneID=7004}},coords={x=0.622,y=0.362,source="quest_giver",zoneID=7004},questType="standard"},
[37097] = {id=37097,name="Talbuk Training: Bulbapore",level=30,requiredLevel=30,faction="horde",expansion=5,zoneID=7004,description="In the far south, in the Spires of Arak , the land is being swallowed by the mushrooms that grow underwater, and strange fungal creatures grow uninhibited. Taking on a strange creature, like the fungal giant Bulbapore , will grant you a chance to expose your mount to unfamiliar predators.",starts={{npcID=87242,x=0.622,y=0.362,zoneID=7004}},ends={{npcID=87242,x=0.622,y=0.362,zoneID=7004}},coords={x=0.622,y=0.362,source="quest_giver",zoneID=7004},questType="standard"},
[37098] = {id=37098,name="Talbuk Training: Cruel Ogres",level=35,requiredLevel=35,faction="horde",expansion=5,zoneID=7004,description="Nagrand is home to the mightiest beasts in Draenor, and the ogres of the region have learned to tame them using brutal techniques. There is one ogre in particular, the Gorian Beast-Lasher , that smells of blood and fear. Go on and see how your beast reacts to that.",starts={{npcID=87242,x=0.622,y=0.362,zoneID=7004}},ends={{npcID=87242,x=0.622,y=0.362,zoneID=7004}},coords={x=0.622,y=0.362,source="quest_giver",zoneID=7004},questType="standard"},
