[37103] = {id=37103,name="Talbuk Training: Orc Hunters",level=40,requiredLevel=40,faction="horde",expansion=5,zoneID=7004,description="The Warsong Clan of Nagrand are some of the finest hunters the world of Draenor has ever known. Their beast-killers will aid us in putting this mount to the test. Out in Nagrand , you will find an orc by the name of Karak, the Great Hunter. He has slain more fierce beasts than any other in the clan. Face him astride your mount, and avenge the slain.",starts={{npcID=87242,x=0.622,y=0.362,zoneID=7004}},ends={{npcID=87242,x=0.622,y=0.362,zoneID=7004}},coords={x=0.622,y=0.362,source="quest_giver",zoneID=7004},questType="standard"},
[37104] = {id=37104,name="Talbuk Training: The Garn",level=40,requiredLevel=40,faction="horde",expansion=5,zoneID=7004,description="The last test for your mount will pit it against one of the great terrors of this land. The garn. Wolves as black as night, and twice the size of a normal wolf, they can tear an orc apart in mere moments. The beasts here wisely fear them. There is a lone garn that calls Nagrand its home. Take your talbuk, mount up, and bring it down. If the two of you survive, your talbuk will truly be ready for war.",starts={{npcID=87242,x=0.622,y=0.362,zoneID=7004}},ends={{npcID=87242,x=0.622,y=0.362,zoneID=7004}},coords={x=0.622,y=0.362,source="quest_giver",zoneID=7004},questType="standard"},
[37105] = {id=37105,name="Wolf Training: Cruel Ogres",level=35,requiredLevel=35,faction="horde",expansion=5,zoneID=7004,description="The wolves of this land are the most savage beasts I have seen, and surely do not fear orc nor ogre. Bring him to bear against once of the ogres that you are familiar with. The Gorian Beast-Lasher , the one that smells of blood and fear, see how the wolf reacts to him.",starts={{npcID=87242,x=0.622,y=0.362,zoneID=7004}},ends={{npcID=87242,x=0.622,y=0.362,zoneID=7004}},coords={x=0.622,y=0.362,source="quest_giver",zoneID=7004},questType="standard"},
[37106] = {id=37106,name="Wolf Training: Darkwing Roc",level=38,requiredLevel=38,faction="horde",expansion=5,zoneID=7004,description="The windrocs of Nagrand are a smart predator, often swooping down on unwary prey in packs. If your beast doesn't keep an eye on the sky, it's likely to lose both. Travel to Nagrand and take on the fiercest windroc of the bunch, the Darkwing Roc . It will be a good test for your mount.",starts={{npcID=87242,x=0.622,y=0.362,zoneID=7004}},ends={{npcID=87242,x=0.622,y=0.362,zoneID=7004}},coords={x=0.622,y=0.362,source="quest_giver",zoneID=7004},questType="standard"},
