[37109] = {id=37109,name="Wolf Training: Ironbore",level=40,requiredLevel=40,faction="horde",expansion=5,zoneID=7004,description="You have defeated foes in the sky and on land, and even in the rain. Next, you face beasts beneath your very feet. The rockworm is a cunning predator, striking at prey from below the sands. Many beasts of Nagrand have grown wary of the rumbling of the earth. Take your mount on out to the sandy shores test it against the elder worm Ironbore .",starts={{npcID=87242,x=0.622,y=0.362,zoneID=7004}},ends={{npcID=87242,x=0.622,y=0.362,zoneID=7004}},coords={x=0.622,y=0.362,source="quest_giver",zoneID=7004},questType="standard"},
[37110] = {id=37110,name="Wolf Training: Orc Hunters",level=40,requiredLevel=40,faction="horde",expansion=5,zoneID=7004,description="The Warsong Clan of Nagrand are some of the finest hunters the world of Draenor has ever known. Their beast-killers will aid us in putting this mount to the test. Out in Nagrand , you will find an orc by the name of Karak, the Great Hunter. He has slain more fierce beasts than any other in the clan. Face him astride your mount, and avenge the slain.",starts={{npcID=87242,x=0.622,y=0.362,zoneID=7004}},ends={{npcID=87242,x=0.622,y=0.362,zoneID=7004}},coords={x=0.622,y=0.362,source="quest_giver",zoneID=7004},questType="standard"},
[37111] = {id=37111,name="Wolf Training: The Garn",level=40,requiredLevel=40,faction="horde",expansion=5,zoneID=7004,description="The last test for your mount will pit it against one of the great terrors of this land. The garn. Wolves as black as night, and twice the size of a normal wolf, they can tear an orc apart in mere moments. The beasts here wisely fear them. There is a lone garn that calls Nagrand its home. Take your wolf, mount up, and bring it down. If the two of you survive, your wolf will truly be ready.",starts={{npcID=87242,x=0.622,y=0.362,zoneID=7004}},ends={{npcID=87242,x=0.622,y=0.362,zoneID=7004}},coords={x=0.622,y=0.362,source="quest_giver",zoneID=7004},questType="standard"},
[37113] = {id=37113,name="Thisalee Crow",level=40,requiredLevel=40,faction="alliance",expansion=5,zoneID=6719,mapID=539,questType="standard"},
[37114] = {id=37114,name="Choluna",level=40,requiredLevel=40,faction="alliance",expansion=5,zoneID=6719,mapID=539,questType="standard"},
[37119] = {id=37119,name="The Headhunter's Harvest",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=7078,description="The inn provides a perfect place for adventurers to take a rest between their travels. It's also a great place to talk them into joining our cause over a few rounds of drinks. Go through my selection and let's see if we can obtain a new recruit. I'll give you a little something as a finder's fee for your efforts.",starts={{npcID=84947,x=0.338,y=0.498,zoneID=7078}},ends={{npcID=84947,x=0.338,y=0.498,zoneID=7078}},coords={x=0.338,y=0.498,source="quest_giver",zoneID=7078},questType="standard"},
[37121] = {id=37121,name="The Black Claw",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=7078,description="Behind me, as ye can probably see, is a giant black claw. We found it while we were out hunting new beasts to tame. The animals seem to be quite afraid of it, perhaps the beast it belonged to used to hunt them.",starts={{npcID=86974,x=0.398,y=0.592,zoneID=7078}},ends={{npcID=86974,x=0.398,y=0.592,zoneID=7078}},coords={x=0.398,y=0.592,source="quest_giver",zoneID=7078},questType="standard"},
[37122] = {id=37122,name="Teeth of a Predator",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=7078,description="This necklace dropped off of one of the orc hunters we found while out taming beasts. I've never seen the animals react so strongly to anything!",starts={{npcID=86974,x=0.398,y=0.592,zoneID=7078}},ends={{npcID=86974,x=0.398,y=0.592,zoneID=7078}},coords={x=0.398,y=0.592,source="quest_giver",zoneID=7078},questType="standard"},
[37123] = {id=37123,name="The Black Claw",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=7004,description="You've probably seen this enormous, black claw in our pile of supplies. We found it while we were out hunting new beasts to tame. The animals seem to be quite afraid of it, perhaps the beast it belonged to used to hunt them.",starts={{npcID=87242,x=0.622,y=0.362,zoneID=7004}},ends={{npcID=87242,x=0.622,y=0.362,zoneID=7004}},coords={x=0.622,y=0.362,source="quest_giver",zoneID=7004},questType="standard"},
[37124] = {id=37124,name="Teeth of a Predator",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=7004,description="This necklace dropped off of one of the orc hunters we found while out taming beasts. I've never seen the animals react so strongly to anything.",starts={{npcID=87242,x=0.622,y=0.362,zoneID=7004}},ends={{npcID=87242,x=0.622,y=0.362,zoneID=7004}},coords={x=0.622,y=0.362,source="quest_giver",zoneID=7004},questType="standard"},
[37125] = {id=37125,name="A Rare Find",level=35,requiredLevel=35,faction="both",expansion=5,zoneID=6755,starts={{npcID=87393,x=0.502,y=0.412,zoneID=6755}},ends={{npcID=87393,x=0.502,y=0.412,zoneID=6755}},coords={x=0.502,y=0.412,source="quest_giver",zoneID=6755},questType="standard"},
[37126] = {id=37126,name="An Ogre Without His Sword...",level=40,requiredLevel=40,faction="alliance",expansion=5,zoneID=6755,description="Before I was shipped off to Gorgrond, I was stationed at the Broken Precipice in Nagrand, maintaining order over the unruly dredges. Vizier Dar'gud refused to let me take my favorite sword; he told me \"I wouldn't need it where I was going.\" I want it back, commander, and we are powerful enough together to take it from Dar'gud's bloody corpse. It would mean a great deal to me. An ogre without his sword isn't an ogre at all.",starts={{npcID=86682,x=0.66,y=0.174,zoneID=6755}},ends={{npcID=86682,x=0.66,y=0.174,zoneID=6755}},coords={x=0.66,y=0.174,source="quest_giver",zoneID=6755},questType="standard"},
[37127] = {id=37127,name="The Light of Exodus",level=40,requiredLevel=40,faction="alliance",expansion=5,zoneID=6662,description="My grandfather always told me stories of a powerful crystal made of the Light that would grant power to those who intended to use it for good. He called it the Light of Exodus . I never believed him... until now. Your scouts have found a crystal that sounds just like it. It has been taken by a terrible demon and is being corrupted at the Beacon of Sha'tar in Shattrath. We have to hurry!",starts={{npcID=86934,x=0.335,y=0.407,zoneID=7078}},ends={{npcID=86934,x=0.335,y=0.407,zoneID=7078}},coords={x=0.335,y=0.407,source="quest_giver",zoneID=7078},questType="standard"},
[37128] = {id=37128,name="Settling Grievances",level=40,requiredLevel=40,faction="horde",expansion=5,zoneID=7004,description="Our scouts have found a powerful draenei crystal being corrupted by Ambassador Hellmaw at the Beacon of Sha'tar in Shattrath. The draenei call it the Light of Exodus . Commander, I'd like to accompany you on this mission. Hellmaw slew my brother in Outland... this is personal.",starts={{npcID=86945,x=0.296,y=0.264,zoneID=6662},{npcID=86945,x=0.518,y=0.775,zoneID=6719},{npcID=86945,x=0.481,y=0.726,zoneID=6720},{npcID=86945,x=0.159,y=0.448,zoneID=6723},{npcID=86945,x=0.67,y=0.336,zoneID=6755},{npcID=86945,x=0.468,y=0.493,zoneID=7004}},ends={{npcID=86945,x=0.296,y=0.264,zoneID=6662},{npcID=86945,x=0.518,y=0.775,zoneID=6719},{npcID=86945,x=0.481,y=0.726,zoneID=6720},{npcID=86945,x=0.159,y=0.448,zoneID=6723},{npcID=86945,x=0.67,y=0.336,zoneID=6755},{npcID=86945,x=0.468,y=0.493,zoneID=7004}},coords={x=0.296,y=0.264,source="quest_giver",zoneID=6662},questType="standard"},
[37129] = {id=37129,name="Unwelcome Memories",level=40,requiredLevel=40,faction="alliance",expansion=5,zoneID=6721,description="The botani in the Everbloom Wilds are doin' some sorta foul magic to create these plant... well... zombies, basically. I've seen what happens with armies o' mindless slaves. The Lich King... No matter. We cannae let this escalate any further. I heard o' a particularly nasty one they've just made... let's kill it and see what makes it tick.",starts={{npcID=86927,x=0.181,y=0.263,zoneID=6719},{npcID=86927,x=0.772,y=0.342,zoneID=6722}},ends={{npcID=86927,x=0.181,y=0.263,zoneID=6719},{npcID=86927,x=0.772,y=0.342,zoneID=6722}},coords={x=0.181,y=0.263,source="quest_giver",zoneID=6719},questType="standard"},
[37131] = {id=37131,name="The Dark Lady's Concern",level=40,requiredLevel=40,faction="horde",expansion=5,zoneID=6721,description="The botani in the Everbloom Wilds kill anything foolish enough to wander too close to their blooms and are raising their corpses as mindless soldiers. This is all too reminiscent of the Scourge... and the Dark Lady has taken notice. She has a special mission for us, commander. There is a particularly large infested creature that was recently raised. We are to destroy it and retrieve its remains.",starts={{npcID=86933,x=0.544,y=0.284,zoneID=6722},{npcID=86933,x=0.786,y=0.272,zoneID=6755}},ends={{npcID=86933,x=0.544,y=0.284,zoneID=6722},{npcID=86933,x=0.786,y=0.272,zoneID=6755}},coords={x=0.544,y=0.284,source="quest_giver",zoneID=6722},questType="standard"},
[37140] = {id=37140,name="Leorajh's Prayer Beads",level=40,requiredLevel=40,faction="alliance",expansion=5,zoneID=6722,description="When Leorajh became shaman, pridelord gave prayer beads. Beads help Leorajh hear elements. One day bird-men attacked and took prayer beads. Took them to Skettis. Master, you help Leorajh get prayer beads back?",starts={{npcID=86964,x=0.772,y=0.342,zoneID=6722}},ends={{npcID=86964,x=0.772,y=0.342,zoneID=6722}},coords={x=0.772,y=0.342,source="quest_giver",zoneID=6722},questType="standard"},
[37141] = {id=37141,name="Talonpriest Ishaal",level=30,requiredLevel=30,faction="both",expansion=5,zoneID=6722,mapID=542,starts={{npcID=83959,x=0.464,y=0.466,mapID=542}},ends={{npcID=83959,x=0.464,y=0.466,mapID=542}},coords={x=0.464,y=0.466,source="quest_giver",mapID=542},questType="standard"},
[37142] = {id=37142,name="Ogre Ancestry",level=10,requiredLevel=10,faction="both",expansion=5,zoneID=6874,description="Lunk no like fight, want to learn. You help Lunk learn? Find Lunk ancestors. Lunk have many question. Where Lunk come from? Why Lunk Lunk ? Lunk stay here. Small ogres mean, big ogres meaner.",starts={{npcID=88013,x=0.514,y=0.598,zoneID=7004},{npcID=88013,x=0.342,y=0.502,zoneID=7078}},ends={{npcID=88013,x=0.514,y=0.598,zoneID=7004},{npcID=88013,x=0.342,y=0.502,zoneID=7078}},coords={x=0.514,y=0.598,source="quest_giver",zoneID=7004},questType="dungeon"},
[37144] = {id=37144,name="Talon Guard Kurekk",level=30,requiredLevel=30,faction="both",expansion=5,zoneID=6722,mapID=542,starts={{npcID=80758,x=0.622,y=0.426,mapID=542}},ends={{npcID=80758,x=0.622,y=0.426,mapID=542},{npcID=86475,x=0.64,y=0.37,mapID=542}},coords={x=0.622,y=0.426,source="quest_giver",mapID=542},questType="standard"},
[37145] = {id=37145,name="Budd's Gambit",level=15,requiredLevel=15,faction="both",expansion=5,zoneID=6951,description="Listen, I don't know how I got here, but I have it on good authority that there is an entire island made of shiny things and it's just off of the coast a ways. All we have to do is hop in the water and swim out there, then we can load up our pockets and swim back! I'm just going to rest up and do some stretching before heading out. Don't try and stop me!",starts={{npcID=88017,x=0.508,y=0.606,zoneID=7004},{npcID=88017,x=0.334,y=0.504,zoneID=7078}},ends={{npcID=88017,x=0.508,y=0.606,zoneID=7004},{npcID=88017,x=0.334,y=0.504,zoneID=7078}},coords={x=0.508,y=0.606,source="quest_giver",zoneID=7004},questType="dungeon"},
[37146] = {id=37146,name="Go Fetch",level=20,requiredLevel=20,faction="both",expansion=5,zoneID=6912,description="Now THIS is a savage land worthy of my level of heroism! Oh, hello, I did not see you standing there, staring at me. Perhaps you have noticed that every piece of my armor is an ancient relic, forgotten by time. As you have properly surmised, an adventurer of my stature does not have time to complete the menial requests I am given daily. I must remain here, yelling aloud to the trade district so that others may witness my heroicness and be inspired. Today I require a Nightmare Bell , do find one.",starts={{npcID=88022,x=0.514,y=0.6,zoneID=7004},{npcID=88022,x=0.342,y=0.504,zoneID=7078}},ends={{npcID=88022,x=0.514,y=0.6,zoneID=7004},{npcID=88022,x=0.342,y=0.504,zoneID=7078}},coords={x=0.514,y=0.6,source="quest_giver",zoneID=7004},questType="dungeon"},
[37147] = {id=37147,name="Sky Dancers",level=30,requiredLevel=30,faction="both",expansion=5,zoneID=6988,description="Greetings, , and I thank you for your hospitality. The Shado-pan have sent several warriors to aid against the Iron Horde, however we can. We are few, though, and they are many. The arakkoa in the south are both beautiful and deadly. They appear lighter than air, their attacks a deadly dance that flits from opponent to opponent. The winds are on their side, as the four winds lighten the steps of my own allies. Bring me a sample of their winds, if you are able. It will surely aid us.",starts={{npcID=88023,x=0.508,y=0.606,zoneID=7004},{npcID=88023,x=0.334,y=0.506,zoneID=7078}},ends={{npcID=88023,x=0.508,y=0.606,zoneID=7004},{npcID=88023,x=0.334,y=0.506,zoneID=7078}},coords={x=0.508,y=0.606,source="quest_giver",zoneID=7004},questType="dungeon"},
[37148] = {id=37148,name="Oralius' Adventure",level=35,requiredLevel=35,faction="both",expansion=5,zoneID=7307,description="Me n' Winky, off on adventures again! This is the life, I tell ye. No burning air to breathe, an' plenty of ogres to kill! Oralius rubs his belly.> We did leave a bit of a mess back there in the Blackrock Spire, though. A whole mess of these iron-plated orcs and some proto-dragons marched right on up from the south and took it over. Ol' Winky, he couldn't take the guilt. Went on back by himself he did, to stop them! Or... to JOIN them! Winky, ye two-timing son of an orc. Ye've got to stop him!",starts={{npcID=88024,x=0.598,y=0.244,zoneID=7004},{npcID=88024,x=0.338,y=0.502,zoneID=7078}},ends={{npcID=88024,x=0.598,y=0.244,zoneID=7004},{npcID=88024,x=0.338,y=0.502,zoneID=7078}},coords={x=0.598,y=0.244,source="quest_giver",zoneID=7004},questType="dungeon"},
[37149] = {id=37149,name="The Void-Gate",level=10,requiredLevel=10,faction="both",expansion=5,zoneID=6932,description="My 'master' is an idiot, but you look like you've got some smarts in that oddly-shaped head. Listen up, the Twisting Nether is a chaotic abyss, and things work differently there. I've felt some disturbances, and they don't bode well for any of us. Yes, there are things happening here, in Draenor, that are causing ripples in the nether. No, don't try to wrap your head around how that works, you'll only hurt yourself. It's simple: bring me a Void-Gate Key , and maybe I can stop the bad things.",starts={{npcID=88027,x=0.518,y=0.622,zoneID=7004},{npcID=88027,x=0.338,y=0.502,zoneID=7078}},ends={{npcID=88027,x=0.518,y=0.622,zoneID=7004},{npcID=88027,x=0.338,y=0.502,zoneID=7078}},coords={x=0.518,y=0.622,source="quest_giver",zoneID=7004},questType="dungeon"},
[37150] = {id=37150,name="For the Birds",level=35,requiredLevel=35,faction="both",expansion=5,zoneID=7109,description="Hi! Have you ever held a peachick hatchling? Mylune grabs both of your hands and then stuffs a tiny chirping bird in them.> Isn't it so small and light and downy? Like you're holding a beaky peepy lil' CLOUD! It's so adorable you can't help but hug it and cuddle it and stuff regurgitated food in its teeny-tiny mouth. , the plantfolk in the Everbloom are turning peachicks into monsters before they can grow into beautiful swans. Or whatever they grow into. Please help them!",starts={{npcID=88025,x=0.518,y=0.622,zoneID=7004},{npcID=88025,x=0.338,y=0.502,zoneID=7078}},ends={{npcID=88025,x=0.518,y=0.622,zoneID=7004},{npcID=88025,x=0.338,y=0.502,zoneID=7078}},coords={x=0.518,y=0.622,source="quest_giver",zoneID=7004},questType="dungeon"},
[37151] = {id=37151,name="Cold Steel",level=35,requiredLevel=35,faction="both",expansion=5,zoneID=6984,description="Do you know what I want? What everyone who came through that portal wants. Every soldier running from a world that didn't understand us, didn't need us. I want that world to love us as much as we love it. But we don't really belong there, not anymore. War is part of us, and we can't go back. To everyone back there, we're expendable. The only thing that makes me feel better now is the feel of a cold iron cannon in my hands, pointed at the enemy.",starts={{npcID=88026,x=0.518,y=0.622,zoneID=7004},{npcID=88026,x=0.34,y=0.498,zoneID=7078}},ends={{npcID=88026,x=0.518,y=0.622,zoneID=7004},{npcID=88026,x=0.34,y=0.498,zoneID=7078}},coords={x=0.518,y=0.622,source="quest_giver",zoneID=7004},questType="dungeon"},
[37152] = {id=37152,name="Cro's Revenge",level=40,requiredLevel=40,faction="both",expansion=5,zoneID=6874,description="HA! The fruit vendor was so cunning, but I, Cro Threadstrong , am even MORE cunning. I have come back into the past to defeat the ogre army before that fruit vendor can turn them against me! Bring me the head of a big, strong ogre from the old slag mines, and I will have crushed the fruit vendor before a single apple has even grown! CAN YOU HEAR ME, FRUIT VENDOR? I WILL HAVE MY VICTORY!",starts={{npcID=87991,x=0.598,y=0.26,zoneID=7004},{npcID=87991,x=0.34,y=0.488,zoneID=7078}},ends={{npcID=87991,x=0.598,y=0.26,zoneID=7004},{npcID=87991,x=0.34,y=0.488,zoneID=7078}},coords={x=0.598,y=0.26,source="quest_giver",zoneID=7004},questType="dungeon"},
[37153] = {id=37153,name="Time-Lost Vikings",level=40,requiredLevel=40,faction="both",expansion=5,zoneID=6874,description="Oi, barely made it out of that place! We came through the portal to help, and the next thing you know, we're prisoners in the Bloodmaul Slag Mine. It was brutal! We were shackled for days, and covered in filth. And they took my SHIELD!",starts={{npcID=87992,x=0.598,y=0.26,zoneID=7004},{npcID=87992,x=0.34,y=0.488,zoneID=7078}},ends={{npcID=87992,x=0.598,y=0.26,zoneID=7004},{npcID=87992,x=0.34,y=0.488,zoneID=7078}},coords={x=0.598,y=0.26,source="quest_giver",zoneID=7004},questType="dungeon"},
[37154] = {id=37154,name="The Cure For Death",level=40,requiredLevel=40,faction="both",expansion=5,zoneID=6912,description="Greetings, and my thanks for the warmth of this inn and your hospitality. As you can see, this malady of death continues to plague me. My studies on Azeroth and in Northrend met with little luck, and all of my leads ran dry. I have come to Draenor in the hope of finding something, anything, to go on. My first pilgrimage will be to Auchindoun , a house where souls are put at ease. If you should head there yourself, do let me know if you should happen upon anything of interest.",starts={{npcID=87997,x=0.508,y=0.62,zoneID=7004},{npcID=87997,x=0.34,y=0.488,zoneID=7078}},ends={{npcID=87997,x=0.508,y=0.62,zoneID=7004},{npcID=87997,x=0.34,y=0.488,zoneID=7078}},coords={x=0.508,y=0.62,source="quest_giver",zoneID=7004},questType="dungeon"},
[37155] = {id=37155,name="The Brass Compass",level=40,requiredLevel=40,faction="both",expansion=5,zoneID=6951,description="Greetings, commander. I have come on a mission directly from the captain. Aboard any vessel on Azeroth that's manned by at least one orc, you'll hear sea shanties sung about a device capable of navigating the broad, rough ocean of Draenor. The orcs used it to keep their heading true in the choppiest of storms. Perhaps it's just an old sea tale, but this one chance to find that kind of prize has the captain willing to part with some fine treasure.",starts={{npcID=87995,x=0.598,y=0.26,zoneID=7004},{npcID=87995,x=0.34,y=0.488,zoneID=7078}},ends={{npcID=87995,x=0.598,y=0.26,zoneID=7004},{npcID=87995,x=0.34,y=0.488,zoneID=7078}},coords={x=0.598,y=0.26,source="quest_giver",zoneID=7004},questType="dungeon"},
[37156] = {id=37156,name="The Soulcutter",level=40,requiredLevel=40,faction="both",expansion=5,zoneID=6912,description="Don't look at me! Who do you think you are? You and I are on the same side, you know. The necromancers here, we have to kill them. All of them. Don't you agree? Of course you do, and you can help me accomplish this goal. Find a Soulsever Blade in that hovel where the necromancers have holed up like rats. It has... special properties... that will aid us against the undead.",starts={{npcID=87996,x=0.598,y=0.26,zoneID=7004},{npcID=87996,x=0.34,y=0.488,zoneID=7078}},ends={{npcID=87996,x=0.598,y=0.26,zoneID=7004},{npcID=87996,x=0.34,y=0.488,zoneID=7078}},coords={x=0.598,y=0.26,source="quest_giver",zoneID=7004},questType="dungeon"},
[37157] = {id=37157,name="Feeling A Bit Morose",level=40,requiredLevel=40,faction="both",expansion=5,zoneID=6951,description="So many years of waking up as a spirit, reanimated by some unseen force time and again, has left one with certain desires - the comforting, velvet blackness of death being chief amongst them. One will, however, settle for the lesser prize of a solution capable of removing the scuff marks that the commander's wonderful compatriots left behind in the dining hall in their woefully short stay in Karazhan, whereupon they barely had enough time to irreparably damage the priceless furniture.",starts={{npcID=87994,x=0.508,y=0.62,zoneID=7004},{npcID=87994,x=0.34,y=0.486,zoneID=7078}},ends={{npcID=87994,x=0.508,y=0.62,zoneID=7004},{npcID=87994,x=0.34,y=0.486,zoneID=7078}},coords={x=0.508,y=0.62,source="quest_giver",zoneID=7004},questType="dungeon"},
[37158] = {id=37158,name="Gloriously Incandescent",level=40,requiredLevel=40,faction="both",expansion=5,zoneID=6988,description="I did not come here to fight, I have seen too many die already. I have killed so many with my own hands. I have come to seek the light, and redemption. The arakkoa of this land worship the sun as I do. But they are a violent, isolationist, and decadent race, who seem to derive a different message than my own people. This troubles me. Bring me one of their Sun Crystals . I wish to see this light.",starts={{npcID=87998,x=0.508,y=0.62,zoneID=7004},{npcID=87998,x=0.524,y=0.452,zoneID=7078}},ends={{npcID=87998,x=0.508,y=0.62,zoneID=7004},{npcID=87998,x=0.524,y=0.452,zoneID=7078}},coords={x=0.508,y=0.62,source="quest_giver",zoneID=7004},questType="dungeon"},
[37159] = {id=37159,name="Aviana's Request",level=40,requiredLevel=40,faction="both",expansion=5,zoneID=6988,description="The arakkoa are creatures of the sky, and are thus within the domain of the great Aviana. I have been sent to procure a feather, that we may parley with them through the language of the winds. We will extend an invitation of peace, and a place on the Great Bough. Would you aid us in this quest? The feather must come from an arakkoan of nobility. You will find them in the place known as Skyreach .",starts={{npcID=87999,x=0.598,y=0.26,zoneID=7004},{npcID=87999,x=0.34,y=0.488,zoneID=7078}},ends={{npcID=87999,x=0.598,y=0.26,zoneID=7004},{npcID=87999,x=0.34,y=0.488,zoneID=7078}},coords={x=0.598,y=0.26,source="quest_giver",zoneID=7004},questType="dungeon"},
[37160] = {id=37160,name="Cleaving Time",level=40,requiredLevel=40,faction="both",expansion=5,zoneID=6984,description="I, Gamon , have come through the dark portal to cleave many orc skulls. Yet my weapon has not kept pace with my rage, and is nicked and dull. Find me a new weapon - one that is good for removing Hellscream limbs.",starts={{npcID=88007,x=0.508,y=0.622,zoneID=7004},{npcID=88007,x=0.34,y=0.488,zoneID=7078}},ends={{npcID=88007,x=0.508,y=0.622,zoneID=7004},{npcID=88007,x=0.34,y=0.488,zoneID=7078}},coords={x=0.508,y=0.622,source="quest_giver",zoneID=7004},questType="dungeon"},
[37161] = {id=37161,name="Family Traditions",level=40,requiredLevel=40,faction="both",expansion=5,zoneID=7307,description="He ran off with it! Oh what am I going to do, what am I going to DO? My son, and my knife, they ran off to Blackrock Spire! Well, the knife didn't run, I suppose. That doesn't matter! You've got to get it back! Yes, the knife! You've got to get me back my knife! Go! Now! Stop talking!",starts={{npcID=88000,x=0.508,y=0.62,zoneID=7004},{npcID=88000,x=0.34,y=0.488,zoneID=7078}},ends={{npcID=88000,x=0.508,y=0.62,zoneID=7004},{npcID=88000,x=0.34,y=0.488,zoneID=7078}},coords={x=0.508,y=0.62,source="quest_giver",zoneID=7004},questType="dungeon"},
[37162] = {id=37162,name="Damsels and Dragons",level=40,requiredLevel=40,faction="both",expansion=5,zoneID=7307,description="What ho, squire ! Forgive my lips, as they bear gravest news. Dragons have taken up stinking residence within the hallowed halls of Blackrock Spire! These great wyrms hold a distressed damsel in their scaly graspers. Her name is Zaela, they say. Such a beautiful name! As my squire, it is your Light-given duty to adventure yourself into this spire and procure evidence of these dragons, lest I waste my heroism on a dragonless quest.",starts={{npcID=88001,x=0.598,y=0.26,zoneID=7004},{npcID=88001,x=0.34,y=0.488,zoneID=7078}},ends={{npcID=88001,x=0.598,y=0.26,zoneID=7004},{npcID=88001,x=0.34,y=0.488,zoneID=7078}},coords={x=0.598,y=0.26,source="quest_giver",zoneID=7004},questType="dungeon"},
[37163] = {id=37163,name="Shadowy Secrets",level=40,requiredLevel=40,faction="both",expansion=5,zoneID=6932,description="Though the Lich King has been defeated, we are no closer to unlocking the secrets of the Frozen Throne than we were when jousting pointlessly at the Argent Tournament. Bolvar remains resigned to his fate. Perhaps there is something here, though, that can aid us. Ner'zhul was not always the Lich King, you know. Once, he was a mere orc dabbling in dark powers beyond his comprehension. Find whatever you can of his early studies, and we may have our answers.",starts={{npcID=88002,x=0.598,y=0.26,zoneID=7004},{npcID=88002,x=0.34,y=0.488,zoneID=7078}},ends={{npcID=88002,x=0.598,y=0.26,zoneID=7004},{npcID=88002,x=0.34,y=0.488,zoneID=7078}},coords={x=0.598,y=0.26,source="quest_giver",zoneID=7004},questType="dungeon"},
[37164] = {id=37164,name="The Huntresses",level=40,requiredLevel=40,faction="both",expansion=5,zoneID=6932,description="I do not wish to come out of the shadows, but I mean you no harm. My purpose here is my own secret to keep, I simply needed a warm place to bed down for the night. I can see that you are not the type to be easily swayed into leaving. Very well, perhaps you can aid me in my search. I am looking for someone, it is not important who. All you need to know is that I will reward you for any sign of high elven weaponry that you should come across.",starts={{npcID=88003,x=0.598,y=0.26,zoneID=7004},{npcID=88003,x=0.34,y=0.488,zoneID=7078}},ends={{npcID=88003,x=0.598,y=0.26,zoneID=7004},{npcID=88003,x=0.34,y=0.488,zoneID=7078}},coords={x=0.598,y=0.26,source="quest_giver",zoneID=7004},questType="dungeon"},
[37165] = {id=37165,name="Cenarion Concerns",level=40,requiredLevel=40,faction="both",expansion=5,zoneID=7109,description="Ey mon! De Cenarion Circle sent Zen'kiki out here ta check out dem primals. I woulda been here sooner, but I had a little bit o' trouble gettin' my flight form ta work, mon. De plants in dis place... I can hear dem talk. Dey be yellin' all the time. Angry an' violent yellin'. Would ya bring Zen'kiki back a leaf from dis Everbloom place dey be talkin' about? Maybe I can figure out what dey want.",starts={{npcID=88004,x=0.598,y=0.26,zoneID=7004},{npcID=88004,x=0.34,y=0.488,zoneID=7078}},ends={{npcID=88004,x=0.598,y=0.26,zoneID=7004},{npcID=88004,x=0.34,y=0.488,zoneID=7078}},coords={x=0.598,y=0.26,source="quest_giver",zoneID=7004},questType="dungeon"},
[37166] = {id=37166,name="Titanic Evolution",level=40,requiredLevel=40,faction="both",expansion=5,zoneID=7109,description="Ah, hello! Do not look so surprised! Did I not also brave the dangers of the Mogu'shan Vaults? I am more sturdy than I look! I have learned many things of this wonderful place in history already. Did you know that, just like on our world, the titans once came to this place? At least, that is what I believe! Surely there are signs of the titans' presence here, even now. Should you find one, I would very much like to see it!",starts={{npcID=88005,x=0.588,y=0.268,zoneID=7004},{npcID=88005,x=0.526,y=0.45,zoneID=7078}},ends={{npcID=88005,x=0.588,y=0.268,zoneID=7004},{npcID=88005,x=0.526,y=0.45,zoneID=7078}},coords={x=0.588,y=0.268,source="quest_giver",zoneID=7004},questType="dungeon"},
[37167] = {id=37167,name="And No Maces!",level=40,requiredLevel=40,faction="both",expansion=5,zoneID=8485,description="There are far too many bright-eyed young rogues being sent through this portal and off to war. If I'm going to start up my academy again, some of them have got to survive this little excursion. While I'm here, I figured I might as well use the opportunity to gather some supplies for my grand opening. You can't start a business without plenty of daggers, after all. Grab me a crate of weaponry from the Grimrail Depot , there should be plenty lying around. I'll have something nice for you.",starts={{npcID=88006,x=0.598,y=0.26,zoneID=7004},{npcID=88006,x=0.34,y=0.488,zoneID=7078}},ends={{npcID=88006,x=0.598,y=0.26,zoneID=7004},{npcID=88006,x=0.34,y=0.488,zoneID=7078}},coords={x=0.598,y=0.26,source="quest_giver",zoneID=7004},questType="dungeon"},
[37168] = {id=37168,name="Leorajh, the Enlightened",level=30,requiredLevel=30,faction="both",expansion=5,zoneID=6722,mapID=542,starts={{npcID=87561,x=0.542,y=0.63,mapID=542}},ends={{npcID=87561,x=0.542,y=0.63,mapID=542}},coords={x=0.542,y=0.63,source="quest_giver",mapID=542},questType="standard"},
[37177] = {id=37177,name="Call of the Talon King",level=30,requiredLevel=30,faction="both",expansion=5,zoneID=6722,description="$p, you have done much for my people. I wish to thank you on their behalf. Please visit Veil Terokk when you can.",ends={{npcID=84122,x=0.466,y=0.466,zoneID=6722}},questType="standard"},
[37179] = {id=37179,name="For The Children!",level=40,requiredLevel=40,faction="both",expansion=5,zoneID=7307,description="Wait, wait! Don't attack me! I've changed! Really, I've turned over a new leaf, I promise. I haven't said \"DOOOOOOM!\" in months! All I care about now is saving the poor little orphans of Azeroth, whose parents have been taken by this tragic war. That's why I'm here! Why, with just a single Miniature Iron Star , I could provide clean water and power for all of the orphans of Azeroth! And no one could stop me! So, what do you think, sweetcheeks? Want to help ol' Milhouse save the orphans?",starts={{npcID=88009,x=0.59,y=0.24,zoneID=7004},{npcID=88009,x=0.332,y=0.484,zoneID=7078}},ends={{npcID=88009,x=0.59,y=0.24,zoneID=7004},{npcID=88009,x=0.332,y=0.484,zoneID=7078}},coords={x=0.59,y=0.24,source="quest_giver",zoneID=7004},questType="dungeon"},
[37180] = {id=37180,name="An Ogre Without His Sword...",level=40,requiredLevel=40,faction="horde",expansion=5,zoneID=6755,description="Before I was shipped off to Gorgrond, I was stationed at the Broken Precipice in Nagrand, maintaining order over the unruly dredges. Vizier Dar'gud refused to let me take my favorite sword; he told me \"I wouldn't need it where I was going.\" I want it back, commander, and we are powerful enough together to take it from Dar'gud's bloody corpse. It would mean a great deal to me. An ogre without his sword isn't an ogre at all.",starts={{npcID=86682,x=0.66,y=0.174,zoneID=6755}},ends={{npcID=86682,x=0.66,y=0.174,zoneID=6755}},coords={x=0.66,y=0.174,source="quest_giver",zoneID=6755},questType="standard"},
[37181] = {id=37181,name="Leorajh's Prayer Beads",level=40,requiredLevel=40,faction="horde",expansion=5,zoneID=6722,description="When Leorajh became shaman, pridelord gave prayer beads. Beads help Leorajh hear elements. One day bird-men attacked and took prayer beads. Took them to Skettis. Master, you help Leorajh get prayer beads back?",starts={{npcID=86964,x=0.772,y=0.342,zoneID=6722}},ends={{npcID=86964,x=0.772,y=0.342,zoneID=6722}},coords={x=0.772,y=0.342,source="quest_giver",zoneID=6722},questType="standard"},
[37183] = {id=37183,name="The Critical Path",level=20,requiredLevel=20,faction="alliance",expansion=5,zoneID=6662,description="The auburn forests of Talador sit at a critical crossroads of this continent, commander. The Iron Horde's fleet is already en route from Gorgrond to Shattrath on the west coast. Talador will fall if we don't reinforce them. I took the liberty of dispatching Foreman Eksos , who has already begun construction on an outpost for your forces not far from the Iron Horde landing point. He awaits your orders sir.",starts={{npcID=81492,x=0.378,y=0.368,zoneID=7078}},ends={{npcID=79133,x=0.698,y=0.208,zoneID=6662}},coords={x=0.378,y=0.368,source="quest_giver",zoneID=7078},questType="standard"},
[37184] = {id=37184,name="Taking the Fight to Nagrand",level=35,requiredLevel=35,faction="alliance",expansion=5,zoneID=6755,description="Commander, good to see you. With the fall of the rangari base at Telaar, Vindicator Yrel, recommended that we establish a new foothold in Nagrand . I've taken the liberty of dispatching some of our men and supplies. Rangari D'kaan's already reporting that the outpost is nearly complete. He asked me to let you know they are ready for you. A gryphon is waiting to catch you up with the latest caravan shipment whenever you're ready, .",starts={{npcID=81492,x=0.378,y=0.368,zoneID=7078}},ends={{npcID=79263,x=0.864,y=0.662,zoneID=6755}},coords={x=0.378,y=0.368,source="quest_giver",zoneID=7078},questType="standard"},
[37191] = {id=37191,name="Sanketsu, The Burning Blade",level=40,requiredLevel=40,faction="alliance",expansion=5,zoneID=7078,description="The blade is searing hot to the touch. The jewel on its hilt stares at you, as if daring you to claim it. Perhaps someone at your garrison would be interested in seeing this weapon.",starts={{npcID=87764,x=0.694,y=0.058,zoneID=6662}},ends={{npcID=84268,x=0.292,y=0.346,zoneID=7078}},coords={x=0.694,y=0.058,source="quest_giver",zoneID=6662},questType="standard"},
[37192] = {id=37192,name="Sanketsu, The Burning Blade",level=40,requiredLevel=40,faction="horde",expansion=5,zoneID=7004,description="The blade is searing hot to the touch. The jewel on its hilt stares at you, as if daring you to claim it. Perhaps someone at your garrison would be interested in seeing this weapon.",starts={{npcID=87764,x=0.694,y=0.058,zoneID=6662}},ends={{npcID=79740,x=0.538,y=0.542,zoneID=7004}},coords={x=0.694,y=0.058,source="quest_giver",zoneID=6662},questType="standard"},
[37201] = {id=37201,name="Cymre Brightblade",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6721,description="I found some interesting artifacts on a recent dig, and I'd love to put them through their paces to see how they would have performed in their native cultures. Don't suppose you have anything small and furry that can put up a fight?",starts={{npcID=83837,x=0.51,y=0.706,zoneID=6721}},ends={{npcID=83837,x=0.51,y=0.706,zoneID=6721}},coords={x=0.51,y=0.706,source="quest_giver",zoneID=6721},questType="standard"},
[37202] = {id=37202,name="Hemet Nesingwary Visitor Tracking Event",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6755,mapID=550,questType="standard"},
[37203] = {id=37203,name="Ashlei",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6719,description="I don't really like when my pets fight, but I love making them feel better when they're done.",starts={{npcID=87124,x=0.5,y=0.312,zoneID=6719}},ends={{npcID=87124,x=0.5,y=0.312,zoneID=6719}},coords={x=0.5,y=0.312,source="quest_giver",zoneID=6719},questType="standard"},
[37204] = {id=37204,name="Rekindling an Old Flame",level=40,requiredLevel=40,faction="both",expansion=5,zoneID=6720,description="I am dying, . My flame, it smolders... soon my light will flicker and fade into nothing. You mustn't allow this. Retrieve for me the Essence of Flame. Allow me to live another day and I will burn every breaker to ash, I swear it. I will take vengeance for my brothers and sisters.",starts={{npcID=87971,x=0.748,y=0.3,zoneID=6720}},ends={{npcID=87971,x=0.748,y=0.3,zoneID=6720}},coords={x=0.748,y=0.3,source="quest_giver",zoneID=6720},questType="standard"},
[37205] = {id=37205,name="Gargra",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6720,description="Do you wish to offer challenge? My wolves must train to become strong.",starts={{npcID=87122,x=0.686,y=0.646,zoneID=6720}},ends={{npcID=87122,x=0.686,y=0.646,zoneID=6720}},coords={x=0.686,y=0.646,source="quest_giver",zoneID=6720},questType="standard"},
[37206] = {id=37206,name="Tarr the Terrible",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6755,description="Tarr is the true warlord! Bring your army to fight and I show you.",starts={{npcID=87110,x=0.562,y=0.098,zoneID=6755}},ends={{npcID=87110,x=0.562,y=0.098,zoneID=6755}},coords={x=0.562,y=0.098,source="quest_giver",zoneID=6755},questType="standard"},
[37207] = {id=37207,name="Vesharr",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6722,description="I had a vision with one who had mastered pets came to challenge me. Has the vision finally come to pass?",starts={{npcID=87123,x=0.464,y=0.452,zoneID=6722}},ends={{npcID=87123,x=0.464,y=0.452,zoneID=6722}},coords={x=0.464,y=0.452,source="quest_giver",zoneID=6722},questType="standard"},
[37208] = {id=37208,name="Taralune",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6662,description="I strive to teach through non-lethal pet battle. Are you willing to learn?",starts={{npcID=87125,x=0.49,y=0.804,zoneID=6662}},ends={{npcID=87125,x=0.49,y=0.804,zoneID=6662}},coords={x=0.49,y=0.804,source="quest_giver",zoneID=6662},questType="standard"},
[37209] = {id=37209,name="Cold Steel Part II",level=35,requiredLevel=35,faction="both",expansion=5,zoneID=6984,description="Hey, you. I wanted to thank you for what you did for me. The feel of that cannon in my hands is all the therapy I'll ever need. But now... ...I'm all out of bullets. Guess I'll just sit here and wait to die.",starts={{npcID=88026,x=0.518,y=0.622,zoneID=7004},{npcID=88026,x=0.34,y=0.498,zoneID=7078}},ends={{npcID=88026,x=0.518,y=0.622,zoneID=7004},{npcID=88026,x=0.34,y=0.498,zoneID=7078}},coords={x=0.518,y=0.622,source="quest_giver",zoneID=7004},questType="dungeon"},
[37210] = {id=37210,name="Aogexon's Fang",level=35,requiredLevel=35,faction="both",expansion=5,zoneID=6755,starts={{npcID=87706,x=0.502,y=0.412,zoneID=6755}},ends={{npcID=87706,x=0.502,y=0.412,zoneID=6755}},coords={x=0.502,y=0.412,source="quest_giver",zoneID=6755},questType="standard"},
[37211] = {id=37211,name="Bergruu's Horn",level=35,requiredLevel=35,faction="both",expansion=5,zoneID=6755,starts={{npcID=87706,x=0.502,y=0.412,zoneID=6755}},ends={{npcID=87706,x=0.502,y=0.412,zoneID=6755}},coords={x=0.502,y=0.412,source="quest_giver",zoneID=6755},questType="standard"},
