[37318] = {id=37318,name="The Dead Do Not Forget...",level=35,requiredLevel=35,faction="both",expansion=5,zoneID=6723,description="Many years ago my family and I were slain in this very spot. The saberon you see around you are descended from the tribe that murdered my village. Long have I waited, here in this forgotten place, to see justice brought to the saberon for their crimes. The Snarlpaw chief is a boneseer, a saberon who divines the future using the remains of the dead. Collect the ancient skulls of the Snarlpaw ancestors and place them in the boneseer's cauldron . Let their own bones fill their cauldron for once!",starts={{npcID=88500,x=0.794,y=0.302,zoneID=6755}},ends={{npcID=237705,x=0.797,y=0.302,zoneID=6755}},coords={x=0.794,y=0.302,source="quest_giver",zoneID=6755},questType="standard"},
[37319] = {id=37319,name="Jewelcrafting Special Order: Wedding Bands",level=10,requiredLevel=10,faction="both",expansion=5,zoneID=7004,description="We've been asked to craft a pair of wedding bands. The clients requested that they be made by you.",starts={{npcID=88545,x=0.506,y=0.576,zoneID=7078},{npcID=88546,x=0.536,y=0.366,zoneID=7004}},ends={{npcID=88545,x=0.506,y=0.576,zoneID=7078},{npcID=88546,x=0.536,y=0.366,zoneID=7004}},coords={x=0.506,y=0.576,source="quest_giver",zoneID=7078},questType="standard"},
[37320] = {id=37320,name="Jewelcrafting Special Order: A Fine Choker",level=10,requiredLevel=10,faction="both",expansion=5,zoneID=7004,description="We have a request for a fine necklace. The client wants to give it to an old enemy, to end the conflict. She didn't specify a design, but I think I heard her mumbling under her breath about a choker. Oh, and she asks that the chain be \"extra sturdy\".",starts={{npcID=88545,x=0.506,y=0.576,zoneID=7078},{npcID=88546,x=0.536,y=0.366,zoneID=7004}},ends={{npcID=88545,x=0.506,y=0.576,zoneID=7078},{npcID=88546,x=0.536,y=0.366,zoneID=7004}},coords={x=0.506,y=0.576,source="quest_giver",zoneID=7078},questType="standard"},
[37321] = {id=37321,name="Jewelcrafting Special Order: A Yellow Brighter Than Gold",level=10,requiredLevel=10,faction="both",expansion=5,zoneID=7004,description="We've been commissioned to make a gold bracelet, set with a taladite crystal \"even brighter than gold\". I can handle the metal work, but the crystal isn't something I can do.",starts={{npcID=88545,x=0.506,y=0.576,zoneID=7078},{npcID=88546,x=0.536,y=0.366,zoneID=7004}},ends={{npcID=88545,x=0.506,y=0.576,zoneID=7078},{npcID=88546,x=0.536,y=0.366,zoneID=7004}},coords={x=0.506,y=0.576,source="quest_giver",zoneID=7078},questType="standard"},
[37322] = {id=37322,name="The Prophet's Final Message",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=6719,mapID=539,description="This unassuming iridescent crystal contains some of the final thoughts of Great Prophet Velen, created sometime in the hours before he confronted Ner'zhul. Deliver the crystal to Prophet Velen's Memorial beneath the Coliseum of Light near Karabor to hear his final message.",ends={{npcID=237790,x=0.738,y=0.558,mapID=539}},questType="standard"},
[37323] = {id=37323,name="Jewelcrafting Special Order: Blue the Shade of Sky and Sea",level=10,requiredLevel=10,faction="both",expansion=5,zoneID=7004,description="The client wants a pair of silver earrings, set with blue crystals to match her eyes. The metal work is simple enough, but I don't know how to create such a shade of taladite.",starts={{npcID=88545,x=0.506,y=0.576,zoneID=7078},{npcID=88546,x=0.536,y=0.366,zoneID=7004}},ends={{npcID=88545,x=0.506,y=0.576,zoneID=7078},{npcID=88546,x=0.536,y=0.366,zoneID=7004}},coords={x=0.506,y=0.576,source="quest_giver",zoneID=7078},questType="standard"},
[37324] = {id=37324,name="Out of Stock: Blackrock Ore",level=10,requiredLevel=10,faction="both",expansion=5,zoneID=7004,description="Our latest bracelet design is selling like mad, but we are completely out of the blackrock to make them.",questType="standard"},
[37325] = {id=37325,name="Out of Stock: True Iron Ore",level=10,requiredLevel=10,faction="both",expansion=5,zoneID=7004,description="It seems our little boutique is gaining a reputation. We use true iron in all our designs, and guess what: we're out!",questType="standard"},
[37326] = {id=37326,name="Befriending the Locals",level=30,requiredLevel=30,faction="horde",expansion=5,zoneID=6722,description="We need allies desperately if we want a chance at surviving until tomorrow. We've made contact with one of the outcast arakkoa, but he refused to discuss alliances without speaking to you first. He called himself Dusk-Seer Irrizar. You should speak with him, commander. You can find him just southwest of Veil Terokk.",starts={{npcID=81920,x=0.402,y=0.434,zoneID=6722}},ends={{npcID=83463,x=0.438,y=0.488,zoneID=6722}},coords={x=0.402,y=0.434,source="quest_giver",zoneID=6722},questType="standard"},
[37327] = {id=37327,name="Befriending the Locals",level=30,requiredLevel=30,faction="alliance",expansion=5,zoneID=6722,description="Commander, I believe it best for the safety of this outpost if we secure an ally. We've made contact with one of the outcast arakkoa, but he refused to make any promises of alliance without speaking to you first. He called himself Dusk-Seer Irrizar. Could you go speak with him, commander? You can find him just southwest of Veil Terokk.",starts={{npcID=81929,x=0.398,y=0.608,zoneID=6722}},ends={{npcID=83463,x=0.438,y=0.488,zoneID=6722}},coords={x=0.398,y=0.608,source="quest_giver",zoneID=6722},questType="standard"},
[37328] = {id=37328,name="Not Here, Not Now",level=30,requiredLevel=30,faction="horde",expansion=5,zoneID=6722,description="I will travel to your people to make arrangements soon. For now, begone. Leave me in peace.",starts={{npcID=83463,x=0.438,y=0.488,zoneID=6722}},ends={{npcID=81920,x=0.402,y=0.434,zoneID=6722}},coords={x=0.438,y=0.488,source="quest_giver",zoneID=6722},questType="standard"},
[37329] = {id=37329,name="Not Here, Not Now",level=30,requiredLevel=30,faction="alliance",expansion=5,zoneID=6722,description="I will travel to your people to make arrangements soon. For now, begone. Leave me in peace.",starts={{npcID=83463,x=0.438,y=0.488,zoneID=6722}},ends={{npcID=81929,x=0.398,y=0.608,zoneID=6722}},coords={x=0.438,y=0.488,source="quest_giver",zoneID=6722},questType="standard"},
[37330] = {id=37330,name="Not Here, Not Now",level=30,requiredLevel=30,faction="horde",expansion=5,zoneID=6722,description="I will travel to your people to make arrangements soon. For now, begone. Leave me in peace.",starts={{npcID=83463,x=0.438,y=0.488,zoneID=6722}},ends={{npcID=81920,x=0.402,y=0.434,zoneID=6722}},coords={x=0.438,y=0.488,source="quest_giver",zoneID=6722},questType="standard"},
[37331] = {id=37331,name="Not Here, Not Now",level=30,requiredLevel=30,faction="alliance",expansion=5,zoneID=6722,description="I will travel to your people to make arrangements soon. For now, begone. Leave me in peace.",starts={{npcID=83463,x=0.438,y=0.488,zoneID=6722}},ends={{npcID=81929,x=0.398,y=0.608,zoneID=6722}},coords={x=0.438,y=0.488,source="quest_giver",zoneID=6722},questType="standard"},
[37332] = {id=37332,name="Fungal Bundle",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=6719,description="The umbraspore giant you killed seemed immune to the volatile spores in the area. Perhaps the odd growths you found all over its body contribute to its immunity. You grab a big, disgusting fungal lump in order to give it to the rangari for study.",ends={{npcID=81324,x=0.566,y=0.234,zoneID=6719}},questType="standard"},
[37333] = {id=37333,name="LFGDungeons - Draenor - Heroic Random - 1st",level=10,requiredLevel=10,faction="none",expansion=5,questType="standard"},
[37335] = {id=37335,name="LFGDungeons - Draenor - Normal Random - 1st",level=10,requiredLevel=10,faction="none",expansion=5,questType="standard"},
[37416] = {id=37416,name="Feast of the Spires",level=30,requiredLevel=30,faction="horde",expansion=5,zoneID=6722,mapID=542,description="Boss-mon, I prepared a great feast for you right over dere. You should be havin' a bite or two before you be goin' out for da day. Trust me, you will feel much betta if you do!",questType="standard"},
[37417] = {id=37417,name="Feast of the Spires",level=30,requiredLevel=30,faction="alliance",expansion=5,zoneID=6722,mapID=542,description="Commander, I prepared a great feast for ye right over there. You should be have a bite o' two before you be go out fer the day. Trust me, it's good fer ya!",questType="standard"},
