[37467] = {id=37467,name="The Walk of Shame",level=10,requiredLevel=10,faction="both",expansion=5,zoneID=7334,description="The echoes of Nar'thalas still haunt me, and I cannot bear the pain of this accursed town any longer. I may still be able to get you closer to the Tidestone, however. We will need to skirt around the edge of town. Follow me.",starts={{npcID=88867,x=0.518,y=0.442,zoneID=7334}},ends={{npcID=88890,x=0.542,y=0.42,zoneID=7334}},coords={x=0.518,y=0.442,source="quest_giver",zoneID=7334},questType="standard"},
[37468] = {id=37468,name="Into the Academy",level=10,requiredLevel=10,faction="both",expansion=5,zoneID=7334,description="The sunken structure on the other side of this bridge was once called Nar'thalas Academy: the center of magical studies in all of Azeroth. You should have seen her in her full splendor. The Tidestone should be locked up within. I dare not enter, but you - my champion - you go with my blessing.",questType="standard"},
[37469] = {id=37469,name="The Tidestone: Shattered",level=10,requiredLevel=10,faction="both",expansion=5,zoneID=7334,description="I suppose you can go in, then. The shattered pieces of the Tidestone of Golganneth are contained within the academy's eastern wing. Even as curator, I cannot attest to their condition, as I have not been in to inspect them in many millennia. Oh, young ? Please do not touch anything.",questType="standard"},
[37470] = {id=37470,name="The Head of the Snake",level=10,requiredLevel=10,faction="both",expansion=5,zoneID=7334,description="Those naga have the Tidestone shards, . They will soon be dragging them into their watery holes, away from our reach. It would be wise to take out their leaders before that happens.",starts={{npcID=89009,x=0.578,y=0.434,zoneID=7334}},ends={{npcID=91403,x=0.616,y=0.41,zoneID=7334}},coords={x=0.578,y=0.434,source="quest_giver",zoneID=7334},questType="standard"},
[37474] = {id=37474,name="Basics First",level=1,requiredLevel=1,faction="none",expansion=5,questType="standard"},
