[37563] = {id=37563,name="The Frostwolves Stand Ready",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=6720,description="Though we have lost much this day, the Frostwolves stand ready to uphold our pact with your people. To honor this agreement, some of my clan have asked to join your ranks and fight alongside your forces. Our numbers are strained so I ask that you chose only one. Speak with me when you have made your decision.",starts={{npcID=76730,x=0.762,y=0.55,zoneID=6720},{npcID=88147,x=0.782,y=0.55,zoneID=6720}},ends={{npcID=76730,x=0.762,y=0.55,zoneID=6720},{npcID=88147,x=0.782,y=0.55,zoneID=6720}},coords={x=0.762,y=0.55,source="quest_giver",zoneID=6720},questType="standard"},
[37565] = {id=37565,name="The Right Weapon for the Job",level=10,requiredLevel=10,faction="both",expansion=5,zoneID=7334,questType="standard"},
[37566] = {id=37566,name="The Prince is Going Down",level=10,requiredLevel=10,faction="both",expansion=5,zoneID=7334,description="! I knew you'd come. Quick, let me out of here and we'll take this giant down.",starts={{npcID=89051,x=0.534,y=0.63,zoneID=7334}},ends={{npcID=109334,x=0.52,y=0.618,zoneID=7334}},coords={x=0.534,y=0.63,source="quest_giver",zoneID=7334},questType="standard"},
[37568] = {id=37568,name="Your First Alchemy Work Order",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=7004,description="Now that the alchemy lab is complete, we can start producing alchemical catalysts for you. When you have the ingredients, please speak with my assistant to start the first work order.",starts={{npcID=79813,x=0.536,y=0.366,zoneID=7004}},ends={{npcID=79814,x=0.534,y=0.364,zoneID=7004}},coords={x=0.536,y=0.366,source="quest_giver",zoneID=7004},questType="standard"},
[37569] = {id=37569,name="Your First Blacksmithing Work Order",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=7004,description="Now that the forge is complete, we can start producing truesteel ingots for you. When you have the ingredients, please speak with my assistant to start the first work order.",starts={{npcID=79867,x=0.48,y=0.322,zoneID=7004}},ends={{npcID=79817,x=0.534,y=0.364,zoneID=7004}},coords={x=0.48,y=0.322,source="quest_giver",zoneID=7004},questType="standard"},
[37570] = {id=37570,name="Your First Enchanting Work Order",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=7004,description="Now that the enchanter's study is complete, we can start producing draenic dust for you. When you have the ingredients, please speak with my assistant to start the first work order.",starts={{npcID=79821,x=0.48,y=0.326,zoneID=7004}},ends={{npcID=79820,x=0.48,y=0.326,zoneID=7004}},coords={x=0.48,y=0.326,source="quest_giver",zoneID=7004},questType="standard"},
[37571] = {id=37571,name="Your First Engineering Work Order",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=7004,description="Now that the engineering works is complete, we can start producing gearspring parts for you. When you have the ingredients, please speak with my assistant to start the first work order.",starts={{npcID=79826,x=0.536,y=0.366,zoneID=7004}},ends={{npcID=86696,x=0.536,y=0.366,zoneID=7004}},coords={x=0.536,y=0.366,source="quest_giver",zoneID=7004},questType="standard"},
[37572] = {id=37572,name="Your First Inscription Work Order",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=7004,description="Now that the scribe's quarters are complete, we can start producing war paints for you. When you have the ingredients, please speak with my assistant to start the first work order.",starts={{npcID=79829,x=0.53,y=0.364,zoneID=7004}},ends={{npcID=79831,x=0.538,y=0.366,zoneID=7004}},coords={x=0.53,y=0.364,source="quest_giver",zoneID=7004},questType="standard"},
[37573] = {id=37573,name="Your First Jewelcrafting Work Order",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=7004,description="Now that the gem boutique is complete, we can start producing taladite crystals for you. When you have the ingredients, please speak with my assistant to start the first work order.",starts={{npcID=79832,x=0.478,y=0.32,zoneID=7004}},ends={{npcID=79830,x=0.478,y=0.322,zoneID=7004}},coords={x=0.478,y=0.32,source="quest_giver",zoneID=7004},questType="standard"},
[37574] = {id=37574,name="Your First Leatherworking Work Order",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=7004,description="Now that the tannery is complete, we can start producing burnished leather for you. When you have the ingredients, please speak with my assistant to start the first work order.",starts={{npcID=79834,x=0.53,y=0.366,zoneID=7004}},ends={{npcID=79833,x=0.538,y=0.366,zoneID=7004}},coords={x=0.53,y=0.366,source="quest_giver",zoneID=7004},questType="standard"},
[37575] = {id=37575,name="Your First Tailoring Work Order",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=7004,description="Now that the tailoring emporium is complete, we can start producing hexweave cloth for you. When you have the ingredients, please speak with my assistant to start the first work order.",starts={{npcID=79864,x=0.532,y=0.364,zoneID=7004}},ends={{npcID=79863,x=0.534,y=0.364,zoneID=7004}},coords={x=0.532,y=0.364,source="quest_giver",zoneID=7004},questType="standard"},
