[37678] = {id=37678,name="Hit the Books",level=10,requiredLevel=10,faction="both",expansion=5,zoneID=7334,description="One problem with maintaining such a large arcane library is that the books often pick up an errant enchantment and start darting about on their own. These overmagicked books need to be destroyed before they cause any further damage. If you encounter any of these exasperating essays, please put them down. Quietly.",questType="standard"},
[37681] = {id=37681,name="Short-Supply Reward",level=1,requiredLevel=1,faction="both",expansion=5,questType="standard"},
[37682] = {id=37682,name="Short-Supply Reward",level=1,requiredLevel=1,faction="both",expansion=5,questType="standard"},
