[38142] = {id=38142,name="Archdruid of the Claw",level=10,requiredLevel=10,faction="both",expansion=5,zoneID=7558,description="Near the southern edge of our forest you will find Sleeper's Barrow. There, Archdruid Koda Steelclaw and her dedicated disciples carry out their sacred duty to observe the Emerald Dream. Find disciple Rylissa Bearsong in Steelclaw Vale and notify her of the crisis in the Grove of Cenarius.",starts={{npcID=91651,x=0.518,y=0.64,zoneID=7558},{npcID=94179,x=0.544,y=0.734,zoneID=7558}},ends={{npcID=73426,x=0.49,y=0.822,zoneID=7558}},coords={x=0.518,y=0.64,source="quest_giver",zoneID=7558},questType="standard"},
[38143] = {id=38143,name="Awakening the Archdruid",level=10,requiredLevel=10,faction="both",expansion=5,zoneID=7558,description="Now, we must focus our efforts on waking Archdruid Steelclaw. She and our druid brethren slumber in the barrow dens to the south. With the furbolgs quelled, we can pass safely to the entrance. Go and awaken the Archdruid. I pray to Elune that we are not too late.",questType="standard"},
[38144] = {id=38144,name="The Demons Below",level=10,requiredLevel=10,faction="both",expansion=5,zoneID=7558,description="Something, someone, intended us to never awaken. I sense their presence is still here in the barrow. My body is weak from deep slumber. If you would aid us, clear our barrow of any enemies.",questType="standard"},
[38145] = {id=38145,name="Out of the Dream",level=10,requiredLevel=10,faction="both",expansion=5,zoneID=7558,description="Malfurion Stormrage... A name I have not heard in centuries. He was teacher to many of us. If he seeks my audience, I cannot refuse. I will go to the Grove of Cenarius, but first, we must awaken the rest of my clan. They slumber with no way of waking. A mysterious force of great power is at work against us. I am still too weak from my hibernation. Please, stranger, go and free them from their dreams.",questType="standard"},
[38146] = {id=38146,name="The Chieftain's Beads",level=10,requiredLevel=10,faction="both",expansion=5,zoneID=7558,description="The ceremonial beads, decorated with shells and feathers, are worn by the clan's chieftain. Perhaps Elder Sookh would be interested in seeing these.",ends={{npcID=93890,x=0.484,y=0.846,zoneID=7558}},questType="standard"},
[38147] = {id=38147,name="Entangled Dreams",level=10,requiredLevel=10,faction="both",expansion=5,zoneID=7558,description="I sense powerful magic emanating from deep within the barrow. Whatever is down there weaves a powerful spell, entangling us within our dreams. I am still too weak, but your skills are quite impressive, hero. I can see why Malfurion puts his trust in you. Go and eliminate the source of this magic.",questType="standard"},
[38148] = {id=38148,name="Return to the Grove",level=10,requiredLevel=10,faction="both",expansion=5,zoneID=7558,description="Now that my clan is assembled, we shall return to the Grove of Cenarius. Speak to Malfurion when you arrive. We will find out the cause of Cenarius' illness.",questType="standard"},
