[38296] = {id=38296,name="Herbs Galore",level=10,requiredLevel=10,faction="both",expansion=5,zoneID=6722,starts={{npcID=91404,x=0.344,y=0.33,zoneID=7078}},ends={{npcID=91404,x=0.344,y=0.33,zoneID=7078},{npcID=91031,x=0.402,y=0.56,zoneID=7004}},coords={x=0.344,y=0.33,source="quest_giver",zoneID=7078},questType="standard"},
[38297] = {id=38297,name="Herbs Galore",level=10,requiredLevel=10,faction="none",expansion=5,zoneID=7004,mapID=525,questType="standard"},
[38299] = {id=38299,name="Critters of Draenor",level=1,requiredLevel=1,faction="alliance",expansion=5,zoneID=7078,description="I love collecting pets, and I've picked up a few unusual pets here in Draenor. What would you say to a battle? If you can defeat my humble team, I think we'll both learn a few new tricks.",starts={{npcID=90675,x=0.29,y=0.404,zoneID=7078},{npcID=91014,x=0.29,y=0.404,zoneID=7078},{npcID=91015,x=0.29,y=0.404,zoneID=7078},{npcID=91016,x=0.29,y=0.404,zoneID=7078},{npcID=91017,x=0.29,y=0.404,zoneID=7078}},ends={{npcID=90675,x=0.29,y=0.404,zoneID=7078},{npcID=91014,x=0.29,y=0.404,zoneID=7078},{npcID=91015,x=0.29,y=0.404,zoneID=7078},{npcID=91016,x=0.29,y=0.404,zoneID=7078},{npcID=91017,x=0.29,y=0.404,zoneID=7078}},coords={x=0.29,y=0.404,source="quest_giver",zoneID=7078},questType="standard"},
[38300] = {id=38300,name="Critters of Draenor",level=1,requiredLevel=1,faction="horde",expansion=5,zoneID=7004,description="I love collecting pets, and I've picked up a few unusual pets here in Draenor. What would you say to a battle? If you can defeat my humble team, I think we'll both learn a few new tricks.",starts={{npcID=91026,x=0.336,y=0.424,zoneID=7004},{npcID=91361,x=0.336,y=0.424,zoneID=7004},{npcID=91362,x=0.336,y=0.424,zoneID=7004},{npcID=91363,x=0.336,y=0.424,zoneID=7004},{npcID=91364,x=0.336,y=0.424,zoneID=7004}},ends={{npcID=91026,x=0.336,y=0.424,zoneID=7004},{npcID=91361,x=0.336,y=0.424,zoneID=7004},{npcID=91362,x=0.336,y=0.424,zoneID=7004},{npcID=91363,x=0.336,y=0.424,zoneID=7004},{npcID=91364,x=0.336,y=0.424,zoneID=7004}},coords={x=0.336,y=0.424,source="quest_giver",zoneID=7004},questType="standard"},
[38304] = {id=38304,name="Val'sharah",level=10,requiredLevel=10,faction="none",expansion=5,zoneID=7558,mapID=641,description="Go through the portal in Dalaran and meet Malfurion Stormrage in Val'Sharah .",questType="standard"},
[38305] = {id=38305,name="Cenarius, Keeper of the Grove",level=10,requiredLevel=10,faction="none",expansion=5,zoneID=7558,mapID=641,description="Greetings, hero. Welcome to Val'sharah . It has been an age since I have set foot in these precious woods. Too long... Our work here is simple. We must call upon my mentor, Cenarius, and learn where he safeguards the Tears of Elune. With them, you will be one step closer to sealing Sargeras' Tomb and thwarting the Legion. You have many treacherous tasks in front of you. Consider your visit here a brief respite. Come, this will not take long.",questType="standard"},
[38307] = {id=38307,name="The Warchief Beckons",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=7502,description="Greetings, $p. I am here on behalf of Lady Sylvanas Windrunner . I should hope you recognize the name. Read it and follow me. You can read, can't you?",starts={{npcID=96683,x=0.612,y=0.088,zoneID=14}},ends={{npcID=96683,x=0.612,y=0.088,zoneID=14}},coords={x=0.612,y=0.088,source="quest_giver",zoneID=14},questType="standard"},
[38308] = {id=38308,name="Eyes in the Overlook",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=7541,description="Alliance personnel from the Skyfire were spotted parachuting into Blackbeak Overlook. I was unable to confirm numbers or positions during my flyover, but I did see parachutes tangled in treetops and a LOT of ravenbears on the ground. If anyone is up there, they must be laying low and keeping an eye on us. I have posted a rider at the top of the overlook to keep watch while I press forward into Stormheim . - Liza Cullen, Dread-Rider - 1st Wing",starts={{npcID=244453,x=0.367,y=0.311,zoneID=7541}},coords={x=0.367,y=0.311,source="quest_giver",zoneID=7541},questType="standard"},
[38312] = {id=38312,name="A Grapple a Day",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=7541,description="So these trials are what will get us the Aegis, and the next one is on the top of that mountain? That may prove problematic. The only way I see up the mountain is through that vrykul city, and the gates are shut tight. We should be able to grapple over, though. If you don't have a launcher, I managed to wrangle a spare from one of these vrykul. I'll scout ahead and see if I can find a good spot to get in.",starts={{npcID=91222,x=0.374,y=0.638,zoneID=7541}},ends={{npcID=91481,x=0.42,y=0.644,zoneID=7541}},coords={x=0.374,y=0.638,source="quest_giver",zoneID=7541},questType="standard"},
[38317] = {id=38317,name="Masters of Disguise",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=7541,description="\"My chute caught a piece of shrapnel. Made a rough landing in a ravenbear nest. Luckily, a bunch of eggs broke my fall. Lost sight of Illandris and Shwayder. Both are masters of disguise, and I am confident they can remain undetected. Will continue to monitor the enemy's activity. Just need to clean all the yolk off my cloaking device. Hope the mother's not around...",starts={{npcID=113911,x=0.332,y=0.314,zoneID=7541}},ends={{npcID=97250,x=0.364,y=0.366,zoneID=7541}},coords={x=0.332,y=0.314,source="quest_giver",zoneID=7541},questType="standard"},
[38318] = {id=38318,name="No Wings Required",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=7541,description="Now that you've got the launcher, we should be able to infiltrate the city. It looks like there's a good spot to grapple onto on the wall just past us. There's a vantage point on top of this ridge. Once we're in, I'll try to slip past the guards and get a look at the mountain path. I'd appreciate if you could make some distractions for me. If all goes well, I'll meet up with you in the upper city. Good luck!",starts={{npcID=91481,x=0.42,y=0.644,zoneID=7541}},ends={{npcID=91519,x=0.438,y=0.682,zoneID=7541},{npcID=91553,x=0.462,y=0.704,zoneID=7541}},coords={x=0.42,y=0.644,source="quest_giver",zoneID=7541},questType="standard"},
[38320] = {id=38320,name="Treasure: The Blade of Kra'nak",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6723,mapID=534,questType="standard"},
[38322] = {id=38322,name="Return to the Grove",level=10,requiredLevel=10,faction="both",expansion=5,zoneID=7558,description="Now that my grove is safe, I can turn my attention to the threat you speak of. To hear of Cenarius' plight is disturbing indeed. Tell Malfurion that I shall meet him at the Grove.",starts={{npcID=91066,x=0.488,y=0.702,zoneID=7558}},ends={{npcID=91109,x=0.518,y=0.64,zoneID=7558}},coords={x=0.488,y=0.702,source="quest_giver",zoneID=7558},questType="standard"},
[38323] = {id=38323,name="Return to the Grove",level=10,requiredLevel=10,faction="both",expansion=5,zoneID=7558,description="Forgive me, . Archdruid Moonclaw's fall is a terrible blow... Malfurion must be informed of what has transpired here. Inform him of Thaon's fate and of the return of Xavius. Make haste, friend. I fear this may be the greatest threat Val'sharah has ever faced.",starts={{npcID=100573,x=0.622,y=0.762,zoneID=7558}},ends={{npcID=91109,x=0.518,y=0.64,zoneID=7558}},coords={x=0.622,y=0.762,source="quest_giver",zoneID=7558},questType="standard"},
[38324] = {id=38324,name="Accessories of the Cursed",level=10,requiredLevel=10,faction="both",expansion=5,zoneID=7588,description="Wait! Before ye go rushin' off, we might want to be gettin more than just seaweed. Ye see, these vrykul also be carrying bones with them - worn all over like jewelry. If ye can get yer hands on some of the bones they got lyin around, it'll add to the disguise. So what ye waitin for?",starts={{npcID=91531,x=0.646,y=0.436,zoneID=7588}},ends={{npcID=91531,x=0.646,y=0.436,zoneID=7588}},coords={x=0.646,y=0.436,source="quest_giver",zoneID=7588},questType="standard"},
[38331] = {id=38331,name="Havi's Test",level=10,requiredLevel=10,faction="both",expansion=5,zoneID=7541,description="I could sense your power the moment you arrived in this land. You carry great purpose and a heavy task. Know that the Aegis of Agrammar rests in the high halls of the All-Father. Only if you prove your valor, can you claim it against your foe. Many trials must you face for this, but first I must know your strength. My stew is incomplete, and my old bones couldn't carry the ingredients up the hill. You look like you have a good arm. Will you help an old man finish his stew?",starts={{npcID=96254,x=0.418,y=0.43,zoneID=7541}},ends={{npcID=96254,x=0.418,y=0.43,zoneID=7541}},coords={x=0.418,y=0.43,source="quest_giver",zoneID=7541},questType="standard"},
[38332] = {id=38332,name="The Ranger Lord",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=7541,description="Good to see you survived the wreck. Nathanos made it as well, though his face is now even uglier than before. He took a group of rangers north to look for Sylvanas - nobody has seen her since the battle. He asked me to send you his way if you ever woke up.",starts={{npcID=91473,x=0.36,y=0.276,zoneID=7541}},ends={{npcID=91158,x=0.378,y=0.216,zoneID=7541}},coords={x=0.36,y=0.276,source="quest_giver",zoneID=7541},questType="standard"},
[38334] = {id=38334,name="Treasure: Jewel of Hellfire",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6723,mapID=534,questType="standard"},
[38337] = {id=38337,name="Built to Scale",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=7541,description="The vrykul around here seem to use scales from these drakes to fashion their armor. If you were able to gather enough material from the local drakes, you may be able to make something useful out of it.",ends={{npcID=91222,x=0.374,y=0.638,zoneID=7541},{npcID=91481,x=0.42,y=0.644,zoneID=7541},{npcID=91519,x=0.438,y=0.682,zoneID=7541},{npcID=91553,x=0.462,y=0.704,zoneID=7541},{npcID=91558,x=0.464,y=0.721,zoneID=7541},{npcID=91771,x=0.372,y=0.636,zoneID=7541}},questType="standard"},
[38339] = {id=38339,name="A Little Kelp From My Foes",level=10,requiredLevel=10,faction="both",expansion=5,zoneID=7588,description="I'm not sure what yer doin' here, but ye have my thanks. If ye want to get any further, though, ye'll need to get past that foul dog, Guarm. I've tried meself a few times, and I think I have a plan. If we can get some of the seaweed these kvaldir wear, we might be able to trick the mutt. Guarm's mean, ye see, but not too smart. What do ye say? Think ye can take on a few kvaldir?",starts={{npcID=91531,x=0.646,y=0.436,zoneID=7588}},ends={{npcID=91531,x=0.646,y=0.436,zoneID=7588}},coords={x=0.646,y=0.436,source="quest_giver",zoneID=7588},questType="standard"},
[38341] = {id=38341,name="Halting the Nightmare",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=7558,mapID=641,description="The corruption of the vale is the work of satyrs. The new power they wield is unlike any I've seen... it is dark, seething and terrible. Nefarious demon totems help spread their taint upon the land. The Nghtmare totems must be destroyed if we are to hold back the tide of corruption.",questType="standard"},
[38342] = {id=38342,name="Another Way",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=7541,description="Well, the bridge option is out. You still got that grapple launcher handy? It looks like we can get across from the top of that tower over there. First thing's first, though, we'll need to deal with the big ugly sitting out front. You take point.",starts={{npcID=91553,x=0.462,y=0.704,zoneID=7541}},ends={{npcID=91558,x=0.464,y=0.721,zoneID=7541}},coords={x=0.462,y=0.704,source="quest_giver",zoneID=7541},questType="standard"},
[38347] = {id=38347,name="Stealth by Seaweed",level=10,requiredLevel=10,faction="both",expansion=5,zoneID=7588,description="There! The disguise be complete! Don't mind the smell, there. It's probably better that we smell like the kvaldir, as well. Though I have a feeling I'll be needin a priest to get this stench out once we're gone.",starts={{npcID=91531,x=0.646,y=0.436,zoneID=7588}},ends={{npcID=97419,x=0.648,y=0.442,zoneID=7588}},coords={x=0.646,y=0.436,source="quest_giver",zoneID=7588},questType="standard"},
[38351] = {id=38351,name="Portable Portals",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=7004,description="My assistants have figured out how to convert ogre waystones into useful items for our garrison. Speak with Varsha outside to start your first work order.",starts={{npcID=79836,x=0.62,y=0.354,zoneID=7004}},ends={{npcID=79836,x=0.62,y=0.354,zoneID=7004}},coords={x=0.62,y=0.354,source="quest_giver",zoneID=7004},questType="standard"},
[38353] = {id=38353,name="Rescued From Darkness",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=7558,mapID=641,description="Midnight Vale is home to a unique breed of Nightsaber known as the Vale Prowler. For centuries, our clan has lived in harmony with these great feline hunters. However, even as we speak satyrs are twisting and corrupting the vale into a place of death and nightmare. Even the forest itself lashes out in torment against the living, causing many of the forest creatures to flee the vale. I fear for the safety of the youngest nightsabers, who may yet be caught in the twisting chaos, unable to escape.",questType="standard"},
[38354] = {id=38354,name="Portable Portals",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=7078,description="My assistants have figured out how to convert ogre waystones into useful items for our garrison. Speak with Apprentice Var'nath outside to start your first work order.",starts={{npcID=77367,x=0.39,y=0.588,zoneID=7078}},ends={{npcID=77367,x=0.39,y=0.588,zoneID=7078}},coords={x=0.39,y=0.588,source="quest_giver",zoneID=7078},questType="standard"},
[38355] = {id=38355,name="7.0 Val'sharah - Treasure 002 - Moonrest Shore - twh",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=7558,mapID=641,questType="standard"},
[38356] = {id=38356,name="Bringing the Bass",level=40,requiredLevel=40,faction="alliance",expansion=5,zoneID=6721,description="It's a bit quiet around here, in between the invasions and all. You're in luck though, Commander! I can fix that, and boost morale among your troops all at the same time. All you need to do is bring me a few items from around Draenor, and I'll fill your garrison with music. I'll even throw in a few music rolls from my own collection to get you started! What do you say?",starts={{npcID=91589,x=0.338,y=0.37,zoneID=7078}},ends={{npcID=91589,x=0.338,y=0.37,zoneID=7078}},coords={x=0.338,y=0.37,source="quest_giver",zoneID=7078},questType="standard"},
[38357] = {id=38357,name="Side Effects May Include Mild Undeath",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=7541,description="Exposure to this particular \"byproduct\" is quite nasty. Rapid cell degeneration quickly reduces the subject to a shambling husk incapable of any reason or thought beyond a violent, throbbing hatred for the warmth of life. As you might imagine, the local fauna have been affected by the spill. Oh, and most of the crew as well... Anyway, good luck!",starts={{npcID=91590,x=0.36,y=0.274,zoneID=7541}},ends={{npcID=91590,x=0.36,y=0.274,zoneID=7541}},coords={x=0.36,y=0.274,source="quest_giver",zoneID=7541},questType="standard"},
[38358] = {id=38358,name="Pump it Up",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=7541,description="The Black Rose was a seafaring laboratory for the Royal Apothecary Society. Naturally, we had some volatile... \"byproducts\" onboard. Regrettably, one such substance was released during our skirmish with the Alliance gunship. As you can see, it is taking quite a toll on the coast. The R.A.S. must remedy this situation before we press further inland. Please take a containment unit and fill it with waste - for us to dispose of properly at a later time, of course.",starts={{npcID=91590,x=0.36,y=0.274,zoneID=7541}},ends={{npcID=91590,x=0.36,y=0.274,zoneID=7541},{npcID=91693,x=0.376,y=0.218,zoneID=7541}},coords={x=0.36,y=0.274,source="quest_giver",zoneID=7541},questType="standard"},
[38359] = {id=38359,name="7.0 Val'sharah - Treasure 003 - Lorlathil - twh",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=7558,mapID=641,questType="standard"},
[38360] = {id=38360,name="The Windrunner's Fate",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=7541,description="Finding Sylvanas is our only priority! We will cover more ground if we split up. I will lead a team into the hills above the enemy's camp while you search the wreckage itself for any signs of the crew. Once we've cleared the high ground, I will meet you at the far end of the beach.",starts={{npcID=91158,x=0.378,y=0.216,zoneID=7541}},ends={{npcID=91158,x=0.378,y=0.216,zoneID=7541}},coords={x=0.378,y=0.216,source="quest_giver",zoneID=7541},questType="standard"},
[38361] = {id=38361,name="Wrath of the Blightcaller",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=7541,description="The Alliance dogs have bitten off more than they can chew. They have attacked the Banshee Queen, and invoked the wrath of her champion! Like my bow, my axes, and my hounds, you will be an agent of vengeance. Pile the bodies high, , and know that I am doing the same. When next we meet, I expect to see blood upon your hands.",starts={{npcID=91158,x=0.378,y=0.216,zoneID=7541}},ends={{npcID=91158,x=0.378,y=0.216,zoneID=7541}},coords={x=0.378,y=0.216,source="quest_giver",zoneID=7541},questType="standard"},
[38362] = {id=38362,name="A Grim Trophy",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=7541,description="It would seem Sylvanas does not wish to be followed - by us or anyone else. Her will is her own, it is not my place to question. Only to obey. In the hills nearby, a gryphon master is preparing to take flight, no doubt to pursue our queen from the sky. My rangers are lying in wait - we need only to close our jaws around him. I will have his head when this is over.",starts={{npcID=91158,x=0.378,y=0.216,zoneID=7541}},ends={{npcID=91158,x=0.378,y=0.216,zoneID=7541}},coords={x=0.378,y=0.216,source="quest_giver",zoneID=7541},questType="standard"},
[38363] = {id=38363,name="7.0 Val'sharah - Treasure 004 - Thas'talah Basin - twh",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=7558,mapID=641,questType="standard"},
[38366] = {id=38366,name="7.0 Val'sharah - Treasure 005 - Thas'talah - twh",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=7558,mapID=641,questType="standard"},
[38369] = {id=38369,name="7.0 Val'sharah - Treasure 006 - Ravencourt - twh",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=7558,mapID=641,questType="standard"},
[38371] = {id=38371,name="7.0 Val'sharah - Treasure 007 - Sylvan Lake - ZtO",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=7558,mapID=641,questType="standard"},
[38376] = {id=38376,name="The Search for the Highlord",level=10,requiredLevel=10,faction="both",expansion=5,zoneID=7796,description="Tirion is fading away on that infernal shore... and the Ashbringer with him! We must not waste another moment. Give the word and we'll set off. We're ready when you are.",ends={{npcID=91144,x=0.204,y=0.614,zoneID=7796}},questType="standard"},
[38377] = {id=38377,name="The Emerald Queen",level=10,requiredLevel=10,faction="both",expansion=5,zoneID=7558,description=", you have returned. Good. I have counseled with the other archdruids and concluded that Cenarius' condition is merely a symptom of a much greater problem. Your experiences in Moonclaw Vale make that clear. We need help. There is one who can bring understanding to these events. With Thaon gone, we must ask that you aid us in reaching out to the Lady of Dreams.",starts={{npcID=91109,x=0.518,y=0.64,zoneID=7558}},ends={{npcID=100387,x=0.524,y=0.64,zoneID=7558}},coords={x=0.518,y=0.64,source="quest_giver",zoneID=7558},questType="standard"},
[38380] = {id=38380,name="Vignette: Hivequeen Zsala",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=7558,mapID=641,questType="standard"},
[38381] = {id=38381,name="Archdruid of Lore",level=10,requiredLevel=10,faction="both",expansion=5,zoneID=7558,description="Elothir resides in the ancient grove Thas'talah, where he communes with nature and instructs his acolytes in the ways of healing and the preservation of lore. Seek him out and tell him that he is desperately needed here.",starts={{npcID=91651,x=0.518,y=0.64,zoneID=7558},{npcID=94179,x=0.544,y=0.734,zoneID=7558}},ends={{npcID=91066,x=0.488,y=0.702,zoneID=7558}},coords={x=0.518,y=0.64,source="quest_giver",zoneID=7558},questType="standard"},
[38382] = {id=38382,name="Archdruid of the Vale",level=10,requiredLevel=10,faction="both",expansion=5,zoneID=7558,description="Deep within our forest lies Moonclaw Vale. There you will find a reclusive group of feral druids charged with the protection of Val'sharah from any that would seek to disrupt the balance of nature. These druids are led by Thaon Moonclaw , the most fierce of the Archdruids. Seek him out. Let him know that Cenarius is in need of his aid.",starts={{npcID=91651,x=0.518,y=0.64,zoneID=7558},{npcID=94179,x=0.544,y=0.734,zoneID=7558}},ends={{npcID=95395,x=0.61,y=0.732,zoneID=7558}},coords={x=0.518,y=0.64,source="quest_giver",zoneID=7558},questType="standard"},
[38383] = {id=38383,name="7.0 Stormheim - Treasure 019 - Helheim - ZTO",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=7541,mapID=634,questType="standard"},
[38384] = {id=38384,name="Nature's Call",level=10,requiredLevel=10,faction="both",expansion=5,zoneID=7558,description="What vile power is this?! A curse with the strength to paralyze a demigod? Unimaginable! Quickly, , you must gather the archdruids of the forest. With their help, we can summon Ysera. She will surely know what horror has overtaken my mentor. I will remain here and lend Cenarius what aid I can. Return to Lorlathil and speak with Aranelle . She will know the archdruids' whereabouts. And please, friend, make haste...",starts={{npcID=91109,x=0.518,y=0.64,zoneID=7558}},ends={{npcID=94179,x=0.544,y=0.734,zoneID=7558}},coords={x=0.518,y=0.64,source="quest_giver",zoneID=7558},questType="standard"},
[38386] = {id=38386,name="7.0 Val'sharah - Treasure 008 - Shadowfen - twh",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=7558,mapID=641,questType="standard"},
