[38391] = {id=38391,name="7.0 Val'sharah - Treasure 013 - Val'sharah - twh",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=7558,mapID=641,questType="standard"},
[38392] = {id=38392,name="7.0 Val'sharah - Treasure 014 - Malorne's Refuge - twh",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=7558,mapID=641,questType="standard"},
[38393] = {id=38393,name="7.0 Val'sharah - Treasure 015 - Malorne's Refuge - twh",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=7558,mapID=641,questType="standard"},
[38405] = {id=38405,name="To Weather the Storm",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=7541,description="I've been doing some nosing around, and it looks like these vrykul are making regular trips up the mountain themselves. They've got some specialized gear for it, so while we're here we should take some. I'd recommend finding some climbing treads to keep your grip on the slopes, as well as an oiled cloak to keep the rain out. Also, it looks like they carry enchanted lodestones , which seem to keep the lightning at bay. You should probably grab one of those, too.",starts={{npcID=91481,x=0.42,y=0.644,zoneID=7541}},ends={{npcID=91519,x=0.438,y=0.682,zoneID=7541}},coords={x=0.42,y=0.644,source="quest_giver",zoneID=7541},questType="standard"},
[38406] = {id=38406,name="Sea Scorpion Lunker",level=10,requiredLevel=10,faction="both",expansion=5,zoneID=7078,starts={{npcID=85984,x=0.382,y=0.72,zoneID=7004},{npcID=85984,x=0.534,y=0.14,zoneID=7078}},ends={{npcID=85984,x=0.382,y=0.72,zoneID=7004},{npcID=85984,x=0.534,y=0.14,zoneID=7078}},coords={x=0.382,y=0.72,source="quest_giver",zoneID=7004},questType="standard"},
[38407] = {id=38407,name="Bottled Up",level=10,requiredLevel=10,faction="both",expansion=5,zoneID=7334,description="Lady Irisse at the Crumbled Palace, she can point you in the right direction?>",ends={{npcID=88798,x=0.47,y=0.414,zoneID=7334}},questType="standard"},
[38408] = {id=38408,name="New Goods",level=40,requiredLevel=40,faction="alliance",expansion=5,zoneID=7078,starts={{npcID=79953,x=0.292,y=0.346,zoneID=7078},{npcID=84268,x=0.292,y=0.346,zoneID=7078}},coords={x=0.292,y=0.346,source="quest_giver",zoneID=7078},questType="standard"},
[38410] = {id=38410,name="Impalement Insurance",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=7541,description="I've got bad news. Those harpoon launchers up on the walls might cause us some problems. They can't get at us down here, but once you start climbing that path, they're likely going to try to skewer you. If you use that grapple launcher, you should be able to get on top of the walls and dismantle them. Watch out for the drakes, though!",starts={{npcID=91519,x=0.438,y=0.682,zoneID=7541}},ends={{npcID=91553,x=0.462,y=0.704,zoneID=7541}},coords={x=0.438,y=0.682,source="quest_giver",zoneID=7541},questType="standard"},
[38412] = {id=38412,name="Above the Winter Moonlight",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=7541,description="You should have a good vantage from this tower to grapple over to the mountain path. I can't help you once you're across, but you should be able to take it all the way up to the top. I hope you're able to find what you need from the dragons up there. Who knows what the God-King has done to them.",starts={{npcID=91558,x=0.464,y=0.721,zoneID=7541}},ends={{npcID=91249,x=0.446,y=0.774,zoneID=7541}},coords={x=0.464,y=0.721,source="quest_giver",zoneID=7541},questType="standard"},
[38413] = {id=38413,name="Wings of Liberty",level=10,requiredLevel=10,faction="both",expansion=5,zoneID=7541,description="When the Felskorn assaulted the nest, the Thorignir fought bravely to save our brood. But their demonic allies proved too much, and many of us were captured. Even now they work to corrupt my brothers and sisters to turn them to their side. Please, outsider, free them from this fate!",starts={{npcID=91249,x=0.446,y=0.774,zoneID=7541},{npcID=96465,x=0.428,y=0.826,zoneID=7541}},ends={{npcID=96465,x=0.428,y=0.826,zoneID=7541}},coords={x=0.446,y=0.774,source="quest_giver",zoneID=7541},questType="standard"},
[38414] = {id=38414,name="Heart of a Dragon",level=10,requiredLevel=10,faction="both",expansion=5,zoneID=7541,description="Through brute force and corruption, the God-King has taken the power you seek, but there may be hope for you and the Thorignir, . With the aid of fel powers such as I've never seen, the Felskorn are corrupting our young and seeking to enslave the Thorignir. Their leader, a demon of great power, has captured our mother and seeks to bend her to the God-King's will. Find her and free her from the demon's grasp - only then might the Thorignir regain our power and grant you aid.",questType="standard"},
[38415] = {id=38415,name="Garrison Campaign: Onslaught at Auchindoun",level=40,requiredLevel=40,faction="horde",expansion=5,zoneID=6662,description="Your ally, Liadrin, has sent a missive requesting aid near Auchindoun. The Sargerei have made a new assault there and breached something important. It is no coincidence this happened after Gul'dan's ascendancy. We will watch the front here, commander.",starts={{npcID=90481,x=0.408,y=0.732,zoneID=6720},{npcID=90481,x=0.614,y=0.458,zoneID=6723}},coords={x=0.408,y=0.732,source="quest_giver",zoneID=6720},questType="standard"},
[38416] = {id=38416,name="Secrets of the Sargerei",level=40,requiredLevel=40,faction="horde",expansion=5,zoneID=6662,description="The Auchenai have been reporting for some time that something was... wrong... with Auchindoun. They were never able to find a reason. Suddenly the Sargerei attacked and blew open a hole into a subchamber. Corruption leaks from that hole, we need to stop it.",questType="standard"},
[38417] = {id=38417,name="The Sargerei Menace",level=40,requiredLevel=40,faction="horde",expansion=5,zoneID=6662,mapID=535,description="An attack such as this was unexpected. They have deployed heavily and it will take me some time to marshal enough forces to root them out. Any Sargerei you can slay will make retaking this area much easier commander.",questType="standard"},
[38421] = {id=38421,name="Garrison Campaign: Onslaught at Auchindoun",level=40,requiredLevel=40,faction="alliance",expansion=5,zoneID=6662,description="The Auchenai have sent me an urgent missive - Auchindoun is in jeopardy again! The Sargerei have renewed their assault and breached the underhalls. I sense the hand of Gul'dan is behind this. Gather your things and meet me in the Court of Souls West of Auchindoun at once!",starts={{npcID=90309,x=0.584,y=0.602,zoneID=6723}},coords={x=0.584,y=0.602,source="quest_giver",zoneID=6723},questType="standard"},
[38422] = {id=38422,name="Makrura Wave Event",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=7541,mapID=634,questType="standard"},
[38423] = {id=38423,name="Vignette: Stormdrake Matriarch",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=7541,mapID=634,questType="standard"},
[38424] = {id=38424,name="Thane's Mead Hall",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=7541,mapID=634,questType="standard"},
[38426] = {id=38426,name="Treasure: Tome of Secrets",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6723,mapID=534,questType="standard"},
[38427] = {id=38427,name="New Goods",level=40,requiredLevel=40,faction="horde",expansion=5,zoneID=7004,starts={{npcID=79740,x=0.538,y=0.542,zoneID=7004}},coords={x=0.538,y=0.542,source="quest_giver",zoneID=7004},questType="standard"},
[38428] = {id=38428,name="A Fel Puppy Of My Own",level=40,requiredLevel=40,faction="both",expansion=5,zoneID=6723,mapID=534,starts={{npcID=90426,x=0.316,y=0.67,mapID=534}},ends={{npcID=90426,x=0.316,y=0.67,mapID=534}},coords={x=0.316,y=0.67,source="quest_giver",mapID=534},questType="standard"},
[38435] = {id=38435,name="The Invasion of Tanaan",level=40,requiredLevel=40,faction="alliance",expansion=5,zoneID=6720,description="It is done! By your command we have built our first ship and can run our naval operations from here. Now that we have our transport, we can let Yrel and Archmage Khadgar know that we are ready to kick off an invasion of Tanaan. Speak with them at the docks to embark.",starts={{npcID=95002,x=0.298,y=0.106,zoneID=6719}},ends={{npcID=91913,x=0.75,y=0.578,zoneID=6719},{npcID=91913,x=0.734,y=0.712,zoneID=6723},{npcID=91913,x=0.322,y=0.326,zoneID=7078}},coords={x=0.298,y=0.106,source="quest_giver",zoneID=6719},questType="standard"},
[38436] = {id=38436,name="Obstacle Course",level=40,requiredLevel=40,faction="alliance",expansion=5,zoneID=7078,description="Our landing was unopposed. Why are these docks all but abandoned? The rangari scouts up ahead report trouble. Bleeding Hollow scavengers are looting some abandoned buildings to the northwest, and an encampment of warlock cultists lurk near the Dark Portal. Let's find out what we can and meet up with our scouts.",starts={{npcID=91913,x=0.75,y=0.578,zoneID=6719},{npcID=91913,x=0.734,y=0.712,zoneID=6723},{npcID=91913,x=0.322,y=0.326,zoneID=7078}},ends={{npcID=91923,x=0.624,y=0.542,zoneID=6723}},coords={x=0.75,y=0.578,source="quest_giver",zoneID=6719},questType="standard"},
[38437] = {id=38437,name="Max-level Choice Tracker: Tanaan 6.2 - The Fel Forge",level=1,requiredLevel=1,faction="horde",expansion=5,zoneID=6723,mapID=534,questType="standard"},
[38438] = {id=38438,name="Max-level Choice Tracker: Tanaan 6.2 - The Fel Forge",level=1,requiredLevel=1,faction="alliance",expansion=5,zoneID=6723,mapID=534,questType="standard"},
[38440] = {id=38440,name="Assault on The Fel Forge",level=40,requiredLevel=40,faction="alliance",expansion=5,zoneID=6723,description="The Iron Horde is growing stronger each day as their war machines are empowered with fel magic. We have even obtained word that they are constructing a Fel Reaver! Head to the Fel Forge and destroy their forces before we are overwhelmed.",ends={{npcID=90309,x=0.584,y=0.602,zoneID=6723}},questType="standard"},
[38441] = {id=38441,name="Assault on The Fel Forge",level=40,requiredLevel=40,faction="horde",expansion=5,zoneID=6723,description="The Iron Horde is growing stronger each day as their war machines are empowered with fel magic. We have even obtained word that they are constructing a Fel Reaver! Head to the Fel Forge and destroy their forces before we are overwhelmed.",ends={{npcID=90481,x=0.408,y=0.732,zoneID=6720},{npcID=90481,x=0.614,y=0.458,zoneID=6723}},questType="standard"},
[38443] = {id=38443,name="Journey to the Repose",level=10,requiredLevel=10,faction="both",expansion=5,zoneID=7334,description="For now, the Illidari can hold the line against the Legion. We will return later to help them drive the Legion from the upper reaches of Faronaar. You and I must concentrate on the Pillars of Creation if the Tomb of Sargeras is to be resealed. Your saving of Stellagosa is fortuitous. Surely if anyone knows where a Pillar of Creation is, it will be her grandfather, Senegos. The Azurewing Repose is to the northeast. I will meet you there, .",starts={{npcID=93326,x=0.434,y=0.434,zoneID=7334}},ends={{npcID=93354,x=0.48,y=0.272,zoneID=7334}},coords={x=0.434,y=0.434,source="quest_giver",zoneID=7334},questType="standard"},
[38444] = {id=38444,name="In, Through, and Beyond!",level=40,requiredLevel=40,faction="alliance",expansion=5,zoneID=6723,description="Gul'dan seems to have concentrated his defenses on this chokepoint. The guns up ahead are unlike anything we've seen before - they're empowered with fel energy. Our enemies think this pass is impregnable. Let's prove them wrong, commander! If we can break through, the terrain ahead will make an excellent stronghold. Destroy that cannon!",starts={{npcID=91923,x=0.624,y=0.542,zoneID=6723}},ends={{npcID=91923,x=0.624,y=0.542,zoneID=6723}},coords={x=0.624,y=0.542,source="quest_giver",zoneID=6723},questType="standard"},
[38445] = {id=38445,name="The Assault Base",level=40,requiredLevel=40,faction="alliance",expansion=5,zoneID=6723,description="While you were playing with fel fire, I've located the perfect position for an assault outpost. Follow me and we can get this base started!",starts={{npcID=91923,x=0.624,y=0.542,zoneID=6723}},ends={{npcID=90309,x=0.584,y=0.602,zoneID=6723}},coords={x=0.624,y=0.542,source="quest_giver",zoneID=6723},questType="standard"},
[38446] = {id=38446,name="Commander in the Field!",level=40,requiredLevel=40,faction="alliance",expansion=5,zoneID=6723,description="This battle will be won, but it will be hard fought. Our rangari did manage to get a few scouts out to the rest of the jungle though. Perhaps it is best you collect this intelligence yourself and see what this jungle holds for us all.",starts={{npcID=91935,x=0.098,y=0.534,zoneID=6723}},ends={{npcID=90309,x=0.584,y=0.602,zoneID=6723}},coords={x=0.098,y=0.534,source="quest_giver",zoneID=6723},questType="standard"},
[38449] = {id=38449,name="Assault on the Temple of Sha'naar",level=40,requiredLevel=40,faction="horde",expansion=5,zoneID=6723,description="Up in the hills of Tanaan Jungle , the Sargerei have converted a once-sacred temple into a den of demonic summoning. We must attack them now, before their rituals complete. The longer we delay, the stronger our enemy grows.",ends={{npcID=90481,x=0.408,y=0.732,zoneID=6720},{npcID=90481,x=0.614,y=0.458,zoneID=6723}},questType="standard"},
[38453] = {id=38453,name="Garrison Campaign: The Bane of the Bleeding Hollow",level=40,requiredLevel=40,faction="horde",expansion=5,zoneID=6723,description="Commander, now that we've had time to get scouts all over the jungle we have heard some news near Zeth'Gol. It appears that somebody else has a vendetta against the Bleeding Hollow and has been... hunting... them. Their hunters are closing in on the assassin. You know what they say about \"the enemy of my enemy...\" We should collect their tracking maps and try to find the killer first!",starts={{npcID=90481,x=0.408,y=0.732,zoneID=6720},{npcID=90481,x=0.614,y=0.458,zoneID=6723}},coords={x=0.408,y=0.732,source="quest_giver",zoneID=6720},questType="standard"},
[38455] = {id=38455,name="Frenzied Furbolgs",level=10,requiredLevel=10,faction="both",expansion=5,zoneID=7558,description="I would help you seek audience with the Archdruid, but we have a difficult situation on our hands. The nearby furbolgs have gone into a frenzied rage. For days, it has been all we can do to protect our grove from their aggression. They have cut off our access to the barrow dens, where the Archdruid and our clan sleep in the Emerald Dream. In order to awaken them, we must first get past the furbolg.",questType="standard"},
[38458] = {id=38458,name="Garrison Campaign: The Warlock",level=40,requiredLevel=40,faction="horde",expansion=5,zoneID=6723,description="Commander, you have a visitor. One of Gul'dan 's warlocks just walked up to the base and surrendered. He says he has information of a terrible event that is about to occur. I suggest you speak with him immediately.",starts={{npcID=90481,x=0.408,y=0.732,zoneID=6720},{npcID=90481,x=0.614,y=0.458,zoneID=6723}},ends={{npcID=92055,x=0.472,y=0.704,zoneID=6723}},coords={x=0.408,y=0.732,source="quest_giver",zoneID=6720},questType="standard"},
[38459] = {id=38459,name="The Ancient Trials",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=7541,description="I know who you are, champion, and I know what you seek. Come to me, if you think yourself truly worthy.",starts={{npcID=97305,x=0.368,y=0.31,zoneID=7541}},ends={{npcID=96254,x=0.418,y=0.43,zoneID=7541}},coords={x=0.368,y=0.31,source="quest_giver",zoneID=7541},questType="standard"},
[38460] = {id=38460,name="Let's Make A Deal",level=10,requiredLevel=10,faction="both",expansion=5,zoneID=7334,description="Hey there! You seem like a gullib- er... um... \"intelligent\" type. I propose a deal. I need a minion to be my muscle to help me acquire a few special... \"ingredients\" for a ritual. In exchange, I'll give you my former master to do with whatever you demon-slaying types do with demons. If you are interested, just sign here. In blood, please.",starts={{npcID=91166,x=0.624,y=0.514,zoneID=7334}},ends={{npcID=91166,x=0.624,y=0.514,zoneID=7334}},coords={x=0.624,y=0.514,source="quest_giver",zoneID=7334},questType="standard"},
[38462] = {id=38462,name="Breaching the Barrier",level=40,requiredLevel=40,faction="both",expansion=5,zoneID=6723,description="The ritual site is already prepared, and it is protected by a barrier... one that I created. I can destroy the barrier, but I will need three items currently in use at Forge Camp Vengeance. If you can get those ritual items, I will meet you at the Corrupted Refuge and remove the barrier. Even if it kills me.",starts={{npcID=92055,x=0.472,y=0.704,zoneID=6723}},ends={{npcID=92120,x=0.626,y=0.31,zoneID=6723}},coords={x=0.472,y=0.704,source="quest_giver",zoneID=6723},questType="standard"},
[38463] = {id=38463,name="The Cipher of Damnation",level=40,requiredLevel=40,faction="horde",expansion=5,zoneID=6723,description="Your ally and I will remove this barrier now, though it will take a greater part of our strength. What lies beyond will not be easy. Gul'dan will have empowered an elemental lord with the Cipher, driving it insane. He will use it to destroy the link between the elements and Draenor. If you destroy that elemental, we could recover the Cipher.",starts={{npcID=92120,x=0.626,y=0.31,zoneID=6723}},ends={{npcID=93659,x=0.628,y=0.278,zoneID=6723}},coords={x=0.626,y=0.31,source="quest_giver",zoneID=6723},questType="standard"},
[38465] = {id=38465,name="Vignette: Shyama the Dreaded",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=7558,mapID=641,questType="standard"},
[38469] = {id=38469,name="Bonus Objective: The Moonclaw Vale",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=7558,mapID=641,questType="standard"},
[38472] = {id=38472,name="Whitewater Typhoon",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=7541,mapID=634,questType="standard"},
[38473] = {id=38473,name="Will of the Thorignir",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=7541,description="In the summit of storms the dragons await. Born of the gods, they will test your will. They roost above Hrydshal, where their children serve the Drekirjar. But they are no allies to man or vrykul, and so you must earn their blessing as they see fit. A friend of yours awaits in Hrydshal, no doubt searching for the answers you now possess. Go to her, and together, you will test your might against the storm!",starts={{npcID=96254,x=0.418,y=0.43,zoneID=7541}},ends={{npcID=91222,x=0.374,y=0.638,zoneID=7541}},coords={x=0.418,y=0.43,source="quest_giver",zoneID=7541},questType="standard"},
[38474] = {id=38474,name="7.0 Stormheim - Treasure 001 - Hrydshal - ZTO",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=7541,mapID=634,questType="standard"},
