[38496] = {id=38496,name="Vignette: BH Master Scout",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6721,mapID=543,questType="standard"},
[38498] = {id=38498,name="7.0 Stormheim - Treasure 018 - Maw of Nashal - ZTO",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=7541,mapID=634,questType="standard"},
[38499] = {id=38499,name="Strange New Ores",level=10,requiredLevel=10,faction="both",expansion=5,zoneID=7502,description="You smell that, smith? Ahhhh... that there's the smell of opportunity. Dalaran's taken us to some strange new shores, filled with mysterious metals. I'm tethered to my shop here, but you... you've got the freedom to explore and mine at will. Bring me something interesting, and we'll see what we can make with it.",questType="standard"},
[38500] = {id=38500,name="Leysmithing Mastery",level=10,requiredLevel=10,faction="both",expansion=5,zoneID=7502,description="Well, now that we have the flux we can put it to work and see how it goes. Why don't you take a crack at it this time and make some gauntlets for me. I'll observe your work... from a distance.",questType="standard"},
[38501] = {id=38501,name="Hatecoil Hammerwork",level=10,requiredLevel=10,faction="both",expansion=5,zoneID=7502,description="There may be a way to jump-start our research into leystone. I've heard reports of naga camps down in Azsuna. If they've been in Azsuna for long enough, their smiths have certainly started experimenting with leystone themselves. Be on the lookout for some leystone armor on the naga... ideally something more elaborate than a bracer.",questType="standard"},
[38502] = {id=38502,name="The Methods of the Nightfallen",level=10,requiredLevel=10,faction="both",expansion=5,zoneID=7334,description="I have a theory, . Have you encountered the nightfallen elves of Azsuna? They descend from the Highborne, and the accomplishments of Highborne smiths are legendary. These fallen elves do a bit of arcane tinkering, crafting sentries to patrol their camps. Bring me a memory core from one of their constructs. Who knows what manner of smithlore might lie within!",questType="standard"},
[38503] = {id=38503,name="7.0 Stormheim - Treasure 020 - Helheim - ZTO",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=7541,mapID=634,questType="standard"},
[38505] = {id=38505,name="Engineers: Not COMPLETELY Useless",level=10,requiredLevel=10,faction="both",expansion=5,zoneID=7502,description="Unfortunately, I have no idea how to access any information within this core. But I know someone who does. Head over to \"Like Clockwork\", the engineering shop three doors down from here. Timofey Oshenko owes me a favor. He should be able to extract the memory out of the core.",questType="standard"},
[38506] = {id=38506,name="Chicken Scratch",level=10,requiredLevel=10,faction="both",expansion=5,zoneID=7502,description="I think I have just the thing to extract the information from this core for you. You may wish to avert your eyes, blacksmith.",questType="standard"},
[38507] = {id=38507,name="Secrets of Leysmithing",level=10,requiredLevel=10,faction="both",expansion=5,zoneID=7502,description="I could spend hours poring over the details of this fascinating manuscript! ...is what I would say if this weren't the simplest of tasks for someone of my skill level. It's about something called \"Leysmithing\". Here. There it is, word-for-word. Bring me something interesting next time.",questType="standard"},
[38509] = {id=38509,name="7.0 Stormheim - Treasure 021 - Helheim - ZTO",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=7541,mapID=634,questType="standard"},
[38510] = {id=38510,name="7.0 Stormheim - Treasure 021 - Helheim - ZTO",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=7541,mapID=634,questType="standard"},
[38511] = {id=38511,name="7.0 Stormheim - Treasure 022 - Helheim - ZTO",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=7541,mapID=634,questType="standard"},
[38513] = {id=38513,name="The Highmountain Smiths",level=10,requiredLevel=10,faction="both",expansion=5,zoneID=7503,description="I think we've gone as far as we can go with what I know, . The tauren of Highmountain must have some smiths among their ranks. See if you can find out how to further progress our leysmithing abilities from them.",ends={{npcID=92242,x=0.552,y=0.842,zoneID=7503}},questType="standard"},
[38514] = {id=38514,name="You Are Not Worthy",level=10,requiredLevel=10,faction="both",expansion=5,zoneID=7503,description="You wish me to teach you how to strengthen your crafts? We do not simply share the secrets of our trade with outsiders who ask for them. We do, however, respect craftsmanship and discipline. Let's see your hammerwork. Our greenhorn trainees use those small anvils over there. Craft your best pair of gauntlets so I may judge your work.",starts={{npcID=92242,x=0.552,y=0.842,zoneID=7503}},ends={{npcID=92242,x=0.552,y=0.842,zoneID=7503}},coords={x=0.552,y=0.842,source="quest_giver",zoneID=7503},questType="standard"},
[38515] = {id=38515,name="Nature Provides",level=10,requiredLevel=10,faction="both",expansion=5,zoneID=7502,description="This is interesting, it says that leystone reacts violently with anything it views as a contaminant. Our foreign-mined flux was enough to cause the small explosion. Local ingredients, however, have learned to coexist with leystone. Up in Highmountain, an herb called foxflower grows that can be turned into a suitable flux. Go and gather some foxflower that we can turn into a usable flux.",questType="standard"},
[38516] = {id=38516,name="7.0 Stormheim - Treasure 022 - Helheim - ZTO",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=7541,mapID=634,questType="standard"},
[38518] = {id=38518,name="From One Master to Another",level=10,requiredLevel=10,faction="both",expansion=5,zoneID=7502,description="Now young one, go back to your master in Dalaran and continue to practice your swing. We'll always be here if you wish to come back and learn more.",starts={{npcID=92242,x=0.552,y=0.842,zoneID=7503}},coords={x=0.552,y=0.842,source="quest_giver",zoneID=7503},questType="standard"},
[38519] = {id=38519,name="Grayheft",level=10,requiredLevel=10,faction="both",expansion=5,zoneID=7503,description="Our tribe regularly crafts legplates out of leystone. I will share our pattern with you... if you do me a favor. My father fell to the drogbar several years ago, and they took his hammer as a trophy. That hammer was in my family for countless generations. Now, it languishes in the hands of the vile drogbar, Kubrul. I would very much like to have it back.",starts={{npcID=92245,x=0.55,y=0.844,zoneID=7503}},ends={{npcID=92245,x=0.55,y=0.844,zoneID=7503}},coords={x=0.55,y=0.844,source="quest_giver",zoneID=7503},questType="standard"},
[38522] = {id=38522,name="Not Just Weapons and Armor",level=10,requiredLevel=10,faction="both",expansion=5,zoneID=7502,description="You know, we aren't just limited to armorsmithing and weaponsmithing. I regularly make chisels for the scribes, crucibles for the alchemists, and even thimbles for the tailors. They should sew in full plate gauntlets if they're really all that worried about their poor little thumbs. Anyhow, I have a recipe I think an adventurer like you might be interested in. Let's try it out.",questType="standard"},
[38523] = {id=38523,name="Leystone Hoofplates",level=10,requiredLevel=10,faction="both",expansion=5,zoneID=7502,description="Here, bring these hoofplates to Mei Francis, down at the mounts and pets store, to get your mount properly shod. I'll share the pattern when you return.",questType="standard"},
[38524] = {id=38524,name="Felsmith Nal'ryssa",level=45,requiredLevel=45,faction="both",expansion=5,zoneID=7637,description="Word has been circulating in smithing circles about a pair of Illidari blacksmiths that have been doing exciting work out on the demon-infested front lines of Suramar. I'd follow up myself, but anything described as \"demon-infested\" is a little too exotic for my tastes. I just make the armor. I prefer not to wear it. You, though... you could follow up on this tip. Be on the lookout for Nal'ryssa. From what I hear, she's a hell of a smith.",ends={{npcID=92264,x=0.3,y=0.534,zoneID=7637}},questType="standard"},
[38525] = {id=38525,name="Part of the Team",level=45,requiredLevel=45,faction="both",expansion=5,zoneID=1519,description="You're a blacksmith? Still working in leystone, are you? I might be able to help you out. Alliances out here are hard-won. You've got a pretty face, but that's no guarantee that you aren't working for the demons. I can't afford to trust you yet. Don't come back until you're caked in demon's blood. Then we'll talk smithing.",starts={{npcID=92264,x=0.3,y=0.534,zoneID=7637}},ends={{npcID=92264,x=0.3,y=0.534,zoneID=7637}},coords={x=0.3,y=0.534,source="quest_giver",zoneID=7637},questType="standard"},
[38526] = {id=38526,name="Smith Under Fire",level=45,requiredLevel=45,faction="both",expansion=5,zoneID=7637,description="You lack recipes for boots? What, were you trained by a tauren or something? Hurry up, then. We probably have a few minutes before the demons attack again. Here's a pattern - show me your work.",starts={{npcID=92264,x=0.3,y=0.534,zoneID=7637}},ends={{npcID=92264,x=0.3,y=0.534,zoneID=7637}},coords={x=0.3,y=0.534,source="quest_giver",zoneID=7637},questType="standard"},
[38527] = {id=38527,name="Nal'ryssa's Technique",level=45,requiredLevel=45,faction="both",expansion=5,zoneID=7637,description="Listen, . We need smiths like you to carry on the traditions of the Illidari, should we fail in our crusade against the Legion. You are ready to learn. Bring me materials. Lots of them. When you return, we will have much to discuss.",starts={{npcID=92264,x=0.3,y=0.534,zoneID=7637}},ends={{npcID=92264,x=0.3,y=0.534,zoneID=7637}},coords={x=0.3,y=0.534,source="quest_giver",zoneID=7637},questType="standard"},
[38528] = {id=38528,name="Leystone's Potential",level=45,requiredLevel=45,faction="both",expansion=5,zoneID=7637,description="As I'm sure you've deduced, all of the leystone recipes you know can be improved. By learning to harness leystone's true potential, you can reduce the amount of material you use and still yield an equivalent result. Here, I'll show you. We'll start, as one does, with the humble bracer. This particular piece of armor benefits from the addition of brimstone runes. See for yourself.",starts={{npcID=92264,x=0.3,y=0.534,zoneID=7637}},ends={{npcID=92264,x=0.3,y=0.534,zoneID=7637}},coords={x=0.3,y=0.534,source="quest_giver",zoneID=7637},questType="standard"},
[38529] = {id=38529,name="7.0 Stormheim - Treasure 023 - Weeping Bluffs - ZTO",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=7541,mapID=634,questType="standard"},
[38530] = {id=38530,name="The Firmament Stone",level=45,requiredLevel=45,faction="both",expansion=5,zoneID=7503,description="When working with felslate and demonsteel, one must use special equipment. Specifically, an anvil hard enough to withstand the energy given off when felslate is hammered. Urael and I no longer possess such an anvil. But your friends, the Highmountain tauren, do. Gain access to the Firmament Stone, their sacred anvil, and we can start working with demonsteel again.",starts={{npcID=92264,x=0.3,y=0.534,zoneID=7637}},ends={{npcID=92242,x=0.552,y=0.842,zoneID=7503}},coords={x=0.3,y=0.534,source="quest_giver",zoneID=7637},questType="standard"},
[38531] = {id=38531,name="Leystone Mastery",level=45,requiredLevel=45,faction="both",expansion=5,zoneID=7503,description="Smiths that seek access to the Firmament Stone must first prove complete mastery over leystone. Craft an entire set of Leystone Armor, then submit it to me for inspection. Thala can provide you with an armor stand.",starts={{npcID=92242,x=0.552,y=0.842,zoneID=7503}},ends={{npcID=92242,x=0.552,y=0.842,zoneID=7503}},coords={x=0.552,y=0.842,source="quest_giver",zoneID=7503},questType="standard"},
[38532] = {id=38532,name="Maw of Souls: Hammered By The Storm",level=45,requiredLevel=45,faction="both",expansion=5,zoneID=7503,description="Your hammer looks weak, and would probably break upon striking the Firmament Stone. The vrykul master blacksmiths of old were known for the strength of their hammers. The only way to get our hands on such a hammer would be to go where vrykul go when they die. To the Maw of Souls. The goddess that resides over that realm is named Helya. She hoards the trinkets they bring for her own desires. Defeat her and you may be able to acquire such a hammer.",starts={{npcID=92242,x=0.552,y=0.842,zoneID=7503}},ends={{npcID=92242,x=0.552,y=0.842,zoneID=7503}},coords={x=0.552,y=0.842,source="quest_giver",zoneID=7503},questType="dungeon"},
[38533] = {id=38533,name="Tribal Knowledge",level=45,requiredLevel=45,faction="both",expansion=5,zoneID=7637,description="First, however, you'll need proper patterns for demonsteel armor. While access to the stone is earned through hard work and perseverance, access to our recipes is limited to the trusted members of our tribe. Perhaps you should seek another smith if you wish to discuss demonsteel patterns.",starts={{npcID=92243,x=0.546,y=0.84,zoneID=7503}},ends={{npcID=92264,x=0.3,y=0.534,zoneID=7637}},coords={x=0.546,y=0.84,source="quest_giver",zoneID=7503},questType="standard"},
[38534] = {id=38534,name="Demonsteel Armguards",level=45,requiredLevel=45,faction="both",expansion=5,zoneID=7503,mapID=650,starts={{npcID=92243,x=0.546,y=0.84,mapID=650}},ends={{npcID=92243,x=0.546,y=0.84,mapID=650}},coords={x=0.546,y=0.84,source="quest_giver",mapID=650},questType="standard"},
